TRADUZIONI = {'togli filtro\nkaraoke': 'drop the\nkaraoke filter', 'rimetti filtro\nkaraoke': 'add the\nkaraoke filter', 'Devocalizza': 'Remove\nvocals', 'Rimetti\nla voce': 'Restore\nvocals', 'PRONTA\nsuona pure': 'READY\nplay it', 'Preparo\n%d%%': 'Preparing\n%d%%', 'Preparo…': 'Preparing…', 'VAI\n%d%%': 'GO\n%d%%', "Abbassa la voce del brano. Si puo' premere anche prima di far partire la base — anzi conviene: cosi' parte gia' pronta. A brano finito si spegne da solo.": 'Lowers the vocals in the song. You can press it before starting the backing track — better still: that way it starts ready. It switches itself off when the song ends.'}

CODICE_DEVOC = '# -*- coding: utf-8 -*-\n"""\ndevocalizza.py — toglie (o abbassa) la voce da un brano, sul PC del cliente.\n\nCOME FUNZIONA\n    Usa un modello MDX-Net, lo stesso che sta dentro Ultimate Vocal Remover.\n    Lavora sullo spettro: il suono viene scomposto in 3072 bande, il modello\n    dice quali parti sono musica, e quello che resta e\' la voce.\n\n    Il modello gira con onnxruntime SUL PROCESSORE: non serve una scheda\n    video, e nemmeno la connessione dopo la prima volta.\n\nCOSA SERVE, E COME SE LO PROCURA\n    - onnxruntime  (~14 MB, da PyPI)   in dipendenze/devocalizza/\n    - il modello   (~64 MB, da GitHub) in dipendenze/devocalizza/\n    Si scaricano DA SOLI al primo uso, come gia\' succede per yt-dlp e deno:\n    il cliente non deve installare niente a mano. Chi non preme il bottone\n    non scarica nulla.\n\n⚠️ NON TOGLIE LA VOCE PERFETTAMENTE, e non e\' un difetto: e\' un modello\n   veloce, scelto per girare su qualunque PC. Lasciando dentro un po\' di voce\n   originale (`quanto_voce`) i difetti si sentono molto meno - ed e\' anche\n   quello che serve dal vivo, dove la voce guida aiuta chi canta.\n"""\n\nimport os\nimport subprocess\nimport sys\nimport threading\nimport urllib.request\n\n# --- DUE MODI, e cambiano il risultato per chi canta:\n#\n#     "tutta"  toglie TUTTA la voce, cori compresi.\n#     "cori"   toglie SOLO chi canta davanti e LASCIA I CORI nella base —\n#              e i cori nella base sono un miglioramento gia\' misurato su 14\n#              brani in questo progetto, non un\'opinione.\n#\n# ⚠️ I due modelli NON hanno le stesse misure: il primo lavora su 3072 bande,\n#    il secondo su 2048, e la finestra da cui vengono e\' diversa. Sbagliarla\n#    non da\' errore: il modello risponde lo stesso e separa male. Il valore\n#    del secondo (5120) e\' stato TROVATO PROVANDO, non copiato.\n#\n# ⚠️ `esce`: cosa restituisce il modello. I modelli "Inst" danno LA BASE, i\n#    modelli "Voc" danno LA VOCE — e la base si ricava per differenza. Non e\'\n#    scritto da nessuna parte nel file .onnx: si vede provando. MISURATO:\n#    usando un modello della voce come se desse la base si porta via il 99%\n#    della musica (-44 dB), cioe\' resta quasi il silenzio.\nMODELLI = {\n    \'tutta\': dict(file="UVR-MDX-NET-Inst_HQ_3.onnx",\n                  n_fft=6144, dim_f=3072, dim_t=256, hop=1024, esce=\'base\'),\n    \'cori\':  dict(file="UVR_MDXNET_KARA_2.onnx",\n                  n_fft=5120, dim_f=2048, dim_t=256, hop=1024, esce=\'base\'),\n    # ⭐ IL MIGLIORE PER TOGLIERE LA VOCE: mel_band_roformer_karaoke (aufr33 e\n    #    viperx), a 8 bit. L\'utente l\'ha ascoltato contro quello normale:\n    #    "sembrerebbe apposto". Gira in un MOTORE A PARTE (vedi\n    #    `_MotoreRoformer`), perche\' ha bisogno di PyTorch e il programma\n    #    compilato PyTorch non ce l\'ha — apposta, per non pesare 300 MB.\n    # ⚠️ MISURATO su i7-11800H: 0,75x il tempo reale. Non basta per partire\n    #    SUBITO, ma basta partire POCO DOPO: un brano di 4 minuti si puo\'\n    #    mandare dopo circa 1 minuto e 20 (vedi `_voce_separa_avanti`).\n    # ⛔ onnxruntime NON va: la stessa rete in ONNX a 8 bit fa 0,44x, e con\n    #    le ottimizzazioni piene si rompe su /band_split/Split.\n    \'roformer\': dict(file="roformer_karaoke_int8.pt", tipo=\'roformer\',\n                     n_fft=2048, dim_f=1025, dim_t=801, hop=441, esce=\'voce\'),\n}\n\n# --- il motore del roformer: pezzi da 8 s ESATTI (la rete e\' tracciata\n#     cosi\'), di cui 0,25 s per parte sono solo contesto: senza, il modello\n#     non sa cosa c\'e\' prima e dopo e sbaglia proprio sui bordi del pezzo.\nRF_N = 352800\nRF_CTX = 11025\nTIPO = \'mdx\'\n# ⭐ LA CODA: il roformer restituisce anche 46 ms OLTRE la fine del pezzo\n#    (li ha gia\' calcolati, sono nel contesto). Chi scrive il brano li mette\n#    giu\', e il pezzo dopo sfuma partendo da LORO invece che dal ripiego del\n#    filtro. Senza, a ogni giunta (ogni 7,5 s) la sfumatura passava per il\n#    filtro — che e\' piu\' vuoto — e si sentiva un piccolo calo: le\n#    "depressioni".\nCODA = 0\n\n\ndef _modelli_in_piu():\n    """Modelli aggiunti a mano, senza toccare il programma.\n\n    ⭐ Basta mettere il file .onnx in `dipendenze/devocalizza/` e descriverlo\n       in `modelli.json`, nella stessa cartella:\n\n           {\n             "kim": {"file": "Kim_Vocal_2.onnx", "n_fft": 7680,\n                     "dim_f": 3072, "dim_t": 256, "hop": 1024,\n                     "esce": "voce"}\n           }\n\n    ⚠️ `dim_f` e `dim_t` NON si indovinano: si leggono dal modello stesso\n       (l\'ingresso e\' (1, 4, dim_f, dim_t)). `n_fft` invece va provato: se e\'\n       sbagliato il modello NON da\' errore, risponde lo stesso e separa male.\n    """\n    import json\n    try:\n        p = os.path.join(cartella(), \'modelli.json\')\n        if not os.path.exists(p):\n            return {}\n        with open(p, encoding=\'utf-8\') as f:\n            dati = json.load(f)\n        buoni = {}\n        for nome, m in (dati or {}).items():\n            if not isinstance(m, dict) or not m.get(\'file\'):\n                continue\n            buoni[str(nome)] = dict(\n                file=m[\'file\'],\n                n_fft=int(m.get(\'n_fft\', 6144)),\n                dim_f=int(m.get(\'dim_f\', 3072)),\n                dim_t=int(m.get(\'dim_t\', 256)),\n                hop=int(m.get(\'hop\', 1024)),\n                esce=\'voce\' if str(m.get(\'esce\', \'base\')) == \'voce\' else \'base\')\n        if buoni:\n            print("[devocalizza] modelli in piu\' da modelli.json: %s"\n                  % \', \'.join(sorted(buoni)))\n        return buoni\n    except Exception as e:\n        print("[devocalizza] modelli.json non letto: %s" % e)\n        return {}\n# ⭐ Si parte da \'tutta\': via TUTTA la voce, cori compresi.\n#\n# ⚠️ Prima era \'cori\', che lascia i cori nella base — e i cori nella base sono\n#    un miglioramento misurato su 14 brani in questo progetto. Ma dal vivo\n#    l\'utente ha scelto diversamente: con \'cori\' il solista si sente ancora in\n#    sottofondo, perche\' quel modello per costruzione lascia passare le voci\n#    allargate. Meglio rinunciare ai cori che avere il cantante originale\n#    sotto a quello vero.\n#    Chi la pensa al contrario mette \'cori\' in devoc_modo nelle impostazioni.\nPREDEFINITO = \'tutta\'\nBASE_URL = ("https://github.com/TRvlvr/model_repo/releases/download/"\n            "all_public_uvr_models/")\n\nSR = 44100\n\n# ⛔ Le misure si prendono TUTTE dallo stesso modo, mai una per una a mano:\n#    scriverle a mano significa, prima o poi, avere il nome di un modello e la\n#    finestra di un altro. E quell\'errore non si vede — il modello risponde\n#    lo stesso e separa male.\n_M = MODELLI[PREDEFINITO]\nN_FFT = _M[\'n_fft\']\nHOP = _M[\'hop\']\nDIM_F = _M[\'dim_f\']\nDIM_T = _M[\'dim_t\']\nCHUNK = HOP * (DIM_T - 1)\nMODELLO_NOME = _M[\'file\']\nMODELLO_URL = BASE_URL + MODELLO_NOME\nESCE = _M.get(\'esce\', \'base\')      # \'base\' oppure \'voce\'\n\n\ndef tutti_i_modelli():\n    """Quelli scritti qui piu\' quelli aggiunti in `modelli.json`.\n\n    Chi sta in modelli.json VINCE sullo stesso nome: cosi\' si puo\' correggere\n    la finestra di un modello senza toccare il programma.\n    """\n    fuori = dict(MODELLI)\n    fuori.update(_modelli_in_piu())\n    return fuori\n\n\ndef _usa(modo):\n    """Imposta le misure del modo scelto. Da chiamare PRIMA di separare."""\n    global N_FFT, HOP, DIM_F, DIM_T, CHUNK, MODELLO_NOME, MODELLO_URL, ESCE, TIPO\n    global CODA\n    elenco = tutti_i_modelli()\n    m = elenco.get(modo or PREDEFINITO) or elenco[PREDEFINITO]\n    N_FFT, HOP, DIM_F, DIM_T = m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'], m[\'dim_t\']\n    CHUNK = HOP * (DIM_T - 1)\n    ESCE = m.get(\'esce\', \'base\')\n    TIPO = m.get(\'tipo\', \'mdx\')\n    CODA = 0\n    if TIPO == \'roformer\':\n        CHUNK = RF_N - 2 * RF_CTX           # la parte utile del pezzo\n        CODA = 2048\n    if MODELLO_NOME != m[\'file\']:\n        _sessione[0] = None            # cambia modello: si riapre\n    MODELLO_NOME = m[\'file\']\n    MODELLO_URL = BASE_URL + MODELLO_NOME\n    return m\n# la ruota di onnxruntime per la versione di Python con cui e\' fatto il\n# programma: deve combaciare, altrimenti non si carica\nONNX_URL = ("https://files.pythonhosted.org/packages/source-independent/"\n            "onnxruntime-1.29.0-cp313-cp313-win_amd64.whl")\nONNX_PYPI = "https://pypi.org/pypi/onnxruntime/json"\n\n_lucchetto = threading.Lock()\n_sessione = [None]\n\n\n# --------------------------------------------------------------- le cartelle\ndef _base():\n    """La cartella del programma, sia da sorgente sia compilato."""\n    if getattr(sys, \'frozen\', False) or (\'__compiled__\' in globals()):\n        return os.path.dirname(os.path.abspath(sys.argv[0]))\n    return os.path.abspath(os.path.join(os.path.dirname(__file__), \'..\'))\n\n\ndef cartella():\n    d = os.path.join(_base(), \'dipendenze\', \'devocalizza\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        # in Program Files potrebbe non essere scrivibile: si ripiega\n        # nella cartella dell\'utente, dove i permessi ci sono sempre\n        d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or\n                         os.path.expanduser(\'~\'), \'KaraDom\', \'devocalizza\')\n        os.makedirs(d, exist_ok=True)\n    return d\n\n\ndef _ffmpeg():\n    for c in (os.path.join(_base(), \'dipendenze\', \'ffmpeg.exe\'),\n              os.path.join(_base(), \'ffmpeg.exe\'),\n              \'ffmpeg\'):\n        if c == \'ffmpeg\' or os.path.exists(c):\n            return c\n    return \'ffmpeg\'\n\n\n# ------------------------------------------------------- procurarsi il pezzo\ndef _scarica(url, dove, avviso=None):\n    """Scarica dicendo a che punto e\', e NON lascia mai un file a meta\':\n    si scrive in un file temporaneo e si rinomina solo alla fine."""\n    tmp = dove + \'.parte\'\n    req = urllib.request.Request(url, headers={\'User-Agent\': \'KaraDom\'})\n    with urllib.request.urlopen(req, timeout=60) as r:\n        totale = int(r.headers.get(\'Content-Length\') or 0)\n        fatto = 0\n        with open(tmp, \'wb\') as f:\n            while True:\n                pezzo = r.read(262144)\n                if not pezzo:\n                    break\n                f.write(pezzo)\n                fatto += len(pezzo)\n                if avviso and totale:\n                    avviso(fatto * 100 // totale)\n    os.replace(tmp, dove)\n    return dove\n\n\ndef _onnx_wheel_url():\n    """L\'indirizzo vero della ruota giusta, chiesto a PyPI.\n\n    Non si scrive a mano: gli indirizzi dei pacchetti cambiano a ogni\n    versione, e uno sbagliato darebbe un 404 al primo cliente che prova.\n    """\n    import json\n    tag = \'cp%d%d\' % (sys.version_info[0], sys.version_info[1])\n    with urllib.request.urlopen(ONNX_PYPI, timeout=30) as r:\n        dati = json.loads(r.read().decode(\'utf-8\'))\n    for versione in sorted(dati.get(\'releases\', {}), reverse=True):\n        for file in dati[\'releases\'][versione]:\n            n = file.get(\'filename\', \'\')\n            if tag in n and \'win_amd64\' in n and n.endswith(\'.whl\'):\n                return file[\'url\'], n\n    raise RuntimeError("nessuna versione di onnxruntime per Python %s"\n                       % \'.\'.join(map(str, sys.version_info[:2])))\n\n\ndef procura_onnxruntime(avviso=None):\n    """Ritorna il modulo onnxruntime, scaricandolo se non c\'e\'."""\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    d = cartella()\n    if d not in sys.path:\n        sys.path.insert(0, d)\n    try:\n        import onnxruntime\n        return onnxruntime\n    except Exception:\n        pass\n\n    if avviso:\n        avviso(0, "Scarico il motore (una volta sola, ~14 MB)…")\n    url, nome = _onnx_wheel_url()\n    whl = os.path.join(d, nome)\n    if not os.path.exists(whl):\n        _scarica(url, whl, (lambda p: avviso(p, "Motore… %d%%" % p)) if avviso else None)\n    # la ruota e\' uno zip: si scompatta qui dentro e basta\n    import zipfile\n    with zipfile.ZipFile(whl) as z:\n        z.extractall(d)\n    try:\n        os.remove(whl)\n    except Exception:\n        pass\n    import onnxruntime\n    return onnxruntime\n\n\ndef procura_modello(avviso=None):\n    d = cartella()\n    f = os.path.join(d, MODELLO_NOME)\n    if not os.path.exists(f):\n        if avviso:\n            avviso(0, "Scarico il modello (una volta sola, ~64 MB)…")\n        _scarica(MODELLO_URL, f,\n                 (lambda p: avviso(p, "Modello… %d%%" % p)) if avviso else None)\n    return f\n\n\ndef pronto():\n    """True se non c\'e\' niente da scaricare."""\n    if TIPO == \'roformer\':\n        return roformer_disponibile()\n    try:\n        import onnxruntime  # noqa: F401\n        motore = True\n    except Exception:\n        motore = os.path.isdir(os.path.join(cartella(), \'onnxruntime\'))\n    return motore and os.path.exists(os.path.join(cartella(), MODELLO_NOME))\n\n\n# ------------------------------------------------ il motore del roformer\n# ⭐ Gira in un PROCESSO A PARTE, con un Python che ha PyTorch. Il programma\n#    gli passa un pezzo da 8 s, lui risponde con la VOCE di quel pezzo.\n#    Cosi\':\n#      - il programma compilato resta com\'e\' (PyTorch e\' escluso apposta\n#        dalla build: 300 MB in piu\' per tutti, anche per chi non lo usa);\n#      - se il motore si pianta, il programma non se ne accorge nemmeno;\n#      - gira a priorita\' BASSA: la musica e il video che stanno suonando\n#        vengono prima di lui, e non si sentono scatti.\n# ⚠️ Il testo qui sotto e\' il motore stesso: si riscrive su disco a ogni\n#    avvio, cosi\' una patch lo aggiorna senza scaricare niente.\nMOTORE_PY = r\'\'\'# -*- coding: utf-8 -*-\n# Motore del roformer per KaraDom: lo avvia il programma, non va lanciato a mano.\nimport struct\nimport sys\n\nimport torch\n\nN = 352800\nNFFT = 2048\nHOP = 441\n\ntorch.set_num_threads(max(1, int(sys.argv[2])))\nrete = torch.jit.load(sys.argv[1], map_location="cpu").eval()\nfin = torch.hann_window(NFFT)\ningresso = sys.stdin.buffer\nuscita = sys.stdout.buffer\n\n\ndef leggi(quanti):\n    b = bytearray()\n    while len(b) < quanti:\n        p = ingresso.read(quanti - len(b))\n        if not p:\n            return None\n        b += p\n    return b\n\n\ndef voce_di(x):\n    """x: (2, N) -> la voce, (2, N)."""\n    S = torch.stft(x, n_fft=NFFT, hop_length=HOP, win_length=NFFT, window=fin,\n                   center=True, normalized=False, return_complex=True)\n    S = torch.view_as_real(S)                       # (2, 1025, 801, 2)\n    frame = S.shape[2]\n    # la rete vuole frequenze e canali alternati: indice = frequenza*2 + canale\n    S = S.permute(1, 0, 2, 3).reshape(1, 2050, frame, 2)\n    y = rete(S)                                     # (1, 1, 2050, 801, 2)\n    y = y.reshape(1025, 2, frame, 2).permute(1, 0, 2, 3).contiguous()\n    return torch.istft(torch.view_as_complex(y), n_fft=NFFT, hop_length=HOP,\n                       win_length=NFFT, window=fin, center=True,\n                       normalized=False, length=N)\n\n\nwith torch.inference_mode():\n    voce_di(torch.zeros(2, N))                      # il primo giro scalda\n    uscita.write(b"PRONTO\\n")\n    uscita.flush()\n    while True:\n        h = leggi(4)\n        if h is None:\n            break\n        n = struct.unpack("<I", bytes(h))[0]\n        if n == 0:\n            break\n        dati = leggi(n * 8)\n        if dati is None:\n            break\n        x = torch.frombuffer(dati, dtype=torch.float32).view(2, n)\n        if n < N:\n            x = torch.nn.functional.pad(x, (0, N - n))\n        v = voce_di(x[:, :N].contiguous())[:, :n]\n        uscita.write(v.contiguous().numpy().astype("<f4").tobytes())\n        uscita.flush()\n\'\'\'\n\n_motore = [None]\n\n\ndef _cartelle_roformer():\n    """Dove puo\' stare il roformer.\n\n    ⛔⛔ NON SOLO `cartella()`. Dentro la patch questo modulo non ha un vero\n        `__file__` (e\' \'<patch_voce_devoc>\'), e `_base()` risponde con la\n        cartella SOPRA quella da cui e\' partito il programma: sul PC\n        dell\'utente `C:\\\\Program Files\\\\dipendenze\\\\devocalizza`, senza\n        "KaraDom". Il modello messo accanto agli altri, nella cartella del\n        programma, non veniva trovato, e SENZA DIRE NIENTE si tornava al\n        modello vecchio: la prima prova "col roformer" era col modello\n        vecchio. Adesso si guarda in tutti i posti sensati.\n    """\n    tutte = [cartella()]\n    try:\n        tutte.append(os.path.join(os.path.dirname(os.path.abspath(sys.executable)),\n                                  \'dipendenze\', \'devocalizza\'))\n    except Exception:\n        pass\n    tutte.append(_cartella_utente())\n    visti, fuori = set(), []\n    for d in tutte:\n        k = os.path.abspath(d).lower()\n        if k not in visti:\n            visti.add(k)\n            fuori.append(d)\n    return fuori\n\n\ndef _cartella_utente():\n    """Quella dove si puo\' SEMPRE scrivere (Program Files spesso no)."""\n    d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or os.path.expanduser(\'~\'),\n                     \'KaraDom\', \'devocalizza\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        pass\n    return d\n\n\ndef _file_roformer():\n    for d in _cartelle_roformer():\n        f = os.path.join(d, MODELLI[\'roformer\'][\'file\'])\n        if os.path.exists(f):\n            return f\n    return None\n\n\ndef _python_motore():\n    """Il Python col PyTorch dentro. Prima quello scritto nelle impostazioni\n    (`devoc_python`), poi quello che si scarica accanto ai modelli."""\n    candidati = []\n    try:\n        from .database import Database\n        v = str(Database.get_config(\'devoc_python\', \'\')).strip()\n        if v:\n            candidati.append(v)\n    except Exception:\n        pass\n    for d in _cartelle_roformer():\n        candidati.append(os.path.join(d, \'motore\', \'python.exe\'))\n    for c in candidati:\n        if c and os.path.exists(c):\n            return c\n    return None\n\n\ndef roformer_disponibile():\n    """C\'e\' tutto per usare il roformer, senza scaricare niente?"""\n    return bool(_python_motore()) and bool(_file_roformer())\n\n\nclass _MotoreRoformer(object):\n    """Il processo del roformer. Un pezzo alla volta, in fila."""\n\n    def __init__(self, python, modello, thread):\n        import subprocess as sp\n        script = os.path.join(_cartella_utente(), \'roformer_motore.py\')\n        try:\n            vecchio = open(script, encoding=\'utf-8\').read()\n        except Exception:\n            vecchio = None\n        if vecchio != MOTORE_PY:\n            with open(script, \'w\', encoding=\'utf-8\', newline=\'\\n\') as f:\n                f.write(MOTORE_PY)\n        registro = open(os.path.join(_cartella_utente(), \'roformer_motore.log\'), \'ab\')\n        flag = 0\n        if os.name == \'nt\':\n            # niente finestra nera + priorita\' sotto il normale: chi suona\n            # viene prima di chi prepara\n            flag = 0x08000000 | 0x00004000\n        self.p = sp.Popen([python, \'-u\', script, modello, str(thread)],\n                          stdin=sp.PIPE, stdout=sp.PIPE, stderr=registro,\n                          creationflags=flag)\n        riga = self.p.stdout.readline()\n        if not riga.startswith(b\'PRONTO\'):\n            raise RuntimeError("il motore del roformer non e\' partito (%r) - "\n                               "vedi roformer_motore.log" % riga[:200])\n        self.lucchetto = threading.Lock()\n\n    def vivo(self):\n        return self.p.poll() is None\n\n    def voce(self, x):\n        """x: (2, n) con n <= RF_N -> la voce, (2, n)."""\n        import struct\n        import numpy as np\n        n = int(x.shape[1])\n        grezzo = np.ascontiguousarray(x, dtype=\'<f4\').tobytes()\n        with self.lucchetto:\n            self.p.stdin.write(struct.pack(\'<I\', n) + grezzo)\n            self.p.stdin.flush()\n            dati = bytearray()\n            while len(dati) < n * 8:\n                pezzo = self.p.stdout.read(n * 8 - len(dati))\n                if not pezzo:\n                    raise RuntimeError("il motore del roformer si e\' fermato")\n                dati += pezzo\n        return np.frombuffer(bytes(dati), dtype=\'<f4\').reshape(2, n)\n\n    def base(self, pezzo, mix=None, a=None):\n        """Il pezzo SENZA la voce, calcolato con 0,25 s di contesto per parte.\n\n        ⚠️ Il contesto si prende dal brano vero (`mix`, `a`) quando c\'e\':\n           cosi\' i bordi del pezzo il modello li vede come li sente chi\n           ascolta. Senza, si mette silenzio, che e\' meglio di niente.\n        """\n        import numpy as np\n        lung = pezzo.shape[1]\n        if mix is not None and a is not None:\n            tot = mix.shape[1]\n            da = int(a) - RF_CTX\n            fin = mix[:, max(0, da):max(0, min(tot, da + RF_N))]\n            sx = max(0, -da)\n            fin = np.pad(fin, ((0, 0), (sx, max(0, RF_N - sx - fin.shape[1]))))\n        else:\n            fin = np.pad(pezzo, ((0, 0), (RF_CTX, max(0, RF_N - RF_CTX - lung))))\n        v = self.voce(fin[:, :RF_N].astype(\'float32\'))\n        base = pezzo - v[:, RF_CTX:RF_CTX + lung]\n        # la CODA (vedi sopra): solo se il brano continua davvero.\n        # ⚠️ la misura e\' fissa QUI, non letta dal modulo: un altro lavoro che\n        #    apre il modello veloce la metterebbe a zero sotto i piedi\n        if mix is not None and a is not None:\n            coda = max(0, min(2048, mix.shape[1] - (int(a) + lung)))\n            if coda:\n                dopo = mix[:, int(a) + lung:int(a) + lung + coda]\n                base = np.concatenate(\n                    [base, dopo - v[:, RF_CTX + lung:RF_CTX + lung + coda]], axis=1)\n        return base\n\n\n_lucchetto_motore = threading.Lock()\n\n\ndef _motore_roformer(avviso=None):\n    # ⚠️ una serratura SUA: il motore impiega 12 s a partire, e con quella di\n    #    onnxruntime in quei 12 s si sarebbe fermato anche il modello veloce\n    #    che intanto pulisce la testa del brano\n    with _lucchetto_motore:\n        m = _motore[0]\n        if m is not None and m.vivo():\n            return m\n        py = _python_motore()\n        modello = _file_roformer()\n        if not py or not modello:\n            raise RuntimeError("il roformer non e\' su questo PC")\n        if avviso:\n            avviso(0, "Avvio il motore…")\n        _motore[0] = _MotoreRoformer(py, modello, quanti_thread())\n        return _motore[0]\n\n\n# --------------------------------------------------------------- lo spettro\ndef _finestra():\n    import numpy as np\n    # hann periodica, la stessa che usa il modello in addestramento\n    n = np.arange(N_FFT)\n    return (0.5 - 0.5 * np.cos(2.0 * np.pi * n / N_FFT)).astype(\'float32\')\n\n\ndef _stft(x, win, n_fft=None, hop=None, dim_f=None):\n    """x: (canali, campioni) -> (canali, DIM_F, frame) complesso.\n\n    Bordi riflessi, come `center=True`: senza, il primo e l\'ultimo pezzo di\n    ogni blocco perderebbero energia e si sentirebbero gli attacchi.\n\n    ⚠️ Le misure si possono passare: con due brani preparati insieme (uno\n       col roformer, uno col modello veloce) quelle del modulo cambiano\n       sotto i piedi. Vedi `_SessioneMDX`.\n    """\n    import numpy as np\n    N_FFT_, HOP_, DIM_F_ = n_fft or N_FFT, hop or HOP, dim_f or DIM_F\n    meta = N_FFT_ // 2\n    x = np.pad(x, ((0, 0), (meta, meta)), mode=\'reflect\')\n    frame = 1 + (x.shape[1] - N_FFT_) // HOP_\n    fuori = np.empty((x.shape[0], DIM_F_, frame), dtype=\'complex64\')\n    for i in range(frame):\n        pezzo = x[:, i * HOP_:i * HOP_ + N_FFT_] * win\n        fuori[:, :, i] = np.fft.rfft(pezzo, axis=1)[:, :DIM_F_]\n    return fuori\n\n\ndef _istft(S, win, campioni, n_fft=None, hop=None, dim_f=None):\n    """L\'inverso: si risomma con la finestra e si divide per quanto ogni\n    campione e\' stato coperto, se no dove le finestre si accavallano il\n    suono verrebbe piu\' forte."""\n    import numpy as np\n    N_FFT, HOP, DIM_F = (n_fft or globals()[\'N_FFT\'], hop or globals()[\'HOP\'],\n                         dim_f or globals()[\'DIM_F\'])\n    canali, _, frame = S.shape\n    meta = N_FFT // 2\n    lungo = (frame - 1) * HOP + N_FFT\n    fuori = np.zeros((canali, lungo), dtype=\'float32\')\n    pesi = np.zeros(lungo, dtype=\'float32\')\n    pieno = np.zeros((canali, N_FFT // 2 + 1), dtype=\'complex64\')\n    for i in range(frame):\n        pieno[:] = 0\n        pieno[:, :DIM_F] = S[:, :, i]\n        onda = np.fft.irfft(pieno, n=N_FFT, axis=1).astype(\'float32\')\n        fuori[:, i * HOP:i * HOP + N_FFT] += onda * win\n        pesi[i * HOP:i * HOP + N_FFT] += win * win\n    pesi[pesi < 1e-8] = 1e-8\n    fuori /= pesi\n    return fuori[:, meta:meta + campioni]\n\n\n# ------------------------------------------------------------- il lavoro vero\ndef _leggi_audio(percorso):\n    """Audio in stereo 44100 tramite ffmpeg: cosi\' legge tutto — mp3, mp4,\n    mkv, quello che c\'e\' — senza altre librerie."""\n    import numpy as np\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-i\', percorso,\n           \'-f\', \'f32le\', \'-acodec\', \'pcm_f32le\',\n           \'-ac\', \'2\', \'-ar\', str(SR), \'-\']\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000      # niente finestra nera\n    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0 or not p.stdout:\n        raise RuntimeError("ffmpeg non ha letto l\'audio: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    d = np.frombuffer(p.stdout, dtype=\'float32\').reshape(-1, 2).T.copy()\n    return d\n\n\ndef _scrivi_audio(dati, percorso):\n    import numpy as np\n    grezzo = np.ascontiguousarray(dati.T.astype(\'float32\')).tobytes()\n    cmd = [_ffmpeg(), \'-v\', \'error\', \'-y\',\n           \'-f\', \'f32le\', \'-ar\', str(SR), \'-ac\', \'2\', \'-i\', \'-\']\n    if percorso.lower().endswith(\'.mp3\'):\n        cmd += [\'-codec:a\', \'libmp3lame\', \'-b:a\', \'320k\']\n    cmd += [percorso]\n    kw = {}\n    if os.name == \'nt\':\n        kw[\'creationflags\'] = 0x08000000\n    p = subprocess.run(cmd, input=grezzo, stdout=subprocess.PIPE,\n                       stderr=subprocess.PIPE, **kw)\n    if p.returncode != 0:\n        raise RuntimeError("ffmpeg non ha scritto il file: %s"\n                           % p.stderr.decode(\'utf-8\', \'replace\')[-300:])\n    return percorso\n\n\ndef quanti_thread(rimisura=False):\n    """Quanti core usare, MISURATO su questa macchina.\n\n    ⛔ Non si indovina: su 16 core usarli tutti e\' risultato il caso PEGGIORE\n       (2,06 s a blocco contro 1,67 con dodici, +19% di attesa) — oltre una\n       certa soglia i thread si ostacolano fra loro. Ma dove sia quella\n       soglia dipende dalla macchina, e una regola fissa andrebbe bene solo\n       sul computer su cui l\'ho scritta.\n\n    Quindi la prima volta si prova davvero: tre impostazioni, un blocco\n    ciascuna, si tiene la piu\' rapida e si ricorda. Costa pochi secondi, una\n    volta sola nella vita del programma.\n    """\n    n = max(1, os.cpu_count() or 4)\n    if not rimisura:\n        try:\n            from .database import Database\n            v = int(str(Database.get_config(\'devoc_thread\', \'0\')).strip())\n            if 1 <= v <= n:\n                return v\n        except Exception:\n            pass\n    # ripiego finche\' la misura non c\'e\': tre quarti dei core\n    return max(2, int(n * 0.75)) if n > 2 else n\n\n\ndef misura_thread(avviso=None):\n    """Prova le impostazioni su UN blocco e ricorda la migliore."""\n    import time\n    import numpy as np\n    import onnxruntime as ort\n\n    n = max(1, os.cpu_count() or 4)\n    candidati = sorted({max(2, n // 2), max(2, int(n * 0.75)), n} if n > 2 else {n})\n    modello = procura_modello(avviso)\n\n    # un blocco di rumore basta: si misura la macchina, non la musica\n    finto = np.random.randn(1, 4, DIM_F, DIM_T).astype(\'float32\') * 0.01\n    esiti = []\n    for th in candidati:\n        try:\n            o = ort.SessionOptions()\n            o.intra_op_num_threads = th\n            o.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n            s = ort.InferenceSession(modello, sess_options=o,\n                                     providers=[\'CPUExecutionProvider\'])\n            nome = s.get_inputs()[0].name\n            s.run(None, {nome: finto})          # il primo giro scalda\n            t0 = time.perf_counter()\n            s.run(None, {nome: finto})\n            esiti.append((time.perf_counter() - t0, th))\n            del s\n        except Exception:\n            continue\n    if not esiti:\n        return quanti_thread()\n    esiti.sort()\n    migliore = esiti[0][1]\n    try:\n        from .database import Database\n        Database.set_config(\'devoc_thread\', str(migliore))\n    except Exception:\n        pass\n    print("[devocalizza] misurato su questa macchina: %d core su %d "\n          "(%s)" % (migliore, n,\n                    ", ".join("%d=%.2fs" % (t2, t1) for t1, t2 in esiti)))\n    return migliore\n\n\ndef _sessione_onnx(avviso=None):\n    with _lucchetto:\n        if _sessione[0] is not None:\n            return _sessione[0]\n        ort = procura_onnxruntime(avviso)\n        modello = procura_modello(avviso)\n        # la prima volta si misura la macchina, poi il valore resta\n        try:\n            from .database import Database\n            if not str(Database.get_config(\'devoc_thread\', \'\')).strip():\n                if avviso:\n                    avviso(0, "Guardo quanto e\' veloce questo computer…")\n                misura_thread(avviso)\n        except Exception:\n            pass\n        opz = ort.SessionOptions()\n        opz.intra_op_num_threads = quanti_thread()\n        opz.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n        _sessione[0] = ort.InferenceSession(\n            modello, sess_options=opz, providers=[\'CPUExecutionProvider\'])\n        return _sessione[0]\n\n\ndef separa(percorso, avanzamento=None, modo=None):\n    """(base, voce) come due array (2, campioni). E\' il passo lento."""\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    if TIPO == \'roformer\':\n        motore = _motore_roformer(avanzamento)\n        mix = _leggi_audio(percorso)\n        totale = mix.shape[1]\n        base = np.zeros_like(mix)\n        quanti = max(1, (totale + CHUNK - 1) // CHUNK)\n        for n in range(quanti):\n            a = n * CHUNK\n            b = min(totale, a + CHUNK)\n            base[:, a:b] = motore.base(mix[:, a:b], mix, a)[:, :b - a]\n            if avanzamento:\n                avanzamento(int((n + 1) * 100 / quanti), "Separazione… %d%%"\n                            % int((n + 1) * 100 / quanti))\n        return base, mix - base\n    sess = _sessione_onnx(avanzamento)\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    base = np.zeros_like(mix)\n    quanti = max(1, (totale + CHUNK - 1) // CHUNK)\n    for n in range(quanti):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        if pezzo.shape[1] < CHUNK:            # l\'ultimo si allunga con silenzio\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - pezzo.shape[1])))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        # ⚠️ L\'ORDINE DEI QUATTRO PIANI CONTA: il modello li vuole alternati\n        #    per canale — sinistro reale, sinistro immaginario, destro reale,\n        #    destro immaginario. Mettendoli a blocchi (prima i due reali, poi\n        #    i due immaginari) il modello non riconosce piu\' niente e\n        #    restituisce quasi l\'ingresso: misurato, toglieva 0,6 dB invece\n        #    di separare.\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        onda = _istft(S2, win, CHUNK)\n        base[:, a:b] = onda[:, :b - a]\n        if avanzamento:\n            avanzamento(int((n + 1) * 100 / quanti), "Separazione… %d%%"\n                        % int((n + 1) * 100 / quanti))\n\n    voce = mix - base\n    return base, voce\n\n\ndef apri(modo=None, avviso=None):\n    """Prepara il modello e da\' gli attrezzi per lavorare UN pezzo alla volta.\n\n    Torna (sessione, finestra, CHUNK, SR). Serve a chi il giro dei pezzi se lo\n    fa per conto suo — per esempio chi sta riscrivendo un brano mentre suona e\n    deve decidere lui quando fermarsi e da dove ripartire.\n    """\n    with _lucchetto_misure:\n        _usa(modo)\n        tipo, chunk = TIPO, CHUNK\n        if tipo != \'roformer\':\n            # ⭐ la sessione si porta dietro le SUE misure (vedi `_SessioneMDX`)\n            mis = dict(n_fft=N_FFT, hop=HOP, dim_f=DIM_F, dim_t=DIM_T, esce=ESCE)\n            win = _finestra()\n            sess = _sessione_onnx(avviso)\n    if tipo == \'roformer\':\n        # ⚠️ fuori dalla serratura delle misure: il motore puo\' metterci 12 s\n        #    a partire, e intanto il modello veloce di un\'altra riga aspetterebbe\n        return _motore_roformer(avviso), None, chunk, SR\n    return _SessioneMDX(sess, mis), win, chunk, SR\n\n\n_lucchetto_misure = threading.Lock()\n\n\nclass _SessioneMDX(object):\n    """La sessione di onnxruntime INSIEME alle misure del suo modello.\n\n    ⛔⛔ Le misure (N_FFT, HOP, DIM_F, ...) sono variabili del modulo, e le\n        cambia chiunque apra un modello. Con due righe preparate insieme —\n        una col roformer, una col modello veloce — la seconda apertura\n        cambiava le misure alla prima mentre lavorava, e il modello\n        rispondeva lo stesso ma separava male, senza un errore.\n    """\n\n    def __init__(self, sess, mis):\n        self.sess = sess\n        self.mis = mis\n\n    def get_inputs(self):\n        return self.sess.get_inputs()\n\n    def run(self, *a, **k):\n        return self.sess.run(*a, **k)\n\n\ndef base_del_pezzo(sess, win, pezzo, mix=None, a=None):\n    """Il pezzo SENZA la voce. `pezzo`: (2, CHUNK) float32.\n\n    `mix` e `a` (il brano intero e dove comincia il pezzo) servono al\n    roformer per guardare un po\' prima e un po\' dopo; gli MDX li ignorano.\n\n    ⚠️ L\'ORDINE DEI QUATTRO PIANI CONTA: il modello li vuole alternati per\n       canale (sinistro reale, sinistro immaginario, destro reale, destro\n       immaginario). A blocchi non da\' errore: separa male e basta.\n    """\n    if isinstance(sess, _MotoreRoformer):\n        return sess.base(pezzo, mix, a)\n    import numpy as np\n    if isinstance(sess, _SessioneMDX):\n        m = sess.mis\n    else:\n        m = dict(n_fft=N_FFT, hop=HOP, dim_f=DIM_F, dim_t=DIM_T, esce=ESCE)\n    S = _stft(pezzo, win, m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'])[:, :, :m[\'dim_t\']]\n    x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                 axis=0).astype(\'float32\')[None]\n    y = sess.run(None, {sess.get_inputs()[0].name: x})[0][0]\n    S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n    uscita = _istft(S2, win, pezzo.shape[1], m[\'n_fft\'], m[\'hop\'], m[\'dim_f\'])\n    # ⚠️ Qui esce SEMPRE la base, qualunque cosa produca il modello: chi\n    #    chiama non deve sapere se ha davanti un modello della base o della\n    #    voce. MISURATO: sbagliare questa riga porta via il 99% della musica.\n    if m[\'esce\'] == \'voce\':\n        return pezzo[:, :uscita.shape[1]] - uscita\n    return uscita\n\n\ndef separa_progressiva(percorso, quanto_voce=0.0, modo=None):\n    """Consegna il brano A PEZZI, appena sono pronti.\n\n    Serve per suonare mentre si separa: ogni giro restituisce\n    (secondo_di_inizio, audio_gia_devocalizzato). Il calcolo va a circa meta\'\n    della durata del brano, quindi ogni secondo speso ne produce due: con un\n    piccolo vantaggio iniziale il calcolo resta davanti a chi ascolta per\n    tutto il brano.\n\n    ⚠️ Il primo pezzo costa piu\' degli altri: la prima chiamata al modello\n    include l\'apertura del file e la preparazione, ed e\' il ritardo che\n    l\'ascoltatore sente prima di partire.\n    """\n    import numpy as np\n\n    _usa(modo)                       # prima le misure, poi il modello\n    if TIPO == \'roformer\':\n        motore = _motore_roformer()\n        mix = _leggi_audio(percorso)\n        totale = mix.shape[1]\n        for n in range((totale + CHUNK - 1) // CHUNK):\n            a = n * CHUNK\n            b = min(totale, a + CHUNK)\n            base = motore.base(mix[:, a:b], mix, a)[:, :b - a]\n            if quanto_voce > 0:\n                base = base + (mix[:, a:b] - base) * float(quanto_voce)\n            yield a / float(SR), base\n        return\n    sess = _sessione_onnx()\n    nome_in = sess.get_inputs()[0].name\n    win = _finestra()\n    mix = _leggi_audio(percorso)\n    totale = mix.shape[1]\n\n    for n in range((totale + CHUNK - 1) // CHUNK):\n        a = n * CHUNK\n        b = min(totale, a + CHUNK)\n        pezzo = mix[:, a:b]\n        vero = pezzo.shape[1]\n        if vero < CHUNK:\n            pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - vero)))\n        S = _stft(pezzo, win)[:, :, :DIM_T]\n        x = np.stack([S[0].real, S[0].imag, S[1].real, S[1].imag],\n                     axis=0).astype(\'float32\')[None]\n        y = sess.run(None, {nome_in: x})[0][0]\n        S2 = np.stack([y[0] + 1j * y[1], y[2] + 1j * y[3]]).astype(\'complex64\')\n        base = _istft(S2, win, CHUNK)[:, :vero]\n        if quanto_voce > 0:\n            base = base + (mix[:, a:b] - base) * float(quanto_voce)\n        yield a / float(SR), base\n\n\ndef quanto_abbassare():\n    """Di quanti decibel si abbassa la voce. Ritorna il FATTORE da usare.\n\n    ⛔ Non si TOGLIE la voce, si ABBASSA: il brano resta intero e la parte\n       riconosciuta come voce viene tirata giu\'. Cosi\' quello che il modello\n       sbaglia a riconoscere non resta a volume pieno - viene abbassato anche\n       lui - e non ci sono buchi nel suono.\n    """\n    db = 12.0\n    try:\n        from .database import Database\n        db = float(str(Database.get_config(\'devoc_db\', \'12\')).strip() or 12)\n    except Exception:\n        pass\n    db = max(0.0, min(60.0, db))\n    if db >= 60:\n        return 0.0                      # praticamente via del tutto\n    return 10.0 ** (-db / 20.0)         # -12 dB -> resta il 25%\n\n\ndef modo_scelto():\n    """Quale dei due modi ha scelto l\'utente nelle Opzioni (scheda Audio)."""\n    try:\n        from .database import Database\n        m = str(Database.get_config(\'devoc_modo\', PREDEFINITO)).strip()\n        if m in tutti_i_modelli():\n            # ⛔ il roformer ha bisogno del SUO motore: se su questo PC non\n            #    c\'e\', si torna al modello di sempre invece di non fare niente\n            if m == \'roformer\' and not roformer_disponibile():\n                return PREDEFINITO\n            return m\n    except Exception:\n        pass\n    return PREDEFINITO\n\n\ndef devocalizza(percorso, uscita=None, quanto_voce=None, avanzamento=None,\n                modo=None):\n    """Scrive il brano con la VOCE ABBASSATA.\n\n    quanto_voce: quanto ne resta. Se non lo si dice, si prende il livello\n    scelto nelle Opzioni (predefinito -12 dB, cioe\' ne resta un quarto).\n    modo: se non lo si dice, si usa quello scelto nelle Opzioni.\n    """\n    if quanto_voce is None:\n        quanto_voce = quanto_abbassare()\n    base, voce = separa(percorso, avanzamento, modo=modo or modo_scelto())\n    if quanto_voce > 0:\n        base = base + voce * float(quanto_voce)\n    # niente distorsione se la somma supera il fondo scala\n    import numpy as np\n    picco = float(np.max(np.abs(base))) if base.size else 0.0\n    if picco > 1.0:\n        base = base / picco\n    if not uscita:\n        radice, est = os.path.splitext(percorso)\n        uscita = radice + \' (devocalizzato)\' + (\'.mp3\' if est.lower() in\n                                                (\'.mp4\', \'.mkv\', \'.webm\', \'.avi\')\n                                                else est)\n    return _scrivi_audio(base, uscita)\n'

CODICE_DEP = 'def completa_mancanti(dest_dir=None, url=None, timeout=TIMEOUT, log=print,\n                      aspetta=False):\n    """Scarica i file mancanti IN SOTTOFONDO, e torna subito.\n\n    ⛔ PERCHE\' IN SOTTOFONDO: chi la chiama lo fa dal filo della GRAFICA, e da\n       quando fra le dipendenze c\'e\' anche il motore che separa la voce\n       (onnxruntime + il modello, circa 90 MB) un cliente che non li ha\n       ancora si troverebbe il programma fermo per tutto lo scaricamento,\n       senza capire perche\'. Cosi\' invece il programma parte, si usa, e i\n       file arrivano quando arrivano — nessuno li sta aspettando.\n\n    `aspetta=True` per chi vuole il vecchio comportamento e il conto dei file.\n    """\n    import threading\n    if aspetta:\n        return _completa_mancanti_ora(dest_dir, url, timeout, log)\n    threading.Thread(target=_completa_mancanti_ora,\n                     args=(dest_dir, url, timeout, log),\n                     daemon=True, name=\'dipendenze\').start()\n    return 0, 0\n\n\ndef _completa_mancanti_ora(dest_dir=None, url=None, timeout=TIMEOUT, log=print):\n    """Scarica dallo zip SOLO i file che mancano nella cartella dipendenze.\n\n    ⚠️ Perche\' esiste: `sync_dipendenze` non era chiamata da nessuna parte del\n    programma (verificato il 3 set 2026), e cosi\' nell\'installato mancavano\n    `ytdlp_local_server.py`, `yt-dlp.conf` e la cartella `pyserver/`: il server\n    yt-dlp locale non partiva mai e si ripiegava sull\'exe.\n\n    A differenza di `sync_dipendenze` NON tocca i file gia\' presenti: cosi\' non\n    puo\' riportare indietro roba piu\' nuova - per esempio `yt-dlp.exe`, che si\n    aggiorna per conto suo dall\'updater. Legge lo zip per Range: scarica solo i\n    pezzi che servono, non i 400 MB.\n\n    Ritorna (file scaricati, byte). (-1, 0) se lo zip non e\' raggiungibile.\n    """\n    dest = dest_dir or _dest_dir()\n    indirizzo = url or DEP_ZIP_URL\n    try:\n        os.makedirs(dest, exist_ok=True)\n        zf = zipfile.ZipFile(_HttpRangeFile(indirizzo, timeout))\n    except (urllib.error.URLError, OSError, zipfile.BadZipFile) as e:\n        log("[dipendenze] zip non raggiungibile: %s" % e)\n        return -1, 0\n\n    manca = [i for i in zf.infolist() if not i.is_dir()\n             and not os.path.exists(os.path.join(dest, i.filename.replace("/", os.sep)))]\n    if not manca:\n        return 0, 0\n    log("[dipendenze] mancano %d file, li scarico..." % len(manca))\n    presi = byte = 0\n    for info in manca:\n        try:\n            raw = _fetch_member(indirizzo, info, timeout)\n            _write_atomic(os.path.join(dest, info.filename.replace("/", os.sep)), raw)\n            presi += 1\n            byte += info.file_size\n        except Exception as e:\n            log("[dipendenze] %s non scaricato: %s" % (info.filename, e))\n    log("[dipendenze] completati %d file (%.1f MB) in %s" % (presi, byte / 1048576.0, dest))\n    return presi, byte'

CODICE_SYS = 'def _filtro_voce(self, quanto: int):\n    """La catena di filtri per ffmpeg. Vuota = suono naturale.\n\n    `quanto`: 0 = voce com\'e\', 100 = centro tolto del tutto.\n\n    ⭐ Con `devoc_k5` acceso si usa la formula nuda di K5: vedi `_k5_puro`.\n\n    ⛔ NON basta `stereotools` e via: da solo porta giu\' la voce E IL\n       BASSO della stessa quantita\', perche\' cassa e basso stanno al\n       centro pure loro, e il brano si svuota.\n    ⛔ E NON si rimedia rialzando i bassi dopo: MISURATO su tre brani\n       veri, quella pezza tirava su il livello di +6 dB e i picchi di\n       +8 (il brano distorceva), perche\' rialza anche il basso che sta\n       ai LATI, che non era mai stato abbassato.\n    ⛔⛔ IL TAGLIO DEV\'ESSERE NETTO, MA DI DUE FILTRI, NON TRE.\n       Con un taglio dolce a 200 Hz la voce non scendeva sotto i -18 dB\n       per quanto si girasse la manopola, e sembrava il limite del\n       metodo: NON LO ERA. Era il ramo del grave — che per definizione\n       non viene toccato — che si portava dietro il corpo della voce\n       (200-500 Hz).\n       Ma stringendo TROPPO si rompe il suono: due rami filtrati, quando\n       si rimettono insieme, tornano dritti solo se i filtri sono in\n       numero PARI. MISURATO col rumore, senza togliere niente (k=0),\n       guardando quanto la catena da sola storpia il suono:\n           un filtro    -30 dB a 120 Hz\n           DUE filtri     0,0 dB dappertutto   <- questa\n           tre filtri   -27 dB a 120 Hz\n       Con tre filtri c\'era un buco di 27 dB in mezzo al basso. Si\n       sentiva, ed e\' il motivo per cui "la qualita\' non era delle\n       migliori".\n\n    ⭐ TERZA BANDA: sopra i 12 kHz il centro NON si tocca. Li\' la voce\n       non c\'e\' quasi (solo le esse), mentre ci stanno piatti, riverbero\n       e l\'aria del brano: togliendo anche quelle il suono si spegneva.\n       MISURATO: aria (9-16 kHz) da -10,4 a -4,1 dB, voce identica.\n       Anche questo taglio somma dritto (0,0 dB, verificato col rumore).\n\n    ⚠️ E\' una catena con piu\' rami: la puo\' eseguire ffmpeg (che scrive\n       un file), NON un player. MPV i filtri a piu\' ingressi non li\n       applica — e comunque non applica NESSUN filtro messo a brano\n       gia\' partito (vedi `set_voce`).\n\n    ⚠️ QUELLO CHE QUESTO METODO NON SA FARE: toglie solo la parte di\n       voce che sta ESATTAMENTE al centro. Riverbero, raddoppi e cori\n       allargati stanno ai lati e restano — la voce si sente ancora,\n       piu\' lontana. Per farla sparire davvero servirebbe un modello\n       che la separa, che e\' un altro mestiere.\n\n    ⚠️ CHI SUONA IN MONO: togliendo il centro le due casse diventano\n       una il negativo dell\'altra, e sommandole si annullano. Su un\n       impianto mono la base sparirebbe quasi del tutto. E\' cosi\' per\n       qualunque sistema che toglie la voce in questo modo.\n    """\n    try:\n        q = max(0, min(100, int(quanto)))\n    except Exception:\n        q = 0\n    if q <= 0:\n        return \'\'\n    # ⭐ L\'INTERRUTTORE "COME K5": la formula nuda, a banda intera.\n    #    Chiesto esplicitamente. E\' PEGGIO (la base scende di 25,8 dB\n    #    invece di 5,0, misurato su 5 brani) e si porta via cassa e basso:\n    #    e\' un passo indietro voluto, per avere lo stesso comportamento di\n    #    K5. Si spegne rimettendo `devoc_k5` a 0.\n    try:\n        from .database import Database as _DbK5\n        if str(_DbK5.get_config(\'devoc_k5\', \'0\')).strip() in (\'1\', \'si\', \'True\'):\n            return self._k5_puro(q)\n    except Exception:\n        pass\n    # quanto centro si porta via: 1 = tutto\n    k = q / 100.0\n    # uscita_sinistra = L - k*(L+R)/2, e viceversa. `pan` sa sottrarre,\n    # `stereotools` no: il suo mlev non arriva a zero (ffmpeg lo rifiuta).\n    a = 1.0 - k / 2.0\n    b = -k / 2.0\n    # ⚠️ con getattr, non self.TAGLIO_GRAVE secco: le patch a caldo\n    #    rimpiazzano le funzioni ma non i valori scritti nella classe,\n    #    e senza il ripiego qui il tasto morirebbe con un AttributeError\n    t = getattr(self, \'TAGLIO_GRAVE\', 120)\n    alto = getattr(self, \'TAGLIO_ARIA\', 12000)\n    volte = getattr(self, \'RIPIDITA\', 2)\n    giu = ",".join(["lowpass=f=%d:poles=2" % t] * volte)\n    su = ",".join(["highpass=f=%d:poles=2" % t] * volte)\n    giu2 = ",".join(["lowpass=f=%d:poles=2" % alto] * volte)\n    su2 = ",".join(["highpass=f=%d:poles=2" % alto] * volte)\n    return ("asplit=3[g][m][s];"\n            "[g]%s[grave];"\n            "[s]%s[aria];"\n            "[m]%s,%s,"\n            "pan=stereo|c0=%.4f*c0%+.4f*c1|c1=%.4f*c1%+.4f*c0[mezzo];"\n            "[grave][mezzo][aria]amix=inputs=3:normalize=0"\n            % (giu, su2, su, giu2, a, b, a, b))\n\n# =================================================================\n#  ABBASSA LA VOCE\n# =================================================================\n#  La voce sta quasi sempre al CENTRO del mix: uguale nelle due casse.\n#  Abbassando quello che le due casse hanno in comune, la voce scende.\n#  Non si separa niente, non c\'e\' nessun modello, non nasce nessun file\n#  da consegnare: solo una copia di servizio dell\'audio.\n#\n#  ⛔ PERCHE\' NON UN FILTRO DENTRO IL PLAYER, che sarebbe la strada\n#     comoda: MISURATO. MPV accetta la riga \'af\' su un brano gia\'\n#     partito, la RILEGGE pure identica, e NON la applica — il suono\n#     non cambia di un decibel. Succede anche con un banalissimo\n#     \'volume=0.1\', quindi non e\' colpa del filtro: MPV non ricostruisce\n#     la catena su un file gia\' avviato, e il filtro morde solo se c\'e\'\n#     gia\' quando il file parte. BASS un filtro del genere non ce l\'ha\n#     proprio, e metterci codice Python dentro il thread audio aveva\n#     bloccato il programma.\n#     Percio\': si prepara l\'audio PRIMA e si riparte dallo stesso punto.\n\n\ndef _k5_puro(self, quanto: int):\n    """La cancellazione del centro NUDA, a banda intera: il modo di K5.\n\n    ⚠️ LA FORMULA ESATTA DI K5 NON E\' STATA LETTA, e non si puo\': sta\n       compilata dentro un callback DSP della libreria BASS (verificato\n       nell\'eseguibile — `DeVocal` compare una volta sola, accanto a\n       `BASS_FX`, e di leggibile non c\'e\' altro). Questa e\' la formula\n       CLASSICA, quella che si ottiene con un interruttore e nessun\n       parametro, che e\' cio\' che K5 espone. E\' la cosa piu\' vicina che si\n       possa scrivere onestamente, non una copia certificata.\n\n    ⛔ Toglie il centro a TUTTE le frequenze, quindi si porta via anche\n       cassa, rullante e basso, e il suono collassa verso il mono.\n       MISURATO su 5 brani: la base scende di 25,8 dB contro i 5,0 della\n       versione a tre bande. E\' un passo indietro voluto, chiesto per\n       avere lo stesso identico comportamento di K5.\n\n    Si accende con `devoc_k5` = 1 nelle impostazioni; senza, resta la\n    versione a tre bande, che e\' migliore.\n    """\n    k = max(0.0, min(1.0, quanto / 200.0))     # a 100 -> 0,5\n    return (\'pan=stereo|c0=%.4f*c0-%.4f*c1|c1=%.4f*c1-%.4f*c0\'\n            % (1.0 - k, k, 1.0 - k, k))\n\n\ndef _voce_mappa(self):\n    """Da quale file viene ogni copia. Senza, premendo due volte si\n    abbasserebbe la voce di una voce gia\' abbassata."""\n    return self.__dict__.setdefault(\'_voce_da\', {})\n\n\ndef _voce_log(self, testo):\n    """Una riga nel registro. ⚠️ Serve davvero: senza, premendo il tasto\n    e non sentendo niente non c\'e\' modo di sapere dove si e\' fermato."""\n    try:\n        import datetime as _dt\n        _d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or\n                          os.path.expanduser(\'~\'), \'KaraDom\')\n        os.makedirs(_d, exist_ok=True)\n        with open(os.path.join(_d, \'patch033.log\'), \'a\', encoding=\'utf-8\') as _f:\n            _f.write(\'%s  %s\\n\' % (\n                _dt.datetime.now().strftime(\'%Y-%m-%d %H:%M:%S\'), testo))\n    except Exception:\n        pass\n\n\ndef _voce_ffmpeg(self):\n    """Dove sta ffmpeg.\n\n    ⚠️ NON si scrive \'ffmpeg\' e basta: sui PC dei clienti non e\' nel\n    PATH di sistema, sta nella cartella dipendenze spedita col\n    programma. Chiamandolo nudo falliva in silenzio.\n    """\n    try:\n        from .yt2mp3 import _dep as _dip\n        f = _dip(\'ffmpeg.exe\' if os.name == \'nt\' else \'ffmpeg\')\n        if os.path.exists(f):\n            return f\n    except Exception:\n        pass\n    try:\n        from .normalizzazione import _get_ffmpeg_path\n        return _get_ffmpeg_path()\n    except Exception:\n        pass\n    return \'ffmpeg\'\n\n\ndef _voce_chiave(self, riferimento):\n    """Come si riconosce un brano, comunque ci si arrivi.\n\n    ⛔ NON il percorso del file. Lo STESSO video di YouTube arriva a volte\n       come link, a volte come flusso diretto, a volte come mp4 gia\'\n       scaricato, e ogni volta l\'audio staccato prende un nome diverso\n       (yt_39f5..., yt_8297..., _v3Bwv4xu3Q_...). Con la chiave sul\n       percorso, il brano preparato PRIMA non veniva piu\' ritrovato al\n       momento di suonarlo, e tutto il lavoro fatto in anticipo era\n       buttato: il tasto premuto prima sembrava non funzionare.\n       Per YouTube la chiave e\' il codice del video, che non cambia mai.\n    """\n    r = str(riferimento or \'\')\n    if not r:\n        return \'\'\n    # ⛔ il codice del video si cerca QUI, senza importare niente: con un\n    #    `from . import youtube_local` dentro un `try`, se l\'import fallisce\n    #    l\'errore sparisce e la chiave diventa un percorso senza senso —\n    #    e il brano preparato prima non si ritrova piu\'. Visto succedere.\n    import re as _re\n    m = _re.search(r\'(?:v=|youtu\\.be/|/embed/|/shorts/)([A-Za-z0-9_-]{11})\', r)\n    if m:\n        return \'yt:\' + m.group(1)\n    nudo = os.path.splitext(os.path.basename(r))[0]\n    if _re.fullmatch(r\'[A-Za-z0-9_-]{11}\', nudo):\n        return \'yt:\' + nudo          # l\'mp4 in cache si chiama col codice\n    try:\n        return os.path.abspath(r).lower()\n    except Exception:\n        return r.lower()\n\n\ndef _voce_audio_memo(self):\n    """Per ogni brano, l\'audio gia\' staccato dal video.\n\n    ⛔ SERVE: quando il brano viene caricato per suonare,\n       `_video_audio_extracted` viene AZZERATO. Cosi\' il lavoro fatto in\n       anticipo — video scaricato e audio staccato — si perdeva, e alla\n       partenza il programma ricominciava da capo, stavolta dal flusso\n       diretto di YouTube: cioe\' riscaricando tutto il brano. Intanto la\n       base suonava con la voce originale.\n    """\n    return self.__dict__.setdefault(\'_voce_audio_gia_fatto\', {})\n\n\ndef _voce_gia_pronto(self):\n    """Il brano con la voce gia\' abbassata, se l\'abbiamo gia\' fatto.\n\n    ⭐ QUESTA E\' LA SCORCIATOIA CHE CONTA: il file preparato e\' un wav\n       intero del brano, non un pezzo. Se c\'e\', alla partenza NON serve\n       piu\' niente di quello che sta in mezzo — non il video, non l\'audio\n       staccato, non il ricordo di dove stava. Si carica e basta.\n    ⛔ Prima passavo per tutta la catena (video -> audio staccato ->\n       copia), e bastava che uno solo di quegli anelli non si ritrovasse\n       perche\' il lavoro gia\' fatto andasse perso e la voce si sentisse\n       lo stesso. E\' successo cinque volte di fila, ogni volta per un\n       anello diverso.\n    """\n    q = getattr(self, \'voce_giu\', 0)\n    if q <= 0:\n        return None\n    import hashlib\n    import tempfile\n    for rif in (getattr(self, \'_voce_brano_scelto\', None),\n                getattr(self, \'current_file\', None)):\n        if not rif:\n            continue\n        chiave = self._voce_chiave(rif)\n        nome = hashlib.sha1(\n            (\'%s|%d\' % (chiave, q)).encode(\'utf-8\', \'replace\')\n        ).hexdigest()[:16]\n        p = os.path.join(tempfile.gettempdir(), \'kd_voce_%s.wav\' % nome)\n        try:\n            if os.path.exists(p) and os.path.getsize(p) > 1000:\n                # ⭐ Se il brano si riconosce dal CODICE DEL VIDEO, quello\n                #    non mente: non serve nessun\'altra prova.\n                # ⛔ La durata come controllo era troppo severa: fra video\n                #    e audio estratto ballano dei secondi (visto: 284\n                #    contro 278), e buttava via il lavoro GIUSTO. Si usa\n                #    solo quando il brano si riconosce per il percorso,\n                #    che e\' l\'aggancio debole.\n                if chiave.startswith(\'yt:\') or self._voce_stessa_durata(p):\n                    return p\n        except Exception:\n            pass\n    return None\n\n\ndef _voce_stessa_durata(self, preparato):\n    """Il file pronto e\' davvero di QUESTO brano?\n\n    ⛔ SERVE: caricando un secondo link senza ripassare dal tasto, il\n       "brano scelto" restava quello di prima e partiva l\'audio del brano\n       SBAGLIATO. Il nome non basta a garantire niente — la durata si\'.\n       Se non combacia, il file non si usa e si rifa\'.\n\n    A brano fermo la durata non si sa ancora: li\' non c\'e\' niente da\n    sbagliare (non sta suonando nulla) e si lascia passare.\n    """\n    try:\n        attesa = 0\n        for dove in (getattr(self.engine, \'total_duration_ms\', 0),\n                     getattr(self.monitor, \'total_duration_ms\', 0)):\n            if dove and dove > 1000:\n                attesa = dove\n                break\n        if not attesa:\n            return True\n        # wav 44100 Hz, 16 bit, 2 canali = 4 byte per campione\n        secondi = (os.path.getsize(preparato) - 44) / (44100.0 * 4)\n        differenza = abs(secondi * 1000 - attesa)\n        # ⚠️ larga: fra la durata del video e quella dell\'audio estratto\n        #    ballano dei secondi, e stretta buttava via il file giusto.\n        #    Serve solo a non scambiare un brano per un altro.\n        if differenza > max(15000, attesa * 0.10):\n            self._voce_log(\'il brano pronto e- di un ALTRO pezzo \'\n                           \'(dura %.0f s, questo %.0f s): non lo uso\'\n                           % (secondi, attesa / 1000.0))\n            return False\n        return True\n    except Exception:\n        return True\n\n\ndef _voce_pulisci_temporanei(self):\n    """Butta l\'audio di servizio rimasto dai brani gia\' fatti.\n\n    Sono due famiglie, tutte e due nella cartella temporanea:\n      kd_voce_*.wav          il brano con la voce abbassata (~48 MB)\n      *_extracted_audio.wav  l\'audio staccato dal video     (~78 MB)\n\n    ⚠️ Quello che sta ancora suonando NON si tocca: Windows non lascia\n       cancellare un file aperto, quindi al massimo il tentativo fallisce\n       e si tira dritto — ma si salta anche a mano, per non provarci.\n    ⚠️ Costo: rifacendo lo stesso brano si ripaga il minuto di\n       preparazione, perche\' la copia non c\'e\' piu\'.\n    """\n    import glob\n    import tempfile\n    vivi = set()\n    for x in (getattr(self, \'_video_audio_extracted\', None),\n              getattr(getattr(self, \'bass_engine\', None), \'current_file\', None)):\n        if x:\n            try:\n                vivi.add(os.path.abspath(x).lower())\n            except Exception:\n                pass\n    # ⛔⛔ SI SALVA ANCHE CIO\' CHE E\' STATO PREPARATO E NON HA ANCORA\n    #     SUONATO. Prima si proteggeva solo il file in quell\'istante sotto\n    #     la puntina: cosi\' la pulizia buttava l\'audio staccato un attimo\n    #     prima per il brano che stava per partire. Al play il programma lo\n    #     cercava, lo trovava in memoria ma sul disco non c\'era piu\'\n    #     ("trovato=... c-e-=False"), e lo riestraeva: SEI SECONDI in cui\n    #     si sente l\'audio ORIGINALE, con la voce. E\' il "salto" all\'avvio.\n    try:\n        for v in (self._voce_audio_memo() or {}).values():\n            if v:\n                vivi.add(os.path.abspath(v).lower())\n    except Exception:\n        pass\n    # ⭐ e le basi pulite che hanno il TESTO AL VOLO pronto: e\' da loro\n    #    che parte il brano col testo (vedi `_testo_scambio`)\n    try:\n        for p in (self.__dict__.get(\'_testo_pronto\') or {}).values():\n            if p and p.get(\'base\'):\n                vivi.add(os.path.abspath(p[\'base\']).lower())\n    except Exception:\n        pass\n    cartella = tempfile.gettempdir()\n    tolti = byte = 0\n    for schema in (\'kd_voce_*\', \'*_extracted_audio.wav\'):\n        for p in glob.glob(os.path.join(cartella, schema)):\n            try:\n                if os.path.abspath(p).lower() in vivi:\n                    continue\n                q = os.path.getsize(p)\n                os.remove(p)\n                tolti += 1\n                byte += q\n            except Exception:\n                pass          # in uso: lo prendera\' il giro dopo\n    if tolti:\n        self._voce_log(\'pulizia: tolti %d file di servizio (%.0f MB)\'\n                       % (tolti, byte / 1048576.0))\n    try:\n        self._voce_audio_memo().clear()\n    except Exception:\n        pass\n\n\ndef _voce_fine_brano(self):\n    """Il brano e\' arrivato in fondo: il tasto della voce si spegne.\n\n    ⛔ SOLO QUI, non in `stop`: da `stop` passano anche l\'interruzione, il\n       fade out e il cambio brano, e spegnere li\' vorrebbe dire disarmare\n       a ogni fermata. La richiesta e\' un\'altra: **a brano finito**.\n    ⚠️ Si torna al filo della grafica con `after`: questi tre punti girano\n       nel filo che sorveglia la riproduzione, e da li\' non si toccano i\n       bottoni.\n    """\n    def _spegni():\n        try:\n            self.voce_giu = 0\n            self._voce_brano_scelto = None\n            lib = getattr(self, \'libreria\', None)\n            if lib is not None:\n                lib._voce_disarma()\n            self._voce_log(\'brano finito: tasto della voce rimesso a posto\')\n        except Exception:\n            pass\n    try:\n        self.master.after(0, _spegni)\n    except Exception:\n        _spegni()\n\n\ndef _voce_originale(self, percorso):\n    """Dalla copia si risale sempre al file di partenza."""\n    try:\n        return self._voce_mappa().get(percorso, percorso)\n    except Exception:\n        return percorso\n\n\ndef _voce_prepara(self, sorgente, quanto, chiave=None):\n    """La copia dell\'audio con la voce gia\' abbassata.\n\n    La fa una volta sola: dopo resta nella cartella temporanea e si\n    riusa, cosi\' accendere e spegnere e\' immediato.\n    MISURATO: 0,3 secondi per un brano di 4 minuti e 44.\n    """\n    filtro = self._filtro_voce(quanto)\n    if not filtro or not sorgente or not os.path.exists(sorgente):\n        return None\n    # ⛔⛔ PROVATO E RITIRATO (11-09-2026, 00:55): "all\'inizio si e\' sentita\n    #    la MUSICA DOPPIA".\n    #\n    #    L\'idea era: se il modello c\'e\', il ripiego non e\' il filtro ma\n    #    l\'ORIGINALE (`filtro = None`), cosi\' i primi secondi — quelli che\n    #    il modello non fa in tempo a rifare — suonano perfetti invece che\n    #    svuotati. Sulla carta regge: all\'inizio di un brano c\'e\' quasi\n    #    sempre l\'introduzione strumentale.\n    #\n    #    Ma cosi\' il file di lavoro nasce IDENTICO all\'originale, e il\n    #    programma non li distingue piu\': si e\' ritrovato a suonarli tutti\n    #    e due insieme, l\'audio del video e quello di BASS. Da qui la\n    #    musica doppia.\n    #\n    #    Se un domani si riprova, prima va sistemato CHI SCEGLIE il file da\n    #    suonare (`_voce_scegli` / `_activate_video_mpv_audio`), che oggi\n    #    si regola sul fatto che i due file siano diversi.\n    import hashlib\n    import subprocess\n    import tempfile\n    # ⛔ il nome NON si ricava dal percorso del file audio: lo stesso\n    #    brano cambia percorso a seconda di come ci si arriva, e il\n    #    lavoro fatto prima non si ritroverebbe piu\' (vedi _voce_chiave)\n    # ⛔⛔ NEL NOME CI VANNO ANCHE IL MODO E I DECIBEL, o cambiare le\n    #    impostazioni NON SERVE A NIENTE. Prima il nome era solo\n    #    (brano | livello): cambiando modello da Opzioni il nome restava\n    #    identico, il file gia\' lavorato veniva ritrovato e riusato, e si\n    #    risentiva esattamente la stessa cosa. Ore perse a credere che le\n    #    impostazioni fossero ignorate — venivano lette, era il file a non\n    #    cambiare mai. Cosi\' invece ogni combinazione ha il suo file, e\n    #    tornando su una gia\' provata la si riascolta subito.\n    try:\n        from . import devocalizza as _dv\n        firma = \'%s|%.4f\' % (_dv.modo_scelto(), _dv.quanto_abbassare())\n    except Exception:\n        firma = \'?\'\n    nome = hashlib.sha1((\'%s|%d|%s\' % (chiave or sorgente, quanto, firma))\n                        .encode(\'utf-8\', \'replace\')).hexdigest()[:16]\n    fuori = os.path.join(tempfile.gettempdir(), \'kd_voce_%s.wav\' % nome)\n    self._voce_log(\'preparo: modo/dB = %s  ->  %s\'\n                   % (firma, os.path.basename(fuori)))\n    if not (os.path.exists(fuori) and os.path.getsize(fuori) > 1000):\n        try:\n            # ⚠️ -filter_complex, non -af: la catena ha piu\' rami (il\n            #    grave che se ne va per conto suo e torna indietro)\n            # ⚠️ 44100 e 16 bit NON sono a caso: e\' la frequenza a cui\n            #    lavora il modello che poi riscrive questo stesso file\n            #    davanti alla puntina. Con due frequenze diverse i byte\n            #    finirebbero nel punto sbagliato del brano.\n            comando = [self._voce_ffmpeg(), \'-y\', \'-v\', \'error\',\n                       \'-i\', sorgente]\n            if filtro:\n                comando += [\'-filter_complex\', filtro]\n            comando += [\'-acodec\', \'pcm_s16le\', \'-ar\', \'44100\',\n                        \'-ac\', \'2\', fuori]\n            subprocess.run(\n                comando, capture_output=True, timeout=180,\n                creationflags=0x08000000 if os.name == \'nt\' else 0)\n        except Exception as e:\n            self._voce_log(\'voce: ffmpeg non ce l-ha fatta: %s\' % e)\n            return None\n    if not (os.path.exists(fuori) and os.path.getsize(fuori) > 1000):\n        self._voce_log(\'voce: ffmpeg non ha scritto niente\')\n        return None\n    try:\n        self._voce_mappa()[fuori] = sorgente\n    except Exception:\n        pass\n    return fuori\n\n\ndef _voce_scegli(self, sorgente):\n    """Il file da dare al motore audio: l\'originale, oppure quello con\n    la voce giu\' se il tasto e\' premuto.\n\n    Lo chiamano anche gli altri punti che caricano l\'audio di un video,\n    cosi\' la scelta vale sempre, anche cambiando brano.\n    """\n    try:\n        if not getattr(self, \'voce_giu\', 0):\n            return sorgente\n        # ⛔ se e\' GIA\' il brano preparato, si suona com\'e\': rimetterlo in\n        #    lavorazione vorrebbe dire abbassare la voce di una voce gia\'\n        #    abbassata, e per giunta rifare tutto da capo\n        if os.path.basename(str(sorgente)).startswith(\'kd_voce_\'):\n            return sorgente\n        # ⚠️ la chiave si prende dal BRANO (link o file scelto), non\n        #    dall\'audio staccato: e\' cosi\' che si ritrova il lavoro fatto\n        #    in anticipo, quando il brano era arrivato per un\'altra strada\n        chiave = self._voce_chiave(\n            getattr(self, \'_voce_brano_scelto\', None)\n            or getattr(self, \'current_file\', None) or sorgente)\n        pronto = self._voce_prepara(self._voce_originale(sorgente),\n                                    self.voce_giu, chiave)\n        if not pronto:\n            self._voce_log(\'voce: NON preparata, suono l-originale\')\n            return sorgente\n        return pronto\n    except Exception as e:\n        # ⛔ QUI NON SI STA ZITTI: un `except` muto che rimetteva il file\n        #    originale faceva sembrare che il tasto non funzionasse,\n        #    senza una riga da nessuna parte.\n        self._voce_log(\'voce: scelta del file fallita - %s: %s\'\n                       % (type(e).__name__, e))\n        return sorgente\n\n\ndef _voce_chi_suona(self):\n    """Quale motore sta suonando e da quale file.\n    (None, None) = il suono esce ancora dal video."""\n    try:\n        if getattr(self, \'is_bass_audio\', False) and self.bass_engine:\n            return \'bass\', getattr(self.bass_engine, \'current_file\', None)\n        if getattr(self, \'is_mpv_audio\', False) and self.mpv_player:\n            return \'mpv\', getattr(self, \'_video_audio_extracted\', None)\n    except Exception:\n        pass\n    return None, None\n\n\ndef _voce_scambia(self, motore, file_nuovo):\n    """Rimette in moto il brano con l\'audio giusto, dallo stesso punto."""\n    if not file_nuovo or not os.path.exists(file_nuovo):\n        self._voce_log(\'voce: il file da suonare non c-e-\')\n        return False\n    q = getattr(self, \'voce_giu\', 0)\n    try:\n        if motore == \'bass\':\n            be = self.bass_engine\n            if be is None:\n                return False\n            pos = 0\n            try:\n                pos = int(be.get_position_ms() or 0)\n            except Exception:\n                pass\n            if not be.load(file_nuovo):\n                self._voce_log(\'voce a %d%%: NON fatto - BASS non ha aperto il file\' % q)\n                return False\n            be.play()\n            be.seek_ms(pos)\n            try:\n                be.set_volume(max(0.0, min(1.0, self._user_volume)))   # 0..1: NON 0..127\n            except Exception:\n                pass\n            try:\n                be.set_pitch(self.current_pitch)\n                be.set_speed(max(0.25, min(4.0, self.current_speed)))\n            except Exception:\n                pass\n            self._voce_log(\'voce a %d%%: FATTO (BASS, ripreso da %d ms)\' % (q, pos))\n            if q > 0:\n                self._voce_avvia_modello(file_nuovo,\n                                         self._voce_originale(file_nuovo), pos)\n            return True\n\n        if motore == \'mpv\' and self.mpv_player:\n            pos = 0.0\n            try:\n                pos = float(self.mpv_player.time_pos or 0.0)\n            except Exception:\n                pass\n            # ⚠️ il punto di partenza si mette PRIMA di caricare: cosi\'\n            #    il brano riprende dov\'era senza un salto sentibile\n            try:\n                self.mpv_player[\'start\'] = \'%.3f\' % max(0.0, pos)\n            except Exception:\n                pass\n            self.mpv_player.play(str(file_nuovo).replace(\'\\\\\', \'/\'))\n            try:\n                self._apply_mpv_volume()\n                self._apply_rate()\n            except Exception:\n                pass\n            self._voce_log(\'voce a %d%%: FATTO (MPV, ripreso da %.1f s)\' % (q, pos))\n            if q > 0:\n                self._voce_avvia_modello(file_nuovo,\n                                         self._voce_originale(file_nuovo),\n                                         int(pos * 1000))\n            return True\n    except Exception as e:\n        self._voce_log(\'voce a %d%%: NON fatto - %s: %s\' % (q, type(e).__name__, e))\n    return False\n\n# -----------------------------------------------------------------\n#  LA VOCE SPARISCE MENTRE IL BRANO SUONA\n# -----------------------------------------------------------------\n#  Il file con la voce abbassata (metodo del centro) e\' gia\' li\' e suona.\n#  Da qui in avanti un operaio in sottofondo separa la voce col modello e\n#  RISCRIVE I BYTE PIU\' AVANTI, quelli che la puntina non ha ancora\n#  raggiunto. BASS rilegge dal disco mentre suona — VERIFICATO, non\n#  supposto — quindi la voce se ne va da sola, senza ricaricare niente e\n#  senza un salto.\n#\n#  MISURATO su questa macchina, SOLO PROCESSORE (il cliente la scheda\n#  video non ce l\'ha):\n#     primo pezzo pronto in 2,2 s con 4 thread, modello ancora da aprire\n#     ogni pezzo copre 5,9 s di musica e si prepara in 2,0-2,7 s\n#  Cioe\' l\'operaio va piu\' veloce della musica e le resta davanti.\n#\n#  ⚠️ Se il computer e\' troppo lento e la puntina lo raggiunge, non\n#     succede niente di brutto: quel tratto resta com\'e\' (voce abbassata\n#     col metodo del centro) e l\'operaio salta avanti.\n\n\ndef set_voce(self, quanto: int, brano=None, riga=False):\n    """Abbassa il volume della VOCE del brano.\n\n    quanto: 0 = voce com\'e\', 100 = voce giu\' al massimo.\n    brano:  quale brano preparare quando la base e\' FERMA.\n    riga:   lo chiede il tasto di UNA RIGA della scaletta: si prepara\n            quel brano e basta (vedi sotto).\n\n    ⛔ `brano` SERVE: a base ferma `self.current_file` e\' vuoto — il\n       programma sa quale file suonare solo quando si preme play. Senza\n       questo, premendo il tasto prima non si preparava niente e nel\n       registro restava solo "nessun brano scelto, aspetto".\n       Chi preme il tasto (la barra della libreria) sa qual e\' il brano\n       selezionato, e ce lo passa.\n    """\n    # ⛔⛔ IL TASTO DI UNA RIGA NON TOCCA CIO\' CHE SUONA. Prima passava di\n    #     qui come il tasto in alto: armando la riga B mentre suonava A,\n    #     il comando finiva su A (e\' "cio\' che suona"), il livello di\n    #     tutto il programma andava a 100 — cosi\' partivano senza voce\n    #     anche le righe NON armate — e B non veniva preparato affatto.\n    #     Adesso si prepara B e basta. Il livello del brano lo decide la\n    #     sua riga al momento del play (`_voce_decidi_per` in libreria).\n    if riga and brano:\n        try:\n            q = max(1, min(100, int(quanto)))\n        except Exception:\n            q = 100\n        self._voce_log(\'riga: preparo %s a %d%% (cio- che suona resta com-e-)\'\n                       % (str(brano)[-70:], q))\n        self._voce_prepara_in_anticipo(brano_riga=brano, quanto=q)\n        return True\n    if brano:\n        self._voce_brano_scelto = brano\n    try:\n        self.voce_giu = max(0, min(100, int(quanto)))\n    except Exception:\n        self.voce_giu = 0\n    q = self.voce_giu\n    # ⚠️ Il turno cambia SOLO se cambia davvero qualcosa (il livello o il\n    #    brano): l\'operaio che sta lavorando si ferma quando il turno non\n    #    e\' piu\' il suo.\n    # ⛔ NON a ogni chiamata: `play` richiama questa funzione da solo poco\n    #    dopo la partenza, e bumpare sempre ammazzava proprio l\'operaio\n    #    che aveva gia\' preparato il brano mentre era fermo — cioe\' il\n    #    lavoro che serve, buttato un istante prima di servire.\n    # ⛔ IL NOME NON E\' A CASO: qui c\'era `self._voce_chiave`, che e\' anche\n    #    il nome del METODO che riconosce il brano. La tupla finiva\n    #    sull\'oggetto e copriva il metodo: chiamarlo dava\n    #    "\'tuple\' object is not callable", l\'errore veniva ingoiato, e il\n    #    tasto smetteva di funzionare sia prima sia dopo l\'avvio.\n    # ⛔ IL SEGNO E\' LA CHIAVE DEL BRANO, NON `current_file`: a base ferma\n    #    `current_file` e\' VUOTO e si riempie quando si preme play. Cosi\'\n    #    lo stesso brano sembrava diventarne un altro proprio all\'avvio,\n    #    il turno cambiava, e l\'operaio che aveva gia\' preparato mezzo\n    #    brano veniva ammazzato un istante prima di servire. VISTO NEL\n    #    REGISTRO: "primo pezzo scritto" e due secondi dopo "fermato, e\'\n    #    arrivato un altro comando".\n    segno = (self._voce_chiave(getattr(self, \'_voce_brano_scelto\', None)\n                               or getattr(self, \'current_file\', None)), q)\n    if segno != getattr(self, \'_voce_turno_segno\', None):\n        self._voce_turno_segno = segno\n        self._voce_turno = getattr(self, \'_voce_turno\', 0) + 1\n\n    # ⭐ SI PUO\' PREMERE A BRANO FERMO: la scelta si annota e parte\n    #    insieme al brano (ci pensa `play`). Chi prepara la serata\n    #    decide prima, non a musica gia\' partita.\n    if not self.is_playing:\n        # ⭐ NON ci si limita ad annotare: si COMINCIA A PREPARARE adesso,\n        #    a musica ferma. E\' il caso importante — il tasto si preme\n        #    prima proprio per avere il brano gia\' pulito quando parte.\n        self._voce_log(\'voce a %d%%: base ferma, comincio a preparare adesso\' % q)\n        if q > 0:\n            self._voce_prepara_in_anticipo()\n        return True\n\n    motore, sorgente = self._voce_chi_suona()\n    if motore is None or not sorgente:\n        # il suono esce ancora dal video: prima si stacca l\'audio dal\n        # video (gira in un thread a parte), poi ci pensa la coda di\n        # _finish_activate_video_mpv, che passa da _voce_scegli\n        if getattr(self.engine, \'is_video\', False) and self.engine.vlc_player:\n            self._voce_log(\'voce a %d%%: stacco l-audio dal video, un istante\' % q)\n            # ⭐ zitto SUBITO: un secondo di silenzio al posto di un\n            #    secondo di brano originale con la voce (vedi\n            #    `_voce_muta_video`)\n            self._voce_muta_video(True)\n            try:\n                self._activate_video_mpv_audio()\n                return True\n            except Exception as e:\n                self._voce_log(\'voce a %d%%: NON fatto - %s\' % (q, e))\n                return False\n        self._voce_log(\'voce a %d%%: NON fatto - non so quale file sta suonando \'\n                       \'[bass=%s mpv=%s video=%s]\'\n                       % (q, getattr(self, \'is_bass_audio\', \'?\'),\n                          getattr(self, \'is_mpv_audio\', \'?\'),\n                          getattr(self.engine, \'is_video\', \'?\')))\n        return False\n\n    sorgente = self._voce_originale(sorgente)\n    if q <= 0:\n        return self._voce_scambia(motore, sorgente)\n\n    # ⚠️ la preparazione va in un thread a parte: sono pochi decimi, ma\n    #    la finestra non deve fermarsi nemmeno per quelli\n    def _lavora():\n        # ⛔⛔ LA CHIAVE E\' QUELLA DI CIO\' CHE SUONA, NON DELLA RIGA SCELTA.\n        #     Prima si prendeva `_voce_brano_scelto`: armando il brano B\n        #     mentre suonava A, si preparava l\'audio di A col NOME di B.\n        #     Il file restava in memoria, e quando poi partiva B si\n        #     sentiva A — il brano sbagliato, davanti al pubblico.\n        #     L\'audio che suona si riconosce dalla memoria degli stacchi\n        #     (chiave -> file): e\' la stessa chiave della preparazione in\n        #     anticipo, quindi un brano gia\' pronto si ritrova lo stesso.\n        chiave = self._voce_chiave_di_cio_che_suona(sorgente)\n        pronto = self._voce_prepara(sorgente, q, chiave)\n        if not pronto:\n            self._voce_log(\'voce a %d%%: NON fatto - audio non preparato\' % q)\n            return\n        # ⛔ SE STA GIA\' SUONANDO PROPRIO QUEL FILE non si ricarica: e\' il\n        #    caso della base col testo al volo, che parte GIA\' pulita.\n        #    Ricaricarla dallo stesso punto e\' il "saltino" all\'avvio.\n        try:\n            _gia = getattr(getattr(self, \'bass_engine\', None), \'current_file\', None)\n            if motore == \'bass\' and _gia and (os.path.abspath(str(_gia)).lower()\n                                              == os.path.abspath(str(pronto)).lower()):\n                self._voce_log(\'voce a %d%%: suona gia- la base pulita, non la \'\n                               \'ricarico\' % q)\n                self._voce_avvia_modello(pronto, sorgente,\n                                         max(0, self._voce_dove_siamo_ms()))\n                return\n        except Exception:\n            pass\n        try:\n            self.master.after(0, lambda: self._voce_scambia(motore, pronto))\n        except Exception as e:\n            self._voce_log(\'voce: non torno alla finestra: %s\' % e)\n\n    threading.Thread(target=_lavora, daemon=True).start()\n    return True\n\n\ndef _voce_prepara_in_anticipo(self, brano_riga=None, quanto=None):\n    """Il brano deve PARTIRE gia\' pulito.\n\n    ⛔ QUESTO E\' IL CASO IMPORTANTE, non l\'altro: il tasto si preme PRIMA\n       di mandare la base. Dal vivo una base non si aggiusta mentre suona\n       — se il cantante ha gia\' attaccato e sotto si sente ancora la voce\n       originale, quel brano e\' da buttare.\n       Percio\' la preparazione comincia adesso, a musica ferma, e quando\n       si preme play il lavoro e\' gia\' avanti.\n\n    `brano_riga` / `quanto`: lo chiede UNA RIGA della scaletta. Si prepara\n    quel brano e basta, anche con un altro che suona, senza toccare ne\'\n    il brano che suona ne\' il livello della voce di tutto il programma.\n    """\n    riga = bool(brano_riga)\n    q = quanto if riga else getattr(self, \'voce_giu\', 0)\n    try:\n        q = int(q or 0)\n    except Exception:\n        q = 0\n    if q <= 0:\n        return\n    # ⛔ PRIMA quello che ci ha passato chi ha premuto il tasto: a base\n    #    ferma `current_file` e\' VUOTO (lo riempie `play`), e senza questo\n    #    non si preparava mai niente.\n    brano = brano_riga or getattr(self, \'_voce_brano_scelto\', None) or getattr(\n        self, \'current_file\', None)\n    if not brano:\n        self._voce_log(\'in anticipo: nessun brano scelto, aspetto\')\n        return\n    e_link = str(brano).lower().startswith((\'http://\', \'https://\'))\n    if not e_link and not os.path.exists(brano):\n        self._voce_log(\'in anticipo: il file non c\\\'e\\\' (%s)\' % brano[:80])\n        # la riga torna viola, invece di restare arancione per sempre\n        self._voce_nota(self._voce_chiave(brano) if riga else None, fallito=True)\n        return\n    self._voce_log(\'in anticipo: preparo %s\'\n                   % (brano[:70] if e_link else os.path.basename(brano)))\n    # ⛔⛔ SI AZZERA QUI, SUBITO, prima del thread. Lo stato "pronto" e\'\n    #     uno solo per tutto il programma e restava acceso dal brano di\n    #     PRIMA: armando il secondo, il tasto leggeva "pronto" e diceva\n    #     100% all\'istante, mentre il lavoro vero finiva tre minuti dopo.\n    #     VISTO NEL REGISTRO: PRONTA alle 12:09 (primo), secondo armato\n    #     alle 12:10 e subito verde, PRONTA vero alle 12:13.\n    #     Azzerarlo dentro il thread non basta: prima di arrivarci ci\n    #     sono il download e lo stacco dell\'audio, e il tasto guarda ogni\n    #     700 ms.\n    self._voce_pronto = False\n    self._voce_si_parte = False\n    self._voce_avanzamento = (0, 0)\n    turno = getattr(self, \'_voce_turno\', 0)\n    # ⭐ Il SEGNO, non il contatore: (chiave del brano, livello). E\' cio\'\n    #    che dice se il lavoro serve ancora. Il contatore si muove anche\n    #    quando non e\' cambiato niente di importante — `play` richiama\n    #    `set_voce` da solo — e guardando quello si ammazzava l\'operaio.\n    # ⭐ Per una riga il segno non c\'e\' (None = si va avanti comunque):\n    #    il suo lavoro non dipende da cio\' che suona\n    segno_mio = None if riga else getattr(self, \'_voce_turno_segno\', None)\n    chiave_mia = self._voce_chiave(brano) if riga else None\n    # lo stato di QUESTO brano, per la sua riga (vedi `_voce_nota`)\n    self._voce_nota(chiave_mia, av=(0, 0), vai=False, pronto=False,\n                    fallito=False)\n\n    def _lavora():\n        # ⛔ TUTTO DENTRO UNA RETE: questo gira in un thread, e li\' dentro\n        #    un errore NON SI VEDE — il lavoro si ferma a meta\' e nel\n        #    registro non compare niente. E\' successo: la traccia si\n        #    interrompeva dopo "video pronto" e non c\'era modo di sapere\n        #    perche\'. Adesso l\'errore finisce nel registro, per intero.\n        try:\n            _lavora_davvero()\n        except Exception as e:\n            import traceback\n            self._voce_log(\'in anticipo: ESPLOSO %s: %s\' % (type(e).__name__, e))\n            for r in traceback.format_exc().splitlines()[-6:]:\n                self._voce_log(\'       \' + r)\n        # ⚠️ se il lavoro e\' finito senza arrivare a "pronta" (file che\n        #    manca, download fallito...) la riga lo deve sapere, se no\n        #    resta arancione per sempre\n        try:\n            if chiave_mia and not self.__dict__.get(\'_voce_lavori\', {}).get(\n                    chiave_mia, {}).get(\'pronto\'):\n                self._voce_nota(chiave_mia, fallito=True)\n        except Exception:\n            pass\n\n    def _lavora_davvero():\n        sorgente = brano\n        if e_link:\n            # ⛔ UN LINK VA PRIMA SCARICATO, altrimenti non c\'e\' niente da\n            #    preparare e il tasto premuto prima non serve a nulla —\n            #    che e\' esattamente il caso importante.\n            #    `scarica_video` fa tutto: se il file c\'e\' gia\' lo riusa,\n            #    se il pre-scarico della scaletta e\' in corso lo ASPETTA\n            #    invece di avviarne un secondo.\n            try:\n                from . import youtube_local as yl\n                f, _t = yl.scarica_video(brano)\n            except Exception as e:\n                self._voce_log(\'in anticipo: non riesco a scaricare il video (%s)\' % e)\n                return\n            if not f or not os.path.exists(f):\n                self._voce_log(\'in anticipo: il video non e\\\' arrivato\')\n                return\n            if not riga and turno != getattr(self, \'_voce_turno\', 0):\n                return\n            self._voce_log(\'in anticipo: video pronto (%s)\' % os.path.basename(f))\n            sorgente = f\n        try:\n            # ⚠️ se e\' un video l\'audio va staccato. Si guarda\n            #    l\'estensione di `sorgente` — cioe\' del file VERO, che per\n            #    un link e\' quello appena scaricato: guardando il link non\n            #    ci sarebbe nessuna estensione e l\'audio non si\n            #    staccherebbe mai.\n            # ⚠️ E NON si guarda `engine.is_video`: a base ferma quello\n            #    parla ancora del brano di PRIMA.\n            est = os.path.splitext(sorgente)[1].lower()\n            if est in (\'.mp4\', \'.mkv\', \'.avi\', \'.mov\', \'.wmv\', \'.webm\', \'.flv\',\n                       \'.mpg\', \'.mpeg\', \'.m4v\'):\n                estratto = self._extract_video_audio(sorgente)\n                if estratto and os.path.exists(estratto):\n                    # ⛔ con un altro brano che suona NON si tocca: e\' il\n                    #    file da cui sta suonando LUI (lo usano il tono e\n                    #    lo stacco dell\'audio). Basta la memoria qui sotto.\n                    if not getattr(self, \'is_playing\', False):\n                        self._video_audio_extracted = estratto\n                    # si segna, cosi\' alla partenza non si rifa\' tutto\n                    _k = self._voce_chiave(brano)\n                    self._voce_audio_memo()[_k] = estratto\n                    self._voce_log(\'memoria: segno [%s] -> %s\'\n                                   % (_k, os.path.basename(estratto)))\n                    sorgente = estratto\n        except Exception as e:\n            self._voce_log(\'in anticipo: audio del video non estratto (%s)\' % e)\n        pronto = self._voce_prepara(sorgente, q, self._voce_chiave(brano))\n        if not pronto:\n            self._voce_log(\'in anticipo: audio non preparato\')\n            return\n        self._voce_log(\'in anticipo: pronto il ripiego, comincio col modello\')\n        # ⛔⛔ QUI IL MODELLO MORIVA, E IN SILENZIO. Il 10-09-2026 non ha\n        #    lavorato NEMMENO UNA VOLTA — zero righe \'modello:\' nel\n        #    registro, nemmeno un errore — e si sentiva solo il ripiego,\n        #    cioe\' il filtro, che svuota la musica e lascia il riverbero.\n        #\n        #    C\'era `if turno != self._voce_turno: return`, muto. Ma il\n        #    CONTATORE non e\' la domanda giusta: `play` richiama\n        #    `set_voce` da solo appena parte il brano, e con un video di\n        #    YouTube quella chiamata arriva mentre il file vero (l\'audio\n        #    estratto) sta prendendo il posto del link. Il contatore si\n        #    muove, e l\'operaio veniva ucciso un istante prima di iniziare.\n        #\n        # ⭐ La domanda giusta e\': **e\' ancora lo stesso brano, con la\n        #    voce ancora giu\'?** Se si\', si continua. `_voce_turno_segno`\n        #    e\' proprio la coppia (chiave del brano, livello).\n        if not self._voce_stesso_lavoro(segno_mio):\n            return\n        # ⭐ DUE PASSATE, E L\'ORDINE CONTA: prima \'cori\', poi \'tutta\'.\n        #    MISURATO su Tozzi: da solo \'tutta\' toglie 45,6 dB di voce;\n        #    \'cori\' e poi \'tutta\' ne toglie **54,1**, e la base resta la\n        #    stessa (8,3 contro 8,5). Nessun\'altra combinazione guadagna:\n        #      stesso modello due volte  45,6 -> 45,7  (niente)\n        #      \'tutta\' e poi \'cori\'      45,6 -> 45,6  (niente)\n        #    Quello che il primo ha tolto non c\'e\' piu\': il guadagno c\'e\'\n        #    solo se il secondo modello e\' DIVERSO e piu\' aggressivo.\n        #\n        # ⚠️ Costa il doppio: da ~3,25x del singolo si scende a ~1,6x il\n        #    tempo reale, che resta sopra la soglia per lavorare mentre il\n        #    brano suona. Su una macchina piu\' lenta puo\' non bastare: la\n        #    seconda passata parte solo se la prima ha rifatto il brano\n        #    INTERO, quindi al peggio si resta al risultato di prima.\n        #    Si spegne con `devoc_due_passate` = 0.\n        due = True\n        try:\n            from .database import Database\n            due = str(Database.get_config(\'devoc_due_passate\', \'1\')).strip() != \'0\'\n        except Exception:\n            pass\n        if not due:\n            self._voce_avanzamento = (0, 0)\n            self._voce_pronto = False\n            # ⭐ col roformer: testa col modello veloce, poi lui (vedi\n            #    `_voce_ibrido`), cosi\' si puo\' premere play subito\n            ibrido = False\n            try:\n                from . import devocalizza as _dvm\n                ibrido = _dvm.modo_scelto() == \'roformer\'\n            except Exception:\n                pass\n            if ibrido:\n                # il testo al volo solo per i VIDEO: le basi hanno il loro\n                _video = e_link or os.path.splitext(str(brano))[1].lower() in (\n                    \'.mp4\', \'.mkv\', \'.webm\', \'.avi\', \'.mov\', \'.wmv\', \'.flv\',\n                    \'.m4v\', \'.mpg\', \'.mpeg\')\n                self._voce_ibrido(pronto, sorgente, turno, chiave_mia=chiave_mia,\n                                  chiave_testo=self._voce_chiave(brano) if _video else None)\n            else:\n                self._voce_separa_avanti(pronto, sorgente, 0, turno,\n                                         chiave_mia=chiave_mia)\n            self._voce_pronto = True\n            self._voce_nota(chiave_mia, pronto=True, vai=True)\n            self._voce_log(\'PRONTA: il brano e- stato preparato\')\n            return\n        self._voce_avanzamento = (0, 0)\n        self._voce_pronto = False\n        intero = self._voce_separa_avanti(pronto, sorgente, 0, turno,\n                                          modo=\'cori\', chiave_mia=chiave_mia)\n        if not intero:\n            self._voce_log(\'modello: la prima passata non ha coperto tutto, \'\n                           \'salto la seconda\')\n            return\n        if not self._voce_stesso_lavoro(segno_mio):\n            return\n        # ⛔ la seconda passata legge il file GIA\' RIPULITO, non l\'originale:\n        #    e\' proprio quello il punto.\n        self._voce_separa_avanti(pronto, pronto, 0, turno, modo=\'tutta\',\n                                 chiave_mia=chiave_mia)\n        # ⭐ da qui il brano e\' pronto DAVVERO: tutto rifatto, due passate.\n        self._voce_pronto = True\n        self._voce_nota(chiave_mia, pronto=True, vai=True)\n        self._voce_log(\'PRONTA: il brano e- stato preparato per intero\')\n\n    threading.Thread(target=_lavora, daemon=True).start()\n\n\ndef _voce_stesso_lavoro(self, segno_mio, dove=\'modello\'):\n    """E\' ancora lo stesso brano, con la voce ancora giu\'?\n\n    ⛔ NON si guarda il contatore dei turni. `play` richiama `set_voce`\n       da solo appena il brano parte, e con un video di YouTube quella\n       chiamata arriva mentre l\'audio estratto prende il posto del link:\n       il contatore si muove pur non essendo cambiato NIENTE che conti,\n       e l\'operaio veniva ucciso un istante prima di servire. Zero righe\n       \'modello:\' nel registro per tutta la giornata del 10-09-2026.\n\n    Il `segno` e\' la coppia (chiave del brano, livello): se e\' la stessa,\n    il lavoro serve ancora. Se non lo sappiamo (None), si continua — meglio\n    lavorare per niente che non lavorare mai.\n    """\n    if segno_mio is None:\n        return True\n    adesso = getattr(self, \'_voce_turno_segno\', None)\n    if adesso is None or adesso == segno_mio:\n        return True\n    # ⚠️ si scrive COSA e\' cambiato: una via d\'uscita muta e\' costata ore\n    self._voce_log(\'%s: fermato, e- cambiato il lavoro (avevo %s, adesso %s)\'\n                   % (dove, str(segno_mio)[:60], str(adesso)[:60]))\n    return False\n\n\ndef _voce_scrivi_pezzo(self, f, inizio, a, base, sr, sfuma_ms=30):\n    """Scrive un pezzo rifatto SFUMANDO l\'attacco su quello che c\'era.\n\n    ⛔ SENZA QUESTO SI SENTE UNO SCATTO. Il pezzo nuovo (rifatto dal\n       modello) e quello vecchio (il ripiego) sono due segnali diversi:\n       incollandoli di netto, al punto di giunzione il suono fa un salto,\n       e un salto si sente come un clic. E\' il "tipo uno scatto fra la\n       base cattiva e quella buona".\n\n    Si legge quello che c\'e\' gia\' nei primi millisecondi, e si passa da\n    quello al nuovo con una rampa dolce. Trenta millisecondi bastano: sono\n    troppo pochi perche\' l\'orecchio senta un dissolvenza, abbastanza\n    perche\' non senta il gradino.\n    """\n    import numpy as np\n    n = base.shape[1] if base.ndim > 1 else len(base)\n    nuovo = np.clip(base.T, -1.0, 1.0)\n    quanti = min(int(sr * sfuma_ms / 1000.0), n)\n    if quanti > 1 and a > 0:\n        try:\n            f.seek(inizio + a * 4)\n            grezzo = f.read(quanti * 4)\n            if len(grezzo) == quanti * 4:\n                vecchio = (np.frombuffer(grezzo, dtype=\'<i2\')\n                           .reshape(-1, 2).astype(np.float32) / 32767.0)\n                rampa = np.linspace(0.0, 1.0, quanti, dtype=np.float32)[:, None]\n                nuovo[:quanti] = vecchio * (1.0 - rampa) + nuovo[:quanti] * rampa\n        except Exception:\n            pass                      # se non si riesce, si scrive netto\n    f.seek(inizio + a * 4)\n    f.write((nuovo * 32767.0).astype(\'<i2\').tobytes())\n    f.flush()\n\n\ndef _voce_muta_video(self, muto):\n    """Zittisce (o riaccende) l\'audio del VIDEO.\n\n    ⛔ SERVE PER IL "SALTINO" ALL\'AVVIO. Il video parte col suo audio —\n       voce compresa — e veniva zittito solo a scambio finito, un secondo\n       dopo. In quel secondo si sentiva il brano ORIGINALE, poi di colpo\n       quello pulito: e\' quello il salto.\n       Zittendolo subito, al posto del secondo di voce c\'e\' un secondo di\n       silenzio: molto meno fastidioso, e non c\'e\' piu\' nessun salto fra\n       due suoni diversi.\n\n    ⚠️ Se poi lo scambio NON riesce si deve riaccendere, o resta muto per\n       tutto il brano: vedi le uscite anticipate di\n       `_finish_activate_video_mpv`.\n    """\n    # ⭐ interruttore: `devoc_muta_subito` a 0 e il video NON viene zittito\n    #    in anticipo (torna il comportamento di prima, col secondo di\n    #    audio originale). Serve per capire da dove viene un difetto:\n    #    sentendo o non sentendo quel secondo si distingue se il problema\n    #    sta nello scambio o nel file preparato.\n    if muto:\n        try:\n            from .database import Database\n            if str(Database.get_config(\'devoc_muta_subito\', \'1\')).strip() == \'0\':\n                return\n        except Exception:\n            pass\n    for p in (getattr(self.engine, \'vlc_player\', None),\n              getattr(self.engine, \'vlc_player_pubblico\', None)):\n        if p is None:\n            continue\n        try:\n            p.audio_set_mute(bool(muto))\n        except Exception:\n            pass\n\n\ndef _voce_chiave_di_cio_che_suona(self, sorgente):\n    """La chiave del brano il cui audio e\' `sorgente`.\n\n    Per un video l\'audio e\' quello staccato, e la memoria degli stacchi\n    dice di quale brano e\': si cerca li\'. Per un file normale la chiave\n    viene dal file stesso. MAI dalla riga selezionata: puo\' essere un\n    altro brano (vedi `set_voce`).\n    """\n    try:\n        s = os.path.abspath(str(sorgente)).lower()\n        for k, v in (self._voce_audio_memo() or {}).items():\n            if v and os.path.abspath(str(v)).lower() == s:\n                return k\n    except Exception:\n        pass\n    return self._voce_chiave(getattr(self, \'current_file\', None) or sorgente)\n\n\ndef _voce_wav_dove(self, percorso):\n    """Da che byte cominciano i suoni, e con che misure.\n\n    ⛔ Non si da\' per scontato 44: ffmpeg a volte infila altri pezzi\n       nell\'intestazione, e scrivendo all\'offset sbagliato si sporcherebbe\n       il file invece di correggerlo.\n    """\n    import struct\n    with open(percorso, \'rb\') as f:\n        if f.read(4) != b\'RIFF\':\n            return None\n        f.read(4)\n        if f.read(4) != b\'WAVE\':\n            return None\n        canali = freq = bit = None\n        while True:\n            testa = f.read(8)\n            if len(testa) < 8:\n                return None\n            nome, quanto = struct.unpack(\'<4sI\', testa)\n            if nome == b\'fmt \':\n                d = f.read(quanto)\n                canali = struct.unpack(\'<H\', d[2:4])[0]\n                freq = struct.unpack(\'<I\', d[4:8])[0]\n                bit = struct.unpack(\'<H\', d[14:16])[0]\n            elif nome == b\'data\':\n                return dict(inizio=f.tell(), quanti=quanto, canali=canali,\n                            freq=freq, bit=bit)\n            else:\n                f.seek(quanto + (quanto & 1), 1)\n\n\ndef _voce_dove_siamo_ms(self):\n    """Dov\'e\' arrivata la puntina, adesso. -1 = non sta suonando niente.\n\n    ⛔⛔ PRIMA NON SI CONTROLLAVA CHE STESSE SUONANDO, e a base ferma il\n        motore audio ha ancora caricato il brano di prima: rispondeva con\n        la posizione VECCHIA. Il modello ci credeva, pensava che la puntina\n        fosse gia\' avanti e SALTAVA LA TESTA anche quando non c\'era niente\n        da saltare — con la voce che restava li\' dentro. E\' l\'"inizio\n        brutto" e il "salto" all\'avvio: non il modello lento, ma una\n        posizione inventata.\n        VISTO NEL REGISTRO: "primo pezzo scritto dal secondo 5.9" con la\n        base FERMA, subito dopo aver premuto il tasto.\n    """\n    if not getattr(self, \'is_playing\', False):\n        return -1\n    try:\n        if getattr(self, \'is_bass_audio\', False) and self.bass_engine:\n            return int(self.bass_engine.get_position_ms() or 0)\n        if getattr(self, \'is_mpv_audio\', False) and self.mpv_player:\n            return int((self.mpv_player.time_pos or 0) * 1000)\n    except Exception:\n        pass\n    return -1\n\n# ═══════════════════════════════════════════════════════════════════\n#  TESTO AL VOLO: il video di YouTube diventa una base col testo\n# ═══════════════════════════════════════════════════════════════════\n# ⭐ Un video devocalizzato ha gia\' la VOCE separata: la si manda al\n#    server con artista e titolo, e torna il testo coi tempi di QUESTA\n#    incisione — sillabe scritte a mano se il brano e\' in archivio,\n#    altrimenti righe allineate dal LAM. Al play il brano parte come una\n#    base mp3 col testo: la base pulita suona, il testo scorre, niente\n#    video.\n# ⚠️ E\' TUTTO IN PIU\': se il testo non c\'e\' (o non arriva in tempo, o il\n#    server non risponde) il brano parte come prima, col video. Si spegne\n#    con `testo_al_volo` = 0.\n# ⚠️ indirizzo e chiave stanno DENTRO `_testo_chiedi_ora`, non qui come\n#    costanti della classe: la patch a caldo porta le funzioni, non le\n#    costanti, e nel programma gia\' compilato non ci sarebbero.\n\n\ndef _voce_separa_avanti(self, file_giu, sorgente, da_ms, turno,\n                        modo=None, marca=True, chiave_mia=None):\n    """UN SOLO operaio per file: vedi `_voce_separa_avanti_lavoro`.\n\n    ⛔⛔ PRIMA PARTIVANO IN DUE SULLO STESSO BRANO: quello della riga,\n        che lo preparava da prima, e un secondo avviato dallo scambio\n        appena il brano partiva. Col roformer il motore e\' uno solo e i\n        pezzi li fa in fila: due operai = meta\' velocita\' ciascuno, e\n        quello che era davanti alla puntina veniva raggiunto. Il secondo\n        rifaceva pure pezzi gia\' fatti.\n    """\n    attivi = self.__dict__.setdefault(\'_voce_file_al_lavoro\', set())\n    try:\n        chi = (os.path.abspath(str(file_giu)).lower(), modo)\n    except Exception:\n        chi = (str(file_giu), modo)\n    if chi in attivi:\n        self._voce_log(\'modello: su questo brano lavora gia- un altro, \'\n                       \'non ne parto un secondo\')\n        return None\n    attivi.add(chi)\n    try:\n        return self._voce_separa_avanti_lavoro(\n            file_giu, sorgente, da_ms, turno, modo=modo, marca=marca,\n            chiave_mia=chiave_mia)\n    finally:\n        attivi.discard(chi)\n\n\ndef _voce_separa_avanti_lavoro(self, file_giu, sorgente, da_ms, turno,\n                               modo=None, marca=True, chiave_mia=None,\n                               fino=None):\n    """Riscrive il brano, davanti alla puntina, con la voce tolta davvero.\n\n    Gira in un thread suo. Si ferma da solo se il brano cambia, se la\n    voce viene rimessa, o se qualcuno preme di nuovo (il `turno` non\n    combacia piu\').\n\n    `chiave_mia`: il lavoro e\' per UNA RIGA della scaletta, non per cio\'\n    che suona. Allora la puntina, il livello della voce e i cambi di\n    brano sono affari di un ALTRO brano, e non lo riguardano — finche\'\n    non tocca proprio a lui suonare.\n    """\n    import subprocess\n    import numpy as np\n\n    # ⛔⛔ OGNI RIGA E\' INDIPENDENTE. Preparando la riga B mentre suona A,\n    #     prima si guardava la puntina di A (e si saltavano pezzi di B che\n    #     nessuno stava suonando), il livello di A (A senza voce giu\' =\n    #     "voce rimessa", e B si fermava) e i cambi di A (partiva un\n    #     altro brano e B moriva a meta\'). Adesso, per una riga, conta\n    #     solo cio\' che succede a LEI.\n    def _suona_il_mio():\n        if not chiave_mia:\n            return bool(getattr(self, \'is_playing\', False))\n        if not getattr(self, \'is_playing\', False):\n            return False\n        # ⛔ PRIMA DI TUTTO IL FILE VERO: se il motore audio sta suonando\n        #    proprio il file che sto riscrivendo, e\' il mio, senza\n        #    discussioni. Col solo nome del brano, per un video di\n        #    YouTube `current_file` puo\' essere l\'audio staccato, che ha un\n        #    altro nome: non lo riconosceva, e l\'operaio scriveva senza\n        #    guardare la puntina.\n        try:\n            _mot, _src = self._voce_chi_suona()\n            if _src and (os.path.abspath(str(_src)).lower()\n                         == os.path.abspath(str(file_giu)).lower()):\n                return True\n        except Exception:\n            pass\n        cf = getattr(self, \'current_file\', None)\n        return (self._voce_chiave(cf) == chiave_mia\n                or self._voce_chiave_di_cio_che_suona(cf) == chiave_mia)\n\n    def _dove():\n        if chiave_mia and not _suona_il_mio():\n            return -1\n        return self._voce_dove_siamo_ms()\n\n    def _voce_rimessa():\n        if chiave_mia and not _suona_il_mio():\n            return False\n        return not getattr(self, \'voce_giu\', 0)\n\n    def _cedi_il_passo():\n        """MENTRE SUONA, il modello lascia respirare la macchina.\n\n        ⛔ UN MIDI si suona DENTRO KaraDom, nota per nota: "ho cliccato\n           play su un midi e si stava per freezzare" (utente, 11-09).\n        ⛔ Anche col video c\'e\' poco da stare allegri: due lettori VLC\n           (principale e pubblico) piu\' il modello riempiono il\n           processore, e l\'audio gracchia ("un rumore tipo trrrrr").\n        """\n        if not getattr(self, \'is_playing\', False):\n            if getattr(self, \'_voce_detto_rallento\', False):\n                self._voce_detto_rallento = False\n            return\n        quanto = 1.0 if getattr(self, \'is_midi\', False) else 0.25\n        if not getattr(self, \'_voce_detto_rallento\', False):\n            self._voce_detto_rallento = True\n            self._voce_log(\'modello: sta suonando (%s), rallento di %.2f s a pezzo \'\n                           \'per non rubargli il processore\'\n                           % (\'MIDI\' if getattr(self, \'is_midi\', False) else \'base o video\',\n                              quanto))\n        time.sleep(quanto)\n    try:\n        from . import devocalizza as dv\n    except Exception as e:\n        self._voce_log(\'modello: non riesco a caricare devocalizza (%s)\' % e)\n        return\n\n    # ⛔ IL SEGNALE PORTA IL NOME DEL MODO: con due passate in fila\n    #    un solo segnale faceva credere alla seconda che fosse gia\'\n    #    tutto fatto, e la seconda non partiva mai.\n    segnale = file_giu + \'.completo\' + (\'.\' + modo if modo else \'\')\n    if os.path.exists(segnale):\n        # ⛔ QUI SI RISPONDE "FATTO", NON "NIENTE". Uscendo a mani vuote\n        #    chi chiama credeva che la passata NON avesse coperto il brano,\n        #    saltava la seconda e non arrivava mai lo stato "pronto": il\n        #    tasto restava arancione per sempre e la percentuale non\n        #    compariva. Il lavoro c\'era, era la risposta a mancare.\n        self._voce_log(\'modello%s: gia\\\' fatto in passato, va bene cosi\\\'\'\n                       % (\' \' + modo if modo else \'\'))\n        self._voce_avanzamento = (1, 1)\n        self._voce_nota(chiave_mia, av=(1, 1))\n        return True\n\n    info = self._voce_wav_dove(file_giu)\n    if not info or info.get(\'bit\') != 16 or info.get(\'canali\') != 2:\n        self._voce_log(\'modello: il file non ha il formato che mi aspetto (%s)\'\n                       % info)\n        return\n\n    try:\n        # ⛔ il modo scelto nelle impostazioni: con `None` si apriva\n        #    SEMPRE il predefinito, qualunque cosa dicesse `devoc_modo`\n        sess, win, CHUNK, SRM = dv.apri(modo or dv.modo_scelto())\n        # ⚠️ fotografati SUBITO: sono variabili del modulo, e un altro\n        #    lavoro che apre un altro modello le cambierebbe sotto i piedi\n        tipo_mio = getattr(dv, \'TIPO\', \'\')\n        coda_mia = int(getattr(dv, \'CODA\', 0) or 0)\n    except Exception as e:\n        self._voce_log(\'modello: non parte (%s: %s)\' % (type(e).__name__, e))\n        return\n    if info[\'freq\'] != SRM:\n        self._voce_log(\'modello: il file va a %d Hz e il modello a %d: lascio stare\'\n                       % (info[\'freq\'], SRM))\n        return\n\n    # il brano di partenza, tutto in memoria alla frequenza del modello\n    try:\n        r = subprocess.run([self._voce_ffmpeg(), \'-v\', \'error\', \'-i\', sorgente,\n                            \'-f\', \'f32le\', \'-ac\', \'2\', \'-ar\', str(SRM), \'-\'],\n                           capture_output=True, timeout=300,\n                           creationflags=0x08000000 if os.name == \'nt\' else 0)\n        mix = np.ascontiguousarray(\n            np.frombuffer(r.stdout, dtype=np.float32).reshape(-1, 2).T)\n    except Exception as e:\n        self._voce_log(\'modello: non riesco a leggere il brano (%s)\' % e)\n        return\n    totale = mix.shape[1]\n    if totale < CHUNK:\n        return\n\n    quanti = (totale + CHUNK - 1) // CHUNK\n    n = max(0, int(da_ms / 1000.0 * SRM) // CHUNK)\n    da_capo = (n == 0)\n    primo = True\n    aspettato = 0\n    scritti = 0\n    saltati = 0\n    t0 = time.time()\n\n    # ⭐ lo stesso metro di `_voce_prepara_in_anticipo`: conta il BRANO,\n    #    non il contatore dei turni (vedi `_voce_stesso_lavoro`).\n    # ⛔⛔ QUANTA VOCE LASCIARE: prima questo valore delle Opzioni finiva\n    #     SOLO nel nome del file, e il suono non lo usava mai — la voce\n    #     veniva tolta tutta, sempre, qualunque cosa si scegliesse. Ed e\'\n    #     proprio lasciarne un filo che riempie i BUCHI dove la voce c\'era\n    #     (strumenti portati via insieme a lei): e\' quello che fa K5, "la\n    #     voce pur sentendosi lievemente non fa rumore".\n    try:\n        resto = float(dv.quanto_abbassare())\n    except Exception:\n        resto = 0.0\n    if resto > 0:\n        self._voce_log(\'modello: lascio il %.0f%% della voce (riempie i buchi)\'\n                       % (resto * 100))\n\n    # ⭐ per una riga non c\'e\' segno: il suo lavoro non lo ferma il brano\n    #    che suona (vedi `_suona_il_mio`)\n    segno_mio = None if chiave_mia else getattr(self, \'_voce_turno_segno\', None)\n    # i pezzi saltati, da riprendere alla fine. ⭐ Partendo da piu\' avanti\n    # (il roformer dopo la testa fatta dal modello veloce) ci vanno anche\n    # quelli PRIMA del punto di partenza: se la puntina non ci e\' ancora\n    # arrivata, si rifanno anche loro col modello buono.\n    rimasti = list(range(0, n)) if (n > 0 and fino is None) else []\n\n    with open(file_giu, \'r+b\') as f:\n        while n < quanti:\n            if not self._voce_stesso_lavoro(segno_mio):\n                return\n            _cedi_il_passo()\n            # ⭐ il modello veloce si ferma dove comincia il roformer\n            #    (vedi `_voce_ibrido`): il punto si ricalcola a ogni pezzo,\n            #    perche\' se la base sta gia\' suonando si sposta in avanti\n            if fino is not None and n * CHUNK >= fino():\n                break\n            # ⛔ NON si controlla `is_playing`: il lavoro comincia a base\n            #    FERMA, appena si arma il tasto, proprio perche\' il brano\n            #    deve PARTIRE gia\' pulito. Controllando che stia suonando,\n            #    l\'operaio moriva subito e restava solo il ripiego.\n            if _voce_rimessa():\n                self._voce_log(\'modello: fermato (voce rimessa) dopo %d pezzi\'\n                               % scritti)\n                return\n\n            # ⛔⛔ MAI SCRIVERE DOVE LA PUNTINA STA PASSANDO.\n            #     Il blocco dev\'essere tutto DAVANTI, non a cavallo:\n            #     riscrivere i byte che BASS sta leggendo in quell\'istante\n            #     non e\' solo lavoro sprecato, e\' proprio quello che fa\n            #     sporcare l\'audio.\n            #     VISTO NEL REGISTRO: la puntina al secondo 12 e il\n            #     modello che scriveva il tratto 5,9-11,8. Prima bastava\n            #     che il blocco CONTENESSE la puntina piu\' 0,7 s, quindi\n            #     passava un blocco gia\' mezzo suonato.\n            dove = _dove()\n            if dove >= 0:\n                sicuro = (dove / 1000.0 + 2.0) * SRM     # due secondi d\'aria\n                minimo = int(sicuro // CHUNK) + 1        # il blocco DOPO\n                if n < minimo:\n                    if not saltati:\n                        self._voce_log(\'modello: la puntina e- avanti, \'\n                                       \'salto al pezzo %d (secondo %.1f)\'\n                                       % (minimo, minimo * CHUNK / float(SRM)))\n                    # ⭐ I PEZZI SALTATI SI SEGNANO E SI RIPRENDONO ALLA\n                    #    FINE, quando la puntina e\' ormai lontana e\n                    #    scriverli e\' sicuro. Prima andavano persi: il\n                    #    brano restava incompleto per sempre, la testa\n                    #    con la voce dentro, e con essa saltava anche la\n                    #    seconda passata (che parte solo su brano intero).\n                    rimasti.extend(range(n, minimo))\n                    saltati += minimo - n\n                    n = minimo\n                    continue\n\n            a = n * CHUNK\n            b = min(totale, a + CHUNK)\n            pezzo = mix[:, a:b]\n            if pezzo.shape[1] < CHUNK:\n                pezzo = np.pad(pezzo, ((0, 0), (0, CHUNK - pezzo.shape[1])))\n            try:\n                # ⭐ con la CODA oltre la fine del pezzo, se il modello la\n                #    da\': la giunta col pezzo dopo sfuma da modello a\n                #    modello, non passando per il filtro (vedi dv.CODA)\n                fin_pezzo = min(totale, b + coda_mia)\n                base = dv.base_del_pezzo(sess, win, pezzo, mix, a)[:, :fin_pezzo - a]\n                if resto > 0:\n                    base = base + (mix[:, a:a + base.shape[1]] - base) * resto\n            except Exception as e:\n                self._voce_log(\'modello: si e\\\' inceppato al pezzo %d (%s)\' % (n, e))\n                return\n\n            # ⛔⛔ SI RICONTROLLA ADESSO, un attimo prima di scrivere.\n            #     Fra il controllo di sopra e questo punto passano un paio\n            #     di secondi — il tempo che il modello lavora — e in quei\n            #     due secondi la puntina entra nel blocco. VISTO NEL\n            #     REGISTRO: play alle 14:36:21, blocco 0-5,9 s scritto\n            #     alle 14:36:23, cioe\' proprio sotto la puntina.\n            #     Riscrivere i byte che BASS sta leggendo e\' quello che\n            #     fa sentire "la musica peggio della voce".\n            dove = _dove()\n            # ⛔ SE NON SI SA DOV\'E\' LA PUNTINA, NON SI SCRIVE. Appena\n            #    premuto play il motore audio non risponde ancora, e\n            #    prima il codice lo prendeva per "nessuno sta suonando"\n            #    e scriveva lo stesso — proprio sotto l\'inizio del brano.\n            #    VISTO NEL REGISTRO: play alle 14:54:47, tratto 0-5,9 s\n            #    scritto alle 14:54:48, e "0 saltati".\n            if _suona_il_mio() and dove < 0:\n                if aspettato < 25:\n                    aspettato += 1\n                    time.sleep(0.2)\n                    continue\n                self._voce_log(\'modello: il motore audio non dice dove sta \'\n                               \'la puntina, mi fermo per non sporcare\')\n                return\n            aspettato = 0\n            if dove >= 0 and (dove / 1000.0) * SRM >= a - SRM:\n                # ⛔ ANCHE QUESTO SALTO VA ANNOTATO: e\' il controllo fatto\n                #    un attimo prima di scrivere, quando la puntina e\'\n                #    entrata nel blocco mentre il modello lavorava. Senza\n                #    annotarlo, quel pezzo si perdeva e il brano non\n                #    risultava mai completo.\n                rimasti.append(n)\n                saltati += 1\n                n += 1\n                continue\n\n            # ⭐ sfumato, non incollato di netto: vedi `_voce_scrivi_pezzo`\n            self._voce_scrivi_pezzo(f, info[\'inizio\'], a, base, SRM)\n            scritti += 1\n            if fino is not None:\n                # per BRANO: con piu\' righe insieme un valore solo si\n                # mescolerebbe fra loro\n                self.__dict__.setdefault(\'_voce_testa_fino\', {})[file_giu] = \\\n                    int(b * 1000.0 / SRM)\n            # ⭐ a che punto siamo: lo legge il tasto, che finche\' non e\'\n            #    pronto non lascia partire il brano (deve funzionare al\n            #    PRIMO giro: non si puo\' dire a un cliente "falla suonare\n            #    una volta a vuoto")\n            # ⭐ LA PERCENTUALE DICE UNA COSA SOLA E CHIARA:\n            #    - modello veloce (testa, vedi `_voce_ibrido`): quanto manca\n            #      al tasto verde;\n            #    - poi: quanta parte del brano e\' gia\' pulita col modello\n            #      buono. Prima era la posizione del pezzo nel brano: col\n            #      roformer che parte da meta\' saltava subito al 60-70% e\n            #      poi restava li\' ("arrivato al 69% subito").\n            if fino is not None:\n                _tot = max(1, min(quanti, int((fino() + CHUNK - 1) // CHUNK)))\n                self._voce_avanzamento = (min(n + 1, _tot), _tot)\n            else:\n                self._voce_avanzamento = (min(scritti, quanti), quanti)\n            self._voce_nota(chiave_mia, av=self._voce_avanzamento)\n            # ⭐⭐ SI PUO\' PARTIRE PRIMA DELLA FINE. Il modello non deve\n            #     andare piu\' veloce della musica: basta che, partendo\n            #     adesso, la puntina non lo raggiunga mai. Col roformer a\n            #     0,75x un brano di 4 minuti si manda dopo circa 1\'20",\n            #     invece di aspettarne 5 e mezzo.\n            #     Il conto si fa con la velocita\' VERA di questa macchina,\n            #     misurata mentre lavora: su un PC piu\' lento si aspetta\n            #     di piu\', da solo, senza regole scritte per il mio.\n            # ⚠️ Un quarto di margine: mentre il brano suona il computer\n            #    ha anche il video e l\'audio da mandare avanti.\n            if (da_capo and not saltati\n                    and not getattr(self, \'_voce_si_parte\', False)):\n                fatti = (n + 1) * CHUNK / float(SRM)\n                durata = totale / float(SRM)\n                vel = fatti / max(0.001, time.time() - t0)\n                manca = max(0.0, durata - fatti)\n                aria = CHUNK / float(SRM) + 3.0\n                if manca <= 0 or (manca / vel) * 1.25 <= durata - aria:\n                    self._voce_si_parte = True\n                    self._voce_nota(chiave_mia, vai=True)\n                    self._voce_log(\'modello: SI PUO- PARTIRE (fatti %.0f s su \'\n                                   \'%.0f, %.2fx il tempo reale)\'\n                                   % (fatti, durata, vel))\n            if primo:\n                primo = False\n                self._voce_log(\'modello: primo pezzo scritto dopo %.1f s \'\n                               \'(dal secondo %.1f)\' % (time.time() - t0, a / float(SRM)))\n            n += 1\n\n    # ⛔ Il segnale "e\' completo" si mette SOLO se il brano e\' stato\n    #    rifatto tutto, dall\'inizio e senza salti. Altrimenti al giro\n    #    dopo il file verrebbe riusato com\'e\', con dei tratti in cui la\n    #    voce c\'e\' ancora, e non lo rifarebbe piu\' nessuno.\n    # ⭐ IL RECUPERO: i pezzi saltati si rifanno adesso. La puntina e\' molto\n    #    piu\' avanti (il modello va piu\' veloce della musica), quindi\n    #    scrivere quei tratti e\' sicuro — e il brano diventa COMPLETO.\n    #    Serve a due cose insieme, che erano lo stesso problema:\n    #      - la testa del brano non resta piu\' com\'era (l\'"inizio brutto");\n    #      - la seconda passata puo\' partire, perche\' parte solo su un\n    #        brano intero.\n    recuperati = 0\n    if rimasti:\n        self._voce_log(\'modello%s: riprendo %d pezzi saltati\'\n                       % (\' \' + modo if modo else \'\', len(rimasti)))\n        try:\n            with open(file_giu, \'r+b\') as f:\n                for n in rimasti:\n                    if not self._voce_stesso_lavoro(segno_mio):\n                        break\n                    # ⛔ IL BRANO E\' GIA\' PASSATO: rifare la testa non\n                    #    serve a nessuno (il file di lavoro viene buttato a\n                    #    fine brano) e sembra che il lavoro ricominci da\n                    #    capo — "e\' arrivato in fondo e poi ha ripetuto il\n                    #    caricamento" (utente, 11-09). Venti pezzi col\n                    #    roformer sono minuti di processore per niente.\n                    if (chiave_mia and not _suona_il_mio()\n                            and chiave_mia in (self.__dict__.get(\'_voce_suonati\') or ())):\n                        self._voce_log(\'modello: il brano e- gia- passato, \'\n                                       \'non rifaccio la testa\')\n                        break\n                    _cedi_il_passo()\n                    if _voce_rimessa():\n                        break\n                    a = n * CHUNK\n                    b = min(totale, a + CHUNK)\n                    if b <= a:\n                        continue\n                    # ⛔ e\' passata, ma si controlla lo stesso che la\n                    #    puntina non ci sia tornata sopra (uno puo\' aver\n                    #    riavvolto il brano mentre lavoravamo)\n                    dove = _dove()\n                    if dove >= 0:\n                        qui = dove / 1000.0 * SRM\n                        if a - SRM <= qui <= b + SRM:\n                            continue\n                        # ⚠️ gia\' suonato: rifarlo non serve a chi\n                        #    ascolta, e ruba tempo al brano dopo in coda\n                        if b < qui:\n                            continue\n                    pezzo = mix[:, a:b]\n                    if pezzo.shape[1] < CHUNK:\n                        pezzo = np.pad(pezzo,\n                                       ((0, 0), (0, CHUNK - pezzo.shape[1])))\n                    try:\n                        base = dv.base_del_pezzo(sess, win, pezzo, mix, a)[:, :b - a]\n                        if resto > 0:\n                            base = base + (mix[:, a:b] - base) * resto\n                    except Exception as e:\n                        self._voce_log(\'modello: inceppato sul recupero del \'\n                                       \'pezzo %d (%s)\' % (n, e))\n                        break\n                    self._voce_scrivi_pezzo(f, info[\'inizio\'], a, base, SRM)\n                    recuperati += 1\n                    self._voce_avanzamento = (min(scritti + recuperati, quanti),\n                                              quanti)\n                    self._voce_nota(chiave_mia, av=self._voce_avanzamento)\n                f.flush()\n        except Exception as e:\n            self._voce_log(\'modello: recupero non riuscito (%s)\' % e)\n        self._voce_log(\'modello%s: recuperati %d pezzi su %d\'\n                       % (\' \' + modo if modo else \'\', recuperati, len(rimasti)))\n\n    # ⛔ INTERO = TUTTI i pezzi scritti, contati. Prima bastava "partito\n    #    dall\'inizio e niente salti": col modello veloce che si ferma a\n    #    meta\' (vedi `_voce_ibrido`) il brano risultava completo e il\n    #    segnale diceva "fatto" su un file fatto a meta\'.\n    intero = (scritti + recuperati) >= quanti\n    # ⛔ Il segnale "e\' completo" si mette SOLO se il brano e\' stato\n    #    rifatto tutto: al giro dopo il file si riusa com\'e\'.\n    if intero:\n        try:\n            with open(segnale, \'wb\') as f:\n                f.write(b\'fatto\\n\')\n        except Exception:\n            pass\n    # ⭐ la velocita\' vera del roformer su QUESTO PC, per decidere la\n    #    prossima volta da dove farlo partire (vedi `_voce_ibrido`)\n    try:\n        if tipo_mio == \'roformer\' and scritti >= 3:\n            _vel = scritti * CHUNK / float(SRM) / max(1.0, time.time() - t0)\n            # ⛔⛔ LA VELOCITA\' SI MISURA A MACCHINA LIBERA. Misurandola\n            #     mentre suona un video usciva 0,17x invece di 0,75x, e\n            #     con quel numero il programma decideva che il roformer non\n            #     ce l\'avrebbe fatta: lasciava quasi tutto il brano al\n            #     modello veloce, e si sentivano i suoi rumori (utente,\n            #     11-09). Una misura presa sotto carico non e\' la macchina.\n            if getattr(self, \'is_playing\', False):\n                self._voce_log(\'modello: %.2fx misurato mentre suonava: NON lo \'\n                               \'prendo per buono\' % _vel)\n            else:\n                from .database import Database\n                Database.set_config(\'devoc_vel_roformer\', \'%.3f\' % _vel)\n                self._voce_log(\'modello: velocita- misurata %.2fx il tempo reale\' % _vel)\n    except Exception:\n        pass\n    if fino is None:\n        self._voce_avanzamento = (quanti, quanti)\n        self._voce_nota(chiave_mia, av=(quanti, quanti))\n    self._voce_log(\'modello%s: FINITO, %d pezzi in %.0f s (%d saltati perche\\\' \'\n                   \'la puntina era gia\\\' oltre)%s\'\n                   % (\' \' + modo if modo else \'\', scritti, time.time() - t0,\n                      saltati,\n                      \'\' if intero else \' - il brano non e\\\' completo, si rifara\\\'\'))\n    # ⭐ chi chiama deve sapere se il brano e\' stato rifatto TUTTO: la\n    #    seconda passata ha senso solo su un brano intero.\n    return intero\n\n\ndef _voce_ibrido(self, file_giu, sorgente, turno, chiave_mia=None, da_ms=0,\n                 chiave_testo=None):\n    """Il roformer SENZA ASPETTARE: la testa col modello veloce, il resto\n    col roformer.\n\n    ⛔⛔ IL ROFORMER VA PIU\' PIANO DELLA MUSICA (0,75x sul PC dell\'utente,\n        meno mentre il video suona). Premendo play subito la puntina lo\n        raggiungeva in pochi secondi, e da li\' in poi si sentiva il\n        RIPIEGO del filtro: "la base malissimo e la voce nitida".\n        VISTO NEL REGISTRO l\'11-09 alle 14:25: primo pezzo alle :30,\n        play alle :34.\n\n    ⭐ Cosi\' invece:\n       1. il modello veloce (MDX, ~3x) pulisce la TESTA del brano: in\n          pochi secondi e\' davanti alla puntina e non si fa piu\'\n          raggiungere;\n       2. si ferma al punto da cui il roformer, partendo, arriva in fondo\n          prima della puntina — il punto si ricalcola a ogni pezzo con la\n          puntina vera, se la base sta gia\' suonando;\n       3. il roformer fa da li\' alla fine, e poi torna a rifare la testa\n          finche\' la puntina non ci e\' ancora passata.\n       Premendo play subito: la testa si sente col modello veloce, il\n       resto col roformer. Aspettando, e\' tutto roformer.\n    """\n    attivi = self.__dict__.setdefault(\'_voce_file_al_lavoro\', set())\n    chi = (os.path.abspath(str(file_giu)).lower(), None)\n    if chi in attivi:\n        self._voce_log(\'ibrido: su questo brano lavora gia- un altro\')\n        return None\n    attivi.add(chi)\n    try:\n        from . import devocalizza as dv\n        if os.path.exists(file_giu + \'.completo\'):\n            self._voce_log(\'ibrido: il roformer l-ha gia- fatto tutto in passato\')\n            self._voce_avanzamento = (1, 1)\n            self._voce_si_parte = True\n            self._voce_nota(chiave_mia, av=(1, 1), vai=True)\n            if chiave_testo:\n                try:\n                    self._testo_chiedi(chiave_testo, sorgente, file_giu)\n                except Exception as _et:\n                    self._voce_log(\'testo: richiesta non partita (%s)\' % _et)\n            return True\n        # il motore del roformer si accende SUBITO, insieme al modello\n        # veloce: sono i suoi 12 secondi di partenza, cosi\' non si aspettano\n        # ⛔ NON `dv.apri(\'roformer\')`: cambierebbe le misure del modulo\n        #    mentre il modello veloce le sta usando\n        threading.Thread(target=dv._motore_roformer, daemon=True).start()\n\n        info = self._voce_wav_dove(file_giu) or {}\n        try:\n            durata = info[\'quanti\'] / float(info[\'canali\'] * info[\'bit\'] // 8) / info[\'freq\']\n        except Exception:\n            durata = 240.0\n        try:\n            from .database import Database\n            vel = float(str(Database.get_config(\'devoc_vel_roformer\', \'0.6\')).strip())\n        except Exception:\n            vel = 0.6\n        # ⚠️ mai sotto 0,35: con un numero piu\' basso il conto dice che il\n        #    roformer non ce la fa mai e tutto il brano finisce al modello\n        #    veloce, che e\' proprio quello che l\'utente sente come "rumori".\n        #    Se poi la puntina lo raggiunge davvero, quei pezzi restano col\n        #    modello veloce: si perde qualita\', non si rompe niente.\n        vel = max(0.35, min(5.0, vel))\n        SR = 44100\n\n        def dove_serve():\n            """Da che campione il roformer arriva in fondo prima della puntina."""\n            p = 0.0\n            if getattr(self, \'is_playing\', False):\n                try:\n                    _m, _s = self._voce_chi_suona()\n                    if _s and (os.path.abspath(str(_s)).lower()\n                               == os.path.abspath(str(file_giu)).lower()):\n                        p = max(0.0, self._voce_dove_siamo_ms() / 1000.0)\n                except Exception:\n                    pass\n            aria = 7.5 + 3.0 + 12.0          # un pezzo, due secondi, la partenza\n            # ⚠️ un terzo di margine sulla velocita\': mentre il video\n            #    suona il roformer ha meno processore\n            x = durata - (vel / 1.35) * max(0.0, durata - p - aria)\n            return int(max(0.0, min(durata, x)) * SR)\n\n        # ⭐⭐ PIU\' RIGHE INSIEME. Il roformer e\' un motore solo: due brani\n        #     insieme = meta\' velocita\' ciascuno, e il primo verrebbe\n        #     raggiunto dalla puntina. Quindi il ROFORMER fa un brano alla\n        #     volta (questa serratura), ma il MODELLO VELOCE parte subito\n        #     per tutti: ogni riga diventa verde in pochi secondi.\n        #     Se il roformer e\' occupato, il modello veloce pulisce il\n        #     brano INTERO: cosi\', se lo si manda prima che tocchi al\n        #     roformer, non si sente mai il filtro.\n        turno_rf = self.__dict__.setdefault(\'_voce_lucchetto_rf\', threading.Lock())\n        occupato = turno_rf.locked()\n        tutto = lambda: 10 ** 12                      # noqa: E731\n        # ⭐⭐ TESTO AL VOLO, IN DUE TEMPI (deve funzionare al PRIMO giro):\n        #   1. SUBITO l\'audio ORIGINALE al server: se il brano e\' in\n        #      archivio il testo torna in mezzo minuto (misurato su\n        #      "Gloria": riconosciuto e controllato sull\'originale in 10 s);\n        #   2. se l\'archivio non basta serve il LAM, e il LAM vuole la\n        #      VOCE separata di tutto il brano: allora il modello veloce fa\n        #      il brano intero e si richiede con la voce.\n        #   Finche\' la risposta del punto 1 non c\'e\', il modello veloce\n        #   intanto va avanti (cosi\' il punto 2, se serve, e\' gia\' pronto);\n        #   appena c\'e\' il testo si torna al solito: testa e poi roformer.\n        voglio_testo = bool(chiave_testo) and self._testo_acceso()\n        if voglio_testo:\n            try:\n                self._testo_chiedi(chiave_testo, sorgente, file_giu, originale=True)\n            except Exception as _et:\n                self._voce_log(\'testo: richiesta non partita (%s)\' % _et)\n\n        def _testo_deciso():\n            p = (self.__dict__.get(\'_testo_pronto\') or {}).get(chiave_testo) or {}\n            return bool(p.get(\'sillabe\')) or bool(p.get(\'definitivo\'))\n\n        def fino_mdx():\n            if occupato or (voglio_testo and not _testo_deciso()):\n                return 10 ** 12\n            return dove_serve()\n        testa = self.__dict__.setdefault(\'_voce_testa_fino\', {})\n        testa[file_giu] = 0\n        if occupato:\n            self._voce_log(\'ibrido: il roformer lavora su un altro brano: \'\n                           \'il modello veloce pulisce questo tutto intero\')\n        else:\n            self._voce_log(\'ibrido: brano di %.0f s, roformer a %.2fx: testa col \'\n                           \'modello veloce fino al secondo %.0f circa%s\'\n                           % (durata, vel, dove_serve() / float(SR),\n                              \' (o tutto, se per il testo serve la voce)\'\n                              if voglio_testo else \'\'))\n        self._voce_separa_avanti_lavoro(file_giu, sorgente, da_ms, turno,\n                                        modo=\'tutta\', chiave_mia=chiave_mia,\n                                        fino=fino_mdx)\n        fatto_fino = int(testa.get(file_giu, 0) or 0)\n        # il modello veloce ha fatto il brano intero (aspettando il testo):\n        # per il roformer vale come "occupato", parte dal punto giusto adesso\n        if fatto_fino >= (durata - 10.0) * 1000:\n            occupato = True\n        if not occupato and turno_rf.locked():\n            # nel frattempo il roformer l\'ha preso un altro brano: il\n            # modello veloce finisce anche il resto, per non lasciare filtro\n            self._voce_log(\'ibrido: il roformer si e- occupato nel frattempo, \'\n                           \'il modello veloce finisce il brano\')\n            self._voce_separa_avanti_lavoro(file_giu, sorgente, fatto_fino, turno,\n                                            modo=\'tutta\', chiave_mia=chiave_mia,\n                                            fino=tutto)\n            occupato = True\n        # ⭐ da qui si puo\' mandare: la testa (o tutto) e\' pulita\n        self._voce_si_parte = True\n        self._voce_nota(chiave_mia, vai=True)\n        # punto 2: l\'archivio non e\' bastato e la voce c\'e\' tutta -> LAM\n        if voglio_testo and not _testo_deciso() and occupato:\n            try:\n                self._testo_chiedi(chiave_testo, sorgente, file_giu)\n            except Exception as _et:\n                self._voce_log(\'testo: richiesta non partita (%s)\' % _et)\n        # ⭐ DA QUI LA RIGA E\' PRONTA. Il roformer continua a migliorare il\n        #    brano in sottofondo, ma la percentuale non deve ricominciare\n        #    da capo: "e\' arrivato all\'82% e poi ha ripreso da capo, adesso\n        #    e\' al 3%" (utente, 11-09). Per chi guarda il tasto il brano e\'\n        #    pronto: il resto e\' rifinitura.\n        if occupato:\n            self._voce_pronto = True\n            self._voce_avanzamento = (1, 1)\n            self._voce_nota(chiave_mia, pronto=True, vai=True, av=(1, 1))\n            # ⛔ il testo e\' gia\' stato chiesto qui sopra (punto 2): si chiede\n            #    PRIMA di fermarsi, perche\' la voce separata c\'e\' (l\'ha fatta\n            #    il modello veloce) e serve anche se la rifinitura col\n            #    roformer non si fa piu\' (utente, 11-09).\n            # ⛔⛔ E QUI CI SI FERMA SE IL BRANO E\' GIA\' ANDATO: "non deve\n            #     ripetere, deve fermarsi; alla peggio si vedra\' il video"\n            #     (utente, 11-09). Il brano e\' gia\' pulito tutto dal\n            #     modello veloce: rifinirlo col roformer dopo che e\' stato\n            #     mandato non serve a nessuno e tiene occupata la macchina.\n            if chiave_mia and chiave_mia in (self.__dict__.get(\'_voce_suonati\') or ()):\n                self._voce_log(\'ibrido: il brano e- gia- andato, mi fermo qui \'\n                               \'(e- gia- tutto pulito dal modello veloce)\')\n                return True\n        with turno_rf:\n            if occupato:\n                # il modello veloce ha fatto tutto: il roformer parte dal\n                # punto che la puntina non raggiunge ADESSO\n                da_ms = int(dove_serve() * 1000.0 / SR)\n            else:\n                da_ms = fatto_fino or int(dove_serve() * 1000.0 / SR)\n            # da qui la percentuale conta il brano pulito col roformer\n            self._voce_avanzamento = (0, 1)\n            self._voce_nota(chiave_mia, av=(0, 1))\n            self._voce_log(\'ibrido: ora il roformer, dal secondo %.1f\'\n                           % (da_ms / 1000.0))\n            # modo=None: il modo scelto (roformer), e il segnale "completo"\n            # e\' quello senza modo, lo stesso guardato qui sopra\n            return self._voce_separa_avanti_lavoro(file_giu, sorgente, da_ms,\n                                                   turno, chiave_mia=chiave_mia)\n    finally:\n        attivi.discard(chi)\n\n\ndef _voce_nota(self, chiave, **campi):\n    """Lo stato del lavoro di UN brano: av (fatti, totali), vai, pronto,\n    fallito.\n\n    ⛔ Prima c\'era un solo stato per tutto il programma\n       (`_voce_avanzamento`, `_voce_pronto`, `_voce_si_parte`): con due\n       righe preparate insieme si leggevano la percentuale una dell\'altra.\n       Quello unico resta per il tasto in alto; le righe leggono questo.\n    """\n    if not chiave:\n        return\n    tutti = self.__dict__.setdefault(\'_voce_lavori\', {})\n    tutti.setdefault(chiave, {}).update(campi)\n\n\ndef _testo_acceso(self):\n    try:\n        from .database import Database\n        return str(Database.get_config(\'testo_al_volo\', \'1\')).strip() != \'0\'\n    except Exception:\n        return True\n\n\ndef _testo_artista_titolo(self, testo):\n    """(artista, titolo) da come si chiama il brano: il titolo del video,\n    la riga della scaletta o il nome del file.\n\n    Si tolgono i marchi che non fanno parte del titolo ("Official Video",\n    "Lyrics", "(Voce Guida) by DOM", ".mp3"...) e si divide sul trattino.\n    Senza trattino non si sa chi e\' l\'artista: niente (il server vuole\n    artista E titolo, per non prendere il testo di una cover).\n    """\n    import re as _re\n    t = str(testo or \'\')\n    t = os.path.basename(t) if (\'\\\\\' in t or \'/\' in t) and not t.lower().startswith(\'http\') else t\n    t = _re.sub(r\'\\.(mp3|mp4|mkv|webm|avi|mov|wav|flac|m4a|kar|mid|cdg)$\', \'\', t, flags=_re.I)\n    t = _re.sub(r\'\\((?:[^)]*)\\)|\\[(?:[^\\]]*)\\]|\\{(?:[^}]*)\\}\', \' \', t)\n    t = _re.sub(r\'\\b(official|ufficiale|video|videoclip|lyrics?|testo|audio|hd|hq|4k|\'\n                r\'remaster(?:ed)?|karaoke|voce\\s*guida|base|cover)\\b\', \' \', t, flags=_re.I)\n    t = _re.sub(r\'\\bby\\s+(dom|mm)\\b.*$\', \' \', t, flags=_re.I)\n    t = t.replace(\'–\', \'-\').replace(\'—\', \'-\')\n    if \'-\' not in t:\n        return \'\', \'\'\n    artista, _, titolo = t.partition(\'-\')\n    artista = _re.sub(r\'\\s+\', \' \', artista).strip(\' .,_\')\n    titolo = _re.sub(r\'\\s+\', \' \', titolo).strip(\' .,_-\')\n    if len(artista) < 2 or len(titolo) < 2:\n        return \'\', \'\'\n    return artista, titolo\n\n\ndef _testo_cache_file(self, chiave):\n    import hashlib\n    d = os.path.join(os.environ.get(\'LOCALAPPDATA\') or os.path.expanduser(\'~\'),\n                     \'KaraDom\', \'testi_al_volo\')\n    try:\n        os.makedirs(d, exist_ok=True)\n    except Exception:\n        pass\n    return os.path.join(d, hashlib.sha1(str(chiave).encode(\'utf-8\')).hexdigest()[:16] + \'.json\')\n\n\ndef _testo_sillabe(self, esito):\n    """Le sillabe nel formato del motore del testo (come un SYLT):\n    [(testo, ms)], con l\'a-capo IN TESTA alla prima sillaba di ogni riga e\n    lo spazio IN CODA all\'ultima sillaba di ogni parola.\n\n    Con le righe del LAM si fa UNA voce per riga: la riga si illumina\n    intera (ordine dell\'utente: "illuminare riga per riga anziche\'\n    sillabare" — le sillabe del LAM sono meno sicure di quelle a mano).\n    """\n    parole = esito.get(\'parole\') or []\n    if not parole:\n        return []\n    fuori = []\n    if esito.get(\'esito\') == \'righe\':\n        righe = {}\n        ordine = []\n        for w in parole:\n            r = w.get(\'r\', 0)\n            if r not in righe:\n                righe[r] = []\n                ordine.append(r)\n            righe[r].append(w)\n        for i, r in enumerate(ordine):\n            ws = righe[r]\n            testo = \' \'.join(str(w.get(\'w\', \'\')) for w in ws).strip()\n            if testo:\n                fuori.append(((\'\\n\' if i else \'\') + testo,\n                              int(round(float(ws[0].get(\'s\', 0)) * 1000))))\n        return fuori\n    riga_prima = None\n    for i, w in enumerate(parole):\n        sil = [str(x) for x in (w.get(\'sil\') or [w.get(\'w\', \'\')])]\n        ts = w.get(\'ts\') or [w.get(\'s\', 0)] * len(sil)\n        nuova = riga_prima is not None and w.get(\'r\') != riga_prima\n        # l\'ultima parola della riga NON ha lo spazio in coda (come nei SYLT)\n        ultima = i + 1 >= len(parole) or parole[i + 1].get(\'r\') != w.get(\'r\')\n        for j, (s, t) in enumerate(zip(sil, ts)):\n            testo = s\n            if j == 0 and nuova:\n                testo = \'\\n\' + testo\n            if j == len(sil) - 1 and not ultima:\n                testo = testo + \' \'\n            fuori.append((testo, int(round(float(t) * 1000))))\n        riga_prima = w.get(\'r\')\n    fuori.sort(key=lambda x: x[1])\n    return fuori\n\n\ndef _testo_chiedi(self, chiave, sorgente, file_giu, originale=False):\n    """Manda l\'audio al server e si tiene il testo che torna (in un\n    thread: puo\' metterci un minuto, col LAM).\n\n    `originale`: si manda l\'audio ORIGINALE subito, senza aspettare la\n    separazione (vedi `_voce_ibrido`): basta per l\'archivio. Senza, si\n    manda la VOCE separata, che serve al LAM."""\n    import json\n    if not chiave or not self._testo_acceso():\n        return\n    pronti = self.__dict__.setdefault(\'_testo_pronto\', {})\n    p = pronti.get(chiave)\n    if p:\n        p[\'base\'] = file_giu\n        # c\'e\' gia\' il testo, o una risposta definitiva: niente da chiedere.\n        # Con l\'originale non si richiede mai due volte.\n        if p.get(\'sillabe\') or p.get(\'definitivo\') or originale:\n            return\n    nome = (self.__dict__.get(\'_voce_titoli\', {}) or {}).get(chiave) or \'\'\n    if not nome and not str(chiave).startswith(\'yt:\'):\n        nome = os.path.basename(str(chiave))\n    # ⛔ un video che ha GIA\' il testo sopra (karaoke, lyrics video) non si\n    #    tocca: resta com\'e\' (vedi `_testo_ha_gia_il_testo`). PRIMA della\n    #    memoria su disco: un testo salvato in una prova non deve passare.\n    if self._testo_ha_gia_il_testo(chiave, nome):\n        pronti[chiave] = {\'sillabe\': [], \'base\': file_giu, \'esito\': \'ha_gia_testo\',\n                          \'definitivo\': True}\n        self._voce_log(\'testo: "%s" ha gia- il testo nel video, non ne aggiungo\'\n                       % str(nome or chiave)[:70])\n        return\n    # gia\' chiesto in passato? (si tiene sul disco, anche il "niente")\n    # ⛔ MA IL "NIENTE" NON VALE PER SEMPRE: le fonti crescono (LRCLIB, il\n    #    delta in casa), e un "niente" di ieri teneva il brano senza testo\n    #    per sempre — visto l\'11-09 sul brano spagnolo, che intanto era\n    #    diventato disponibile. Dopo una settimana si richiede.\n    try:\n        cf = self._testo_cache_file(chiave)\n        if os.path.exists(cf):\n            with open(cf, encoding=\'utf-8\') as f:\n                esito = json.load(f)\n            # ⛔ LE RISPOSTE VECCHIE SI BUTTANO: quando cambiano le regole\n            #    di controllo (soglie, spostamenti) quelle salvate prima\n            #    resterebbero in giro e si vedrebbe un testo fuori tempo\n            #    ("il testo e- molto in anticipo", utente 11-09)\n            if int(esito.get(\'v\') or 0) < 3:\n                self._voce_log(\'testo: risposta salvata con le regole vecchie, \'\n                               \'la butto e richiedo\')\n                os.remove(cf)\n                esito = None\n            vecchio = esito is not None and (\n                time.time() - os.path.getmtime(cf)) > 7 * 24 * 3600\n            if esito is None:\n                pass\n            elif esito.get(\'esito\') == \'niente\' and vecchio:\n                self._voce_log(\'testo: il "niente" di questo brano e- vecchio, \'\n                               \'richiedo (le fonti crescono)\')\n                os.remove(cf)\n            else:\n                self._testo_tieni(chiave, esito, file_giu, da=\'memoria\')\n                return\n    except Exception:\n        pass\n    # ⛔ NON ci si ferma se il nome non ha la forma "Artista - Titolo":\n    #    "non tutti i video hanno quel formato" (utente). Il nome si manda\n    #    com\'e\', insieme a quello che dice YouTube, e il server prova tutte\n    #    le letture — decide la voce. Se nessuna regge, parte il video.\n    artista, titolo = self._testo_artista_titolo(nome)\n    # si segna SUBITO che la richiesta e\' partita, cosi\' non ne parte una\n    # seconda uguale mentre la prima e\' in viaggio\n    if not p:\n        pronti[chiave] = {\'sillabe\': [], \'base\': file_giu, \'esito\': \'in_viaggio\'}\n    threading.Thread(target=self._testo_chiedi_ora,\n                     args=(chiave, sorgente, file_giu, artista, titolo, nome,\n                           originale),\n                     daemon=True).start()\n\n\ndef _testo_chiedi_ora(self, chiave, sorgente, file_giu, artista, titolo, nome=\'\',\n                      originale=False, testo_dato=\'\'):\n    import json\n    import subprocess\n    import urllib.request\n    import uuid\n    import numpy as np\n    t0 = time.time()\n    try:\n        info = self._voce_wav_dove(file_giu)\n        if not info:\n            return\n        r = subprocess.run([self._voce_ffmpeg(), \'-v\', \'error\', \'-i\', sorgente,\n                            \'-f\', \'s16le\', \'-ac\', \'2\', \'-ar\', str(info[\'freq\']), \'-\'],\n                           capture_output=True, timeout=120,\n                           creationflags=0x08000000 if os.name == \'nt\' else 0)\n        orig = np.frombuffer(r.stdout, dtype=\'<i2\')\n        orig = orig[:len(orig) // 2 * 2].reshape(-1, 2).astype(np.float32) / 32768.0\n        if originale:\n            # l\'audio com\'e\', subito: niente da aspettare\n            n = len(orig)\n            voce = np.clip(orig.mean(axis=1), -1, 1)\n        else:\n            # la VOCE = originale meno base pulita, in mono\n            with open(file_giu, \'rb\') as f:\n                f.seek(info[\'inizio\'])\n                base = np.frombuffer(f.read(info[\'quanti\']), dtype=\'<i2\')\n            base = base[:len(base) // 2 * 2].reshape(-1, 2).astype(np.float32) / 32768.0\n            n = min(len(orig), len(base))\n            voce = np.clip((orig[:n] - base[:n]).mean(axis=1), -1, 1)\n        if n < info[\'freq\'] * 20:\n            return\n        durata = n / float(info[\'freq\'])\n        r = subprocess.run([self._voce_ffmpeg(), \'-v\', \'error\', \'-f\', \'s16le\',\n                            \'-ar\', str(info[\'freq\']), \'-ac\', \'1\', \'-i\', \'-\',\n                            \'-ac\', \'1\', \'-ar\', \'22050\', \'-b:a\', \'64k\', \'-f\', \'mp3\', \'-\'],\n                           input=(voce * 32767).astype(\'<i2\').tobytes(),\n                           capture_output=True, timeout=120,\n                           creationflags=0x08000000 if os.name == \'nt\' else 0)\n        mp3 = r.stdout\n        if len(mp3) < 10000:\n            self._voce_log(\'testo: la voce da mandare non e- venuta (%s)\'\n                           % r.stderr.decode(\'utf-8\', \'replace\')[-120:])\n            return\n        # la richiesta, a mano (niente librerie in piu\' sul PC del cliente)\n        yt = self._testo_dati_youtube(chiave)\n        confine = uuid.uuid4().hex\n        parti = []\n        campi = [(\'artista\', artista), (\'titolo\', titolo), (\'durata\', \'%.1f\' % durata),\n                 (\'nome\', nome or \'\'), (\'testo_dato\', testo_dato or \'\'),\n                 (\'audio\', \'originale\' if originale else \'voce\')] + sorted(yt.items())\n        for k, v in campi:\n            parti.append((\'--%s\\r\\nContent-Disposition: form-data; name="%s"\\r\\n\\r\\n%s\\r\\n\'\n                          % (confine, k, v)).encode(\'utf-8\'))\n        parti.append((\'--%s\\r\\nContent-Disposition: form-data; name="voce"; \'\n                      \'filename="voce.mp3"\\r\\nContent-Type: audio/mpeg\\r\\n\\r\\n\'\n                      % confine).encode(\'utf-8\'))\n        corpo = b\'\'.join(parti) + mp3\n        # ⭐ col la voce si manda anche il BRANO ORIGINALE: serve solo se\n        #    non si trova nessun testo e il server deve ascoltare il brano\n        #    (ultima spiaggia). La trascrizione legge le parole dal mix.\n        if not originale:\n            grezzo = subprocess.run(\n                [self._voce_ffmpeg(), \'-v\', \'error\', \'-f\', \'s16le\',\n                 \'-ar\', str(info[\'freq\']), \'-ac\', \'1\', \'-i\', \'-\',\n                 \'-ac\', \'1\', \'-ar\', \'22050\', \'-b:a\', \'64k\', \'-f\', \'mp3\', \'-\'],\n                input=(np.clip(orig[:n].mean(axis=1), -1, 1) * 32767).astype(\'<i2\').tobytes(),\n                capture_output=True, timeout=120,\n                creationflags=0x08000000 if os.name == \'nt\' else 0).stdout\n            if len(grezzo) > 10000:\n                corpo += (\'\\r\\n--%s\\r\\nContent-Disposition: form-data; \'\n                          \'name="originale"; filename="originale.mp3"\\r\\n\'\n                          \'Content-Type: audio/mpeg\\r\\n\\r\\n\' % confine).encode(\'utf-8\')\n                corpo += grezzo\n        corpo += (\'\\r\\n--%s--\\r\\n\' % confine).encode(\'utf-8\')\n        url = \'https://lyrics.karadom.it/testo_al_volo/testo\'\n        try:\n            from .database import Database\n            url = str(Database.get_config(\'testo_al_volo_url\', url)).strip() or url\n        except Exception:\n            pass\n        req = urllib.request.Request(\n            url, data=corpo, method=\'POST\',\n            headers={\'Content-Type\': \'multipart/form-data; boundary=\' + confine,\n                     \'X-KaraDom-Testo\': \'kdTesto_9wQ4mZ2rX7\', \'User-Agent\': \'KaraDom\'})\n        self._voce_log(\'testo: chiedo al server "%s" (YouTube: %s - %s, canale %s; \'\n                       \'voce di %.0f s, %d KB)\'\n                       % (nome or (\'%s - %s\' % (artista, titolo)),\n                          yt.get(\'yt_artista\') or \'?\', yt.get(\'yt_brano\') or \'?\',\n                          yt.get(\'yt_canale\') or \'?\', durata, len(mp3) // 1024))\n        # ⚠️ l\'ultima spiaggia (il server ascolta il brano) puo\' durare\n        #    minuti: si aspetta, tanto gira in un thread suo\n        with urllib.request.urlopen(req, timeout=60 if originale else 900) as risp:\n            esito = json.loads(risp.read().decode(\'utf-8\'))\n    except Exception as e:\n        self._voce_log(\'testo: il server non risponde (%s): resta il video\' % str(e)[:120])\n        return\n    self._voce_log(\'testo: risposta in %.0f s: %s%s\'\n                   % (time.time() - t0, esito.get(\'esito\'),\n                      (\' da \' + str(esito.get(\'fonte\'))) if esito.get(\'fonte\') else \'\'))\n    # ⭐ il server ha trovato il brano su Genius ma non riesce a leggerlo:\n    #    lo scarichiamo NOI e glielo rimandiamo (una volta sola)\n    if esito.get(\'esito\') == \'prendi_da_genius\' and not testo_dato:\n        preso = self._testo_da_genius(esito.get(\'genius_id\'))\n        if len(preso.split()) >= 20:\n            return self._testo_chiedi_ora(chiave, sorgente, file_giu,\n                                          esito.get(\'artista\') or artista,\n                                          esito.get(\'titolo\') or titolo,\n                                          nome, originale, testo_dato=preso)\n        self._voce_log(\'testo: da genius.com non e- arrivato niente\')\n        esito = {\'esito\': \'niente\'}\n    # si tiene anche il "niente": non si richiede a ogni serata.\n    # ⛔ MA NON "serve la voce": e\' una risposta a meta\', salvata\n    #    bloccherebbe per sempre la richiesta col LAM\n    if esito.get(\'esito\') != \'serve_la_voce\':\n        try:\n            with open(self._testo_cache_file(chiave), \'w\', encoding=\'utf-8\') as f:\n                json.dump(esito, f, ensure_ascii=False)\n        except Exception:\n            pass\n    self._testo_tieni(chiave, esito, file_giu, da=\'server\')\n\n\ndef _testo_tieni(self, chiave, esito, file_giu, da=\'\'):\n    pronti = self.__dict__.setdefault(\'_testo_pronto\', {})\n    # ⭐ con l\'audio ORIGINALE l\'archivio non ha trovato niente: non e\' un\n    #    "niente" definitivo, si aspetta la voce separata per il LAM\n    if esito.get(\'esito\') == \'serve_la_voce\':\n        vecchio = pronti.get(chiave) or {}\n        if not vecchio.get(\'sillabe\'):\n            pronti[chiave] = {\'sillabe\': [], \'base\': file_giu, \'esito\': \'aspetta_voce\'}\n        self._voce_log(\'testo (%s): in archivio non c-e-, lo fara- il LAM quando \'\n                       \'la voce separata e- pronta\' % da)\n        return\n    sillabe = self._testo_sillabe(esito) if esito.get(\'esito\') in (\'sillabe\', \'righe\') else []\n    if len(sillabe) < 10:\n        # non si butta un testo gia\' trovato per un "niente" arrivato dopo\n        if (pronti.get(chiave) or {}).get(\'sillabe\'):\n            return\n        pronti[chiave] = {\'sillabe\': [], \'base\': file_giu, \'esito\': \'niente\',\n                          \'definitivo\': True}\n        self._voce_nota(chiave, testo=\'niente\')\n        self._voce_log(\'testo (%s): niente per questo brano, resta il video\' % da)\n        return\n    pronti[chiave] = {\'sillabe\': sillabe, \'base\': file_giu,\n                      \'esito\': esito.get(\'esito\'), \'fonte\': esito.get(\'fonte\'),\n                      \'titolo\': esito.get(\'titolo\') or \'\', \'definitivo\': True}\n    self._voce_nota(chiave, testo=esito.get(\'esito\'))\n    self._voce_log(\'testo (%s): PRONTO, %d %s: al play parte col testo al posto \'\n                   \'del video\' % (da, len(sillabe),\n                                  \'righe\' if esito.get(\'esito\') == \'righe\' else \'sillabe\'))\n    # ⭐ la scaletta si ridisegna, o la ♪ non comparirebbe: quando il testo\n    #    arriva la riga e\' gia\' PRONTA e nessuno la ridisegna piu\'\n    #    ("e\' arrivato al 100% senza testo", utente 11-09)\n    try:\n        fn = getattr(self, \'_voce_ridisegna\', None)\n        if fn:\n            self.master.after(0, fn)\n    except Exception:\n        pass\n\n\ndef _testo_scambio(self, file_path):\n    """Al caricamento di un VIDEO: se c\'e\' il testo pronto e la voce e\'\n    giu\', si carica la BASE PULITA al posto del video. Torna il file da\n    caricare (o quello di prima, se non c\'e\' niente da fare)."""\n    self._testo_da_innestare = None\n    self._testo_sottotitolo = None\n    self._testo_nome_mostrato = None\n    try:\n        if not self._testo_acceso() or not getattr(self, \'voce_giu\', 0):\n            return file_path\n        s = str(file_path or \'\')\n        e_video = s.lower().startswith((\'http://\', \'https://\')) or \\\n            os.path.splitext(s)[1].lower() in (\'.mp4\', \'.mkv\', \'.webm\', \'.avi\',\n                                               \'.mov\', \'.wmv\', \'.flv\', \'.m4v\',\n                                               \'.mpg\', \'.mpeg\')\n        if not e_video:\n            return file_path\n        # ⛔ NON BASTA LA CHIAVE DEL FILE: un video di YouTube puo\' partire\n        #    dal FLUSSO (un indirizzo googlevideo che il codice del video\n        #    non ce l\'ha) invece che dall\'mp4 scaricato. Il testo c\'era ma\n        #    non veniva trovato (utente, 11-09: "non associa il testo").\n        #    Si prova anche col brano della riga e con cio\' che suona.\n        pronti = self.__dict__.get(\'_testo_pronto\') or {}\n        chiave, p = None, None\n        for k in (self._voce_chiave(file_path),\n                  self._voce_chiave(getattr(self, \'_voce_brano_scelto\', None)),\n                  self._voce_chiave_di_cio_che_suona(file_path)):\n            if k and (pronti.get(k) or {}).get(\'sillabe\'):\n                chiave, p = k, pronti[k]\n                break\n        if not p:\n            return file_path\n        # ⭐ SOPRA IL VIDEO: il video resta, il testo e\' un sottotitolo\n        #    karaoke che VLC disegna sopra (vedi `_testo_ass`)\n        if self._testo_modo() == \'sopra\':\n            import hashlib\n            import tempfile\n            h = hashlib.sha1(str(chiave).encode(\'utf-8\')).hexdigest()[:12]\n            # la misura VERA del video: il testo ci si adatta dentro\n            larg, altez = self._testo_misura_video(file_path)\n            # due sottotitoli: 5 righe per il monitor principale, 7 per il\n            # pubblico (la riga da cantare sempre al centro)\n            fatti = []\n            for n in (5, 7):\n                ass = os.path.join(tempfile.gettempdir(), \'kd_testo_%s_%dx%d_%d.ass\'\n                                   % (h, larg, altez, n))\n                with open(ass, \'w\', encoding=\'utf-8-sig\') as f:\n                    f.write(self._testo_ass(p[\'sillabe\'], righe=(p.get(\'esito\') == \'righe\'),\n                                            n_righe=n, larg=larg, alt=altez))\n                fatti.append(ass)\n            self._testo_sottotitolo = tuple(fatti)\n            self._voce_log(\'testo: %s parte col VIDEO e il testo SOPRA (%s), \'\n                           \'video %dx%d\' % (chiave, p.get(\'esito\'), larg, altez))\n            return file_path\n        base = p.get(\'base\')\n        if not base or not os.path.exists(base):\n            return file_path\n        self._testo_da_innestare = (chiave, p)\n        # ⭐ a schermo il nome del VIDEO, non quello del file di lavoro\n        #    ("mette kd_voce al posto del titolo" — utente)\n        self._testo_nome_mostrato = file_path\n        self._voce_log(\'testo: %s parte come BASE COL TESTO (%s), niente video\'\n                       % (chiave, p.get(\'esito\')))\n        return base\n    except Exception as e:\n        self._voce_log(\'testo: scambio non fatto (%s)\' % e)\n        return file_path\n\n\ndef _testo_innesta(self):\n    """Subito dopo `engine.extract`: le sillabe al motore del testo, come\n    se venissero dal SYLT di una base mp3."""\n    # ⭐ SOPRA IL VIDEO: il sottotitolo karaoke a tutti e due i lettori\n    #    (monitor principale e monitor PUBBLICO, che ha il suo)\n    ass = getattr(self, \'_testo_sottotitolo\', None)\n    self._testo_sottotitolo = None\n    self._testo_ass_uri = None\n    if ass and getattr(self.engine, \'is_video\', False):\n        try:\n            ass5, ass7 = ass if isinstance(ass, tuple) else (ass, ass)\n            uri = \'file:///\' + os.path.abspath(ass5).replace(\'\\\\\', \'/\')\n            ok = self._testo_metti_sottotitolo(\n                getattr(self.engine, \'vlc_player\', None), uri)\n            # il lettore del monitor pubblico nasce DOPO: lo aggancia\n            # `_testo_sottotitolo_pubblico` (7 righe), quando lo si crea\n            self._testo_ass_uri = \'file:///\' + os.path.abspath(ass7).replace(\'\\\\\', \'/\')\n            self._voce_log(\'testo: sottotitolo karaoke sopra il video: %s\'\n                           % (\'messo\' if ok else \'NON messo, resta il video\'))\n        except Exception as e:\n            self._voce_log(\'testo: sottotitolo non messo (%s): resta il video\' % e)\n    da = getattr(self, \'_testo_da_innestare\', None)\n    self._testo_da_innestare = None\n    if not da:\n        return\n    chiave, p = da\n    try:\n        sill = list(p[\'sillabe\'])\n        self.engine.syllables_data = sill\n        self.engine.full_text = \'\'.join(s for s, _t in sill)\n        self.engine.is_video = False\n        # il titolo che il server ha riconosciuto; se no, quello del nome\n        t = p.get(\'titolo\') or \'\'\n        if not t:\n            nome = (self.__dict__.get(\'_voce_titoli\', {}) or {}).get(chiave) or \'\'\n            t = self._testo_artista_titolo(nome)[1]\n        if t:\n            self.engine.title = t.upper()\n        self._voce_log(\'testo: %d voci date al motore del testo\' % len(sill))\n    except Exception as e:\n        self._voce_log(\'testo: innesto non riuscito (%s)\' % e)\n\n\ndef load_file(self, file_path: str, tonalita: int = 0, solo_audio: bool = False) -> bool:\n    dbg("SYSTEM", f"load_file: {file_path} ton={tonalita} solo_audio={solo_audio}")\n    """\n    Carica file karaoke - ferma riproduzione precedente se attiva\n    tonalita: semitoni trasposizione (-12 a +12, default 0)\n    solo_audio: True se chiamato dal sottofondo in modalità solo audio\n    NOTA: Pitch per video non supportato (limitazione VLC)\n    """\n    # ⏱️ Diagnostica lentezza avvio riproduzione: timer per fase, per capire\n    # da dati reali (non a intuito) quale passo e\' lento quando succede.\n    _lf_t0 = time.time()\n    def _lf_tick(label):\n        nonlocal _lf_t0\n        now = time.time()\n        print(f"⏱️ [LOADFILE-TIMING] {label}: {(now-_lf_t0)*1000:.0f}ms")\n        _lf_t0 = now\n\n    # ✅ Salva flag solo_audio per uso in questa chiamata\n    if solo_audio:\n        # Sottofondo: salva volume utente prima che venga sovrascritto\n        if not hasattr(self, \'_pre_sottofondo_volume\'):\n            self._pre_sottofondo_volume = self._user_volume\n            print(f"🔊 Salvato volume utente: {self._user_volume:.2f}")\n    else:\n        # Brano normale: ripristina volume utente se sottofondo l\'aveva cambiato\n        if hasattr(self, \'_pre_sottofondo_volume\'):\n            self._user_volume = self._pre_sottofondo_volume\n            del self._pre_sottofondo_volume\n            print(f"🔊 Ripristinato volume utente: {self._user_volume:.2f}")\n        # ✅ Se il sottofondo è attivo, mettilo in pausa e salva posizione\n        if self._sottofondo_manager and self._sottofondo_manager.is_playing:\n            self._sottofondo_manager.pause_for_user_song(self.get_current_position_ms())\n    self._sottofondo_solo_audio = solo_audio\n\n    # ⭐ TESTO AL VOLO (vedi `_testo_scambio`): un video col testo pronto e\n    #    la voce giu\' parte come BASE COL TESTO. Se non c\'e\' niente di\n    #    pronto `file_path` resta quello di prima e tutto va come sempre.\n    if not solo_audio:\n        file_path = self._testo_scambio(file_path)\n    else:\n        self._testo_da_innestare = None\n\n    # ✅ BLOCCA aggiornamenti monitor durante la transizione\n    self._seeking = True\n    self._play_generation += 1  # ✅ Invalida tutte le callback stale\n    self._file_unloaded = False  # ✅ Reset: stiamo caricando un file\n    self._loading_new_file = True  # ✅ Blocca cleanup thread vecchio\n\n    # FIX: reset velocita\' al brano nuovo (la velocita\' del brano\n    # precedente NON deve trasferirsi al successivo).\n    self.current_speed = 1.0\n\n    # FIX: aggiorna anche la UI se registrata (la libreria carica i brani\n    # direttamente senza passare per le callback di ui.py, quindi devo\n    # notificare la UI da qui).\n    try:\n        if hasattr(self, \'_ui_speed_var\') and self._ui_speed_var is not None:\n            self._ui_speed_var.set(1.0)\n        if hasattr(self, \'_ui_speed_label\') and self._ui_speed_label is not None:\n            self._ui_speed_label.config(text="100%")\n    except Exception:\n        pass\n\n    # ✅ Se sta riproducendo O è in pausa, ferma prima\n    if self.is_playing or self.is_paused:\n        # ✅ Se in pausa, riprendi PRIMA di stop (evita stati incoerenti dei player)\n        if self.is_paused:\n            try:\n                if self.engine.is_video and self.engine.vlc_player:\n                    self.engine.vlc_player.set_pause(0)\n                    if self.engine.vlc_player_pubblico:\n                        self.engine.vlc_player_pubblico.set_pause(0)\n                elif self.is_bass_audio and self.bass_engine:\n                    self.bass_engine.pause()  # toggle → resume\n                elif self.is_mpv_audio and self.mpv_player:\n                    self.mpv_player[\'pause\'] = False\n                elif self.is_vlc_audio and self.vlc_audio:\n                    self.vlc_audio.set_pause(0)\n                elif self.is_midi and self.fs:\n                    self.fs.pause()  # toggle → riprendi\n                else:\n                    pygame.mixer.music.unpause()\n            except:\n                pass\n            self.is_paused = False\n            self.is_playing = True\n        self.stop(quick=True)  # Stop rapido senza fade\n        # ✅ Invalida le callback delayed (safety_clear, nuclear_clear)\n        #    schedulate da stop() che cancellerebbero il testo del nuovo brano\n        self._play_generation += 1\n    \n    # ✅ Se il file precedente era video o CDG, ripristina layout\n    if self.engine.is_video or self.is_cdg:\n        self.monitor.video_canvas.pack_forget()\n        self.monitor.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n        self.monitor.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n        self.monitor.text_widget.pack(fill=\'both\', expand=True)\n        print("🔄 Layout ripristinato (video/CDG → testo)")\n        \n        # ✅ RIPRISTINA ANCHE MONITOR PUBBLICO\n        if self.monitor_pubblico:\n            try:\n                pub = self.monitor_pubblico.monitor_frame\n                pub.video_canvas.pack_forget()\n                pub.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                pub.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                pub.text_widget.pack(fill=\'both\', expand=True)\n                print("🔄 Layout monitor pubblico ripristinato")\n            except:\n                pass\n    \n    # ✅ Reset flag video, CDG e audio\n    self.engine.is_video = False\n    self.is_cdg = False\n    self.is_kfn = False\n    self.is_mkf = False\n    self.is_vlc_audio = False\n    self.is_mpv_audio = False  # ✅ Reset MPV audio\n    self.is_bass_audio = False  # ✅ Reset BASS audio\n    self._pitched_file = None\n    self._video_pitch_active = False\n    # ✅ Elimina WAV estratto da video (può essere ~100MB)\n    if self._video_audio_extracted:\n        try:\n            if os.path.exists(self._video_audio_extracted):\n                os.remove(self._video_audio_extracted)\n        except:\n            pass\n    self._video_audio_extracted = None  # ✅ Reset audio estratto\n    # ✅ Ripristina audio video se era mutato\n    if self.engine.vlc_player:\n        try: self.engine.vlc_player.audio_set_mute(False)\n        except: pass\n    # ✅ Stop MPV se attivo\n    if self.mpv_player:\n        try: self.mpv_player.command("stop")\n        except: pass\n    if self.vlc_audio:\n        try:\n            self.vlc_audio.stop()\n            self.vlc_audio.set_media(None)  # ✅ Rilascia file lock\n        except:\n            pass\n        self.vlc_audio = None\n    if hasattr(self.engine, \'is_cdg\'):\n        self.engine.is_cdg = False\n    if hasattr(self.engine, \'is_kfn\'):\n        self.engine.is_kfn = False\n    if hasattr(self.engine, \'is_mkf\'):\n        self.engine.is_mkf = False\n    \n    # ✅ Se c\'era un file diverso caricato, libera le risorse\n    _prev = self._original_file or self.current_file\n    if _prev and _prev != file_path:\n        try:\n            pygame.mixer.music.unload()\n            print(f"🗑️ Liberato file precedente: {Path(self.current_file).name}")\n        except:\n            pass\n    \n    print(f"\\n{\'=\'*60}")\n    print(f"📂 Caricamento: {Path(file_path).name}")\n    self.last_error = ""  # ✅ Reset errore\n    # ✅ Sincronizza pitch corrente con tonalita richiesta\n    self.current_pitch = tonalita\n    if tonalita != 0:\n        print(f"🎵 Pitch: {tonalita:+d} semitoni")\n    print(f"{\'=\'*60}")\n    \n    # ✅ Se è un audio (mp3, wav, ecc.) e ha un CDG associato → usa il CDG\n    ext_lower = Path(file_path).suffix.lower()\n    if ext_lower in (\'.mp3\', \'.wav\', \'.ogg\', \'.m4a\', \'.flac\', \'.aac\', \'.wma\'):\n        cdg_path = Path(file_path).with_suffix(\'.cdg\')\n        if cdg_path.exists():\n            print(f"🎤 CDG associato trovato → uso {cdg_path.name}")\n            file_path = str(cdg_path)\n    \n    _lf_tick("prima di engine.extract (stop/cleanup/layout precedenti)")\n    success = self.engine.extract(file_path)\n    _lf_tick("engine.extract (detect_format + parsing testo/SYLT/video)")\n    # ⭐ testo al volo: le sillabe al motore, come da un SYLT (se ce ne sono)\n    if success:\n        self._testo_innesta()\n\n    if success:\n        # ✅ Sottofondo solo audio: salta caricamento testo nei monitor\n        _skip_text = getattr(self, \'_sottofondo_solo_audio\', False)\n        \n        # ⭐ testo al volo: a schermo il nome del VIDEO, non del file di\n        #    lavoro della base pulita (vedi `_testo_scambio`)\n        _nome_a_video = getattr(self, \'_testo_nome_mostrato\', None) or file_path\n        self._testo_nome_mostrato = None\n        if not _skip_text:\n            # ✅ Carica info nella barra (anche per video)\n            self.monitor.load_text(\n                self.engine.full_text,\n                self.engine.syllables_data,\n                self.engine,  # Passo engine con metadati\n                _nome_a_video  # Passo filepath come filename\n            )\n            \n            # ✅ CARICA ANCHE NEL MONITOR PUBBLICO\n            if self.monitor_pubblico:\n                self.monitor_pubblico.monitor_frame.load_text(\n                    self.engine.full_text,\n                    self.engine.syllables_data,\n                    self.engine,\n                    # URL intera per gli stream (cosi\' load_text riconosce\n                    # http e usa il titolo vero, non "videoplayback?...")\n                    _nome_a_video if str(_nome_a_video).lower().startswith(\n                        ("http://", "https://")) else Path(_nome_a_video).name\n                )\n                print("✅ Testo caricato in monitor pubblico")\n        else:\n            print("🔇 [SOTTOFONDO] Solo audio: testo non caricato nei monitor")\n        \n        # ✅ Invia al web karaocanto.it\n        if self.web_sync.connected:\n            title = getattr(self.engine, \'title\', \'\') or Path(file_path).stem\n            artist = getattr(self.engine, \'artist\', \'\')\n            dbg("SYSTEM", f"WebSync send_song_start: {title}")\n            self.web_sync.send_song_start(title, artist, self.engine.syllables_data)\n        \n        self.current_file = file_path\n        self._original_file = file_path  # ✅ Salva path originale per DB/display\n        dbg("SYSTEM", f"load_file OK: {file_path}")\n        \n        # ✅ NORMALIZZAZIONE VOLUME — gain real-time (solo ALZA brani bassi, mai abbassa)\n        self.normalization_gain = 1.0  # Default: nessuna modifica\n        if self.normalization_enabled:\n            from .database import Database as _DB\n            gain = _DB.get_volume_gain(file_path)\n            \n            # ✅ KFN: se non in cache, analizza l\'audio estratto al volo\n            if gain is None and getattr(self.engine, \'is_kfn\', False):\n                kfn_audio = getattr(self.engine, \'kfn_audio_path\', None)\n                if kfn_audio and os.path.exists(kfn_audio):\n                    try:\n                        from .normalizzazione import analizza_lufs, calcola_gain\n                        print(f"🔊 Normalizzazione: analisi KFN al volo...")\n                        lufs, measured = analizza_lufs(kfn_audio)\n                        if lufs is not None:\n                            gain = calcola_gain(lufs)\n                            _DB.set_volume_gain(file_path, lufs, gain)\n                            print(f"🔊 Normalizzazione: KFN analizzato → {lufs:.1f} LUFS, gain={gain:.2f}")\n                    except Exception as e:\n                        print(f"⚠️ Normalizzazione KFN al volo fallita: {e}")\n            \n            if gain is not None and gain > 1.05:\n                # ✅ BRANO BASSO: applica gain real-time in riproduzione\n                import math\n                db_change = 20 * math.log10(gain)\n                self.normalization_gain = gain\n                print(f"🔊 Normalizzazione: 🔺 ALZO real-time gain={gain:.2f} ({db_change:+.1f}dB)")\n            elif gain is not None:\n                print(f"🔊 Normalizzazione: ≈ OK (brano già forte, gain={gain:.2f})")\n            else:\n                print(f"🔊 Normalizzazione: brano non in cache")\n        else:\n            print(f"🔊 Normalizzazione: DISATTIVATA (normalization_enabled={self.normalization_enabled})")\n        \n        # ✅ SOTTOFONDO SOLO AUDIO: forza audio-only per video\n        if getattr(self, \'_sottofondo_solo_audio\', False) and self.engine.is_video:\n            print("🔇 [SOTTOFONDO] Solo audio: converto video in audio-only")\n            # Ferma VLC video player se creato dall\'engine\n            if self.engine.vlc_player:\n                try:\n                    self.engine.vlc_player.stop()\n                except:\n                    pass\n            self.engine.is_video = False\n            \n            # ✅ Ripristina layout monitor (engine.extract aveva nascosto logo e testo)\n            try:\n                self.monitor.video_canvas.pack_forget()\n                self.monitor.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                self.monitor.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                self.monitor.text_widget.pack(fill=\'both\', expand=True)\n                if self.monitor.logo_label:\n                    self.monitor.logo_label.place(relx=0.5, rely=0.5, anchor=\'center\')\n                print("🖼️ [SOTTOFONDO] Layout monitor principale ripristinato con logo")\n            except:\n                pass\n            # ✅ Ripristina anche monitor pubblico\n            if self.monitor_pubblico:\n                try:\n                    pub = self.monitor_pubblico.monitor_frame\n                    pub.video_canvas.pack_forget()\n                    pub.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                    pub.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                    pub.text_widget.pack(fill=\'both\', expand=True)\n                    if pub.logo_label:\n                        pub.logo_label.place(relx=0.5, rely=0.5, anchor=\'center\')\n                    print("🖼️ [SOTTOFONDO] Layout monitor pubblico ripristinato con logo")\n                except:\n                    pass\n            # Carica come audio via MPV o VLC senza video\n            if self.mpv_player:\n                try:\n                    self.is_mpv_audio = True\n                    self.is_vlc_audio = False\n                    self.mpv_player.command("stop")\n                    self._mpv_pending_file = file_path\n                    print(f"✅ [SOTTOFONDO] Audio video via MPV (no video)")\n                except Exception as e:\n                    print(f"⚠️ MPV fallito: {e}")\n                    self.is_mpv_audio = False\n            elif self.engine.vlc_available and self.engine.ensure_vlc():\n                try:\n                    self.is_vlc_audio = True\n                    if self.vlc_audio:\n                        self.vlc_audio.stop()\n                    self.vlc_audio = self.engine.vlc_instance.media_player_new()\n                    media = self.engine.vlc_instance.media_new(file_path.replace(\'\\\\\', \'/\'))\n                    media.add_option(\':no-video\')\n                    self.vlc_audio.set_media(media)\n                    print(f"✅ [SOTTOFONDO] Audio video via VLC (no video)")\n                except Exception as e:\n                    print(f"⚠️ VLC audio fallito: {e}")\n                    self.is_vlc_audio = False\n            # Reset flag dopo uso\n            # _sottofondo_solo_audio gestito da SottoFondoManager\n        \n        # ⚠️ CON UN VIDEO I FLAG DEL BRANO PRECEDENTE VANNO AZZERATI QUI.\n        # Erano azzerati solo nel ramo "non video" piu\' sotto: dopo un MIDI\n        # restava is_midi=True anche caricando un video, e la tonalita\' non\n        # partiva piu\' (set_pitch da\' l\'audio del video a BASS solo se\n        # `not is_midi`). Sintomo: suoni un MIDI, poi un video, e il tono\n        # non cambia finche\' non si passa da un mp3.\n        if self.engine.is_video:\n            self.is_midi = False\n            self.is_bass_audio = False\n            self.is_cdg = False\n\n        # ===== GESTIONE AUDIO (NON VIDEO) =====\n        if not self.engine.is_video:\n            # ===== GESTIONE CDG (CD+Graphics) =====\n            ext = Path(file_path).suffix.lower()\n            print(f"[LOAD] ext={ext}, is_cdg={getattr(self.engine, \'is_cdg\', False)}, "\n                  f"vlc_available={self.engine.vlc_available}, file={Path(file_path).name}")\n            \n            if ext == \'.cdg\' and getattr(self.engine, \'is_cdg\', False):\n                print(f"🎤 File CDG rilevato - carico audio associato")\n                self.is_midi = False\n                self.is_cdg = True\n                \n                # ✅ Carica audio CDG via MPV (pitch istantaneo) o VLC fallback\n                cdg_audio = self.engine.cdg_audio_path\n                \n                if self.mpv_player and cdg_audio:\n                    try:\n                        self.is_mpv_audio = True\n                        self.is_vlc_audio = False\n                        self.mpv_player.command("stop")\n                        self._mpv_pending_file = cdg_audio\n                        print(f"✅ Audio CDG via MPV: {Path(cdg_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE CDG")\n                    except Exception as e:\n                        print(f"⚠️ MPV CDG fallito: {e}")\n                        self.is_mpv_audio = False\n                elif self.engine.vlc_available and self.engine.ensure_vlc() and cdg_audio:\n                    try:\n                        self.is_vlc_audio = True\n                        if self.vlc_audio:\n                            self.vlc_audio.stop()\n                        self.vlc_audio = self.engine.vlc_instance.media_player_new()\n                        filepath_vlc = cdg_audio.replace(\'\\\\\', \'/\')\n                        media = self.engine.vlc_instance.media_new(filepath_vlc)\n                        if media is None:\n                            raise ValueError(f"VLC media_new None per: {filepath_vlc}")\n                        media.add_option(\':no-video\')  # ✅ Nessuna finestra video\n                        self.vlc_audio.set_media(media)\n                        print(f"✅ Audio CDG via VLC: {Path(cdg_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE CDG")\n                    except Exception as e:\n                        print(f"⚠️ VLC audio CDG fallito, uso pygame: {e}")\n                        self.is_vlc_audio = False\n                        if self.vlc_audio:\n                            try:\n                                self.vlc_audio.stop()\n                                self.vlc_audio.set_media(None)\n                            except:\n                                pass\n                            self.vlc_audio = None\n                        try:\n                            pygame.mixer.music.load(cdg_audio)\n                            print(f"✅ Audio CDG via pygame: {Path(cdg_audio).name}")\n                        except Exception as pe:\n                            self.last_error = f"Errore caricamento audio CDG: {pe}"\n                            print(f"⚠️ {self.last_error}")\n                            success = False\n                elif cdg_audio:\n                    # Fallback pygame se VLC non disponibile\n                    self.is_vlc_audio = False\n                    try:\n                        pygame.mixer.music.load(cdg_audio)\n                        print(f"✅ Audio CDG via pygame: {Path(cdg_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE CDG")\n                    except Exception as e:\n                        self.last_error = f"Errore caricamento audio CDG: {e}"\n                        print(f"⚠️ {self.last_error}")\n                        success = False\n                else:\n                    self.last_error = "Nessun file audio associato al CDG"\n                    print(f"⚠️ {self.last_error}")\n                    success = False\n            # ===== GESTIONE KFN (Karafun) =====\n            elif ext == \'.kfn\' and getattr(self.engine, \'is_kfn\', False):\n                kfn_audio = self.engine.kfn_audio_path\n                kfn_is_midi = getattr(self.engine, \'is_midi\', False)\n                self.is_cdg = False\n                self.is_kfn = True\n                \n                if kfn_is_midi:\n                    # ===== KFN CON MIDI =====\n                    print(f"🎤 File KFN rilevato - audio MIDI")\n                    self.is_midi = True\n                    self.is_bass_audio = False\n                    self.is_mpv_audio = False\n                    self.is_vlc_audio = False\n\n                    # ===== EXPANDER MIDI (X-Light 4 & simili) — moduli/expander_midi.py =====\n                    _exp = None\n                    try:\n                        from .expander_midi import get_expander_player\n                        _exp = get_expander_player()\n                    except Exception as e:\n                        print(f"⚠️ Expander MIDI non disponibile: {e}")\n                    if _exp:\n                        self.fs = _exp\n                    # ===== fine EXPANDER MIDI =====\n\n                    # ✅ Prova BASS Engine (MIDI), fallback a FluidSynth\n                    try:\n                        from .bass_engine import is_bass_available, get_bass_engine\n                        if is_bass_available() and not _exp:\n                            _be = get_bass_engine()\n                            if not _be.initialized:\n                                _be.initialize()\n                            if _be.initialized:\n                                self.fs = _be\n                                print("✅ Usando BASS Engine per KFN MIDI")\n                    except Exception as e:\n                        print(f"⚠️ BASS Engine KFN MIDI non disponibile: {e}")\n                    \n                    if not self.fs:\n                        try:\n                            from .fluidsynth_player import get_fluidsynth_player\n                            self.fs = get_fluidsynth_player()\n                            if self.fs and not self.fs.initialized:\n                                if not self.fs.initialize():\n                                    self.fs = None\n                        except Exception as e:\n                            print(f"⚠️ FluidSynth KFN non disponibile: {e}")\n                            self.fs = None\n                    \n                    if self.fs and self.fs.initialized:\n                        self.fs.load(kfn_audio)\n                        if tonalita != 0 and hasattr(self.fs, \'set_pitch\'):\n                            self.fs.set_pitch(tonalita)\n                        midi_dur = self.fs.get_duration_ms()\n                        if midi_dur > 0:\n                            self.engine.total_duration_ms = midi_dur\n                        print(f"✅ KFN MIDI caricato: {Path(kfn_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE KFN")\n                    else:\n                        self.last_error = "Nessun engine MIDI disponibile per KFN"\n                        print(f"⚠️ {self.last_error}")\n                        success = False\n                else:\n                    # ===== KFN CON MP3 =====\n                    print(f"🎤 File KFN rilevato - audio MP3")\n                    self.is_midi = False\n                    \n                    # ✅ BASS Engine (qualità massima)\n                    try:\n                        from .bass_engine import is_bass_available, get_bass_engine\n                        if is_bass_available():\n                            _be = get_bass_engine()\n                            if not _be.initialized:\n                                _be.initialize()\n                            if _be.initialized and _be.load(kfn_audio):\n                                self.bass_engine = _be\n                                self.is_bass_audio = True\n                                self.is_mpv_audio = False\n                                self.is_vlc_audio = False\n                                if tonalita != 0:\n                                    _be.set_pitch(tonalita)\n                                bass_dur = _be.get_duration_ms()\n                                if bass_dur > 0:\n                                    self.engine.total_duration_ms = bass_dur\n                                print(f"✅ Audio KFN via BASS: {Path(kfn_audio).name}")\n                                print(f"✅ PRONTO PER LA RIPRODUZIONE KFN")\n                    except Exception as e:\n                        print(f"⚠️ BASS KFN fallito: {e}")\n                        self.is_bass_audio = False\n                    \n                    # ✅ Fallback MPV\n                    if not self.is_bass_audio and self.mpv_player and kfn_audio:\n                        try:\n                            self.is_mpv_audio = True\n                            self.is_vlc_audio = False\n                            self.mpv_player.command("stop")\n                            self._mpv_pending_file = kfn_audio\n                            print(f"✅ Audio KFN via MPV: {Path(kfn_audio).name}")\n                            print(f"✅ PRONTO PER LA RIPRODUZIONE KFN")\n                        except Exception as e:\n                            print(f"⚠️ MPV KFN fallito: {e}")\n                            self.is_mpv_audio = False\n                    \n                    # ✅ Fallback pygame\n                    if not self.is_bass_audio and not self.is_mpv_audio:\n                        try:\n                            pygame.mixer.music.load(kfn_audio)\n                            print(f"✅ Audio KFN via pygame: {Path(kfn_audio).name}")\n                            print(f"✅ PRONTO PER LA RIPRODUZIONE KFN")\n                        except Exception as e:\n                            self.last_error = f"Errore caricamento audio KFN: {e}"\n                            print(f"⚠️ {self.last_error}")\n                            success = False\n            \n\n            # ===== GESTIONE MKF (KaraBox) =====\n            elif ext == \'.mkf\' and getattr(self.engine, \'is_mkf\', False):\n                mkf_audio = self.engine.mkf_audio_path\n                self.is_cdg = False\n                self.is_kfn = False\n                self.is_mkf = True\n                self.is_midi = False\n\n                print(f"🎤 File MKF rilevato - audio recuperato")\n\n                # ✅ BASS Engine prima scelta\n                try:\n                    from .bass_engine import is_bass_available, get_bass_engine\n                    if is_bass_available():\n                        _be = get_bass_engine()\n                        if not _be.initialized:\n                            _be.initialize()\n                        if _be.initialized and _be.load(mkf_audio):\n                            self.bass_engine = _be\n                            self.is_bass_audio = True\n                            self.is_mpv_audio = False\n                            self.is_vlc_audio = False\n                            if tonalita != 0:\n                                _be.set_pitch(tonalita)\n                            bass_dur = _be.get_duration_ms()\n                            if bass_dur > 0:\n                                self.engine.total_duration_ms = bass_dur\n                            print(f"✅ Audio MKF via BASS: {Path(mkf_audio).name}")\n                            print(f"✅ PRONTO PER LA RIPRODUZIONE MKF")\n                except Exception as e:\n                    print(f"⚠️ BASS MKF fallito: {e}")\n                    self.is_bass_audio = False\n\n                # ✅ Fallback MPV\n                if not self.is_bass_audio and self.mpv_player and mkf_audio:\n                    try:\n                        self.is_mpv_audio = True\n                        self.is_vlc_audio = False\n                        self.mpv_player.command("stop")\n                        self._mpv_pending_file = mkf_audio\n                        print(f"✅ Audio MKF via MPV: {Path(mkf_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE MKF")\n                    except Exception as e:\n                        print(f"⚠️ MPV MKF fallito: {e}")\n                        self.is_mpv_audio = False\n\n                # ✅ Fallback pygame\n                if not self.is_bass_audio and not self.is_mpv_audio:\n                    try:\n                        pygame.mixer.music.load(mkf_audio)\n                        print(f"✅ Audio MKF via pygame: {Path(mkf_audio).name}")\n                        print(f"✅ PRONTO PER LA RIPRODUZIONE MKF")\n                    except Exception as e:\n                        self.last_error = f"Errore caricamento audio MKF: {e}"\n                        print(f"⚠️ {self.last_error}")\n                        success = False\n\n            # ===== GESTIONE MIDI CON MUTE TRACK 4 + PITCH =====\n            elif ext in [\'.mid\', \'.midi\', \'.kar\']:\n                print(f"🎹 File MIDI rilevato - Pitch: {tonalita:+d} semitoni")\n                self.is_midi = True  # ✅ FLAG MIDI\n\n                # ===== EXPANDER MIDI (X-Light 4 & simili) — moduli/expander_midi.py =====\n                # Se c\'è un expander collegato suona lui e il SoundFont interno\n                # resta spento. Se non c\'è, _exp è None e tutto prosegue come prima.\n                _exp = None\n                try:\n                    from .expander_midi import get_expander_player\n                    _exp = get_expander_player()\n                except Exception as e:\n                    print(f"⚠️ Expander MIDI non disponibile: {e}")\n                if _exp:\n                    self.fs = _exp\n                # ===== fine EXPANDER MIDI =====\n\n                # ✅ Prova BASS Engine (DLL), fallback a FluidSynth\n                try:\n                    from .bass_engine import is_bass_available, get_bass_engine\n                    if is_bass_available() and not _exp:\n                        _be = get_bass_engine()\n                        if not _be.initialized:\n                            print("🎹 Inizializzazione BASS Engine...")\n                            if _be.initialize():\n                                self.fs = _be\n                                print("✅ Usando BASS Engine per MIDI")\n                            else:\n                                print("⚠️ BASS Engine init fallito, provo FluidSynth...")\n                        else:\n                            self.fs = _be\n                            print("✅ Usando BASS Engine (già inizializzato)")\n                except Exception as e:\n                    print(f"⚠️ BASS Engine non disponibile: {e}")\n                \n                if not self.fs:\n                    try:\n                        from .fluidsynth_player import get_fluidsynth_player\n                        self.fs = get_fluidsynth_player()\n                        if self.fs and not self.fs.initialized:\n                            print("🎹 Inizializzazione FluidSynth...")\n                            if not self.fs.initialize():\n                                self.last_error = "Inizializzazione FluidSynth fallita (MIDI senza audio)"\n                                print(f"⚠️ {self.last_error}")\n                                self.fs = None\n                    except Exception as e:\n                        print(f"⚠️ FluidSynth non disponibile: {e}")\n                        import traceback\n                        traceback.print_exc()\n                        self.fs = None\n                \n                if self.fs and self.fs.initialized:\n                    self.fs.load(file_path)\n                    # ✅ Propaga durata MIDI a engine, monitor e LABEL visibili\n                    midi_dur = self.fs.get_duration_ms()\n                    if midi_dur > 0:\n                        self.engine.total_duration_ms = midi_dur\n                        # Aggiorna monitor principale\n                        self.monitor.total_duration_ms = midi_dur\n                        dur_min = int(midi_dur / 60000)\n                        dur_sec = int((midi_dur % 60000) / 1000)\n                        dur_text = f"{dur_min:02d}:{dur_sec:02d}"\n                        self.monitor.total_label.config(text=dur_text)\n                        self.monitor.countdown_label.config(text=f"-{dur_text}")\n                        print(f"🎹 Durata MIDI reale: {dur_text} ({midi_dur}ms)")\n                        # Aggiorna monitor pubblico\n                        if self.monitor_pubblico:\n                            try:\n                                pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n                                pub.total_duration_ms = midi_dur\n                                pub.total_label.config(text=dur_text)\n                                pub.countdown_label.config(text=f"-{dur_text}")\n                            except:\n                                pass\n                    print("✅ MIDI caricato")\n                else:\n                    print("⚠️ Nessun engine MIDI disponibile - MIDI senza audio")\n                    self.fs = None\n                \n                # ✅ Notifica mixer se presente\n                if self.mixer_ref:\n                    self.mixer_ref.load_midi_file(file_path, melody_muted=True)\n            # ===== GESTIONE MP3/Audio =====\n            else:\n                self.is_midi = False\n                self.is_bass_audio = False\n                \n                # ✅ BASS Engine audio (48kHz/32bit, qualità massima)\n                try:\n                    from .bass_engine import is_bass_available, get_bass_engine\n                    if is_bass_available():\n                        _be = get_bass_engine()\n                        if not _be.initialized:\n                            _be.initialize()\n                        if _be.initialized and _be.load(file_path):\n                            self.bass_engine = _be\n                            self.is_bass_audio = True\n                            self.is_mpv_audio = False\n                            self.is_vlc_audio = False\n                            if tonalita != 0:\n                                _be.set_pitch(tonalita)\n                            # ✅ NON toccare speed per MP3 (solo MIDI usa speed)\n                            # Propaga durata\n                            bass_dur = _be.get_duration_ms()\n                            if bass_dur > 0:\n                                self.engine.total_duration_ms = bass_dur\n                                self.monitor.total_duration_ms = bass_dur\n                                d_min = int(bass_dur / 60000)\n                                d_sec = int((bass_dur % 60000) / 1000)\n                                dur_text = f"{d_min:02d}:{d_sec:02d}"\n                                self.monitor.total_label.config(text=dur_text)\n                                self.monitor.countdown_label.config(text=f"-{dur_text}")\n                                if self.monitor_pubblico:\n                                    try:\n                                        pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n                                        pub.total_duration_ms = bass_dur\n                                        pub.total_label.config(text=dur_text)\n                                        pub.countdown_label.config(text=f"-{dur_text}")\n                                    except: pass\n                            print(f"✅ Audio BASS preparato: {Path(file_path).name}")\n                except Exception as e:\n                    print(f"⚠️ BASS Audio non disponibile: {e}")\n                    self.is_bass_audio = False\n                    self.bass_engine = None\n                \n                # ✅ Fallback MPV audio (se BASS non disponibile)\n                if not self.is_bass_audio and self.mpv_player:\n                    try:\n                        self.is_mpv_audio = True\n                        self.is_vlc_audio = False\n                        self.mpv_player.command("stop")\n                        self._mpv_pending_file = file_path\n                        if tonalita != 0:\n                            print(f"🎵 Pitch: {tonalita:+d} (MPV live)")\n                        print(f"✅ Audio MPV preparato: {Path(file_path).name}")\n                    except Exception as e:\n                        print(f"⚠️ MPV fallito: {e}")\n                        self.is_mpv_audio = False\n                \n                # ✅ Fallback VLC + ffmpeg pitch shift\n                if not self.is_bass_audio and not self.is_mpv_audio and self.engine.vlc_available and self.engine.ensure_vlc():\n                    try:\n                        self.is_vlc_audio = True\n                        file_to_load = file_path\n                        self._pitched_file = None\n                        \n                        # ✅ FFmpeg pitch shift (qualità indipendente da velocità)\n                        if tonalita != 0 and FFMPEG_AVAILABLE:\n                            try:\n                                pitched = self.engine._apply_pitch_shift_ffmpeg(file_path, tonalita)\n                                if pitched and os.path.exists(pitched):\n                                    file_to_load = pitched\n                                    self._pitched_file = pitched\n                                    print(f"🎵 Pitch FFmpeg: {tonalita:+d} → {Path(pitched).name}")\n                            except Exception as e:\n                                print(f"⚠️ FFmpeg pitch fallito, uso VLC rate: {e}")\n                        \n                        if self.vlc_audio:\n                            self.vlc_audio.stop()\n                        self.vlc_audio = self.engine.vlc_instance.media_player_new()\n                        filepath_vlc = file_to_load.replace(\'\\\\\', \'/\')\n                        media = self.engine.vlc_instance.media_new(filepath_vlc)\n                        if media is None:\n                            raise ValueError(f"VLC media_new None per: {filepath_vlc}")\n                        media.add_option(\':no-video\')\n                        self.vlc_audio.set_media(media)\n                        print(f"✅ Audio VLC preparato: {Path(file_to_load).name}")\n                    except Exception as e:\n                        print(f"⚠️ VLC audio fallito, uso pygame: {e}")\n                        self.is_vlc_audio = False\n                        if self.vlc_audio:\n                            try: self.vlc_audio.stop(); self.vlc_audio.set_media(None)\n                            except: pass\n                            self.vlc_audio = None\n                        try:\n                            pygame.mixer.music.load(file_path)\n                        except Exception as pe:\n                            self.last_error = f"Errore caricamento audio: {pe}"\n                            print(f"⚠️ {self.last_error}")\n                            success = False\n                elif not self.is_bass_audio and not self.is_mpv_audio:\n                    self.is_vlc_audio = False\n                    try:\n                        pygame.mixer.music.load(file_path)\n                    except Exception as pe:\n                        self.last_error = f"Errore caricamento audio: {pe}"\n                        print(f"⚠️ {self.last_error}")\n                        success = False\n                print(f"✅ PRONTO PER LA RIPRODUZIONE")\n    else:\n        self.last_error = "Impossibile estrarre testo dal file"\n        print(f"❌ {self.last_error}")\n    \n    print(f"{\'=\'*60}\\n")\n    # ✅ NON sbloccare _seeking qui — play() lo gestisce.\n    self._file_unloaded = False  # ✅ File appena caricato, play() non deve ricaricare\n    self._loading_new_file = False  # ✅ Fine caricamento, cleanup thread sicuro\n    # ✅ Aggiorna pannello info centrale per QUALSIASI brano caricato\n    if success and hasattr(self, \'info_brano_ref\') and self.info_brano_ref:\n        try:\n            _is_url = isinstance(file_path, str) and file_path.lower().startswith(("http://", "https://"))\n            if not _is_url:\n                # video YouTube pre-scaricato: trattalo come un brano YT\n                try:\n                    from .youtube_local import titolo_video_cache\n                    _tc = titolo_video_cache(file_path)\n                except Exception:\n                    _tc = \'\'\n                if _tc:\n                    self.engine.yt_title = _tc\n                    _is_url = True\n            if _is_url:\n                # Stream YouTube: il file_path e\' l\'URL del flusso, non un nome.\n                # Uso il titolo VERO risolto da yt-dlp e NON tocco il cantante,\n                # che play_brano ha gia\' impostato col nome della scaletta.\n                titolo = (getattr(self.engine, \'yt_title\', \'\')\n                          or getattr(self.engine, \'title\', \'\') or \'\')\n                if self.info_brano_ref.get(\'brano\'):\n                    self.info_brano_ref[\'brano\'].config(text=titolo or \'---\')\n                if self.info_brano_ref.get(\'ext\'):\n                    self.info_brano_ref[\'ext\'].config(text=\'[YT]\')\n                self._bridge_song = titolo\n            else:\n                nome = Path(file_path).stem\n                cantante = brano = nome\n                if \' - \' in nome:\n                    parts = nome.split(\' - \', 1)\n                    cantante, brano = parts[0].strip(), parts[1].strip()\n                ext = Path(file_path).suffix[1:].upper()\n                if self.info_brano_ref.get(\'cantante\'):\n                    self.info_brano_ref[\'cantante\'].config(text=cantante or \'---\')\n                if self.info_brano_ref.get(\'brano\'):\n                    self.info_brano_ref[\'brano\'].config(text=brano or \'---\')\n                if self.info_brano_ref.get(\'ext\'):\n                    self.info_brano_ref[\'ext\'].config(text=ext or \'---\')\n                self._bridge_song = f"{cantante} - {brano}" if cantante != brano else nome\n        except: pass\n    _lf_tick("resto load_file (motore audio/video, monitor, normalizzazione)")\n    return success\n\n\ndef _testo_dati_youtube(self, chiave):\n    """Artista, brano, canale e titolo vero del video, chiesti a YouTube\n    (yt-dlp, come fa gia\' la scaletta per il titolo). {} se non si riesce.\n\n    ⭐ Per i video musicali YouTube sa artista e brano; il canale dice\n       l\'artista quasi sempre ("AdeleVEVO", "Marco Masini - Topic")."""\n    if not str(chiave).startswith(\'yt:\'):\n        return {}\n    try:\n        from . import youtube_local as yl\n        out = yl._run_ytdlp([\'--no-warnings\', \'--no-playlist\', \'--skip-download\',\n                             \'--print\', \'%(artist)s\\t%(track)s\\t%(channel)s\\t%(title)s\',\n                             \'https://www.youtube.com/watch?v=\' + str(chiave)[3:]],\n                            timeout=25) or \'\'\n        parti = (out.strip().splitlines() or [\'\'])[-1].split(\'\\t\')\n        parti = [(\'\' if p in (\'NA\', \'None\') else p.strip()) for p in parti] + [\'\', \'\', \'\', \'\']\n        return {\'yt_artista\': parti[0], \'yt_brano\': parti[1],\n                \'yt_canale\': parti[2], \'yt_titolo\': parti[3]}\n    except Exception as e:\n        self._voce_log(\'testo: dati di YouTube non letti (%s)\' % str(e)[:80])\n        return {}\n\n\ndef _testo_ha_gia_il_testo(self, chiave, nome=\'\'):\n    """Il video HA GIA\' le parole scritte sopra? (karaoke, lyrics video...)\n\n    ⛔ "Va fatto solo con sorgenti che non hanno il testo all\'interno"\n       (utente): su un video karaoke o un lyrics video il testo al volo\n       metterebbe DUE testi uno sopra l\'altro. Si guarda il nome: quello\n       della riga, quello del file e il titolo vero salvato da YouTube.\n    """\n    import re as _re\n    nomi = [str(nome or \'\'), os.path.basename(str(chiave or \'\'))]\n    try:\n        nomi.append((self.__dict__.get(\'_voce_titoli\', {}) or {}).get(chiave) or \'\')\n        if str(chiave).startswith(\'yt:\'):\n            from . import youtube_local as yl\n            nomi.append(yl.titolo_in_cache(str(chiave)[3:]) or \'\')\n    except Exception:\n        pass\n    tutto = \' \'.join(nomi).lower()\n    # ⛔ SOLO "karaoke": "se c\'e\' scritto lyrics non vuol dire che ci sia\n    #    all\'interno un karaoke" (utente) — un lyrics video, un video col\n    #    "testo" nel titolo, restano candidati.\n    return bool(_re.search(r\'karaoke|karafun\', tutto))\n\n\ndef _testo_modo(self):\n    """\'sopra\' = il testo sopra il VIDEO, come sottotitolo karaoke\n    (richiesta dell\'utente: "il testo si puo\' mettere in overlay sul\n    video?"); \'testo\' = niente video, solo il testo come una base mp3."""\n    try:\n        from .database import Database\n        m = str(Database.get_config(\'testo_al_volo_modo\', \'sopra\')).strip().lower()\n        return \'testo\' if m == \'testo\' else \'sopra\'\n    except Exception:\n        return \'sopra\'\n\n\ndef _testo_ass(self, sillabe, righe=False, n_righe=5, larg=1280, alt=720):\n    """Il karaoke A TUTTO SCHERMO (formato ASS) che VLC disegna sopra il video.\n\n    ⭐ Come il karaoke di KaraDom (utente): la riga da cantare sempre AL\n       CENTRO, le gia\' cantate che salgono sopra, le prossime sotto.\n       `n_righe` = 5 sul monitor principale (la cantabile e\' la 3a), 7 sul\n       monitor pubblico (la 4a). MAIUSCOLO come il monitor, e un velo scuro\n       sul video perche\' si legga. La riga al centro si colora sillaba per\n       sillaba (`\\\\kf`); con le righe del LAM si accende intera (`\\\\k0`).\n    ⚠️ Il formato vuole i centesimi di secondo, e niente graffe o barre\n       nel testo (sono i suoi comandi).\n    """\n    n_righe = 7 if int(n_righe) >= 7 else 5\n    meta = n_righe // 2\n    # ⭐ LA STESSA REGOLA DEL MONITOR di KaraDom (utente: "la grandezza del\n    #    testo senza video andava bene"): l\'altezza si divide per il numero\n    #    di righe e il carattere occupa il 57% di quello spazio. Cosi\' il\n    #    testo sopra il video e quello del monitor si somigliano.\n    #    Su 720: 5 righe -> 82, 7 righe -> 58.\n    # ⛔ E SULLA MISURA DEL VIDEO, non su una fissa: il testo lo disegna VLC\n    #    dentro il rettangolo del video (utente: "usciva dal video").\n    larg, alt = max(320, int(larg)), max(240, int(alt))\n    utile = larg * 0.92           # un margine ai lati, o il testo tocca i bordi\n    passo = float(alt) / n_righe\n    # ⛔ il corpo NON si rimpicciolisce per far stare le righe lunghe\n    #    ("niente righe con testo piccolo"): si tiene la misura del monitor,\n    #    con un tetto perche\' una riga di 26 lettere ci stia, e le righe\n    #    piu\' lunghe SI SPEZZANO in due, come nel karaoke normale.\n    FS = max(16, int(min(0.57 * passo, utile / (0.62 * 26))))\n    MAX_CAR = max(12, int(utile / (0.62 * FS)))\n    Y = [int(passo * (k + 0.5)) for k in range(n_righe)]\n    def hms(ms):\n        ms = max(0, int(ms))\n        return \'%d:%02d:%02d.%02d\' % (ms // 3600000, ms // 60000 % 60,\n                                      ms // 1000 % 60, ms // 10 % 100)\n\n    def pulito(t):\n        return str(t).replace(\'{\', \'(\').replace(\'}\', \')\').replace(\'\\\\\', \' \').upper()\n    # le righe: [[(testo, ms), ...], ...]\n    tutte, riga = [], []\n    for testo, ms in sillabe:\n        if testo.startswith(\'\\n\') and riga:\n            tutte.append(riga)\n            riga = []\n        riga.append((testo.lstrip(\'\\n\'), int(ms)))\n    if riga:\n        tutte.append(riga)\n    tutte = [r for r in tutte if \'\'.join(t for t, _ in r).strip()]\n\n    # dove ha senso andare a capo: davanti a queste parole la frase respira\n    LEGAMI = (\'E\', \'CHE\', \'MA\', \'PERCHE\', "PERCHE\'", \'SE\', \'QUANDO\', \'COME\',\n              \'PERO\', "PERO\'", \'OPPURE\', \'MENTRE\', \'POI\', \'COSI\', "COSI\'",\n              \'PER\', \'CON\', \'DI\', \'DA\', \'IN\', \'SU\', \'TRA\', \'FRA\', \'A\')\n\n    def spezza(r):\n        """Una riga troppo lunga diventa due (o piu\'), tagliata fra le\n        PAROLE: le sillabe restano coi loro tempi.\n\n        ⭐ "Spezzare le righe con un minimo di senso" (utente): a parita\' di\n           misura si preferisce tagliare DOPO una virgola o PRIMA di una\n           congiunzione ("e", "che", "ma", "quando"...), non in mezzo a un\n           pezzo di frase.\n        """\n        intero = \'\'.join(t for t, _ in r)\n        if len(intero) <= MAX_CAR:\n            return [r]\n        if not any(t.endswith(\' \') for t, _ in r[:-1]):\n            return [r]                      # una parola sola lunghissima\n        quante = int(len(intero) / float(MAX_CAR)) + 1\n        pezzi, resto = [], r\n        for q in range(quante - 1, 0, -1):\n            testo_resto = \'\'.join(t for t, _ in resto)\n            obiettivo = len(testo_resto) / float(q + 1)\n            scelto, punteggio = None, None\n            lung = 0\n            for i, (t, _) in enumerate(resto[:-1]):\n                lung += len(t)\n                if not t.endswith(\' \'):\n                    continue\n                # quanto e\' lontano dalla misura giusta, meno i premi\n                p = abs(lung - obiettivo)\n                if t.rstrip().endswith((\',\', \';\', \':\', \'.\', \'!\', \'?\')):\n                    p -= 8\n                dopo = \'\'\n                for t2, _x in resto[i + 1:]:\n                    dopo += t2\n                    if t2.endswith(\' \'):\n                        break\n                if dopo.strip().upper() in LEGAMI:\n                    p -= 5\n                if punteggio is None or p < punteggio:\n                    scelto, punteggio = i, p\n            if scelto is None:\n                break\n            pezzi.append(resto[:scelto + 1])\n            resto = resto[scelto + 1:]\n        pezzi.append(resto)\n        return [p for p in pezzi if p]\n    spezzate = []\n    for r in tutte:\n        spezzate.extend(spezza(r))\n    tutte = spezzate\n    testa = (\'[Script Info]\\nScriptType: v4.00+\\nPlayResX: %d\\nPlayResY: %d\\n\'\n             \'WrapStyle: 2\\nScaledBorderAndShadow: yes\\n\\n[V4+ Styles]\\n\' % (larg, alt) +\n             \'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, \'\n             \'OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, \'\n             \'ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, \'\n             \'MarginL, MarginR, MarginV, Encoding\\n\'\n             # ⭐ come il karaoke di KaraDom: la parte CANTATA e\' ROSSA\n             #    (&H000000FF = rosso), quella da cantare bianca\n             \'Style: Canta,Arial,%d,&H000000FF,&H00FFFFFF,&H00000000,&H96000000,\'\n             \'-1,0,0,0,100,100,0,0,1,5,2,5,20,20,0,1\\n\'\n             # ⭐ le righe GIA\' CANTATE restano ROSSE, come nel monitor di\n             #    KaraDom, dove e\' rosso tutto quello che si e\' gia\' cantato\n             #    (utente, 11-09). Prima tornavano bianche appena salivano.\n             \'Style: Cantata,Arial,%d,&H000000FF,&H000000FF,&H00000000,&H96000000,\'\n             \'-1,0,0,0,100,100,0,0,1,4,1,5,20,20,0,1\\n\'\n             \'Style: DaCantare,Arial,%d,&H00F0F0F0,&H00F0F0F0,&H00000000,&H96000000,\'\n             \'-1,0,0,0,100,100,0,0,1,4,1,5,20,20,0,1\\n\'\n             \'Style: Velo,Arial,20,&H00000000,&H00000000,&H00000000,&H00000000,\'\n             \'0,0,0,0,100,100,0,0,1,0,0,7,0,0,0,1\\n\\n\'\n             \'[Events]\\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, \'\n             \'MarginV, Effect, Text\\n\') % (FS, FS, FS)\n    if not tutte:\n        return testa\n\n    def fs_per(testo_riga):\n        """Sempre la stessa misura. Si stringe SOLO se una singola parola\n        e\' cosi\' lunga da non poter essere spezzata (raro), per non farla\n        uscire dallo schermo: "il video taglia il testo" (utente)."""\n        n = max(1, len(testo_riga))\n        return FS if n <= MAX_CAR else max(20, int(utile / (0.62 * n)))\n    ev = []\n    # un "quadro" per riga: dal momento in cui la riga va al centro\n    # (0,3 s prima della sua prima sillaba; la prima 3 s prima) fino al\n    # quadro dopo\n    cambi = [max(0, r[0][1] - 300) for r in tutte]\n    cambi[0] = max(0, tutte[0][0][1] - 3000)\n    fine_tutto = tutte[-1][-1][1] + 3000\n    for i, r in enumerate(tutte):\n        da = cambi[i]\n        fino = cambi[i + 1] if i + 1 < len(tutte) else fine_tutto\n        if fino <= da:\n            continue\n        for k in range(n_righe):\n            j = i + (k - meta)\n            if j < 0 or j >= len(tutte):\n                continue\n            riga_k = tutte[j]\n            testo_riga = \'\'.join(t for t, _ in riga_k)\n            # ⭐ SCORRE A NASTRO (utente): la riga non salta al suo posto,\n            #    ci sale. Dove stava un attimo prima? Una riga piu\' in\n            #    basso (era il quadro precedente); la prima volta arriva da\n            #    sotto lo schermo.\n            da_y = Y[k + 1] if k + 1 < n_righe else int(Y[-1] + passo)\n            # ⚠️ la salita dura il giusto per vedersi FLUIDA (VLC la disegna\n            #    fotogramma per fotogramma): mezzo secondo circa\n            salita = min(700, max(300, (fino - da) // 3))\n            pos = \'{\\\\an5\\\\move(%d,%d,%d,%d,0,%d)\\\\fs%d}\' % (\n                larg // 2, da_y, larg // 2, Y[k], salita, fs_per(testo_riga))\n            if j < i:\n                ev.append(\'Dialogue: 1,%s,%s,Cantata,,0,0,0,,%s%s\'\n                          % (hms(da), hms(fino), pos, pulito(testo_riga)))\n            elif j > i:\n                ev.append(\'Dialogue: 1,%s,%s,DaCantare,,0,0,0,,%s%s\'\n                          % (hms(da), hms(fino), pos, pulito(testo_riga)))\n            else:\n                pezzi = [pos, \'{\\\\k%d}\' % (max(0, r[0][1] - da) // 10)]\n                if righe:\n                    # ⭐ ANCHE LA RIGA INTERA SI COLORA COI TEMPI: si\n                    #    riempie dal suo inizio fino all\'inizio della riga\n                    #    dopo, come un karaoke normale ("la prima riga deve\n                    #    colorarsi sempre secondo i tempi", utente 11-09).\n                    prossimo = (tutte[i + 1][0][1] if i + 1 < len(tutte)\n                                else r[-1][1] + 3000)\n                    quanto = max(300, min(12000, prossimo - r[0][1]))\n                    pezzi.append(\'{\\\\kf%d}%s\' % (quanto // 10, pulito(testo_riga)))\n                else:\n                    for s, (t, ms) in enumerate(r):\n                        fine = r[s + 1][1] if s + 1 < len(r) else min(fino, ms + 1200)\n                        pezzi.append(\'{\\\\kf%d}%s\' % (max(1, (fine - ms) // 10), pulito(t)))\n                ev.append(\'Dialogue: 2,%s,%s,Canta,,0,0,0,,%s\'\n                          % (hms(da), hms(fino), \'\'.join(pezzi)))\n    # il velo scuro sul video, per tutto il tempo del testo\n    ev.insert(0, \'Dialogue: 0,%s,%s,Velo,,0,0,0,,{\\\\an7\\\\pos(0,0)\\\\1a&H70&\\\\p1}\'\n                 \'m 0 0 l %d 0 %d %d 0 %d{\\\\p0}\'\n                 % (hms(cambi[0]), hms(fine_tutto), larg, larg, alt, alt))\n    return testa + \'\\n\'.join(ev) + \'\\n\'\n\n\ndef _testo_sottotitolo_pubblico(self):\n    """Il sottotitolo karaoke anche sul lettore del monitor PUBBLICO."""\n    uri = getattr(self, \'_testo_ass_uri\', None)\n    pl = getattr(self.engine, \'vlc_player_pubblico\', None)\n    if not uri or pl is None:\n        return\n    if self._testo_metti_sottotitolo(pl, uri):\n        self._voce_log(\'testo: sottotitolo karaoke anche sul monitor pubblico\')\n\n\ndef _testo_metti_sottotitolo(self, pl, uri):\n    """Attacca il sottotitolo a un lettore VLC.\n\n    ⛔ `MediaSlaveType.subtitle` NON si passa com\'e\': la libreria che sta\n       dentro KaraDom vuole un NUMERO, e sollevava\n       "\'MediaSlaveType\' object cannot be interpreted as an integer" —\n       il testo non compariva pur essendo pronto (visto nel registro\n       l\'11-09 alle 16:16). Si passa il numero, e se anche cosi\' non va\n       si prova la vecchia strada (`video_set_subtitle_file`).\n    """\n    if pl is None or not uri:\n        return False\n    try:\n        import vlc as _vlc\n        t = getattr(_vlc, \'MediaSlaveType\', None)\n        t = getattr(t, \'subtitle\', 0) if t is not None else 0\n        t = int(getattr(t, \'value\', t))\n        pl.add_slave(t, uri, True)\n        return True\n    except Exception as e:\n        self._voce_log(\'testo: add_slave non riuscito (%s), provo l-altra strada\' % e)\n    try:\n        p = uri[8:].replace(\'/\', os.sep) if str(uri).startswith(\'file:///\') else uri\n        return bool(pl.video_set_subtitle_file(p))\n    except Exception as e:\n        self._voce_log(\'testo: sottotitolo non messo (%s)\' % e)\n        return False\n\n\ndef _testo_misura_video(self, percorso):\n    """Quanto e\' grande il video (larghezza, altezza).\n\n    ⛔ SERVE DAVVERO: il testo lo disegna VLC DENTRO il rettangolo del\n       video, non sullo schermo. Scrivendo su una misura fissa 1280x720,\n       con un video 4:3 o verticale il testo "usciva dal video" (utente).\n    """\n    import re as _re\n    import subprocess\n    try:\n        if str(percorso).lower().startswith((\'http://\', \'https://\')):\n            return 1280, 720\n        r = subprocess.run([self._voce_ffmpeg(), \'-hide_banner\', \'-i\', percorso],\n                           capture_output=True, timeout=20,\n                           creationflags=0x08000000 if os.name == \'nt\' else 0)\n        testo = (r.stderr or b\'\').decode(\'utf-8\', \'replace\')\n        for m in _re.finditer(r\'Video:.*?\\b(\\d{2,5})x(\\d{2,5})\\b\', testo):\n            w, h = int(m.group(1)), int(m.group(2))\n            if 100 <= w <= 8000 and 100 <= h <= 8000:\n                return w, h\n    except Exception as e:\n        self._voce_log(\'testo: misura del video non letta (%s)\' % str(e)[:60])\n    return 1280, 720\n\n\ndef _voce_avvia_modello(self, file_giu, sorgente, da_ms):\n    """Manda avanti l\'operaio, se il modello c\'e\' gia\' su questo PC."""\n    try:\n        from . import devocalizza as dv\n        if not dv.pronto():\n            # ⛔ NON si scarica niente qui: il cliente ha appena premuto un\n            #    tasto e vuole sentire, non aspettare 64 MB. Si resta col\n            #    metodo del centro, che sta gia\' suonando.\n            self._voce_log(\'modello: non e\\\' ancora su questo PC, resto \'\n                           \'col metodo del centro\')\n            return\n    except Exception as e:\n        self._voce_log(\'modello: non disponibile (%s)\' % e)\n        return\n    turno = getattr(self, \'_voce_turno\', 0)\n    # ⭐ col roformer, anche qui prima il modello veloce (vedi\n    #    `_voce_ibrido`): a brano gia\' partito il roformer da solo\n    #    verrebbe raggiunto dalla puntina in pochi secondi\n    try:\n        if dv.modo_scelto() == \'roformer\':\n            threading.Thread(\n                target=self._voce_ibrido,\n                args=(file_giu, sorgente, turno),\n                kwargs={\'da_ms\': da_ms}, daemon=True).start()\n            return\n    except Exception:\n        pass\n    threading.Thread(\n        target=self._voce_separa_avanti,\n        args=(file_giu, sorgente, da_ms, turno), daemon=True).start()\n\n\ndef play(self, tonalita=None):\n    dbg("SYSTEM", f"play() ton={tonalita} is_playing={self.is_playing} is_paused={self.is_paused} gen={self._play_generation}")\n    """\n    Avvia riproduzione — se in pausa, riavvia da 0\n    """\n    # ✅ Sincronizza pitch: se specificato aggiorna, altrimenti mantieni corrente\n    if tonalita is not None:\n        self.current_pitch = tonalita\n\n    # ⭐ si segna che QUESTO brano e\' stato mandato: a fine brano non si\n    #    rifa\' piu\' la sua testa col roformer (vedi `_voce_separa_avanti_lavoro`)\n    try:\n        _k = self._voce_chiave(getattr(self, \'_voce_brano_scelto\', None)\n                               or getattr(self, \'current_file\', None))\n        if _k:\n            self.__dict__.setdefault(\'_voce_suonati\', set()).add(_k)\n    except Exception:\n        pass\n\n    # ⭐ La voce abbassata vale anche per il brano che sta per partire:\n    #    la si decide PRIMA di premere play, come la tonalita\', e resta\n    #    finche\' non si rimette su. Si riapplica appena il brano parte,\n    #    perche\' ogni brano nuovo riparte con l\'audio pulito.\n    try:\n        if getattr(self, \'voce_giu\', 0):\n            # ⚠️ `self.master`, non `self.root`: in questa classe `root`\n            #    non esiste e l\'errore sarebbe finito nell\'except — la\n            #    voce non si sarebbe riapplicata mai, senza dire niente.\n            self.master.after(400, lambda q=self.voce_giu: self.set_voce(q))\n    except Exception:\n        pass\n\n    # ✅ Se in PAUSA → riavvia da 0 direttamente su ogni player\n    if self.is_paused:\n        print("▶ Play durante pausa → riavvio diretto da 0")\n        self.is_paused = False\n        self.is_playing = True\n        self._seeking = True\n        self.current_time_ms = 0\n        \n        # Reset monitor\n        self.monitor.current_index = -1\n        self.monitor._current_scroll_line = 0\n        self.monitor._scroll_fraction = 0.0\n        self.monitor._scroll_target_fraction = 0.0\n        self.monitor._cached_scroll_index = -1\n        self.monitor.text_widget.yview_moveto(0)\n        if self.monitor_pubblico:\n            pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n            pub.current_index = -1\n            pub._current_scroll_line = 0\n            pub._scroll_fraction = 0.0\n            pub._scroll_target_fraction = 0.0\n            pub._cached_scroll_index = -1\n            pub.text_widget.yview_moveto(0)\n        \n        # Riavvia audio per tipo di player\n        if self.engine.is_video and self.engine.vlc_player:\n            try:\n                self.engine.vlc_player.set_pause(0)  # Forza unpause\n                self.engine.vlc_player.set_time(0)\n                if self.engine.vlc_player_pubblico:\n                    self.engine.vlc_player_pubblico.set_pause(0)\n                    self.engine.vlc_player_pubblico.set_time(0)\n                if self._video_pitch_active and self.vlc_audio:\n                    self.vlc_audio.set_pause(0)\n                    self.vlc_audio.set_time(0)\n            except Exception as e:\n                print(f"⚠️ Restart video da pausa: {e}")\n        elif self.is_bass_audio and self.bass_engine:\n            try:\n                if self.bass_engine.is_paused:\n                    self.bass_engine.pause()  # toggle → resume\n                self.bass_engine.seek_ms(0)\n                print("▶ Audio BASS riavviato da 0")\n                # ✅ riavvia anche la voce guida in cuffia da 0\n                try:\n                    from .cuffia_guida import guida as _guida\n                    _guida.play(self.current_file, sync_ms=0)\n                except Exception as _e:\n                    print(f"⚠️ voce guida: {_e}")\n            except Exception as e:\n                print(f"⚠️ Restart BASS da pausa: {e}")\n        elif self.is_mpv_audio and self.mpv_player:\n            try:\n                self.mpv_player[\'pause\'] = False\n                self.mpv_player.seek(0, \'absolute\')\n            except Exception as e:\n                print(f"⚠️ Restart MPV da pausa: {e}")\n        elif self.is_vlc_audio and self.vlc_audio:\n            try:\n                self.vlc_audio.set_pause(0)  # Forza unpause (non toggle!)\n                self.vlc_audio.set_time(0)\n                self._vlc_play_start = time.time()\n                self._vlc_last_time = 0\n                self._vlc_last_change = 0\n            except Exception as e:\n                print(f"⚠️ Restart VLC audio da pausa: {e}")\n        elif self.is_midi and self.fs:\n            try:\n                self.fs.pause()  # Riprendi (toggle)\n                self.fs.seek_ms(0)\n                self.seek_offset_ms = 0\n            except Exception as e:\n                print(f"⚠️ Restart MIDI da pausa: {e}")\n        else:\n            try:\n                pygame.mixer.music.play(start=0)\n                self.seek_offset_ms = 0\n            except Exception as e:\n                print(f"⚠️ Restart pygame da pausa: {e}")\n        \n        self.web_sync.send_pause(False)\n        self._start_armed_audio_recording()\n        self.master.after(200, lambda: setattr(self, \'_seeking\', False))\n        print("⏮️ Riavvio da pausa completato")\n        return\n    \n    # ✅ RESET PAUSA\n    self.is_paused = False\n    \n    # ✅ BLOCCA aggiornamenti monitor durante startup (VLC riporta garbage iniziale)\n    self._seeking = True\n    self._play_generation += 1  # ✅ Invalida callback stale dal playback precedente\n    \n    # ✅ RIMUOVO il check is_playing - ora si può premere play anche durante la riproduzione\n    # (gestito in ui.py che chiama stop() prima)\n    \n    if not self.current_file:\n        print("⚠️ Nessun file caricato")\n        return\n    \n    # ✅ Se il file è stato scaricato (dopo stop/fade), ricaricalo\n    if getattr(self, \'_file_unloaded\', False):\n        print("🔄 File scaricato — ricarico prima di play...")\n        self._file_unloaded = False\n        self.load_file(self._original_file or self.current_file, self.current_pitch)\n        # load_file imposta _seeking=True, play() continuerà normalmente\n    \n    # ✅ RICARICA TESTO SOLO SE NECESSARIO (fix play dopo stop senza bloccare UI)\n    # ⛔ Durante pitch swap (_skip_monitor_reset), NON toccare il monitor — è lo stesso file\n    if self.engine.syllables_data and not getattr(self, \'_skip_monitor_reset\', False):\n        # Controlla se il testo è già caricato nel monitor\n        # ✅ Controlla anche se il text_widget è effettivamente vuoto\n        widget_empty = False\n        try:\n            widget_text = self.monitor.text_widget.get(\'1.0\', \'end\').strip()\n            widget_empty = len(widget_text) == 0\n        except:\n            widget_empty = True\n        \n        needs_reload = (not self.monitor.syllables_data or \n                       not self.monitor.full_text or\n                       widget_empty)  # ✅ Forza reload se widget vuoto\n        \n        if needs_reload:\n            print("🔄 Ricarico testo nel monitor...")\n            self.monitor.load_text(\n                self.engine.full_text,\n                self.engine.syllables_data,\n                self.engine,\n                self.current_file\n            )\n            if self.monitor_pubblico:\n                self.monitor_pubblico.monitor_frame.load_text(\n                    self.engine.full_text,\n                    self.engine.syllables_data,\n                    self.engine,\n                    self.current_file if str(self.current_file).lower().startswith(\n                        ("http://", "https://")) else Path(self.current_file).name\n                )\n        else:\n            # ✅ Testo già caricato — reset indice e scroll ISTANTANEO (no lerp)\n            self.monitor.current_index = -1\n            self.monitor._scroll_position = 0.0\n            self.monitor._last_scroll_time = 0\n            self.monitor._cached_scroll_index = -1\n            self.monitor._snap_scroll = True  # ✅ Forza snap, no animazione\n            self.monitor.text_widget.yview_moveto(0)\n            if self.monitor_pubblico:\n                pub = self.monitor_pubblico.monitor_frame if hasattr(self.monitor_pubblico, \'monitor_frame\') else self.monitor_pubblico\n                pub.current_index = -1\n                pub._scroll_position = 0.0\n                pub._last_scroll_time = 0\n                pub._cached_scroll_index = -1\n                pub._snap_scroll = True  # ✅ Forza snap, no animazione\n                pub.text_widget.yview_moveto(0)\n    \n    # ✅ NON chiamare reset() qui - cancella lo sfondo appena caricato!\n    # self.monitor.reset()\n    \n    # ✅ NASCONDI LOGO durante riproduzione (ma NON in sottofondo solo audio)\n    if self.monitor.logo_label and not getattr(self, \'_sottofondo_solo_audio\', False):\n        self.monitor.logo_label.place_forget()\n    \n    # ✅ NASCONDI OVERLAY IMMAGINE durante riproduzione (monitor pubblico)\n    if self.monitor_pubblico and self.monitor_pubblico.image_overlay_enabled:\n        self.monitor_pubblico.hide_image_overlay()\n    \n    if self.engine.is_video:\n        try:\n            # ✅ RIPRISTINA LAYOUT VIDEO (necessario dopo fade_out che smonta il canvas)\n            mon = self.monitor\n            try:\n                mon.text_widget.pack_forget()\n                if hasattr(mon, \'text_frame\') and mon.text_frame:\n                    mon.text_frame.place_forget()\n                if hasattr(mon, \'background_canvas\') and mon.background_canvas:\n                    mon.background_canvas.place_forget()\n                if hasattr(mon, \'logo_label\') and mon.logo_label:\n                    mon.logo_label.place_forget()\n                mon.video_canvas.pack(fill=tk.BOTH, expand=True)\n            except: pass\n            \n            # ✅ Ripristina anche monitor pubblico\n            if self.monitor_pubblico and self.monitor_pubblico.visible:\n                try:\n                    pub = self.monitor_pubblico.monitor_frame\n                    pub.text_widget.pack_forget()\n                    if hasattr(pub, \'text_frame\') and pub.text_frame:\n                        pub.text_frame.place_forget()\n                    if hasattr(pub, \'background_canvas\') and pub.background_canvas:\n                        pub.background_canvas.place_forget()\n                    if hasattr(pub, \'logo_label\') and pub.logo_label:\n                        pub.logo_label.place_forget()\n                    pub.video_canvas.pack(fill=tk.BOTH, expand=True)\n                except: pass\n            \n            # ✅ Re-attach HWND (può perdersi dopo fade_out → stop)\n            try:\n                mon.update_idletasks()\n                v_id = mon.video_canvas.winfo_id()\n                if sys.platform.startswith(\'win\'):\n                    self.engine.vlc_player.set_hwnd(v_id)\n                elif sys.platform.startswith(\'linux\'):\n                    self.engine.vlc_player.set_xwindow(v_id)\n            except: pass\n            \n            self.master.update_idletasks()\n            \n            # ===== PITCH + SPEED VIDEO CON VLC RATE =====\n            pitch_rate = pow(2.0, self.current_pitch / 12.0) if self.current_pitch != 0 else 1.0\n            combined_rate = pitch_rate * self.current_speed\n            self.engine.vlc_player.set_rate(combined_rate)\n            if combined_rate != 1.0:\n                print(f"[VIDEO] 🎵 Rate: {combined_rate:.3f} (pitch={self.current_pitch:+d}, speed={self.current_speed:.2f}x)")\n            # ===== FINE PITCH + SPEED VIDEO =====\n            \n            # ✅ SETUP PLAYER PUBBLICO SE VISIBILE (istanza --no-audio)\n            if self.monitor_pubblico and self.monitor_pubblico.visible:\n                print(f"🎬 Setup player pubblico: file={self.current_file[-50:]}")\n                ok = self.engine.setup_public_video_player(self.monitor_pubblico.monitor_frame, self.current_file)\n                # ⭐ testo al volo: il sottotitolo anche sul monitor PUBBLICO\n                #    (il suo lettore nasce qui, dopo il caricamento)\n                self._testo_sottotitolo_pubblico()\n                if ok and self.engine.vlc_player_pubblico:\n                    self.engine.vlc_player_pubblico.set_rate(combined_rate)\n                    # Avvia pubblico (già muto per --no-audio)\n                    self.engine.vlc_player_pubblico.play()\n                    time.sleep(0.1)\n                    print("🔇 Player pubblico avviato (--no-audio)")\n                else:\n                    print("⚠️ Player pubblico NON configurato")\n            else:\n                if self.monitor_pubblico:\n                    print(f"🎬 Monitor pubblico non visibile (visible={self.monitor_pubblico.visible})")\n            \n            # PLAY principale\n            self.engine.vlc_player.play()\n            \n            # ✅ RETRY: VLC a volte non parte al primo play() (pipeline codec non pronto)\n            # stream di rete: piu\' tentativi (il CDN puo\' rifiutare la prima\n            # apertura con un 403 transitorio; ri-play() la ritenta)\n            _retry_n = 20 if str(getattr(self, \'current_file\', \'\') or \'\').lower().startswith(\n                (\'http://\', \'https://\')) else 5\n\n            def _verify_vlc_playing(retries=_retry_n):\n                try:\n                    if not self.is_playing or not self.engine.is_video:\n                        return\n                    if not self.engine.vlc_player:\n                        return\n                    if not self.engine.vlc_player.is_playing() and retries > 0:\n                        print(f"⚠️ VLC non partito — retry ({retries} rimasti)")\n                        # ✅ Re-attach HWND prima del retry (a volte si perde)\n                        try:\n                            v_id = self.monitor.video_canvas.winfo_id()\n                            if sys.platform.startswith(\'win\'):\n                                self.engine.vlc_player.set_hwnd(v_id)\n                        except: pass\n                        self.engine.vlc_player.play()\n                        if self.engine.vlc_player_pubblico:\n                            try: self.engine.vlc_player_pubblico.play()\n                            except: pass\n                        self.master.after(500, lambda: _verify_vlc_playing(retries - 1))\n                    elif self.engine.vlc_player.is_playing():\n                        print("✅ VLC video confermato in riproduzione")\n                except:\n                    pass\n            self.master.after(500, _verify_vlc_playing)\n            \n            # ✅ AUDIO DEL VIDEO ESTRATTO SUBITO, in background.\n            # VLC non sa cambiare tonalita\' (ha solo la velocita\'): la\n            # trasposizione vera la fa MPV sull\'audio estratto. Prima\n            # l\'estrazione partiva al PRIMO tocco della tonalita\', e finche\'\n            # non finiva il video suonava alterato nella velocita\'. Ora si\n            # estrae appena parte il brano: quando il cantante chiede il\n            # tono, il motore e\' gia\' pronto.\n            if self.mpv_player and not self.is_midi:\n                self.master.after(800, self._preestrai_audio_video)\n\n            if self.current_pitch != 0 and self.mpv_player:\n                _pitch_for_video = self.current_pitch\n                def _trigger_video_pitch():\n                    if self.is_playing and self.engine.is_video:\n                        self.set_pitch(_pitch_for_video)\n                self.master.after(1500, _trigger_video_pitch)\n            \n            # ✅ SETTA VOLUME SUBITO (con gain normalizzazione — VLC max 100%)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            _norm_vol = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n            self.engine.vlc_player.audio_set_volume(_norm_vol)\n\n            # ⭐⭐ VOCE ARMATA: LA BASE PREPARATA ATTACCA SUBITO, QUI.\n            #\n            #    Prima il video partiva col SUO audio e lo scambio arrivava\n            #    dopo, portato da `set_voce`: in mezzo restava un secondo\n            #    di brano originale — voce compresa — e poi il salto al\n            #    file pulito. Zittire il video in anticipo toglieva la voce\n            #    ma lasciava un buco di silenzio: era una pezza, non la\n            #    cura. La cura e\' non far mai suonare l\'audio del video\n            #    quando c\'e\' gia\' la base pronta.\n            #\n            # ⚠️ Si chiama SUBITO, non con un `after`: mezzo secondo di\n            #    ritardo e\' esattamente il difetto che si vuole togliere.\n            # ⚠️ Se lo scambio non riesce, `_finish_activate_video_mpv`\n            #    riaccende il video da solo (vedi `_voce_muta_video`):\n            #    meglio l\'audio originale che il silenzio.\n            if getattr(self, \'voce_giu\', 0):\n                try:\n                    self._voce_log(\'play: voce armata, attacco subito la \'\n                                   \'base preparata (niente audio del video)\')\n                    self._voce_muta_video(True)\n                    self._activate_video_mpv_audio()\n                except Exception as _e:\n                    self._voce_log(\'play: non sono riuscito ad attaccare \'\n                                   \'subito la base (%s)\' % _e)\n                    self._voce_muta_video(False)\n            \n            # ✅ VERIFICA VOLUME DOPO PLAY (backup — VLC a volte ignora volume prima del buffering)\n            def _verify_vlc_volume():\n                try:\n                    is_muted = self.engine.vlc_player.audio_get_mute()\n                    if is_muted:\n                        self.engine.vlc_player.audio_set_mute(False)\n                    \n                    _ng2 = self.normalization_gain if self.normalization_enabled else 1.0\n                    _nv = int(min(100, self._user_volume * max(1.0, _ng2) * 100))\n                    self.engine.vlc_player.audio_set_volume(_nv)\n                    \n                    # Se durata non era disponibile, prova ora\n                    if self.engine.total_duration_ms == 0:\n                        duration_ms = self.engine.vlc_player.get_length()\n                        if duration_ms > 0:\n                            self.engine.total_duration_ms = duration_ms\n                            self.monitor.total_duration_ms = duration_ms\n                            total_min = int(duration_ms / 60000)\n                            total_sec = int((duration_ms % 60000) / 1000)\n                            self.monitor.total_label.config(text=f"{total_min:02d}:{total_sec:02d}")\n                            self.monitor.countdown_label.config(text=f"-{total_min:02d}:{total_sec:02d}")\n                            if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n                                self.info_brano_ref[\'duration\'].config(text=f"{total_min:02d}:{total_sec:02d}")\n                        else:\n                            # Riprova tra 500ms\n                            self.master.after(500, _verify_vlc_volume)\n                except:\n                    pass\n            self.master.after(300, _verify_vlc_volume)\n            \n            print("▶ Video avviato (principale con audio, pubblico muto)")\n            \n            self.start_time = time.time() * 1000\n            self.is_playing = True\n            self._video_play_start = time.time()  # ✅ Grace period per end-detection\n            self._video_has_started = False        # ✅ VLC non ha ancora suonato un frame\n            print(f"▶ Video avviato: {Path(self.current_file).name}")\n            \n            # ✅ Se REC rapido è armato, avvia ora: dopo il play effettivo\n            self._start_armed_audio_recording()\n\n            # ✅ Avvia thread per sync video\n            self.playback_thread = threading.Thread(target=self._playback_loop, daemon=True)\n            self.playback_thread.start()\n            # ✅ SBLOCCA monitor dopo stabilizzazione VLC (solo se non è pitch swap)\n            if not getattr(self, \'_skip_monitor_reset\', False):\n                self.master.after(300, lambda: setattr(self, \'_seeking\', False))\n                # ✅ SAFETY BACKUP\n                self.master.after(1500, lambda: setattr(self, \'_seeking\', False))\n        except Exception as e:\n            print(f"⚠️ Errore play video: {e}")\n            import traceback\n            traceback.print_exc()\n        return\n    \n    self.is_playing = True\n    self.seek_offset_ms = 0  # ✅ Reset offset quando si parte dall\'inizio\n    \n    print(f"[PLAY] is_midi={self.is_midi}, is_vlc_audio={self.is_vlc_audio}, "\n          f"vlc_audio={self.vlc_audio is not None}, is_cdg={self.is_cdg}, "\n          f"file={Path(self.current_file).name if self.current_file else \'None\'}")\n    dbg("SYSTEM", f"PLAY: midi={self.is_midi} vlc={self.is_vlc_audio} cdg={self.is_cdg} file={Path(self.current_file).name if self.current_file else \'None\'}")\n    \n    # ✅ Invia sync web karaocanto.it ad ogni play (non solo al load)\n    try:\n        if self.web_sync.connected and self.current_file:\n            title = getattr(self.engine, \'title\', \'\') or Path(self.current_file).stem\n            artist = getattr(self.engine, \'artist\', \'\')\n            self.web_sync.send_song_start(title, artist, self.engine.syllables_data)\n    except Exception as e:\n        print(f"⚠️ WebSync send_song_start: {e}")\n    \n    try:\n        # ✅ Se è MIDI usa FluidSynth\n        if self.is_midi and self.fs:\n            print(f"🎹 Avvio MIDI con FluidSynth: fs.initialized={self.fs.initialized}")\n            # ✅ APPLICA PITCH PRIMA DI PLAY\n            if self.current_pitch != 0 and hasattr(self.fs, \'set_pitch\'):\n                try:\n                    self.fs.set_pitch(self.current_pitch)\n                    print(f"🎵 MIDI pitch pre-play: {self.current_pitch:+d}")\n                except:\n                    pass\n            self.fs.play()\n            self._midi_play_start = time.time()  # ✅ Grace period per end-detection\n            # ✅ RIAPPLICA PITCH DOPO PLAY (safety: fs.play() chiama stop() interno\n            #    che potrebbe interferire con il valore impostato)\n            if self.current_pitch != 0 and hasattr(self.fs, \'set_pitch\'):\n                try:\n                    self.fs.set_pitch(self.current_pitch)\n                    print(f"🎵 MIDI pitch post-play: {self.current_pitch:+d}")\n                except:\n                    pass\n            self.start_time = time.time() * 1000\n            print(f"▶ MIDI avviato con FluidSynth: {Path(self.current_file).name}")\n        elif self.is_midi and not self.fs:\n            print("❌ MIDI ma FluidSynth non disponibile!")\n            return\n        elif self.is_bass_audio and self.bass_engine:\n            # ✅ BASS Engine audio (48kHz/32bit) — solo pitch, no speed\n            _be = self.bass_engine\n            # Applica pitch (senza toccare velocità)\n            if self.current_pitch != 0:\n                _be.set_pitch(self.current_pitch)\n            # Applica volume (con gain normalizzazione real-time — max 100%)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            _bass_vol = min(1.0, self._user_volume * max(1.0, _ng))\n            _be.set_master_gain(_bass_vol)\n            if _ng > 1.05:\n                print(f"🔊 BASS volume: {_bass_vol:.2f} (user={self._user_volume:.0%} × gain={_ng:.2f})")\n            # End callback\n            _be.on_playback_end = lambda: self.master.after(0, self._on_bass_audio_end)\n            _be.play()\n            self.start_time = time.time() * 1000\n            print(f"▶ Audio BASS avviato: {Path(self.current_file).name}")\n            # ✅ Avvia la voce guida in cuffia per QUALSIASI percorso di play\n            #    (libreria, comandi in basso, playlist anche automatiche)\n            try:\n                from .cuffia_guida import guida as _guida\n                _pos = 0\n                try: _pos = self.bass_engine.get_position_ms()\n                except Exception: _pos = 0\n                _guida.play(self.current_file, sync_ms=_pos)\n            except Exception as _e:\n                print(f"⚠️ voce guida: {_e}")\n        elif self.is_mpv_audio and self.mpv_player:\n            # ✅ MPV audio\n            pending = getattr(self, \'_mpv_pending_file\', self.current_file)\n            self.mpv_player.play(pending.replace(\'\\\\\', \'/\'))\n            self.start_time = time.time() * 1000\n            self._mpv_started_pos = None\n            \n            # ✅ SEMPRE applica rate/pitch — pulisce rubberband residuo\n            self._apply_rate()\n            \n            # Volume — imposta subito E verifica dopo\n            self._apply_mpv_volume()\n            \n            print(f"▶ Audio MPV avviato: {Path(pending).name}")\n\n            # Watchdog: alcuni file KFN/MKF possono restare fermi a 0s pur risultando "idle"\n            def _mpv_start_watchdog(expected_file=pending):\n                try:\n                    if not (self.is_mpv_audio and self.mpv_player):\n                        return\n                    pos = self.mpv_player.time_pos\n                    eof = bool(getattr(self.mpv_player, \'eof_reached\', False))\n                    if pos is not None and pos > 0.35:\n                        self._mpv_started_pos = pos\n                        return\n                    if eof:\n                        return\n                    if (getattr(self, \'is_kfn\', False) or getattr(self, \'is_mkf\', False)) and int(getattr(self, \'current_pitch\', 0) or 0) == 0:\n                        try:\n                            pygame.mixer.music.load(expected_file)\n                            self.mpv_player.command(\'stop\')\n                            self.is_mpv_audio = False\n                            print(f"⚠️ MPV fermo a 0s su {Path(expected_file).name} → fallback pygame")\n                        except Exception as pe:\n                            print(f"⚠️ MPV fermo a 0s ma fallback pygame fallito: {pe}")\n                except Exception:\n                    pass\n            self.master.after(2200, _mpv_start_watchdog)\n            \n            # Durata e verifica volume (dopo 500ms per dare tempo a MPV)\n            def _mpv_setup():\n                try:\n                    if self.mpv_player and self.is_mpv_audio:\n                        # ✅ VERIFICA VOLUME (con gain normalizzazione)\n                        try:\n                            actual_vol = self.mpv_player.volume\n                            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                            expected_vol = min(100, self._user_volume * max(1.0, _ng) * 100)\n                            if actual_vol is not None and abs(actual_vol - expected_vol) > 5:\n                                print(f"⚠️ MPV volume drift: actual={actual_vol:.0f} expected={expected_vol:.0f} → correggo")\n                                self.mpv_player[\'volume\'] = expected_vol\n                            else:\n                                print(f"🔊 MPV volume OK: {actual_vol:.0f}%")\n                        except Exception as ve:\n                            print(f"⚠️ MPV volume check: {ve}")\n                        \n                        dur = self.mpv_player.duration\n                        if dur and dur > 0:\n                            dur_ms = int(dur * 1000)\n                            self.engine.total_duration_ms = dur_ms\n                            self.monitor.total_duration_ms = dur_ms\n                            d_min = int(dur_ms / 60000)\n                            d_sec = int((dur_ms % 60000) / 1000)\n                            self.monitor.total_label.config(text=f"{d_min:02d}:{d_sec:02d}")\n                            self.monitor.countdown_label.config(text=f"-{d_min:02d}:{d_sec:02d}")\n                            if self.monitor_pubblico:\n                                try:\n                                    pub = self.monitor_pubblico.monitor_frame\n                                    pub.total_duration_ms = dur_ms\n                                    pub.total_label.config(text=f"{d_min:02d}:{d_sec:02d}")\n                                    pub.countdown_label.config(text=f"-{d_min:02d}:{d_sec:02d}")\n                                except: pass\n                except: pass\n            self.master.after(500, _mpv_setup)\n            # ✅ Seconda verifica volume a 1500ms (MPV potrebbe resettare dopo buffering)\n            self.master.after(1500, self._apply_mpv_volume)\n        elif self.is_vlc_audio and self.vlc_audio:\n            # ✅ VLC audio-only (qualità professionale)\n            ret = self.vlc_audio.play()\n            dbg("SYSTEM", f"VLC audio play() -> ret={ret}")\n            if ret == -1:\n                print("⚠️ VLC play() → -1, fallback pygame")\n                self.is_vlc_audio = False\n                # ✅ CLEANUP VLC prima del fallback (rilascia file lock)\n                try:\n                    self.vlc_audio.stop()\n                    self.vlc_audio.set_media(None)\n                except:\n                    pass\n                self.vlc_audio = None\n                self._seeking = True  # ✅ Previeni false detection "finito"\n                try:\n                    pygame.mixer.music.load(self.current_file)\n                    pygame.mixer.music.play()\n                    dbg("SYSTEM", "pygame music.play()")\n                    pygame.mixer.music.set_volume(self._user_volume)\n                    print("✅ Fallback pygame riuscito (play -1)")\n                except Exception as pe:\n                    print(f"❌ Anche pygame fallito: {pe}")\n                self.master.after(500, lambda: setattr(self, \'_seeking\', False))\n            else:\n                self._vlc_play_start = time.time()  # ✅ Grace period per is_playing()\n                # ✅ SETTA VOLUME SUBITO (con gain normalizzazione — VLC max 100%)\n                _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                vol_pct = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n                self.vlc_audio.audio_set_volume(vol_pct)\n                # ✅ APPLICA PITCH+SPEED SUBITO (rispetta Pedalboard)\n                if self.current_pitch != 0 or self.current_speed != 1.0:\n                    if getattr(self, \'_pitched_file\', None):\n                        # Pitch è nel file → solo speed\n                        self.vlc_audio.set_rate(max(0.25, min(4.0, self.current_speed)))\n                        print(f"🎵 VLC audio: speed={self.current_speed:.2f}x (pitch nel file Pedalboard)")\n                    else:\n                        # Fallback: pitch+speed combinati\n                        _rate = pow(2.0, self.current_pitch / 12.0) * self.current_speed\n                        self.vlc_audio.set_rate(_rate)\n                        print(f"🎵 VLC audio rate={_rate:.3f} (pitch={self.current_pitch:+d}, speed={self.current_speed:.2f}x)")\n            \n            self.start_time = time.time() * 1000\n            \n            # ✅ Volume e durata DOPO che VLC è partito (non subito)\n            def _vlc_audio_setup():\n                try:\n                    if not self.is_vlc_audio or not self.vlc_audio:\n                        return\n                    # ✅ SAFETY: verifica che VLC stia effettivamente suonando\n                    if not self.vlc_audio.is_playing():\n                        print("⚠️ VLC audio non partito dopo 500ms, fallback pygame")\n                        self.is_vlc_audio = False\n                        # ✅ CLEANUP VLC prima del fallback\n                        try:\n                            self.vlc_audio.stop()\n                            self.vlc_audio.set_media(None)\n                        except:\n                            pass\n                        self.vlc_audio = None\n                        # ✅ Previeni false detection "finito" durante switch\n                        self._seeking = True\n                        try:\n                            pygame.mixer.music.load(self.current_file)\n                            pygame.mixer.music.play()\n                            pygame.mixer.music.set_volume(self._user_volume)\n                            self.start_time = time.time() * 1000\n                            print("✅ Fallback pygame riuscito")\n                        except Exception as pe:\n                            print(f"❌ Anche pygame fallito: {pe}")\n                        # ✅ Rilascia flag dopo breve delay\n                        self.master.after(500, lambda: setattr(self, \'_seeking\', False))\n                        return\n                    # Volume (con gain normalizzazione — VLC max 100%)\n                    _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                    vol_pct = int(min(100, self._user_volume * max(1.0, _ng) * 100))\n                    self.vlc_audio.audio_set_volume(vol_pct)\n                    print(f"🔊 VLC audio: volume={vol_pct}%, is_playing=True")\n                    # Durata\n                    dur = self.vlc_audio.get_length()\n                    if dur > 0:\n                        self.engine.total_duration_ms = dur\n                        if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n                            dur_min = int(dur / 60000)\n                            dur_sec = int((dur % 60000) / 1000)\n                            self.info_brano_ref[\'duration\'].config(text=f"{dur_min:02d}:{dur_sec:02d}")\n                    else:\n                        # Riprova durata tra 500ms\n                        def _retry_dur():\n                            try:\n                                if self.is_vlc_audio and self.vlc_audio:\n                                    d = self.vlc_audio.get_length()\n                                    if d > 0:\n                                        self.engine.total_duration_ms = d\n                            except:\n                                pass\n                        self.master.after(500, _retry_dur)\n                except Exception as e:\n                    print(f"⚠️ VLC audio setup: {e}")\n            self.master.after(500, _vlc_audio_setup)  # ✅ 500ms per dare tempo a VLC\n            print(f"▶ Audio VLC avviato: {Path(self.current_file).name}")\n        else:\n            # ✅ RICARICA FILE AUDIO SE È STATO SCARICATO DA STOP()\n            try:\n                pygame.mixer.music.play()\n            except:\n                # File scaricato, ricarica\n                print("🔄 Ricarico file audio...")\n                pygame.mixer.music.load(self.current_file)\n                pygame.mixer.music.play()\n            \n            self.start_time = time.time() * 1000\n            print(f"▶ Audio avviato: {Path(self.current_file).name}")\n            \n            # ✅ Applica volume (pygame capped a 1.0 — gain normalizzazione non supportato)\n            _ng = self.normalization_gain if self.normalization_enabled else 1.0\n            pygame.mixer.music.set_volume(max(0.0, min(1.0, self._user_volume * max(1.0, _ng))))\n        \n        # ✅ Aggiorna duration label nei controlli in basso\n        if hasattr(self, \'info_brano_ref\') and self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n            total_ms = 0\n            if self.engine and self.engine.total_duration_ms > 0:\n                total_ms = self.engine.total_duration_ms\n            elif self.monitor.syllables_data:\n                total_ms = self.monitor.syllables_data[-1][1]\n            \n            if total_ms > 0:\n                total_sec = int(total_ms / 1000)\n                self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n    except Exception as e:\n        print(f"⚠️ Errore play audio: {e}")\n        self.is_playing = False\n        return\n    \n    # ✅ Se REC rapido è armato, avvia ora: dopo il play effettivo\n    self._start_armed_audio_recording()\n\n    self.playback_thread = threading.Thread(target=self._playback_loop, daemon=True)\n    self.playback_thread.start()\n    \n    # ✅ Applica pitch+speed salvati SOLO se diversi da default\n    if self.current_pitch != 0 or self.current_speed != 1.0:\n        self.master.after(400, self._apply_rate)\n    \n    # ✅ SBLOCCA monitor dopo che VLC/pygame si è stabilizzato (solo se non è pitch swap)\n    if not getattr(self, \'_skip_monitor_reset\', False):\n        self.master.after(300, lambda: setattr(self, \'_seeking\', False))\n        # ✅ SAFETY BACKUP: se il primo after non parte (mainloop occupato), rilascia comunque\n        self.master.after(1500, lambda: setattr(self, \'_seeking\', False))\n\n\ndef _audio_video_su_bass(self):\n    """Suona l\'audio estratto dal video con BASS, come si fa con gli MP3.\n\n    PERCHE\' BASS E NON MPV: sugli MP3 la tonalita\' la fa BASS (FREQ per il\n    tono + SoundTouch che ricompensa la durata) e il risultato e\' quello\n    che il cantante si aspetta. Usare lo stesso motore anche per l\'audio\n    dei video vuol dire stessa resa, stesso comportamento, stesse regole.\n    MPV resta come ripiego se BASS non c\'e\'.\n\n    Torna True se l\'ha preso in carico.\n    """\n    try:\n        from .bass_engine import is_bass_available, get_bass_engine\n    except Exception as e:\n        self._voce_log(\'BASS: non riesco a caricarlo (%s)\' % e)\n        return False\n    if not is_bass_available():\n        self._voce_log(\'BASS: dice di non essere disponibile\')\n        return False\n    try:\n        _be = get_bass_engine()\n        if not _be.initialized:\n            _be.initialize()\n        _sorg = self._voce_scegli(self._video_audio_extracted)\n        # ⚠️ si scrive QUALE file si carica: e\' il punto dove il tasto\n        #    premuto a brano fermo si perdeva, e senza questa riga non\n        #    c\'era modo di accorgersene\n        self._voce_log(\'audio del video su BASS, voce a %d%%: %s\'\n                       % (getattr(self, \'voce_giu\', 0),\n                          \'file con la voce giu-\' if _sorg != self._video_audio_extracted\n                          else \'file originale\'))\n        if not _be.initialized or not _be.load(_sorg):\n            self._voce_log(\'audio del video su BASS: NON caricato\')\n            return False\n\n        pos_ms = max(0, self.engine.vlc_player.get_time())\n\n        # il video resta muto: l\'audio esce da BASS\n        self.engine.vlc_player.audio_set_mute(True)\n        if self.engine.vlc_player_pubblico:\n            try: self.engine.vlc_player_pubblico.audio_set_mute(True)\n            except: pass\n\n        self.bass_engine = _be\n        self.is_bass_audio = True\n        self.is_mpv_audio = False\n        self._video_pitch_active = True\n\n        _be.play()\n        _be.seek_ms(pos_ms)\n        try:\n            _be.set_volume(max(0.0, min(1.0, self._user_volume)))   # 0..1: NON 0..127\n        except Exception:\n            pass\n        _be.set_pitch(self.current_pitch)\n        _be.set_speed(max(0.25, min(4.0, self.current_speed)))\n        print(f"🎬 Audio del video su BASS: tonalita\' {self.current_pitch:+d}, "\n              f"posizione {pos_ms}ms")\n        return True\n    except Exception as e:\n        self._voce_log("BASS: audio del video NON riuscito (%s: %s)" % (type(e).__name__, e))\n        return False\n\n\ndef _activate_video_mpv_audio(self):\n    """Attiva audio separato MPV per video (muta VLC, avvia MPV con audio estratto)"""\n    # ⚠️ SI SCRIVE NEL REGISTRO: qui ci sono due uscite silenziose, e\n    #    quando si imboccano il tasto della voce sembra non fare niente\n    #    senza lasciare traccia da nessuna parte. Con `print` non si vede\n    #    nulla: nel programma compilato non c\'e\' nessuna finestra a\n    #    leggerlo.\n    # ⛔⛔ UNA VOLTA SOLA. Lo scambio puo\' arrivare da due strade insieme:\n    #     `play` (che adesso lo chiama subito, per non far suonare l\'audio\n    #     del video) e `set_voce` (che arriva un istante dopo, chiamata dal\n    #     play stesso). VISTO NEL REGISTRO: due "audio del video su BASS"\n    #     a un secondo di distanza — la base partiva e un secondo dopo\n    #     RIPARTIVA. **E\' quello il "saltino".**\n    #     Se l\'audio e\' gia\' staccato non si rifa\': non e\' spreco, e\'\n    #     proprio il difetto.\n    if getattr(self, \'is_bass_audio\', False) or getattr(self, \'is_mpv_audio\', False):\n        self._voce_log(\'stacco: gia- fatto, non lo rifaccio (bass=%s mpv=%s)\'\n                       % (getattr(self, \'is_bass_audio\', False),\n                          getattr(self, \'is_mpv_audio\', False)))\n        return\n\n    if not self.mpv_player or not self.current_file:\n        self._voce_log(\'stacco: NON parte - mpv=%s file=%s\'\n                       % (self.mpv_player is not None,\n                          str(self.current_file)[:60]))\n        return\n\n    # ⭐ Prima di rimettersi a lavorare: l\'audio di questo brano l\'abbiamo\n    #    gia\' staccato prima? Il dato viene azzerato quando il brano si\n    #    carica, ma il file e\' ancora li\' — e rifarlo dal flusso di\n    #    YouTube vuol dire riscaricare tutto il brano mentre la base suona.\n    # ⛔ SI PARTE DAL BRANO SCELTO, non da `current_file`: quando la base\n    #    parte, li\' dentro c\'e\' l\'indirizzo del FLUSSO di YouTube\n    #    (rr3---sn-....googlevideo.com/videoplayback?...), che NON contiene\n    #    il codice del video. Cercando con quello il ricordo non si trova\n    #    mai, e si ricomincia a scaricare tutto da capo.\n    # ⭐ SCORCIATOIA: se il brano con la voce gia\' abbassata c\'e\', prende\n    #    il posto del link e si suona quello. Niente video da riscaricare,\n    #    niente audio da staccare: e\' gia\' tutto dentro quel file.\n    pronto = self._voce_gia_pronto()\n    if pronto:\n        self._voce_log(\'stacco: c-e- gia- il brano pulito, suono quello (%s)\'\n                       % os.path.basename(pronto))\n        self._video_audio_extracted = pronto\n        self._finish_activate_video_mpv()\n        return\n\n    if not (self._video_audio_extracted\n            and os.path.exists(self._video_audio_extracted or \'\')):\n        memo = self._voce_audio_memo()\n        gia = None\n        cercate = []\n        for rif in (getattr(self, \'_voce_brano_scelto\', None), self.current_file):\n            if rif:\n                k = self._voce_chiave(rif)\n                cercate.append(k)\n                gia = memo.get(k)\n                if gia:\n                    break\n        # ⚠️ si scrivono le chiavi VERE, quelle cercate e quelle in\n        #    memoria: e\' l\'unico modo per vedere dove non combaciano,\n        #    invece di tirare a indovinare un tentativo alla volta\n        self._voce_log(\'memoria: cerco %s | dentro ho %s | trovato=%s c-e-=%s\'\n                       % (cercate or [\'(niente)\'],\n                          list(memo.keys()) or \'(vuota)\',\n                          str(gia)[:70],\n                          os.path.exists(gia) if gia else \'-\'))\n        if gia and os.path.exists(gia):\n            self._video_audio_extracted = gia\n            self._voce_log(\'stacco: riuso l-audio staccato prima (%s)\'\n                           % os.path.basename(gia))\n\n    # Se audio già estratto, attiva subito\n    if self._video_audio_extracted and os.path.exists(self._video_audio_extracted):\n        self._voce_log(\'stacco: l-audio c-e- gia-, attacco subito\')\n        self._finish_activate_video_mpv()\n        return\n    # ⛔⛔ UNA ESTRAZIONE ALLA VOLTA. La guardia in cima guarda\n    #     `is_bass_audio`, ma quello diventa vero solo a estrazione FINITA:\n    #     le due chiamate (da `play` e da `set_voce`) arrivavano entrambe\n    #     prima, partivano DUE estrazioni e ognuna, finendo, riattaccava la\n    #     base. VISTO NEL REGISTRO: "devo estrarre" alle :51 e alle :52,\n    #     "audio del video su BASS" alle :53 e di nuovo alle 11:00.\n    # ⚠️ ma il segnale SCADE: se un\'estrazione muore per strada il segnale\n    #    resta acceso e da li\' in poi nessun brano attacca piu\' la base\n    #    ("estrazione gia- in corso" a ogni play, visto l\'11-09)\n    if getattr(self, \'_stacco_in_corso\', False):\n        if time.time() - getattr(self, \'_stacco_quando\', 0) < 60:\n            self._voce_log(\'stacco: estrazione gia- in corso, non ne parto una seconda\')\n            return\n        self._voce_log(\'stacco: l-estrazione di prima e- rimasta appesa, riparto\')\n    self._stacco_in_corso = True\n    self._stacco_quando = time.time()\n    self._voce_log(\'stacco: devo estrarre l-audio, ci vuole un momento\')\n\n    # Altrimenti estrai in background\n    print(f"🎬 Estrazione audio video in background...")\n    _file = self.current_file\n\n    def _bg_extract():\n        try:\n            extracted = self._extract_video_audio(_file)\n            if extracted and os.path.exists(extracted):\n                self._video_audio_extracted = extracted\n                # Torna al main thread per attivare MPV\n                self.master.after(0, self._finish_activate_video_mpv)\n            else:\n                self._stacco_in_corso = False\n                self._voce_muta_video(False)\n                print("⚠️ Estrazione audio video fallita")\n        except Exception as e:\n            self._stacco_in_corso = False\n            self._voce_muta_video(False)\n            print(f"⚠️ Estrazione background: {e}")\n\n    threading.Thread(target=_bg_extract, daemon=True).start()\n\n\ndef _finish_activate_video_mpv(self):\n    """Completa attivazione audio separato per video (main thread).\n\n    Prima si prova BASS (stesso motore degli MP3), poi MPV.\n    """\n    # l\'estrazione e\' finita (bene o male): se ne puo\' partire un\'altra\n    self._stacco_in_corso = False\n    try:\n        # ⛔ se la base e\' GIA\' attaccata non si riattacca: e\' il secondo\n        #    aggancio che faceva ripartire il brano un attimo dopo\n        if getattr(self, \'is_bass_audio\', False) or getattr(self, \'is_mpv_audio\', False):\n            self._voce_log(\'attacco: gia- attaccata, non la riattacco\')\n            return\n        # ⚠️ Ogni uscita lascia una riga: erano tutte mute, e quando il\n        #    tasto della voce non faceva niente non c\'era modo di sapere\n        #    a quale di queste si era fermato.\n        if not self.is_playing or not self.engine.is_video:\n            self._voce_log(\'attacco: lascio stare (suona=%s video=%s)\'\n                           % (self.is_playing,\n                              getattr(self.engine, \'is_video\', \'?\')))\n            self._voce_muta_video(False)\n            return\n        if not self._video_audio_extracted or not os.path.exists(\n                self._video_audio_extracted or \'\'):\n            self._voce_log(\'attacco: l-audio staccato non c-e- (%s)\'\n                           % str(self._video_audio_extracted)[:70])\n            self._voce_muta_video(False)\n            return\n        # BASS per primo, come sempre: se la voce va abbassata gli\n        # arriva gia\' il file giusto (ci pensa _voce_scegli).\n        if self._audio_video_su_bass():\n            return\n        self._voce_log(\'attacco: BASS non l-ha preso, provo con MPV\')\n        if not self.mpv_player:\n            return\n        if not self._video_audio_extracted or not os.path.exists(self._video_audio_extracted):\n            return\n        \n        pos_ms = max(0, self.engine.vlc_player.get_time())\n        \n        # Muta VLC video\n        self.engine.vlc_player.audio_set_mute(True)\n        if self.engine.vlc_player_pubblico:\n            try: self.engine.vlc_player_pubblico.audio_set_mute(True)\n            except: pass\n        \n        # Avvia MPV con audio estratto (pitch via mpv[\'pitch\'] live)\n        mpv_path = str(self._voce_scegli(self._video_audio_extracted)).replace(\'\\\\\', \'/\')\n        self.mpv_player.play(mpv_path)\n        self.is_mpv_audio = True\n        self._video_pitch_active = True\n        \n        # Seek + volume + pitch dopo breve attesa\n        def _sync():\n            try:\n                if self.mpv_player and self._video_pitch_active:\n                    self.mpv_player.seek(pos_ms / 1000.0, \'absolute\')\n                    self._apply_mpv_volume()\n                    self._apply_rate()  # pitch + speed\n                    print(f"🎬 Video MPV audio attivo: pitch={self.current_pitch:+d} pos={pos_ms}ms")\n            except Exception as e:\n                print(f"⚠️ Video MPV sync: {e}")\n        self.master.after(500, _sync)\n    except Exception as e:\n        print(f"⚠️ Attivazione video MPV: {e}")\n        import traceback\n        traceback.print_exc()\n        try: self.engine.vlc_player.audio_set_mute(False)\n        except: pass\n\n\ndef set_pitch(self, semitoni: int):\n    """\n    Imposta pitch in semitoni (-12 a +12).\n    MPV: istantaneo via mpv[\'pitch\'] (zero filtri af/DSP).\n    MIDI: FluidSynth pitch indipendente.\n    Video: audio MPV separato.\n    """\n    semitoni = max(-12, min(12, semitoni))\n    self.current_pitch = semitoni\n    \n    # ✅ YouTube (player separato)\n    if hasattr(self, \'youtube_browser\') and self.youtube_browser:\n        try:\n            self.youtube_browser.set_pitch(semitoni)\n        except:\n            pass\n    \n    # ✅ Video con MPV audio separato\n    if self.engine.is_video and self.engine.vlc_player and self.mpv_player and not self.is_midi and self.is_playing:\n        if semitoni != 0 and not self._video_pitch_active:\n            self._activate_video_mpv_audio()\n        elif (semitoni == 0 and self._video_pitch_active\n              and not getattr(self, \'voce_giu\', 0)):\n            # ⛔ NON si torna all\'audio del video se la voce e\' abbassata:\n            #    il filtro sta nell\'audio staccato, e rimettendo il video\n            #    la voce tornerebbe fuori rimettendo la tonalita\' a zero.\n            self._deactivate_video_mpv_audio()\n    \n    # ✅ Applica pitch + speed — istantaneo!\n    self._apply_rate()\n\n\ndef stop(self, quick=False):\n    dbg("SYSTEM", f"stop(quick={quick}) is_playing={self.is_playing} gen={self._play_generation}")\n    """Ferma riproduzione - quick=True salta il fade (usato da load_file)"""\n    # ⭐ A brano finito si butta l\'audio di servizio: un brano di 4 minuti\n    #    lascia 78 MB di audio staccato piu\' 48 MB di copia pulita, e in\n    #    una serata da venti brani fanno oltre 2 GB che non toglie nessuno.\n    try:\n        self._voce_pulisci_temporanei()\n    except Exception:\n        pass\n    # ℹ️ Il tasto della voce NON si spegne qui: `stop` e\' anche\n    #    l\'interruzione, il fade e il cambio brano. Si spegne quando il\n    #    brano FINISCE — vedi `_voce_fine_brano`, chiamata dai tre punti\n    #    in cui un brano arriva in fondo da solo.\n\n    # ✅ Ferma la voce guida in cuffia insieme alla base\n    try:\n        from .cuffia_guida import guida as _guida\n        _guida.stop()\n    except Exception:\n        pass\n\n    # ✅ Se c\'era una registrazione rapida attiva, fermala\n    if not quick:\n        self._stop_quick_audio_recording_if_needed()\n\n    # ✅ Forza stop video/VLC audio/MIDI anche se is_playing è False\n    video_playing = False\n    vlc_audio_playing = False\n    midi_playing = False\n    try:\n        video_playing = self.engine.is_video and self.engine.vlc_player and self.engine.vlc_player.is_playing()\n    except:\n        pass\n    try:\n        vlc_audio_playing = self.is_vlc_audio and self.vlc_audio and self.vlc_audio.is_playing()\n    except:\n        pass\n    mpv_playing = False\n    bass_playing = False\n    try:\n        mpv_playing = self.is_mpv_audio and self.mpv_player\n    except:\n        pass\n    try:\n        bass_playing = self.is_bass_audio and self.bass_engine and self.bass_engine.is_playing\n    except:\n        pass\n    try:\n        midi_playing = self.is_midi and self.fs and self.fs.is_playing\n    except:\n        pass\n    \n    needs_audio_stop = self.is_playing or self.is_paused or video_playing or vlc_audio_playing or midi_playing or mpv_playing or bass_playing\n    \n    self.is_playing = False\n    self.is_paused = False\n    self._play_generation += 1  # ✅ Invalida callback stale dal playback loop\n    self._ui_update_pending = False  # ✅ Reset anti-accumulo\n    \n    # ✅ PER VIDEO: aspetta che il playback loop esca prima di toccare VLC\n    # VLC non è thread-safe: stop() + get_time() simultanei = segfault\n    if (video_playing or (self.engine.is_video and self.engine.vlc_player)):\n        if self.playback_thread and self.playback_thread.is_alive():\n            for _u_i in range(20):  # Max 200ms\n                if not self.playback_thread.is_alive():\n                    break\n                time.sleep(0.01)\n    \n    try:\n        dbg("SYSTEM", "WebSync send_song_stop")\n        self.web_sync.send_song_stop()\n    except:\n        pass\n    \n    # ===== STOP AUDIO (solo se c\'è audio da fermare) =====\n    if needs_audio_stop:\n        if self.engine.is_video and self.engine.vlc_player:\n            try:\n                # ✅ Ferma anche audio separato (video pitch con MPV)\n                if self._video_pitch_active:\n                    if self.mpv_player:\n                        try: self.mpv_player.command("stop")\n                        except: pass\n                    if self.vlc_audio:\n                        try:\n                            self.vlc_audio.stop()\n                            self.vlc_audio.set_media(None)\n                        except: pass\n                    try: self.engine.vlc_player.audio_set_mute(False)\n                    except: pass\n                \n                # ✅ Stop immediato (niente mini-fade bloccante sul main thread!)\n                self.engine.vlc_player.stop()\n                \n                if self.engine.vlc_player_pubblico:\n                    try: self.engine.vlc_player_pubblico.stop()\n                    except: pass\n            except Exception as e:\n                print(f"⚠️ Stop video fallito: {e}")\n                try:\n                    self.engine.vlc_player.stop()\n                except: pass\n                try:\n                    if self.engine.vlc_player_pubblico:\n                        self.engine.vlc_player_pubblico.stop()\n                except: pass\n            # ⚠️ Se la tonalita\' del video la stava facendo BASS, va fermato\n            # QUI: piu\' sotto c\'e\' un "elif is_bass_audio" che con un video\n            # non viene mai raggiunto, e l\'audio restava a suonare da solo\n            # dopo la chiusura del video.\n            if self.is_bass_audio and self.bass_engine:\n                try: self.bass_engine.stop()\n                except Exception: pass\n                self.is_bass_audio = False\n\n            # ✅ Reset stato video pitch\n            self._video_pitch_active = False\n            self.is_vlc_audio = False\n            self.is_mpv_audio = False\n        elif self.is_bass_audio and self.bass_engine:\n            try:\n                self.bass_engine.stop()\n            except Exception as e:\n                print(f"⚠️ Stop BASS fallito: {e}")\n            self.is_bass_audio = False\n        elif self.is_mpv_audio and self.mpv_player:\n            try:\n                self.mpv_player.command("stop")\n            except Exception as e:\n                print(f"⚠️ Stop MPV fallito: {e}")\n            self.is_mpv_audio = False\n        elif self.is_vlc_audio and self.vlc_audio:\n            try:\n                if not quick:\n                    # ✅ Fade rapido: 5 step da 15ms = 75ms max (era fino a 800ms)\n                    current_vol = self.vlc_audio.audio_get_volume()\n                    if current_vol > 0:\n                        step = max(1, current_vol // 5)\n                        for vol in range(current_vol, 0, -step):\n                            self.vlc_audio.audio_set_volume(vol)\n                            time.sleep(0.015)\n                        self.vlc_audio.audio_set_volume(0)\n                self.vlc_audio.stop()\n                self.vlc_audio.set_media(None)\n            except Exception as e:\n                print(f"⚠️ Stop VLC audio fallito: {e}")\n                try:\n                    self.vlc_audio.stop()\n                    self.vlc_audio.set_media(None)\n                except:\n                    pass\n        else:\n            if self.is_midi and self.fs:\n                try:\n                    self.fs.stop()\n                    # ✅ Ripristina gain dopo stop (con normalizzazione)\n                    _ng = self.normalization_gain if self.normalization_enabled else 1.0\n                    self.fs.set_master_gain(min(1.0, self._user_volume * max(1.0, _ng)))\n                except Exception as e:\n                    print(f"⚠️ Stop MIDI fallito: {e}")\n            else:\n                try:\n                    if not quick and pygame.mixer.music.get_busy():\n                        # ✅ Fade rapido: 5 step da 15ms = 75ms (era 200ms)\n                        for vol in range(8, 0, -2):\n                            pygame.mixer.music.set_volume(vol / 10.0)\n                            time.sleep(0.015)\n                    pygame.mixer.music.stop()\n                    pygame.mixer.music.set_volume(self._user_volume)\n                except Exception as e:\n                    try:\n                        pygame.mixer.music.stop()\n                    except:\n                        pass\n        \n        # Ferma thread\n        if self.playback_thread and self.playback_thread.is_alive():\n            if not quick:\n                time.sleep(0.1)\n    \n    # ===== PULISCI MONITOR — SEMPRE (anche dopo fade_out) =====\n    if not getattr(self, \'_skip_monitor_reset\', False):\n        # Monitor principale\n        try:\n            self.monitor.clear()\n            print("🧹 Clear monitor principale OK")\n        except Exception as e:\n            print(f"⚠️ Clear monitor principale fallito: {e}")\n        \n        # Monitor pubblico — IDENTICO al principale, stessa chiamata\n        if self.monitor_pubblico:\n            pub = self.monitor_pubblico.monitor_frame\n            try:\n                pub.clear()\n                print(f"🧹 Clear monitor pubblico OK (syllables={len(pub.syllables_data)}, cleared={pub._is_cleared})")\n            except Exception as e:\n                print(f"⚠️ Clear monitor pubblico fallito: {e}")\n                # ✅ FALLBACK: forza pulizia testo anche se clear() fallisce\n                try:\n                    pub.syllables_data = []\n                    pub._is_cleared = True\n                    pub.text_widget.config(state=\'normal\')\n                    pub.text_widget.delete(\'1.0\', \'end\')\n                    pub.text_widget.config(state=\'disabled\')\n                    print("🧹 Fallback pulizia pub OK")\n                except:\n                    pass\n            # Yellow bar\n            try:\n                if hasattr(self.monitor_pubblico, \'yellow_bar_container\'):\n                    self.monitor_pubblico.yellow_bar_container.place_forget()\n                    self.monitor_pubblico._yellow_bar_visible = False\n            except:\n                pass\n        else:\n            print("🧹 Monitor pubblico non presente")\n    else:\n        print("⚠️ _skip_monitor_reset=True, monitor NON puliti!")\n    \n    # ✅ RIPRISTINA OVERLAY IMMAGINE dopo stop (vecchio sistema, se presente)\n    if hasattr(self.master, \'_overlay_immagine\'):\n        self.master._overlay_immagine.restore()\n\n    # ✅ RIPRISTINA OVERLAY IMMAGINE sul MONITOR PUBBLICO a fine brano\n    # (l\'immagine deve ricomparire quando un brano finisce e sparire solo\n    #  quando ne riparte uno nuovo — la sparizione avviene al PLAY)\n    if self.monitor_pubblico and getattr(self.monitor_pubblico, \'image_overlay_enabled\', False):\n        try:\n            self.monitor_pubblico.restore_image_overlay()\n        except Exception as _e:\n            print(f"⚠️ restore overlay immagine pubblico fallito: {_e}")\n    \n    if self.engine.is_video:\n        try:\n            self.monitor.video_canvas.pack_forget()\n            self.monitor.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n            self.monitor.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n            self.monitor.text_widget.pack(fill=\'both\', expand=True)\n            # Pubblico\n            if self.monitor_pubblico:\n                pub = self.monitor_pubblico.monitor_frame\n                pub.video_canvas.pack_forget()\n                pub.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                pub.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                pub.text_widget.pack(fill=\'both\', expand=True)\n        except:\n            pass\n    \n    # ✅ RIPRISTINA LAYOUT DOPO CDG\n    if self.is_cdg:\n        try:\n            self.monitor.video_canvas.delete(\'cdg\')  # Pulisci frame CDG\n            self.monitor.video_canvas.pack_forget()\n            self.monitor.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n            self.monitor.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n            self.monitor.text_widget.pack(fill=\'both\', expand=True)\n            # Pubblico\n            if self.monitor_pubblico:\n                pub = self.monitor_pubblico.monitor_frame\n                pub.video_canvas.delete(\'cdg\')\n                pub.video_canvas.pack_forget()\n                pub.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                pub.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                pub.text_widget.pack(fill=\'both\', expand=True)\n            print("🔄 Layout ripristinato dopo CDG")\n        except:\n            pass\n        self.is_cdg = False\n    \n    # Reset stato interno\n    self.start_time = 0\n    self.playback_thread = None\n    \n    # ✅ SAFETY CLEAR — backup a 300ms, 600ms e 1200ms\n    # Cattura stale callbacks che arrivano dopo stop()\n    _stop_gen = self._play_generation\n    def _safety_clear():\n        if self._play_generation != _stop_gen or self.is_playing:\n            return\n        try:\n            # Forza clear su entrambi i monitor\n            if not self.monitor._is_cleared:\n                self.monitor.clear()\n            if self.monitor_pubblico:\n                pub = self.monitor_pubblico.monitor_frame\n                if not getattr(pub, \'_is_cleared\', False):\n                    pub.clear()\n                else:\n                    # ✅ Anche se _is_cleared, forza svuotamento testo\n                    # (potrebbe esserci testo residuo da callback stale)\n                    try:\n                        pub.text_widget.config(state=\'normal\')\n                        pub.text_widget.delete(\'1.0\', \'end\')\n                        pub.text_widget.config(state=\'disabled\')\n                    except:\n                        pass\n        except:\n            pass\n    \n    # ✅ NUCLEAR CLEAR — forza svuotamento diretto del text_widget\n    # Non dipende da clear() o flag, agisce direttamente sul widget\n    def _nuclear_clear():\n        if self._play_generation != _stop_gen or self.is_playing:\n            return\n        for mon in [self.monitor, \n                    self.monitor_pubblico.monitor_frame if self.monitor_pubblico else None]:\n            if mon is None:\n                continue\n            try:\n                mon.syllables_data = []\n                mon._is_cleared = True\n                mon.current_index = -1\n                mon.text_widget.config(state=\'normal\')\n                mon.text_widget.delete(\'1.0\', \'end\')\n                mon.text_widget.config(state=\'disabled\')\n                mon.text_widget.update_idletasks()\n            except:\n                pass\n    \n    try:\n        self.master.after(200, _safety_clear)\n        self.master.after(500, _nuclear_clear)\n        self.master.after(1000, _nuclear_clear)\n        self.master.after(2000, _nuclear_clear)\n    except:\n        pass\n    \n    # ✅ RILASCIA IL FILE per non tenerlo occupato\n    # ⛔ MA SOLO se nessun nuovo brano è stato caricato nel frattempo!\n    #    Confronta la generazione catturata dal nostro playback_loop (_my_generation)\n    #    con la _stop_gen catturata da stop(). Se la generazione è avanzata\n    #    OLTRE _stop_gen, significa che load_file()+play() sono intervenuti.\n    _gen_now = self._play_generation\n    if self._loading_new_file or self.is_playing or self.is_paused:\n        print("⚠️ Skip unload — nuovo brano in caricamento/riproduzione")\n    elif _gen_now > _stop_gen + 1:\n        # stop incrementa di 1, load_file incrementa altre 2 volte, play un\'altra → drift > 1\n        print(f"⚠️ Skip unload — generazione avanzata (stop={_stop_gen}, now={_gen_now})")\n    else:\n        try:\n            pygame.mixer.music.unload()\n        except:\n            pass\n        \n        # ✅ Rilascia VLC audio (MP3/CDG)\n        if self.vlc_audio:\n            try:\n                self.vlc_audio.stop()\n                self.vlc_audio.set_media(None)\n            except:\n                pass\n            self.vlc_audio = None\n        \n        # ✅ Rilascia VLC video\n        if self.engine.vlc_player:\n            try:\n                self.engine.vlc_player.stop()\n                self.engine.vlc_player.set_media(None)\n            except:\n                pass\n        if self.engine.vlc_player_pubblico:\n            try:\n                self.engine.vlc_player_pubblico.stop()\n                self.engine.vlc_player_pubblico.set_media(None)\n            except:\n                pass\n        \n        # ✅ Reset decoder CDG per permettere replay\n        if hasattr(self.engine, \'cdg_decoder\') and self.engine.cdg_decoder:\n            self.engine.cdg_decoder._reset()\n        \n        # ✅ Rilascia file pitched temporaneo\n        if getattr(self, \'_pitched_file\', None):\n            try:\n                import os\n                if os.path.exists(self._pitched_file):\n                    os.remove(self._pitched_file)\n            except:\n                pass\n            self._pitched_file = None\n        \n        # ✅ Mantieni current_file per permettere replay dalla libreria\n        # self.current_file resta valorizzato — play() ricaricherà il file\n        self._file_unloaded = True  # ✅ Flag: play() deve ricaricare\n        \n        print("🗑️ File rilasciato (unload completo)")\n    \n    # ✅ RIPRENDI SOTTOFONDO se era in pausa per brano utente\n    # Schedulato con delay per non interferire se stop() è chiamato da load_file()\n    if self._sottofondo_manager and getattr(self._sottofondo_manager, \'_paused_for_user\', False):\n        _resume_gen = self._play_generation\n        def _maybe_resume():\n            # Solo se nessun nuovo brano è stato caricato nel frattempo\n            if (self._play_generation == _resume_gen \n                and not self.is_playing and not self.is_paused\n                and not getattr(self, \'_loading_new_file\', False)\n                and self._sottofondo_manager.is_playing\n                and self._sottofondo_manager._paused_for_user):\n                self._sottofondo_manager._resume_after_user_song()\n        try:\n            self.master.after(800, _maybe_resume)\n        except:\n            pass\n\n\ndef fade_out(self, duration_ms=3000):\n    dbg("SYSTEM", f"fade_out({duration_ms}ms) is_playing={self.is_playing}")\n    """Fade out graduale della song (eseguire in thread separato!)"""\n    if not self.is_playing:\n        return\n    \n    steps = 60\n    delay = duration_ms / 1000 / steps\n    \n    # ✅ PER VIDEO: ferma il playback loop PRIMA del fade\n    # VLC non è thread-safe: due thread che chiamano VLC = segfault\n    is_video = self.engine.is_video and self.engine.vlc_player\n    if is_video:\n        # Ferma playback loop (che chiama vlc_player.get_time())\n        self.is_playing = False\n        self._play_generation += 1\n        # Aspetta che il loop esca (max 300ms)\n        for _u_i in range(30):\n            if not self.playback_thread or not self.playback_thread.is_alive():\n                break\n            time.sleep(0.01)\n        \n        # Ora siamo l\'UNICO thread che tocca VLC — fade volume\n        try:\n            current_vol = self.engine.vlc_player.audio_get_volume()\n            mpv_vol = 0\n            if self._video_pitch_active and self.mpv_player:\n                try: mpv_vol = self.mpv_player.volume or 0\n                except: pass\n            # ⚠️ Se la tonalita\' del video la sta facendo BASS, l\'audio esce\n            # da LI\': sfumando solo VLC il video si fermava e la musica\n            # restava a suonare.\n            bass_vol = 0\n            if self.is_bass_audio and self.bass_engine:\n                try: bass_vol = max(0.0, min(1.0, self._user_volume))\n                except Exception: bass_vol = 1.0\n\n            for i in range(steps, 0, -1):\n                if not self.engine.vlc_player:\n                    break\n                factor = (i / steps) ** 2\n                vol = int(current_vol * factor)\n                try:\n                    self.engine.vlc_player.audio_set_volume(vol)\n                except Exception:\n                    break\n                if self._video_pitch_active and self.mpv_player and mpv_vol > 0:\n                    try: self.mpv_player[\'volume\'] = mpv_vol * factor\n                    except: pass\n                if bass_vol > 0:\n                    # ⛔ `set_volume` di BASS vuole un GUADAGNO 0..2, non\n                    #    0..127: passandogli 127 veniva schiacciato al\n                    #    massimo e il volume restava pieno per quasi tutta\n                    #    la sfumatura, poi crollava di colpo. Era questo\n                    #    il fade "brusco" sui link.\n                    try: self.bass_engine.set_volume(bass_vol * factor)\n                    except Exception: pass\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out video fallito: {e}")\n        \n        # ✅ STOP VLC direttamente qui (unico thread, niente race condition)\n        try:\n            if self._video_pitch_active:\n                if self.mpv_player:\n                    try: self.mpv_player.command("stop")\n                    except: pass\n                if self.vlc_audio:\n                    try:\n                        self.vlc_audio.stop()\n                        self.vlc_audio.set_media(None)\n                    except: pass\n                try: self.engine.vlc_player.audio_set_mute(False)\n                except: pass\n            # e BASS va fermato per davvero, non solo abbassato\n            if self.is_bass_audio and self.bass_engine:\n                try: self.bass_engine.stop()\n                except Exception: pass\n                try: self.bass_engine.set_volume(max(0.0, min(1.0, self._user_volume)))   # 0..1: NON 0..127\n                except Exception: pass\n                self.is_bass_audio = False\n                self._video_pitch_active = False\n            self.engine.vlc_player.stop()\n            if self.engine.vlc_player_pubblico:\n                try: self.engine.vlc_player_pubblico.stop()\n                except: pass\n        except Exception as e:\n            print(f"⚠️ Stop VLC dopo fade fallito: {e}")\n        \n        self._video_pitch_active = False\n        self.is_vlc_audio = False\n        self.is_mpv_audio = False\n        self.is_paused = False\n        self.playback_thread = None\n        self.start_time = 0\n        \n        # ✅ UI cleanup sul main thread (thread-safe: solo roba Tk)\n        _fade_gen = self._play_generation  # ✅ Cattura generazione del fade\n        def _fade_ui_cleanup():\n            # ✅ Se play() è stato chiamato nel frattempo, NON smontare il layout\n            if self._play_generation != _fade_gen:\n                print("🔉 Fade cleanup ANNULLATO — nuovo play in corso")\n                return\n            try:\n                self._skip_monitor_reset = False\n                self.monitor.clear()\n                if self.monitor_pubblico:\n                    try: self.monitor_pubblico.monitor_frame.clear()\n                    except: pass\n                if self.engine.is_video:\n                    try:\n                        self.monitor.video_canvas.pack_forget()\n                        self.monitor.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                        self.monitor.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                        self.monitor.text_widget.pack(fill=\'both\', expand=True)\n                        if self.monitor_pubblico:\n                            pub = self.monitor_pubblico.monitor_frame\n                            pub.video_canvas.pack_forget()\n                            pub.background_canvas.place(x=0, y=0, relwidth=1, relheight=1)\n                            pub.text_frame.place(relx=0, rely=0, relwidth=1.0, relheight=1.0)\n                            pub.text_widget.pack(fill=\'both\', expand=True)\n                    except: pass\n                if hasattr(self.master, \'_overlay_immagine\'):\n                    try: self.master._overlay_immagine.restore()\n                    except: pass\n            except Exception as e:\n                print(f"⚠️ Fade UI cleanup: {e}")\n        self.master.after_idle(_fade_ui_cleanup)\n\n        # ✅ REC rapido: se il brano viene chiuso con FADE OUT, ferma la registrazione\n        # senza disarmare il bottone. Al prossimo PLAY ripartirà da solo.\n        self._stop_quick_audio_recording_if_needed()\n\n        print("🔉 Fade out video completato")\n        \n        # ✅ RIPRENDI SOTTOFONDO se era in pausa per brano utente\n        if self._sottofondo_manager and getattr(self._sottofondo_manager, \'_paused_for_user\', False):\n            _resume_gen = self._play_generation\n            def _maybe_resume_v():\n                if (self._play_generation == _resume_gen\n                    and not self.is_playing and not self.is_paused\n                    and self._sottofondo_manager.is_playing\n                    and self._sottofondo_manager._paused_for_user):\n                    self._sottofondo_manager._resume_after_user_song()\n            try:\n                self.master.after(800, _maybe_resume_v)\n            except:\n                pass\n        \n        return\n    \n    elif self.is_bass_audio and self.bass_engine:\n        try:\n            original_gain = self.bass_engine.get_master_gain()\n            for i in range(steps, 0, -1):\n                if not self.is_playing:\n                    break\n                factor = (i / steps) ** 2\n                self.bass_engine.set_master_gain(original_gain * factor)\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out BASS fallito: {e}")\n    elif self.is_mpv_audio and self.mpv_player:\n        try:\n            current_vol = self.mpv_player.volume or 100\n            for i in range(steps, 0, -1):\n                if not self.is_playing:\n                    break\n                factor = (i / steps) ** 2\n                self.mpv_player[\'volume\'] = current_vol * factor\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out MPV fallito: {e}")\n    elif self.is_midi and self.fs:\n        try:\n            original_gain = self.fs.get_master_gain()\n            for i in range(steps, 0, -1):\n                if not self.is_playing:\n                    break\n                factor = (i / steps) ** 2\n                self.fs.set_master_gain(original_gain * factor)\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out MIDI fallito: {e}")\n    elif self.is_vlc_audio and self.vlc_audio:\n        try:\n            current_vol = self.vlc_audio.audio_get_volume()\n            for i in range(steps, 0, -1):\n                if not self.is_playing:\n                    break\n                factor = (i / steps) ** 2\n                vol = int(current_vol * factor)\n                self.vlc_audio.audio_set_volume(vol)\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out VLC audio fallito: {e}")\n    else:\n        try:\n            current_vol = pygame.mixer.music.get_volume()\n            for i in range(steps, 0, -1):\n                if not self.is_playing:\n                    break\n                factor = (i / steps) ** 2\n                pygame.mixer.music.set_volume(current_vol * factor)\n                time.sleep(delay)\n        except Exception as e:\n            print(f"⚠️ Fade out audio fallito: {e}")\n    \n    # ✅ REC rapido: se il brano viene chiuso con FADE OUT, ferma la registrazione\n    # senza disarmare il bottone. Al prossimo PLAY ripartirà da solo.\n    self._stop_quick_audio_recording_if_needed()\n\n    # ✅ Per non-video: stop normale\n    self.is_playing = False\n    self._play_generation += 1\n    self.master.after_idle(lambda: self.stop(quick=True))\n    print("🔉 Fade out completato")\n\n\ndef _on_bass_audio_end(self):\n    """Callback quando BASS audio finisce la riproduzione."""\n    if self.is_bass_audio and self.is_playing:\n        print("🎵 BASS audio finito")\n        self.is_playing = False\n        self._voce_fine_brano()\n        self.is_bass_audio = False\n        # ✅ Ferma la voce guida in cuffia a fine brano\n        try:\n            from .cuffia_guida import guida as _guida\n            _guida.stop()\n        except Exception:\n            pass\n        self.web_sync.send_song_stop()\n        self._stop_quick_audio_recording_if_needed()\n        if self.on_playback_end:\n            try: self.on_playback_end()\n            except: pass\n\n\ndef _playback_loop(self):\n    dbg("PLAYBACK", f"_playback_loop START gen={self._play_generation}")\n    """Loop sync per audio e video - SINCRONIZZA ANCHE MONITOR PUBBLICO"""\n    _last_ui_update = 0\n    _ui_interval_ms = 33  # Aggiorna UI ~30 volte/secondo per scroll fluido\n    _last_pub_sync = 0\n    _pub_sync_interval = 500  # Sincronizza player pubblico ogni 500ms\n    \n    # ✅ Cattura generazione — callback stale da generazioni precedenti vengono ignorate\n    _my_generation = self._play_generation\n    \n    # ✅ Interpolazione VLC/MPV per scroll fluido\n    # NOTA: _vlc_last_change = 0 è intenzionale! Con 0, l\'interpolazione\n    # calcola elapsed=epoch (miliardi), il sanity cap (<=500ms) lo blocca,\n    # e current_time resta a 0 finché MPV non riporta il primo vero time_pos.\n    # Se usassimo time.time()*1000, il testo avanzerebbe durante il buffering MPV.\n    _vlc_last_time = 0\n    _vlc_last_change = 0\n    \n    # ✅ SAFETY: forza _seeking=False se bloccato troppo a lungo\n    _seeking_start = time.time() if self._seeking else 0\n    _SEEKING_TIMEOUT = 2.0  # Massimo 2 secondi di seeking\n    \n    while self.is_playing or self.is_paused:\n        try:\n            # ✅ Generazione cambiata → un nuovo play/load ha preso il controllo, esci\n            if _my_generation != self._play_generation:\n                break\n            \n            # ✅ Se in pausa, dormi e non fare nulla\n            if self.is_paused:\n                time.sleep(0.05)\n                continue\n            \n            now_ms = time.time() * 1000\n            \n            if self.engine.is_video:\n                # ✅ Per video usa VLC time — protetto da crash durante stop\n                try:\n                    if not self.engine.vlc_player:\n                        break\n                    current_time = self.engine.vlc_player.get_time()  # in ms\n                except Exception:\n                    break  # Player rilasciato, esci dal loop\n                \n                # VLC può ritornare -1 all\'inizio\n                if current_time < 0:\n                    current_time = 0\n                \n                # ✅ SINCRONIZZA PLAYER PUBBLICO (meno frequente per non sovraccaricare)\n                if self.engine.vlc_player_pubblico and (now_ms - _last_pub_sync) >= _pub_sync_interval:\n                    _last_pub_sync = now_ms\n                    try:\n                        public_time = self.engine.vlc_player_pubblico.get_time()\n                        target_time = current_time + self.public_video_offset_ms\n                        # ⚠️ Su uno STREAM di rete un set_time non e\' gratis:\n                        # VLC riapre/ricerca il segmento e il video "salta"\n                        # (sembra zapping fra pezzi del video). Su file locale\n                        # il seek e\' istantaneo -> soglia stretta come prima.\n                        _soglia = 2000 if str(getattr(self, \'current_file\', \'\') or \'\').lower().startswith(\n                            (\'http://\', \'https://\')) else 150\n                        # ⭐ IL MONITOR PUBBLICO SI PUO\' APRIRE A BRANO\n                        #    GIA\' PARTITO: il suo lettore nasce allora, da\n                        #    un\'altra strada, e il sottotitolo col testo\n                        #    non gli veniva mai attaccato ("se apro dopo il\n                        #    monitor pubblico non sincronizza il testo").\n                        #    Qui si controlla che ce l\'abbia, chiunque\n                        #    l\'abbia creato.\n                        if (getattr(self, \'_testo_ass_uri\', None)\n                                and id(self.engine.vlc_player_pubblico)\n                                != getattr(self, \'_testo_pub_id\', None)):\n                            self._testo_pub_id = id(self.engine.vlc_player_pubblico)\n                            self._testo_sottotitolo_pubblico()\n                        # ⚠️ COL TESTO SOPRA IL VIDEO la soglia si allarga:\n                        #    a ogni riallineamento VLC ridisegna il\n                        #    sottotitolo da capo e il testo SFARFALLA\n                        #    (visto sul monitor pubblico l\'11-09). Mezzo\n                        #    secondo di scarto non si vede, lo sfarfallio si\'.\n                        if getattr(self, \'_testo_ass_uri\', None):\n                            _soglia = max(_soglia, 700)\n                        if abs(public_time - target_time) > _soglia:\n                            self.engine.vlc_player_pubblico.set_time(target_time)\n                    except Exception:\n                        pass  # Player pubblico già fermato\n                \n                # ✅ SINCRONIZZA AUDIO MPV SEPARATO (video pitch attivo)\n                if self._video_pitch_active and self.mpv_player and (now_ms - _last_pub_sync) >= 2000:\n                    try:\n                        mpv_pos = self.mpv_player.time_pos\n                        if mpv_pos is not None and mpv_pos >= 0:\n                            mpv_time_ms = int(mpv_pos * 1000)\n                            if abs(mpv_time_ms - current_time) > 500:\n                                self.mpv_player.seek(current_time / 1000.0, \'absolute\')\n                    except:\n                        pass\n            else:\n                # ✅ Per MIDI (FluidSynth o BASS) — posizione già fluida internamente\n                if self.is_midi and self.fs:\n                    current_time = self.fs.get_position_ms()\n                elif self.is_vlc_audio and self.vlc_audio:\n                    # ✅ VLC audio con interpolazione per scroll fluido\n                    vlc_time = self.vlc_audio.get_time()\n                    if vlc_time >= 0:\n                        if vlc_time != _vlc_last_time:\n                            _vlc_last_time = vlc_time\n                            _vlc_last_change = now_ms\n                            current_time = vlc_time\n                        else:\n                            # VLC non ha aggiornato → interpola col clock di sistema\n                            elapsed = now_ms - _vlc_last_change\n                            current_time = _vlc_last_time + elapsed\n                    else:\n                        current_time = 0\n                elif self.is_bass_audio and self.bass_engine:\n                    # ✅ BASS audio — posizione fluida sub-ms\n                    try:\n                        bass_ms = self.bass_engine.get_position_ms()\n                        current_time = bass_ms if bass_ms >= 0 else 0\n                    except:\n                        current_time = getattr(self, \'current_time_ms\', 0)\n                elif self.is_mpv_audio and self.mpv_player:\n                    # ✅ MPV audio con interpolazione per scroll fluido\n                    try:\n                        mpv_pos = self.mpv_player.time_pos\n                        if mpv_pos is not None and mpv_pos >= 0:\n                            mpv_time_ms = int(mpv_pos * 1000)\n                            if mpv_time_ms != _vlc_last_time:\n                                _vlc_last_time = mpv_time_ms\n                                _vlc_last_change = now_ms\n                                current_time = mpv_time_ms\n                            else:\n                                elapsed = now_ms - _vlc_last_change\n                                current_time = _vlc_last_time + elapsed\n                        else:\n                            current_time = 0\n                    except:\n                        current_time = getattr(self, \'current_time_ms\', 0)\n                else:\n                    # ✅ Per audio pygame: pygame_pos + seek_offset\n                    pygame_pos = pygame.mixer.music.get_pos()\n                    seek_offset = getattr(self, \'seek_offset_ms\', 0)\n                    \n                    if pygame_pos >= 0:\n                        current_time = pygame_pos + seek_offset\n                    elif seek_offset > 0:\n                        current_time = getattr(self, \'current_time_ms\', seek_offset)\n                    else:\n                        current_time = (time.time() * 1000) - self.start_time\n            \n            # ✅ AGGIORNA FRAME CDG SE ATTIVO\n            if self.is_cdg and hasattr(self.engine, \'cdg_decoder\'):\n                self._update_cdg_frame(current_time)\n            \n            # ✅ AGGIORNA UI solo se NON in seeking (evita riavvolgimento durante swap/seek)\n            if self._seeking:\n                # ✅ SAFETY: aspetta che il player sia realmente partito e stabile\n                # La _seeking=True viene impostata al play() per evitare che il monitor\n                # aggiorni con tempi garbage durante il buffering iniziale\n                if _seeking_start == 0:\n                    _seeking_start = time.time()\n                elif (time.time() - _seeking_start) > _SEEKING_TIMEOUT:\n                    print(f"⚠️ _seeking bloccato per {time.time() - _seeking_start:.1f}s → FORZO OFF")\n                    self._seeking = False\n                    _seeking_start = 0\n                else:\n                    time.sleep(0.025)\n                    continue\n            else:\n                _seeking_start = 0\n            \n            # ✅ SALVA TEMPO CORRENTE (solo quando NON in seeking per evitare garbage)\n            self.current_time_ms = current_time\n            \n            # ✅ AGGIORNA UI solo se è passato abbastanza tempo\n            if (now_ms - _last_ui_update) >= _ui_interval_ms and not self._ui_update_pending:\n                _last_ui_update = now_ms\n                _ct = current_time  # Cattura valore per lambda\n                _gen = _my_generation  # Cattura generazione\n                self._ui_update_pending = True\n                \n                # ✅ UN SOLO after() per tutti gli aggiornamenti UI\n                def _do_ui_update(t=_ct, gen=_gen):\n                    try:\n                        self._ui_update_pending = False\n                        if gen != self._play_generation or self._seeking or not self.is_playing:\n                            return\n                        self.monitor.update_at_time(t)\n                        if self.monitor_pubblico and self.monitor_pubblico.visible:\n                            # Offset TEMPORALE solo per il monitor pubblico:\n                            # +ms = testo pubblico in anticipo, -ms = testo pubblico in ritardo.\n                            pub_offset = getattr(self, \'public_video_offset_ms\', 0)\n                            pub_t = max(0, t + pub_offset)\n                            self.monitor_pubblico.monitor_frame.update_at_time(pub_t)\n                        if self.web_sync.connected:\n                            self.web_sync.send_time_update(t, self.monitor.current_index)\n                    except Exception:\n                        self._ui_update_pending = False\n                \n                self.master.after(0, _do_ui_update)\n            \n            # Check se finito\n            if self.engine.is_video:\n                # ✅ Grace period: VLC play() è asincrono, la pipeline video\n                # impiega fino a 3 secondi per avviarsi. Senza questo,\n                # is_playing() ritorna False e il loop crede che il video sia finito!\n                _video_grace = getattr(self, \'_video_play_start\', 0)\n                # ✅ Uno STREAM di rete (YouTube) puo\' metterci parecchio ad\n                #    aprirsi (DNS/TLS/403 transitorio del CDN): finche\' VLC non\n                #    ha MAI suonato non e\' "finito", sta ancora aprendo.\n                if self.engine.vlc_player.is_playing():\n                    self._video_has_started = True\n                _is_stream = str(getattr(self, \'current_file\', \'\') or \'\').lower().startswith(\n                    (\'http://\', \'https://\'))\n                _grace = 3.0\n                if _is_stream and not getattr(self, \'_video_has_started\', False):\n                    _grace = 25.0   # attesa apertura stream (era 3s: il video "non partiva")\n                if time.time() - _video_grace < _grace:\n                    pass  # Troppo presto per rilevare "finito"\n                elif not self.engine.vlc_player.is_playing():\n                    # ✅ Verifica generazione prima di dichiarare "finito"\n                    if _my_generation != self._play_generation:\n                        break  # Un nuovo brano ha preso il controllo\n                    print("🎵 Video finito")\n                    self.is_playing = False\n                    self._voce_fine_brano()\n                    self.web_sync.send_song_stop()\n                    # ✅ CLEANUP COMPLETO + callback (nel thread UI)\n                    _end_gen = _my_generation\n                    _end_callback = self.on_playback_end\n                    def _full_end_cleanup_v(g=_end_gen, cb=_end_callback):\n                        if g != self._play_generation:\n                            return\n                        self._stop_quick_audio_recording_if_needed()\n                        try:\n                            self.stop(quick=True)\n                        except:\n                            pass\n                        if cb:\n                            try:\n                                cb()\n                            except:\n                                pass\n                    try:\n                        self.master.after(50, _full_end_cleanup_v)\n                    except:\n                        pass\n                    break\n            else:\n                # ✅ Check se MIDI o audio finito\n                is_finished = False\n                if self._seeking:\n                    pass  # ✅ MAI rilevare "finito" durante seek\n                elif self.is_midi and self.fs:\n                    # ✅ Grace period: BASS engine potrebbe non essere "active" subito\n                    _midi_grace = getattr(self, \'_midi_play_start\', 0)\n                    if time.time() - _midi_grace < 5.0:\n                        pass  # Troppo presto per rilevare "finito"\n                    else:\n                        is_finished = not self.fs.is_playing\n                elif self.is_vlc_audio and self.vlc_audio:\n                    # ✅ Grace period: VLC play() è asincrono, ci vogliono ~200ms\n                    # prima che is_playing() ritorni True. Senza questo,\n                    # il loop rileva "finito" immediatamente!\n                    vlc_grace = getattr(self, \'_vlc_play_start\', 0)\n                    if time.time() - vlc_grace < 2.0:\n                        pass  # Troppo presto per rilevare "finito"\n                    else:\n                        is_finished = not self.vlc_audio.is_playing()\n                elif self.is_bass_audio and self.bass_engine:\n                    # ✅ BASS audio: check stato canale direttamente (no poll thread per audio)\n                    if time.time() - (self.start_time / 1000) > 2.0:\n                        if not self.bass_engine.is_active():\n                            self.bass_engine.is_playing = False\n                            is_finished = True\n                elif self.is_mpv_audio and self.mpv_player:\n                    # ✅ MPV: eof_reached è affidabile; idle_active da solo no, specie con KFN/MKF\n                    elapsed = time.time() - (self.start_time / 1000)\n                    if elapsed < 3.0:\n                        pass  # Grace period iniziale più lungo\n                    else:\n                        try:\n                            eof = bool(getattr(self.mpv_player, \'eof_reached\', False))\n                            idle = bool(getattr(self.mpv_player, \'idle_active\', False))\n                            pos = getattr(self.mpv_player, \'time_pos\', None)\n                            dur = getattr(self.mpv_player, \'duration\', None)\n                            started = (pos is not None and pos > 0.35) or (getattr(self, \'_mpv_started_pos\', None) is not None)\n                            near_end = bool(dur and pos is not None and (dur - pos) <= 1.5)\n                            if eof:\n                                is_finished = True\n                            elif idle and started and near_end:\n                                is_finished = True\n                            else:\n                                is_finished = False\n                        except:\n                            pass\n                else:\n                    # ✅ Controlla più volte per evitare falsi positivi durante seek\n                    if not pygame.mixer.music.get_busy():\n                        # Aspetta e ricontrolla più volte\n                        time.sleep(0.1)\n                        if not pygame.mixer.music.get_busy() and not self._seeking:\n                            time.sleep(0.1)\n                            is_finished = not pygame.mixer.music.get_busy() and not self._seeking\n                \n                if is_finished:\n                    # ✅ Verifica generazione prima di dichiarare "finito"\n                    if _my_generation != self._play_generation:\n                        break  # Un nuovo brano ha preso il controllo\n                    print("🎵 Audio/MIDI finito")\n                    self.is_playing = False\n                    self._voce_fine_brano()\n                    self.web_sync.send_song_stop()\n                    # ✅ CLEANUP COMPLETO + callback (nel thread UI)\n                    _end_gen = _my_generation\n                    _end_callback = self.on_playback_end\n                    def _full_end_cleanup_a(g=_end_gen, cb=_end_callback):\n                        if g != self._play_generation:\n                            return\n                        self._stop_quick_audio_recording_if_needed()\n                        try:\n                            self.stop(quick=True)\n                        except:\n                            pass\n                        if cb:\n                            try:\n                                cb()\n                            except:\n                                pass\n                    try:\n                        self.master.after(50, _full_end_cleanup_a)\n                    except:\n                        pass\n                    break\n            \n        except Exception as e:\n            print(f"⚠️ Errore sync: {e}")\n        \n        # ✅ SLEEP ADATTIVO: se il mainloop è in ritardo (_ui_update_pending=True),\n        # dormi di più per dargli tempo di processare. L\'audio non è affetto\n        # (VLC/FluidSynth/BASS girano in thread nativi separati).\n        if self._ui_update_pending:\n            time.sleep(0.050)  # Mainloop in ritardo → rallenta a ~20fps, lascia respirare\n        else:\n            time.sleep(0.016 if self.is_cdg else 0.025)  # Normale: 60 FPS CDG, 40 FPS altri'

CODICE_YT = 'def _leggi_filtro_karaoke(self):\n    """Acceso, se non e\' stato spento apposta. La scelta si ricorda: chi\n    cerca gli originali non deve rispegnerlo a ogni avvio."""\n    try:\n        from .database import Database\n        return str(Database.get_config(\'yt_filtro_karaoke\', \'1\')).strip() not in (\'0\', \'no\', \'off\')\n    except Exception:\n        return True\n\n\ndef _aggiorna_btn_karaoke(self):\n    """Acceso = verde. Spento = grigio e barrato, cosi\' si capisce a colpo\n    d\'occhio che quella parola NON viene aggiunta."""\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return\n    # ⚠️ NON si usa `BTN`: quello e\' una variabile locale di __init__ e qui\n    #    dentro non esiste. Il font si richiede a F, che e\' importata dal\n    #    modulo e tiene conto del ridimensionamento dello schermo.\n    #\n    # Il testo dice cosa succede PREMENDOLO, non com\'e\' adesso: e\' l\'unico\n    # modo perche\' si capisca senza doverci pensare.\n    try:\n        if self._filtro_karaoke:\n            b.config(text=_("togli filtro\\nkaraoke"),\n                     bg=\'#28a745\', fg=\'white\', font=F(\'Segoe UI\', 9, \'bold\'))\n        else:\n            b.config(text=_("rimetti filtro\\nkaraoke"),\n                     bg=\'#495057\', fg=\'#ffd700\', font=F(\'Segoe UI\', 9, \'bold\'))\n    except Exception:\n        pass\n\n# ---------------- togliere la voce ----------------\n\n\ndef _cambia_filtro_karaoke(self):\n    self._filtro_karaoke = not self._filtro_karaoke\n    self._aggiorna_btn_karaoke()\n    try:\n        from .database import Database\n        Database.set_config(\'yt_filtro_karaoke\', \'1\' if self._filtro_karaoke else \'0\')\n    except Exception:\n        pass\n\n\ndef _largh_btn_karaoke(self):\n    """Quanto e\' largo il tasto del filtro con la scritta piu\' lunga.\n\n    Si misura senza toccare quella che si vede: si mette da parte il testo\n    attuale, si provano tutte e due le scritte, e si rimette com\'era.\n    """\n    b = getattr(self, \'btn_karaoke\', None)\n    if b is None:\n        return 0\n    try:\n        adesso = b.cget(\'text\')\n        largo = 0\n        for t in (_("togli filtro\\nkaraoke"), _("rimetti filtro\\nkaraoke")):\n            b.config(text=t)\n            b.update_idletasks()\n            largo = max(largo, b.winfo_reqwidth())\n        b.config(text=adesso)\n        return largo\n    except Exception:\n        return 0\n\n\ndef _layout_top(self):\n    top = getattr(self, \'_top\', None)\n    if top is None or not top.winfo_exists():\n        return\n    # nel compilato questo tasto non c\'e\': lo si crea la prima volta\n    if getattr(self, \'btn_karaoke\', None) is None:\n        self._filtro_karaoke = self._leggi_filtro_karaoke()\n        self.btn_karaoke = tk.Button(top, text=_("togli filtro\\nkaraoke"),\n                                     command=self._cambia_filtro_karaoke,\n                                     relief=\'flat\', cursor=\'hand2\',\n                                     bd=0, highlightthickness=0)\n        self._aggiorna_btn_karaoke()\n    # ⛔ Se una patch precedente aveva messo qui "abbassa la voce", va tolto:\n    #    adesso ce n\'e\' uno solo, nella barra della libreria.\n    _vecchio = getattr(self, \'btn_devoc\', None)\n    if _vecchio is not None:\n        try:\n            _vecchio.destroy()\n        except Exception:\n            pass\n        self.btn_devoc = None\n    try:\n        top.update_idletasks()\n    except Exception:\n        pass\n    W = top.winfo_width()\n    H = top.winfo_height()\n    if W < 40 or H < 10:\n        return\n    ox = top.winfo_rootx()\n\n    def rel(w):\n        try:\n            if w is None:\n                return None\n            wd = w.winfo_width()\n            if wd < 5:\n                return None\n            return (w.winfo_rootx() - ox, wd)\n        except Exception:\n            return None\n\n    lib = getattr(self.system, \'libreria\', None)\n    cant = rel(getattr(lib, \'entry_cantante\', None))\n    brano = rel(getattr(lib, \'_lbl_brano\', None))\n    filt = rel(getattr(lib, \'entry_filtro\', None))\n    pad = S(4)\n\n    # --- Dest: label allineata a "Cant:", campo allineato/largo come cantante ---\n    if cant:\n        xcant, wcant = cant\n    else:\n        xcant, wcant = S(60), (W // 2) - S(90)\n    # X della label "Cant:" = inizio del frame cantante + padx(5)\n    lbl_x = S(5)\n    try:\n        fc = self.system.libreria.entry_cantante.master\n        lbl_x = (fc.winfo_rootx() - ox) + S(5)\n    except Exception:\n        pass\n    self.lbl_dest.place(x=max(0, lbl_x), y=0, height=H)\n    self.entry_dest.place(x=xcant, y=0, width=wcant, height=H)\n\n    # --- Sfoglia sotto i tasti ▶ 🗑 (tra campo cantante e label brano) ---\n    gap_x0 = xcant + wcant + pad\n    gap_x1 = (brano[0] if brano else (filt[0] if filt else W)) - pad\n    sfw = max(S(70), gap_x1 - gap_x0)\n    self.btn_sfoglia.place(x=gap_x0, y=0, width=sfw, height=H)\n\n    # --- campo ricerca: comincia sotto la label "Brano (filtro):" e\n    #     arriva fino ai bottoni, che stanno in fondo alla barra ---\n    if brano:\n        xsearch = brano[0]\n    elif filt:\n        xsearch = filt[0]\n    else:\n        xsearch = gap_x0 + sfw + pad\n\n    # --- 3 bottoni (Cerca/Download/Incolla) TUTTI larghi uguali (al piu\' largo) ---\n    # ⚠️ La larghezza si prende sul testo PIU\' LUNGO che ciascun bottone\n    #    puo\' mostrare, non su quello di adesso: il tasto del filtro\n    #    cambia scritta quando lo si preme, e se la misura seguisse il\n    #    testo corrente la barra si riassesterebbe a ogni clic.\n    bw = max(self.btn_cerca.winfo_reqwidth(),\n             self.btn_download.winfo_reqwidth(),\n             self.btn_incolla.winfo_reqwidth(),\n             self._largh_btn_karaoke()) + S(4)   # appena un filo d\'aria\n    # ⭐ I TRE BOTTONI STANNO IN FONDO ALLA BARRA, attaccati al bordo\n    #    destro, e il campo si allunga fino a toccarli.\n    # ⛔ PRIMA ERA LEGATO AL CAMPO FILTRO DELLA LIBRERIA (`filtro_right`),\n    #    che sta piu\' corto: i bottoni finivano a meta\' strada e restava\n    #    un dito di vuoto sulla destra. Il fondo della barra e\' `W`, non\n    #    dove finisce un campo di un altro pannello.\n    buttons_w = 3 * bw + 2 * pad     # Cerca, Download, Incolla\n    bx = max(xsearch + S(80) + pad, W - pad - buttons_w)\n    search_right = bx - pad\n\n    # L\'interruttore "karaoke" sta IN FONDO al campo, dentro il suo\n    # spazio: il campo si accorcia di quel tanto. Cosi\' si vede mentre si\n    # scrive, senza rubare posto ai tre bottoni.\n    campo_right = max(xsearch + S(60), search_right - bw - pad)\n    self.entry_search.place(x=xsearch, y=0, width=campo_right - xsearch, height=H)\n    self.btn_karaoke.place(x=campo_right + pad, y=0,\n                           width=search_right - campo_right - pad, height=H)\n\n    self.btn_cerca.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_download.place(x=bx, y=0, width=bw, height=H); bx += bw + pad\n    self.btn_incolla.place(x=bx, y=0, width=bw, height=H)\n\n# ---------------- scroll rotellina ----------------'

CODICE_LIB = 'def create_slider(self):\n\n    """Crea slider con Treeview"""\n\n    self.slider_frame = tk.Frame(self.parent, bg=\'black\', height=self.slider_height, \n                                  highlightthickness=0, bd=0, \n                                  highlightbackground=\'black\', highlightcolor=\'black\')\n\n    self.slider_frame.place(relx=0, rely=1.0, relwidth=1.0, anchor=\'sw\')\n\n    self.slider_frame.place_forget()\n\n    self.slider_frame.pack_propagate(False)\n    \n    # ✅ Enter per avviare brano selezionato\n    self.slider_frame.bind(\'<Return>\', lambda e: self._on_enter_play(e))\n\n    \n\n    main_container = tk.Frame(self.slider_frame, bg=\'black\', highlightthickness=0,\n                               highlightbackground=\'black\', highlightcolor=\'black\')\n\n    main_container.pack(side=\'top\', fill=\'both\', expand=True)\n\n    \n\n    # ===== ALBERO SINISTRA con Treeview =====\n\n    self.tree_frame = tk.Frame(main_container, bg=\'black\', highlightthickness=0,\n                                width=int(Database.get_config(\'tree_frame_width\', \'320\')))\n    tree_frame = self.tree_frame\n\n    tree_frame.pack(side=\'left\', fill=\'y\')\n\n    tree_frame.pack_propagate(False)\n\n    \n\n    # Header\n\n    tree_header = tk.Frame(tree_frame, bg=\'#1a1a1a\', height=40, \n                           highlightthickness=0)\n\n    tree_header.pack(side=\'top\', fill=\'x\')\n\n    tree_header.pack_propagate(False)\n\n    \n\n    self.label_tree_header = tk.Label(tree_header, text=_("Preferiti"), bg=\'#1a1a1a\', fg=\'white\',\n\n            font=(\'Arial\', 12, \'bold\'))\n\n    self.label_tree_header.pack(side=\'left\', padx=10, pady=10)\n    add_tooltip(self.label_tree_header, _("Cartelle preferite / Playlist"))\n\n    \n\n    self.btn_pref_add = tk.Button(tree_header, text="+", bg=\'#28a745\', fg=\'white\',\n\n                       font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n\n                       cursor=\'hand2\', width=2,\n\n                       command=self.aggiungi_preferito)\n\n    self.btn_pref_add.pack(side=\'right\', padx=2)\n\n    add_tooltip(self.btn_pref_add, _("Aggiungi cartella ai preferiti"))\n\n    \n    # ✅ BOTTONE - ROSSO - Rimuovi preferito selezionato\n    self.btn_pref_remove = tk.Button(tree_header, text="−", bg=\'#dc3545\', fg=\'white\',\n                       font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n                       cursor=\'hand2\', width=2,\n                       command=self.rimuovi_preferito)\n    self.btn_pref_remove.pack(side=\'right\', padx=2)\n    add_tooltip(self.btn_pref_remove, _("Rimuovi preferito selezionato"))\n\n    \n\n    # ✅ BOTTONE PLAYLIST - toggle tra Preferiti e Playlist\n\n    self.btn_playlist_toggle = tk.Button(tree_header, text="📋", bg=\'#8B5CF6\', fg=\'white\',\n\n                           font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n\n                           cursor=\'hand2\', width=2,\n\n                           command=self.toggle_playlist_view)\n\n    self.btn_playlist_toggle.pack(side=\'right\', padx=2)\n\n    add_tooltip(self.btn_playlist_toggle, _("Mostra/Nascondi Playlist"))\n\n    # ✅ Rendi bottoni header più reattivi\n    self._enhance_buttons(tree_header)\n\n    \n\n    # Flag per sapere se stiamo mostrando playlist o preferiti\n\n    self.showing_playlist = False\n\n    self.righe_backup = []  # Backup delle righe quando mostriamo playlist\n\n    \n\n    # I dischi esterni non hanno piu\' un bottone qui: il montaggio\n    # si propone da se\' quando si preme \'+\' per aggiungere una\n    # cartella, che e\' il momento in cui serve davvero.\n    # Vedi libreria.py -> _proponi_disco_da_montare().\n\n    # ===== CONTAINER per Preferiti =====\n\n    self.preferiti_container = tk.Frame(tree_frame, bg=\'black\', highlightthickness=0)\n\n    self.preferiti_container.pack(side=\'top\', fill=\'both\', expand=True)\n\n    \n\n    # Treeview con stile personalizzato\n\n    self.style = ttk.Style()\n\n    self.style.theme_use(\'clam\')\n\n    # ✅ Stile Treeview NERO con testo BIANCO e selezione BLU\n\n    self.style.configure("Custom.Treeview",\n\n                   background="black",\n\n                   foreground="white",\n\n                   fieldbackground="black",\n\n                   borderwidth=0,\n\n                   focuscolor=\'black\',\n\n                   font=self._F(\'Arial\', 16, \'bold\'),\n\n                   rowheight=self._S(35))\n\n    self.style.configure("Custom.Treeview.Heading",\n\n                   background="#1a1a1a",\n\n                   foreground="white",\n\n                   borderwidth=0)\n\n    self.style.map("Custom.Treeview",\n\n             background=[(\'selected\', \'#0078D7\')],\n\n             foreground=[(\'selected\', \'white\')])\n\n    # ✅ Rimuovi bordo focus blu dal Treeview\n    self.style.layout("Custom.Treeview", [\n        (\'Custom.Treeview.treearea\', {\'sticky\': \'nswe\'})\n    ])\n\n    \n\n    # Scrollbar\n\n    tree_scroll = ttk.Scrollbar(self.preferiti_container)\n\n    tree_scroll.pack(side=\'right\', fill=\'y\')\n\n    \n\n    # Treeview\n\n    self.tree = ttk.Treeview(self.preferiti_container, \n\n                             style="Custom.Treeview",\n\n                             yscrollcommand=tree_scroll.set,\n\n                             selectmode=\'extended\',\n\n                             show=\'tree\',\n                             takefocus=False)\n\n    self.tree.pack(side=\'left\', fill=\'both\', expand=True)\n    add_tooltip(self.tree, _("Cartelle preferite - click per selezionare, doppio click per espandere, tasto destro per aggiornare"))\n\n    tree_scroll.config(command=self.tree.yview)\n\n    \n\n    # ✅ SCROLL MOUSE per Treeview - Windows e Linux\n\n    def on_tree_scroll(event):\n\n        self.tree.yview_scroll(-1 * int(event.delta / 120), \'units\')\n\n    \n\n    def on_tree_scroll_linux_up(event):\n\n        self.tree.yview_scroll(-1, \'units\')\n\n    \n\n    def on_tree_scroll_linux_down(event):\n\n        self.tree.yview_scroll(1, \'units\')\n\n    \n\n    self.tree.bind(\'<MouseWheel>\', on_tree_scroll)\n\n    self.tree.bind(\'<Button-4>\', on_tree_scroll_linux_up)\n\n    self.tree.bind(\'<Button-5>\', on_tree_scroll_linux_down)\n\n    \n\n    self.tree.tag_configure(\'open\', foreground=\'#FFD700\', background=\'black\', font=self._F(\'Arial\', 16, \'bold\'))\n\n\n\n    # Bind eventi\n\n    self.tree.bind(\'<<TreeviewSelect>>\', self.on_tree_select)\n\n    self.tree.bind(\'<<TreeviewOpen>>\', self.on_tree_expand)\n\n    self.tree.bind(\'<<TreeviewClose>>\', self.on_tree_close)\n\n    # ✅ Tasto destro su un preferito: mostra menu "Aggiorna preferiti"\n    def _on_tree_right_click(event):\n        item = self.tree.identify_row(event.y)\n        if not item:\n            return \'break\'\n        vals = self.tree.item(item)[\'values\']\n        if not vals:\n            return \'break\'\n        path = str(vals[0])\n        if not os.path.isdir(path):\n            return \'break\'\n        \n        # Mostra menu contestuale\n        menu = tk.Menu(self.tree, tearoff=0, bg=\'#222\', fg=\'white\',\n                      activebackground=\'#0078D7\', activeforeground=\'white\',\n                      font=(\'Segoe UI\', 10))\n        def _aggiorna():\n            self.percorso_attivo = path\n            # forza=True: e\' QUESTO il comando con cui si rilegge il disco.\n            # Il clic normale usa l\'elenco gia\' salvato: si indicizza una\n            # volta sola, poi si riusa (vedi libreria_scan_mixin).\n            self.carica_brani(path, forza=True)\n        menu.add_command(label=_("🔄 Aggiorna preferito (rilegge il disco)"), command=_aggiorna)\n        try:\n            menu.tk_popup(event.x_root, event.y_root)\n        finally:\n            menu.grab_release()\n        return \'break\'\n    \n    self.tree.bind(\'<Button-3>\', _on_tree_right_click)\n    self.tree._custom_context_menu = True\n\n    \n\n    # Popola albero iniziale\n\n    self.popola_albero()\n\n    # ✅ Ripristina ultimo preferito selezionato (ritardato per UI pronta)\n    self.parent.after(1000, self._ripristina_ultimo_preferito)\n\n    \n\n    # ===== CONTAINER per Playlist (inizialmente nascosto) =====\n\n    self.playlist_container = tk.Frame(tree_frame, bg=\'black\', highlightthickness=0)\n\n    # NON pack - sarà mostrato solo quando si clicca il bottone\n    # Modalità playlist: solo database\n    self.playlist_modalita = \'standalone\'\n\n    # Barra playlist: filtro a sinistra, bottoni a destra\n    selector_frame = tk.Frame(self.playlist_container, bg=\'#1a1a1a\')\n    selector_frame.pack(side=\'top\', fill=\'x\', padx=2, pady=2)\n    selector_frame.grid_columnconfigure(0, weight=1)\n    selector_frame.grid_columnconfigure(1, weight=0)\n\n    self.entry_filtro_playlist = tk.Entry(selector_frame, bg=\'#1a1a1a\', fg=\'gray\',\n                                          font=(\'Arial\', 11), relief=\'flat\',\n                                          insertbackground=\'white\', highlightthickness=0)\n    self.entry_filtro_playlist.grid(row=0, column=0, sticky=\'ew\', padx=(5, 6), pady=3, ipady=2)\n    self.entry_filtro_playlist.insert(0, _("Filtra playlist..."))\n    add_tooltip(self.entry_filtro_playlist, _("Filtra le playlist per nome"))\n\n    def on_filtro_pl_focus_in(e):\n        if self.entry_filtro_playlist.get() == _("Filtra playlist..."):\n            self.entry_filtro_playlist.delete(0, tk.END)\n            self.entry_filtro_playlist.config(fg=\'white\')\n\n    def on_filtro_pl_focus_out(e):\n        if not self.entry_filtro_playlist.get():\n            self.entry_filtro_playlist.insert(0, _("Filtra playlist..."))\n            self.entry_filtro_playlist.config(fg=\'gray\')\n\n    self.entry_filtro_playlist.bind(\'<FocusIn>\', on_filtro_pl_focus_in)\n    self.entry_filtro_playlist.bind(\'<FocusOut>\', on_filtro_pl_focus_out)\n    self._filtro_playlist_after_id = None\n    def _debounce_filtra_playlist(event=None):\n        if self._filtro_playlist_after_id:\n            self.parent.after_cancel(self._filtro_playlist_after_id)\n        self._filtro_playlist_after_id = self.parent.after(250, self.filtra_playlist_lista)\n    self.entry_filtro_playlist.bind(\'<KeyRelease>\', _debounce_filtra_playlist)\n\n    btn_frame = tk.Frame(selector_frame, bg=\'#1a1a1a\')\n    btn_frame.grid(row=0, column=1, sticky=\'e\', padx=(0, 4), pady=2)\n    self._enhance_buttons(btn_frame)\n\n    # Listbox per le playlist\n\n    playlist_list_frame = tk.Frame(self.playlist_container, bg=\'black\')\n\n    playlist_list_frame.pack(side=\'top\', fill=\'both\', expand=True)\n\n    \n\n    playlist_scroll = ttk.Scrollbar(playlist_list_frame)\n\n    playlist_scroll.pack(side=\'right\', fill=\'y\')\n\n    \n\n    self.playlist_listbox = tk.Listbox(playlist_list_frame,\n\n                                       bg=\'black\', fg=\'white\',\n\n                                       font=(\'Arial\', 14, \'bold\'),\n\n                                       selectbackground=\'#8B5CF6\',\n\n                                       selectforeground=\'white\',\n\n                                       relief=\'flat\',\n\n                                       highlightthickness=0,\n\n                                       activestyle=\'none\',  # Disabilita evidenziazione al passaggio mouse\n\n                                       yscrollcommand=playlist_scroll.set)\n\n    self.playlist_listbox.pack(side=\'left\', fill=\'both\', expand=True)\n    add_tooltip(self.playlist_listbox, _("Lista playlist - click per selezionare"))\n\n    playlist_scroll.config(command=self.playlist_listbox.yview)\n\n    \n\n    # Scroll mouse per playlist listbox\n\n    def on_playlist_scroll(event):\n\n        self.playlist_listbox.yview_scroll(-1 * int(event.delta / 120), \'units\')\n\n    self.playlist_listbox.bind(\'<MouseWheel>\', on_playlist_scroll)\n\n    self.playlist_listbox.bind(\'<Button-4>\', lambda e: self.playlist_listbox.yview_scroll(-1, \'units\'))\n\n    self.playlist_listbox.bind(\'<Button-5>\', lambda e: self.playlist_listbox.yview_scroll(1, \'units\'))\n\n    \n\n    # Click su playlist (usa ButtonRelease per evitare selezione al movimento mouse)\n\n    self.playlist_listbox.bind(\'<ButtonRelease-1>\', self.on_playlist_click)\n\n    \n\n    # Dati playlist\n\n    self.playlist_data = []  # Lista di {id, nome, brani} o {nome, path} per winlive\n\n    self.playlist_data_filtered = []  # Dati filtrati visibili\n\n    self.percorso_playlist_winlive = Database.get_config(\'percorso_playlist\', \'\')\n\n    \n\n    # ===== LINGUETTA VERTICALE (splitter tra albero e tabella) =====\n    self.v_splitter = tk.Frame(main_container, bg=\'black\', width=18,\n                               cursor=\'sb_h_double_arrow\', highlightthickness=0)\n    self.v_splitter.pack(side=\'left\', fill=\'y\')\n    add_tooltip(self.v_splitter, _("Trascina per ridimensionare pannelli"))\n    \n    grip_v_tab = tk.Frame(self.v_splitter, bg=\'#555555\', width=10, height=80,\n                         cursor=\'sb_h_double_arrow\', relief=\'raised\', bd=1)\n    grip_v_tab.place(relx=0.5, rely=0.5, anchor=\'center\')\n    grip_v_cv = tk.Canvas(grip_v_tab, bg=\'#555555\', width=6, height=60, highlightthickness=0,\n                         cursor=\'sb_h_double_arrow\')\n    grip_v_cv.place(relx=0.5, rely=0.5, anchor=\'center\')\n    grip_v_cv.create_line(1, 5, 1, 55, fill=\'#999999\')\n    grip_v_cv.create_line(4, 5, 4, 55, fill=\'#999999\')\n    \n    for w in (self.v_splitter, grip_v_tab, grip_v_cv):\n        w.bind(\'<Button-1>\', self._start_h_resize)\n        w.bind(\'<B1-Motion>\', self._do_h_resize)\n\n    # ===== DESTRA: TABELLA =====\n\n    right_frame = tk.Frame(main_container, bg=\'black\', highlightthickness=0)\n\n    right_frame.pack(side=\'left\', fill=\'both\', expand=True)\n\n    \n\n    # HEADER SUPERIORE\n\n    self.header_top = tk.Frame(right_frame, bg=\'black\', height=60, \n                          highlightthickness=0, highlightbackground=\'black\')\n\n    self.header_top.pack(side=\'top\', fill=\'x\')\n\n    self.header_top.pack_propagate(False)\n    header_top = self.header_top  # alias locale per compatibilità\n\n    # Striscia per vista playlist (nascosta inizialmente) - stessa altezza del tree_header (40px)\n    self._playlist_strip = tk.Frame(right_frame, bg=\'#1a1a1a\', height=40, highlightthickness=0)\n    self._playlist_strip.pack_propagate(False)\n    self._right_frame = right_frame\n\n    # ✅ Bottoni R, Esporta, Importa - stesse dimensioni dei +/− di sinistra (width=2, font Segoe UI 12 bold)\n    _pl_btn_style = dict(fg=\'white\', font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n                         cursor=\'hand2\', width=2)\n\n    self.btn_pl_rinomina = tk.Button(self._playlist_strip, text="R",\n                                     bg=\'#ffa500\', command=self.rinomina_playlist, **_pl_btn_style)\n    self.btn_pl_rinomina.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_rinomina, _("Rinomina playlist selezionata"))\n\n    self.btn_pl_esporta = tk.Button(self._playlist_strip, text="↗",\n                                    bg=\'#17a2b8\', command=self.esporta_playlist, **_pl_btn_style)\n    self.btn_pl_esporta.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_esporta, _("Esporta playlist in file TXT"))\n\n    self.btn_pl_importa = tk.Button(self._playlist_strip, text="↙",\n                                    bg=\'#6f42c1\', command=self.importa_playlist, **_pl_btn_style)\n    self.btn_pl_importa.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_importa, _("Importa playlist da file TXT"))\n\n    # Separatore visivo\n    tk.Frame(self._playlist_strip, bg=\'#555555\', width=2, height=25).pack(side=\'left\', padx=6)\n\n    self.btn_pl_add_file = tk.Button(self._playlist_strip, text="♫",\n                                      bg=\'#28a745\', command=self._pl_aggiungi_file, **_pl_btn_style)\n    self.btn_pl_add_file.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_add_file, _("Aggiungi un brano alla playlist"))\n\n    self.btn_pl_add_folder = tk.Button(self._playlist_strip, text="📁",\n                                        bg=\'#0078D7\', command=self._pl_aggiungi_cartella, **_pl_btn_style)\n    self.btn_pl_add_folder.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_add_folder, _("Aggiungi tutti i brani di una cartella"))\n\n    # Separatore\n    tk.Frame(self._playlist_strip, bg=\'#555555\', width=2, height=25).pack(side=\'left\', padx=6)\n\n    # ✅ AutoNext toggle\n    self._pl_autonext = False\n    self._pl_autonext_thread = None\n    self._pl_autonext_stop = threading.Event()\n    self._pl_autonext_pause_event = threading.Event()  # set = in pausa\n    self._pl_autonext_blink_active = False\n    self._pl_autonext_blink_after = None\n    self.btn_pl_autonext = tk.Button(self._playlist_strip, text="A",\n                                      bg=\'#555555\', command=self._pl_toggle_autonext, **_pl_btn_style)\n    self.btn_pl_autonext.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_autonext, _("AutoNext: avanza automaticamente al brano successivo"))\n\n    # Spinbox pausa tra brani\n    tk.Label(self._playlist_strip, text=_("sec:"), bg=\'#1a1a1a\', fg=\'#aaa\',\n             font=(\'Segoe UI\', 10)).pack(side=\'left\', padx=(4, 0))\n    self._pl_pausa_var = tk.IntVar(value=7)\n    self._pl_pausa_spin = tk.Spinbox(self._playlist_strip, from_=2, to=60, width=2,\n                                      textvariable=self._pl_pausa_var,\n                                      font=(\'Segoe UI\', 10), bg=\'#2d2d44\', fg=\'yellow\',\n                                      buttonbackground=\'#444\', relief=\'flat\')\n    self._pl_pausa_spin.pack(side=\'left\', padx=2)\n    add_tooltip(self._pl_pausa_spin, _("Secondi di pausa tra un brano e l\'altro"))\n\n    # Countdown label\n    self._pl_countdown = tk.Label(self._playlist_strip, text="", bg=\'#1a1a1a\', fg=\'#ff6600\',\n                                   font=(\'Segoe UI\', 10, \'bold\'))\n    self._pl_countdown.pack(side=\'left\', padx=4)\n\n    # Separatore\n    tk.Frame(self._playlist_strip, bg=\'#555555\', width=2, height=25).pack(side=\'left\', padx=6)\n\n    # ✅ Bottone Mixer Digitale\n    self.btn_pl_mixer = tk.Button(self._playlist_strip, text="MIX",\n                                   fg=\'#00ff00\', bg=\'#555555\',\n                                   font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n                                   cursor=\'hand2\',\n                                   command=self._pl_mixer_connect)\n    self.btn_pl_mixer.pack(side=\'left\', padx=2)\n    add_tooltip(self.btn_pl_mixer, _("Collegamento Mixer Digitale OSC"))\n    \n    # ✅ Controlli Snapshot mixer (visibili solo quando connesso)\n    self._pl_mixer_controls = tk.Frame(self._playlist_strip, bg=\'#1a1a1a\')\n    # NON pack - appare solo quando connesso\n    \n    tk.Label(self._pl_mixer_controls, text=_("Snapshot:"), bg=\'#1a1a1a\', fg=\'white\',\n             font=(\'Segoe UI\', 10)).pack(side=\'left\', padx=(6, 2))\n    \n    self._pl_snap_var = tk.IntVar(value=1)\n    self._pl_snap_spin = tk.Spinbox(self._pl_mixer_controls, from_=1, to=99, width=3,\n                                     textvariable=self._pl_snap_var,\n                                     font=(\'Segoe UI\', 10, \'bold\'),\n                                     bg=\'#2d2d44\', fg=\'yellow\',\n                                     buttonbackground=\'#444\', relief=\'flat\')\n    self._pl_snap_spin.pack(side=\'left\', padx=2)\n    add_tooltip(self._pl_snap_spin, _("Numero snapshot da assegnare/testare"))\n    \n    btn_snap_assign = tk.Button(self._pl_mixer_controls, text=_("Assegna"),\n                                 bg=\'#0078D7\', fg=\'white\',\n                                 font=(\'Segoe UI\', 10, \'bold\'), relief=\'flat\',\n                                 cursor=\'hand2\', padx=8,\n                                 command=self._pl_snap_assegna)\n    btn_snap_assign.pack(side=\'left\', padx=2)\n    add_tooltip(btn_snap_assign, _("Assegna lo snapshot al brano selezionato"))\n    \n    btn_snap_remove = tk.Button(self._pl_mixer_controls, text=_("Rimuovi"),\n                                 bg=\'#dc3545\', fg=\'white\',\n                                 font=(\'Segoe UI\', 10, \'bold\'), relief=\'flat\',\n                                 cursor=\'hand2\', padx=8,\n                                 command=self._pl_snap_rimuovi)\n    btn_snap_remove.pack(side=\'left\', padx=2)\n    add_tooltip(btn_snap_remove, _("Rimuovi snapshot dal brano selezionato"))\n    \n    btn_snap_test = tk.Button(self._pl_mixer_controls, text=_("Test"),\n                               bg=\'#ffa500\', fg=\'white\',\n                               font=(\'Segoe UI\', 10, \'bold\'), relief=\'flat\',\n                               cursor=\'hand2\', padx=8,\n                               command=self._pl_snap_test)\n    btn_snap_test.pack(side=\'left\', padx=2)\n    add_tooltip(btn_snap_test, _("Richiama subito questo snapshot sul mixer"))\n    \n    self._enhance_buttons(self._pl_mixer_controls)\n\n    self._enhance_buttons(self._playlist_strip)\n\n    \n\n    def add_placeholder(entry, placeholder):\n\n        entry.insert(0, placeholder)\n\n        entry.config(fg=\'grey\')\n\n        def on_focus_in(event):\n\n            if entry.get() == placeholder:\n\n                entry.delete(0, tk.END)\n\n                entry.config(fg=\'white\')\n\n        def on_focus_out(event):\n\n            if not entry.get():\n\n                entry.insert(0, placeholder)\n\n                entry.config(fg=\'grey\')\n\n        entry.bind("<FocusIn>", on_focus_in)\n\n        entry.bind("<FocusOut>", on_focus_out)\n\n    \n\n    # SINISTRA - Cantante\n\n    frame_cant = tk.Frame(header_top, bg=\'black\')\n\n    frame_cant.pack(side=\'left\', fill=\'both\', expand=True, padx=3)\n\n    \n\n    _lbl_cant = tk.Label(frame_cant, text=_("Cant:"), bg=\'black\', fg=\'white\',\n\n            font=self._F(\'Arial\', 16, \'bold\'))\n    _lbl_cant.pack(side=\'left\', padx=5)\n    add_tooltip(_lbl_cant, _("Doppio click: aggiungi più cantanti in scaletta"))\n    # Doppio click sulla label "Cant:" → finestra per aggiungere più cantanti (senza brano)\n    _lbl_cant.bind(\'<Double-Button-1>\', self.apri_dialog_cantanti)\n    try:\n        _lbl_cant.config(cursor=\'hand2\')\n    except Exception:\n        pass\n\n    \n\n    self.entry_cantante = tk.Entry(frame_cant, bg=\'#1a1a1a\', fg=\'gray\',\n\n                                   font=self._F(\'Arial\', 16, \'bold\'), relief=\'flat\',\n\n                                   insertbackground=\'white\',\n                                   highlightthickness=0)\n\n    self.entry_cantante.pack(side=\'left\', fill=\'x\', expand=True, padx=5, ipady=6)\n\n    self.entry_cantante.insert(0, _("Inserisci il cantante"))\n    add_tooltip(self.entry_cantante, _("Nome del cantante da aggiungere alla scaletta"))\n\n    \n\n    # Placeholder\n\n    def on_cant_focus_in(e):\n\n        if self.entry_cantante.get() == _("Inserisci il cantante"):\n\n            self.entry_cantante.delete(0, tk.END)\n\n            self.entry_cantante.config(fg=\'white\')\n\n    \n\n    def on_cant_focus_out(e):\n\n        if not self.entry_cantante.get():\n\n            self.entry_cantante.insert(0, _("Inserisci il cantante"))\n\n            self.entry_cantante.config(fg=\'gray\')\n\n    \n\n    self.entry_cantante.bind(\'<FocusIn>\', on_cant_focus_in)\n\n    self.entry_cantante.bind(\'<FocusOut>\', on_cant_focus_out)\n    \n    # ── Autocomplete nomi playlist ──\n    self._cant_sugg_frame = None\n    self._cant_sugg_lb = None\n    \n    def _cant_show_suggestions():\n        t = self.entry_cantante.get().strip().upper()\n        if t == _(\'Inserisci il cantante\').upper() or len(t) < 1:\n            if self._cant_sugg_frame:\n                try: self._cant_sugg_frame.place_forget()\n                except: pass\n            return\n        try:\n            nomi = [p[\'nome\'] for p in self.playlist_data if p.get(\'nome\')]\n        except:\n            nomi = []\n        starts = [n for n in nomi if n.upper().startswith(t)]\n        contains = [n for n in nomi\n                     if t in n.upper() and not n.upper().startswith(t)]\n        risultati = (starts + contains)[:10]\n        if not risultati:\n            if self._cant_sugg_frame:\n                try: self._cant_sugg_frame.place_forget()\n                except: pass\n            return\n        # Crea il frame suggerimenti se non esiste\n        if not self._cant_sugg_frame or not self._cant_sugg_frame.winfo_exists():\n            self._cant_sugg_frame = tk.Frame(self.parent, bg=\'black\', bd=1,\n                                                relief=\'solid\',\n                                                highlightthickness=1,\n                                                highlightbackground=\'#ffa500\')\n            self._cant_sugg_lb = tk.Listbox(self._cant_sugg_frame,\n                bg=\'#1a1a1a\', fg=\'#ffcc00\',\n                font=(\'Arial\', 13, \'bold\'), relief=\'flat\', bd=0,\n                highlightthickness=0,\n                selectbackground=\'#0078D7\', selectforeground=\'white\',\n                activestyle=\'none\')\n            self._cant_sugg_lb.pack(fill=\'both\', expand=True)\n            def _pick(e=None):\n                s = self._cant_sugg_lb.curselection()\n                if not s: return\n                v = self._cant_sugg_lb.get(s[0]).strip()\n                self.entry_cantante.delete(0, tk.END)\n                self.entry_cantante.insert(0, v)\n                self.entry_cantante.config(fg=\'white\')\n                self._cant_sugg_frame.place_forget()\n                # Dopo aver selezionato, sposta focus sul campo brano\n                try: self.entry_filtro.focus_set()\n                except: pass\n                return \'break\'\n            self._cant_sugg_lb.bind(\'<Return>\', _pick)\n            self._cant_sugg_lb.bind(\'<Double-1>\', _pick)\n            self._cant_sugg_lb.bind(\'<ButtonRelease-1>\', _pick)\n            # Anche freccia Su/Giù su listbox + Escape torna alla entry\n            def _lb_escape(e=None):\n                self._cant_sugg_frame.place_forget()\n                self.entry_cantante.focus_set()\n                return \'break\'\n            self._cant_sugg_lb.bind(\'<Escape>\', _lb_escape)\n        # Popola lista\n        self._cant_sugg_lb.delete(0, tk.END)\n        for r in risultati:\n            self._cant_sugg_lb.insert(tk.END, f\'  {r}\')\n        # Posiziona sotto la entry_cantante\n        try:\n            ex = self.entry_cantante.winfo_rootx()\n            ey = self.entry_cantante.winfo_rooty() + self.entry_cantante.winfo_height()\n            px = ex - self.parent.winfo_rootx()\n            py = ey - self.parent.winfo_rooty()\n            w = max(self.entry_cantante.winfo_width(), 250)\n            h = min(len(risultati) * 28 + 4, 260)\n            self._cant_sugg_frame.place(x=px, y=py, width=w, height=h)\n            self._cant_sugg_frame.lift()\n        except: pass\n    \n    def _cant_on_key(e):\n        if e.keysym in (\'Return\', \'Escape\', \'Down\', \'Up\', \'Tab\'): return\n        _cant_show_suggestions()\n    \n    def _cant_on_down(e):\n        if self._cant_sugg_frame and self._cant_sugg_frame.winfo_ismapped():\n            self._cant_sugg_lb.focus_set()\n            self._cant_sugg_lb.selection_clear(0, tk.END)\n            self._cant_sugg_lb.selection_set(0)\n            self._cant_sugg_lb.activate(0)\n            return \'break\'\n    \n    def _cant_on_return(e):\n        # Se il popup è aperto, seleziona il primo suggerimento\n        if self._cant_sugg_frame and self._cant_sugg_frame.winfo_ismapped():\n            if self._cant_sugg_lb.size() > 0:\n                self._cant_sugg_lb.selection_clear(0, tk.END)\n                self._cant_sugg_lb.selection_set(0)\n                v = self._cant_sugg_lb.get(0).strip()\n                self.entry_cantante.delete(0, tk.END)\n                self.entry_cantante.insert(0, v)\n                self.entry_cantante.config(fg=\'white\')\n                self._cant_sugg_frame.place_forget()\n                try: self.entry_filtro.focus_set()\n                except: pass\n            return \'break\'\n        # Popup chiuso: passa al campo brano\n        try: self.entry_filtro.focus_set()\n        except: pass\n        return \'break\'\n    \n    def _cant_on_escape(e):\n        if self._cant_sugg_frame:\n            try: self._cant_sugg_frame.place_forget()\n            except: pass\n    \n    self.entry_cantante.bind(\'<KeyRelease>\', _cant_on_key)\n    self.entry_cantante.bind(\'<Down>\', _cant_on_down)\n    self.entry_cantante.bind(\'<Return>\', _cant_on_return)\n    self.entry_cantante.bind(\'<Escape>\', _cant_on_escape)\n\n                  \n\n    # CENTRO - Brano (filtro)\n\n    frame_brano = tk.Frame(header_top, bg=\'black\')\n\n    frame_brano.pack(side=\'left\', fill=\'both\', expand=True, padx=10)\n\n    \n\n    # ▶ PLAY brano dal campo filtro\n\n\n\n    \n\n    btn_play_filtro = tk.Button(frame_brano, text="▶", bg=\'#28a745\', fg=\'white\',\n\n                       font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\',\n\n                       cursor=\'hand2\', width=2,\n\n                       command=self.play_brano_da_filtro)\n\n    btn_play_filtro.pack(side=\'left\', padx=2)\n\n    add_tooltip(btn_play_filtro, _("Riproduci brano selezionato"))\n\n           \n\n    # 🗑 SVUOTA campo brano/filtro\n\n    btn_svuota = tk.Button(frame_brano, text="🗑", bg=\'#dc3545\', fg=\'white\',\n\n                          font=(\'Segoe UI\', 12, \'bold\'), relief=\'flat\', cursor=\'hand2\', \n\n                          width=2, command=self.svuota_campo_filtro)\n\n    btn_svuota.pack(side=\'left\', padx=2)\n\n    add_tooltip(btn_svuota, _("Svuota campo filtro"))\n\n           \n\n    self._lbl_brano = tk.Label(frame_brano, text=_("Brano (filtro):"), bg=\'black\', fg=\'white\',\n\n            font=self._F(\'Arial\', 16, \'bold\'))\n    self._lbl_brano.pack(side=\'left\', padx=5)\n    add_tooltip(self._lbl_brano, _("Cerca e seleziona un brano"))\n\n    \n\n    self.entry_filtro = tk.Entry(frame_brano, bg=\'#1a1a1a\', fg=\'gray\',\n\n                                 font=self._F(\'Arial\', 16, \'bold\'), relief=\'flat\',\n\n                                 # ⛔ LA LARGHEZZA DI QUESTO CAMPO DECIDE\n                                 #    ANCHE LE COLONNE DELLE RIGHE: la\n                                 #    colonna "Brano" della scaletta si\n                                 #    allinea a questa etichetta e finisce\n                                 #    dove comincia "Ton" (vedi\n                                 #    `_sc_get_col_x`). Allargandolo a 36\n                                 #    i titoli arrivavano addosso ai tasti\n                                 #    in fondo alla riga. 30 e\' il\n                                 #    compromesso. ⚠️ Sceso a 26: con 30 il\n                                 #    tasto VOCE arrivava sopra la sigla\n                                 #    del tipo (MP3, YT) e la copriva.\n                                 insertbackground=\'white\', width=22,\n                                 highlightthickness=0)\n\n    self.entry_filtro.pack(side=\'left\', fill=\'x\', expand=True, padx=1, ipady=10)\n\n    self.entry_filtro.insert(0, _("Filtra brano o autore"))\n    add_tooltip(self.entry_filtro, _("Cerca brano per nome o artista"))\n\n    # Placeholder\n\n    def on_brano_focus_in(e):\n\n        if self.entry_filtro.get() == _("Filtra brano o autore"):\n\n            self.entry_filtro.delete(0, tk.END)\n\n            self.entry_filtro.config(fg=\'white\')\n\n    def on_brano_focus_out(e):\n        def _delayed_placeholder():\n            try:\n                current = self.parent.focus_get()\n                if current in (self.entry_filtro, self.listbox_suggerimenti, self.container_suggerimenti):\n                    return\n                if current and hasattr(current, \'master\') and current.master == self.container_suggerimenti:\n                    return\n            except:\n                pass\n            if not self.entry_filtro.get():\n                self.entry_filtro.insert(0, _("Filtra brano o autore"))\n                self.entry_filtro.config(fg=\'gray\')\n        self.parent.after(50, _delayed_placeholder)\n\n    self.entry_filtro.bind(\'<FocusIn>\', on_brano_focus_in)\n\n    self.entry_filtro.bind(\'<FocusOut>\', on_brano_focus_out)\n\n    self.entry_filtro.bind(\'<KeyRelease>\', self._debounce_suggerimenti)\n    self._debounce_id = None\n    \n    # ── Navigazione tastiera sul campo brano ──\n    def _brano_on_down(e):\n        # Se la listbox suggerimenti è visibile, scendi nel popup\n        try:\n            if self.container_suggerimenti.winfo_ismapped() and self.listbox_suggerimenti.size() > 0:\n                # Bypassa il guard anti-focus-steal\n                self._listbox_click = True\n                self.listbox_suggerimenti.focus_set()\n                self.listbox_suggerimenti.selection_clear(0, tk.END)\n                self.listbox_suggerimenti.selection_set(0)\n                self.listbox_suggerimenti.activate(0)\n                self.listbox_suggerimenti.see(0)\n                # Reset dopo che il focus è stabilito\n                self.parent.after(150, lambda: setattr(self, \'_listbox_click\', False))\n                return \'break\'\n        except: pass\n    \n    def _brano_on_return(e):\n        # Se popup brano aperto: seleziona primo suggerimento\n        try:\n            if self.container_suggerimenti.winfo_ismapped() and self.listbox_suggerimenti.size() > 0:\n                self.listbox_suggerimenti.selection_clear(0, tk.END)\n                self.listbox_suggerimenti.selection_set(0)\n                self.seleziona_suggerimento()\n                # Dopo pick, sposta focus su ton per un eventuale secondo Invio\n                self._listbox_click = True\n                try: self.entry_ton.focus_set()\n                except: pass\n                self.parent.after(150, lambda: setattr(self, \'_listbox_click\', False))\n                return \'break\'\n        except: pass\n        # Nessun popup → aggiungi brano\n        self.aggiungi_brano()\n        return \'break\'\n    \n    self.entry_filtro.bind(\'<Down>\', _brano_on_down)\n    self.entry_filtro.bind(\'<Return>\', _brano_on_return)\n\n    \n\n    # DESTRA - Ton + Aggiungi\n\n    frame_ton = tk.Frame(header_top, bg=\'black\')\n\n    frame_ton.pack(side=\'left\', padx=10)\n\n    \n\n    _lbl_ton = tk.Label(frame_ton, text=_("Ton:"), bg=\'black\', fg=\'white\',\n\n            font=self._F(\'Arial\', 16, \'bold\'))\n    _lbl_ton.pack(side=\'left\', padx=5)\n    add_tooltip(_lbl_ton, _("Tonalità del brano"))\n\n    \n\n    self.entry_ton = tk.Entry(frame_ton, width=3, bg=\'#1a1a1a\', fg=\'white\',\n\n                              font=self._F(\'Arial\', 16, \'bold\'), relief=\'flat\',\n\n                              insertbackground=\'white\', highlightthickness=0)\n\n    self.entry_ton.pack(side=\'left\', padx=5, ipady=6)\n\n    self.entry_ton.insert(0, "0")\n    add_tooltip(self.entry_ton, _("Tonalità: da -12 a +12"))\n    # Invio su Ton = aggiungi brano\n    self.entry_ton.bind(\'<Return>\', lambda e: (self.aggiungi_brano(), \'break\')[1])\n\n    \n\n    btn_aggiungi = tk.Button(frame_ton, text=_("Aggiungi"), bg=\'#28a745\',\n\n                            fg=\'white\', font=self._F(\'Segoe UI\', 12, \'bold\'),\n\n                            relief=\'flat\', cursor=\'hand2\', width=10,\n                            height=2, pady=0,\n\n                            command=self.aggiungi_brano)\n\n    btn_aggiungi.pack(side=\'left\', padx=5)\n\n    add_tooltip(btn_aggiungi, _("Aggiungi brano alla scaletta"))\n\n    \n\n    # ⭐ RIMESSO il 10-09-2026, la sera stessa in cui era stato tolto.\n    #\n    #    Era stato staccato perche\' TOGLIERE la voce sul processore del\n    #    cliente non arriva a una qualita\' accettabile: misurato su tre\n    #    architetture (MDX-Net, MDX23C, htdemucs), tutte lasciano la voce\n    #    a circa -31 dB e sporcano la musica di circa -15 dB.\n    #\n    # ⭐ Ma il tasto non TOGLIE la voce: la ABBASSA (`set_voce`, e\n    #    `quanto_abbassare()` in devocalizza.py). E\' un\'altra cosa, e\n    #    aggira il muro invece di sbatterci: quello che il modello sbaglia\n    #    a riconoscere viene abbassato anche lui invece di restare a\n    #    volume pieno, quindi non ci sono buchi e i difetti non si\n    #    sentono. Dal vivo un filo di voce guida aiuta pure chi canta.\n    #    Quanto abbassare si decide da Opzioni (`devoc_db`, -12 dB di\n    #    serie); il livello del tasto sta in `voce_giu`.\n    #\n    # ⚠️ Nella patch 033 questo tasto SOSTITUIVA la X. Qui no: la X e\'\n    #    tornata e serve, quindi stanno tutti e due.\n    # ⚠️ "Devocalizza" e\' una parola lunga: sta su una riga sola con il\n    #    carattere a 9 e la larghezza a 11. Con 10/8 veniva tagliata.\n    self.btn_voce = tk.Button(header_top, text=_("Devocalizza"),\n                              bg=\'#8e44ad\', fg=\'white\',\n                              font=self._F(\'Segoe UI\', 9, \'bold\'),\n                              relief=\'flat\', cursor=\'hand2\',\n                              width=11, height=2, pady=0,\n                              command=self._voce_su_giu)\n    self.btn_voce.pack(side=\'left\', padx=5)\n    add_tooltip(self.btn_voce,\n                _("Abbassa la voce del brano. Si puo\' premere anche prima "\n                  "di far partire la base — anzi conviene: cosi\' parte "\n                  "gia\' pronta. A brano finito si spegne da solo."))\n\n    # ⛔ LA CROCE NON SI VEDE PIU\' (11-09-2026, chiesto dall\'utente): lo\n    #    spazio e\' andato al campo di ricerca, che si usa molto di piu\'.\n    #    La libreria si chiude lo stesso col tasto che l\'ha aperta.\n    #\n    # ⛔⛔ IL BOTTONE SI CREA LO STESSO, semplicemente NON SI IMPACCHETTA.\n    #    Prima avevo scritto `btn_chiudi = self.btn_voce` per riusare il\n    #    tasto della voce nelle rifiniture qui sotto: e\' sparito anche\n    #    quello. Un oggetto creato e non impacchettato non si vede e non\n    #    da\' fastidio a nessuno; togliere la riga che lo crea, invece,\n    #    lascia in giro un nome che il resto della funzione usa ancora.\n    btn_chiudi = tk.Button(header_top, text="✕",\n                           bg=\'#e74c3c\', fg=\'white\',\n                           font=self._F(\'Segoe UI\', 12, \'bold\'),\n                           relief=\'flat\', cursor=\'hand2\',\n                           width=3, command=self.toggle_slider)\n    # niente .pack(): resta invisibile\n\n    # ✅ Rendi bottoni header più reattivi\n    self._enhance_buttons(frame_brano)\n    self._voce_giu_attiva = False\n    self._enhance_buttons(frame_ton)\n    btn_chiudi.config(takefocus=False, activebackground=\'#9b59b6\', activeforeground=\'white\', pady=3, padx=4)\n    # ⛔ IL TASTO DELLA VOCE NON RICEVEVA NESSUNA RIFINITURA: `_enhance_buttons`\n    #    lavora su `frame_brano` e `frame_ton`, e lui sta in `header_top`.\n    #    Restava grezzo in mezzo a bottoni rifiniti, e si vedeva.\n    self.btn_voce.config(takefocus=False, activebackground=\'#7d3c98\',\n                         activeforeground=\'white\', bd=0,\n                         highlightthickness=0, pady=3, padx=4)\n\n    \n\n    # Campo filtro brani playlist (visibile solo quando si visualizzano brani playlist)\n\n    self.filtro_brani_playlist_frame = tk.Frame(right_frame, bg=\'#1a1a1a\')\n\n    # NON pack inizialmente - sarà mostrato solo quando si visualizzano brani playlist\n\n    \n\n    self.entry_filtro_brani_pl = tk.Entry(self.filtro_brani_playlist_frame, bg=\'#1a1a1a\', fg=\'gray\',\n\n                                          font=(\'Arial\', 12), relief=\'flat\',\n\n                                          insertbackground=\'white\', highlightthickness=0)\n\n    self.entry_filtro_brani_pl.pack(side=\'left\', fill=\'x\', expand=True, padx=5, pady=5, ipady=3)\n\n    self.entry_filtro_brani_pl.insert(0, _("Filtra brani..."))\n    add_tooltip(self.entry_filtro_brani_pl, _("Filtra brani nella playlist selezionata"))\n\n    \n\n    def on_filtro_brani_focus_in(e):\n\n        if self.entry_filtro_brani_pl.get() == _("Filtra brani..."):\n\n            self.entry_filtro_brani_pl.delete(0, tk.END)\n\n            self.entry_filtro_brani_pl.config(fg=\'white\')\n\n    \n\n    def on_filtro_brani_focus_out(e):\n\n        if not self.entry_filtro_brani_pl.get():\n\n            self.entry_filtro_brani_pl.insert(0, _("Filtra brani..."))\n\n            self.entry_filtro_brani_pl.config(fg=\'gray\')\n\n    \n\n    self.entry_filtro_brani_pl.bind(\'<FocusIn>\', on_filtro_brani_focus_in)\n\n    self.entry_filtro_brani_pl.bind(\'<FocusOut>\', on_filtro_brani_focus_out)\n\n    # ✅ Debounce: aspetta 250ms dopo l\'ultimo tasto prima di filtrare\n    self._filtro_brani_after_id = None\n    def _debounce_filtra_brani(event=None):\n        if self._filtro_brani_after_id:\n            self.parent.after_cancel(self._filtro_brani_after_id)\n        self._filtro_brani_after_id = self.parent.after(350, self.filtra_brani_playlist)\n    self.entry_filtro_brani_pl.bind(\'<KeyRelease>\', _debounce_filtra_brani)\n\n    \n\n    # Variabili per memorizzare brani playlist correnti\n\n    self.brani_playlist_correnti = []\n\n    self.playlist_nome_corrente = ""\n\n           \n\n    # RIGHE - Canvas unico con scroll (layout identico all\'originale)\n\n    container_righe = tk.Frame(right_frame, bg=\'black\', highlightthickness=0)\n    container_righe.pack(side=\'top\', fill=\'both\', expand=True)\n    self._container_righe = container_righe\n\n    # ── Dummy canvas/frame per compatibilità playlist ──\n    self.canvas = tk.Canvas(container_righe, bg=\'black\', highlightthickness=0, takefocus=False)\n    self.frame_righe = tk.Frame(self.canvas, bg=\'black\')\n    self.canvas_window = self.canvas.create_window((0,0), window=self.frame_righe, anchor=\'nw\')\n    self.scrollbar_righe = tk.Scrollbar(container_righe, bg=\'#1a1a1a\')\n    self.scrollbar_visible = False\n    self.scrollbar_righe.config(command=self.canvas.yview)\n    def bind_scroll_to_children(widget): pass\n    self.bind_scroll_to_children = bind_scroll_to_children\n\n    # ── Container scaletta: Canvas unico ──\n    self._sc_container = tk.Frame(container_righe, bg=\'black\', bd=0, highlightthickness=0)\n    self._sc_container.pack(side=\'left\', fill=\'both\', expand=True)\n    self._sc_row_h = self._S(44)\n    self._sc_iid_counter = 0\n    self._sc_row_data = {}  # iid -> {cantante, brano, ton, ext, path}\n\n    # ── Intestazioni colonne (allineate dinamicamente ai campi input sopra) ──\n    self._sc_header = tk.Canvas(self._sc_container, bg=\'#1a1a1a\', height=self._S(24),\n                                 highlightthickness=0, bd=0)\n    self._sc_header.pack(side=\'top\', fill=\'x\')\n    def _draw_col_headers(event=None):\n        hc = self._sc_header\n        hc.delete(\'all\')\n        _hf = self._F(\'Arial\', 11, \'bold\')\n        _hcol = \'#888888\'\n        x_cant = self._S(164)\n        try:\n            hc.update_idletasks()\n            hc_rx = hc.winfo_rootx()\n            x_brano = self._lbl_brano.winfo_rootx() - hc_rx\n            x_ton = self.entry_ton.winfo_rootx() - hc_rx\n        except:\n            x_brano, x_ton = self._S(407), max(hc.winfo_width(), self._S(900)) - self._S(180)\n        _hy = self._S(24) // 2\n        hc.create_text(x_cant, _hy, text=_(\'Cantante\'), fill=_hcol, font=_hf, anchor=\'w\')\n        hc.create_text(x_brano, _hy, text=_(\'Brano\'), fill=_hcol, font=_hf, anchor=\'w\')\n        hc.create_text(x_ton, _hy, text=_(\'Ton\'), fill=_hcol, font=_hf, anchor=\'w\')\n    self._sc_header.bind(\'<Configure>\', _draw_col_headers)\n    self._draw_col_headers = _draw_col_headers\n\n    self._sc_scrollbar = tk.Scrollbar(self._sc_container, bg=\'#1a1a1a\', bd=0)\n    # Scrollbar inizia nascosta, verrà mostrata solo se necessario\n    self._sc_scrollbar_visible = False\n\n    self._sc_cv = tk.Canvas(self._sc_container, bg=\'black\', highlightthickness=0, bd=0,\n                            yscrollcommand=self._sc_scrollbar.set)\n    self._sc_cv.pack(side=\'left\', fill=\'both\', expand=True)\n    self._sc_scrollbar.config(command=self._sc_cv.yview)\n\n    # Alias per compatibilità metodi esistenti\n    self._sc_tree = None\n    self._sc_btn_cv = self._sc_cv\n\n    # Mouse wheel (condizionato a _sc_scroll_active)\n    self._sc_scroll_active = False\n    def _sc_mw(e):\n        if not self._sc_scroll_active: return \'break\'\n        self._sc_cv.yview_scroll(-1*int(e.delta/120),\'units\')\n        return \'break\'\n    def _sc_up(e):\n        if not self._sc_scroll_active: return \'break\'\n        self._sc_cv.yview_scroll(-1,\'units\')\n        return \'break\'\n    def _sc_down(e):\n        if not self._sc_scroll_active: return \'break\'\n        self._sc_cv.yview_scroll(1,\'units\')\n        return \'break\'\n    self._sc_cv.bind(\'<MouseWheel>\', _sc_mw)\n    self._sc_cv.bind(\'<Button-4>\', _sc_up)\n    self._sc_cv.bind(\'<Button-5>\', _sc_down)\n\n    # Click/drag/hover\n    self._sc_cv.bind(\'<Button-1>\', self._sc_on_click)\n    self._sc_cv.bind(\'<Double-1>\', self._sc_on_dblclick)\n    self._sc_cv.bind(\'<B1-Motion>\', self._sc_drag_motion)\n    self._sc_cv.bind(\'<ButtonRelease-1>\', self._sc_drag_end)\n    self._sc_cv.bind(\'<Motion>\', self._sc_on_hover)\n    self._sc_cv.bind(\'<Leave>\', self._sc_on_leave)\n    self._sc_cv.bind(\'<Button-3>\', self._sc_on_rightclick)\n    self._sc_cv._custom_context_menu = True  # ✅ Blocca menu contestuale globale\n    \n    # ✅ Tasti freccia per spostare la riga selezionata\n    self._sc_cv.config(takefocus=True)\n    self._sc_cv.bind(\'<Up>\', self._sc_move_selected_up)\n    self._sc_cv.bind(\'<Down>\', self._sc_move_selected_down)\n    self._sc_cv.bind(\'<Escape>\', lambda e: self.deselect_all_righe())\n    self._sc_cv.bind(\'<space>\', self._sc_space_preview)\n\n    # Redraw on resize con debounce\n    self._sc_resize_after = None\n    self._sc_last_size = (0, 0)\n    def _sc_on_resize(e):\n        if self._sc_resize_after:\n            try: self._sc_cv.after_cancel(self._sc_resize_after)\n            except: pass\n        # Solo se la dimensione è cambiata significativamente (delta > 5px)\n        new_size = (e.width, e.height)\n        old_w, old_h = self._sc_last_size\n        if abs(new_size[0] - old_w) < 5 and abs(new_size[1] - old_h) < 5:\n            return\n        self._sc_last_size = new_size\n        self._sc_resize_after = self._sc_cv.after(250, self._sc_redraw_all)\n    self._sc_cv.bind(\'<Configure>\', _sc_on_resize)\n    self._sc_hover_tag = None\n    self._sc_dragging = False\n    self._sc_drag_iid = None\n    self._sc_data = {}\n    self._sc_brano_font = None  # cached font for truncation\n\n    \n\n    # ✅ LINGUETTA che sporge SOPRA il bordo — creata sul PARENT per non essere clippata\n    self._grip_tab = tk.Frame(self.parent, bg=\'#555555\', width=80, height=14,\n                              highlightthickness=0,\n                              cursor=\'sb_v_double_arrow\', relief=\'raised\', bd=1)\n    add_tooltip(self._grip_tab, _("Trascina per ridimensionare la libreria"))\n    self._grip_cv = tk.Canvas(self._grip_tab, bg=\'#555555\', width=60, height=6,\n                              highlightthickness=0, cursor=\'sb_v_double_arrow\')\n    self._grip_cv.place(relx=0.5, rely=0.5, anchor=\'center\')\n    self._grip_cv.create_line(5, 1, 55, 1, fill=\'#999999\')\n    self._grip_cv.create_line(5, 4, 55, 4, fill=\'#999999\')\n    \n    for w in (self._grip_tab, self._grip_cv):\n        w.bind(\'<Button-1>\', self.start_resize)\n        w.bind(\'<B1-Motion>\', self.do_resize)\n        w.bind(\'<ButtonRelease-1>\', self.end_resize)\n\n    \n\n    #self.carica_righe_salvate()\n\n    \n\n\n\n    \n\n    # --- AGGIUNTA: LISTBOX SUGGERIMENTI DINAMICA ---\n\n    # ✅ Creato sulla finestra principale per sovrastare tutto\n\n    self.container_suggerimenti = tk.Frame(self.parent, bg=\'black\', bd=2, relief=\'solid\', takefocus=False)\n\n    self.listbox_suggerimenti = tk.Listbox(\n\n        self.container_suggerimenti, \n\n        bg=\'#1a1a1a\', fg=\'yellow\', \n\n        font=(\'Arial\', 14), \n\n        relief=\'flat\', bd=0, \n\n        highlightthickness=1,\n\n        highlightbackground=\'#333333\',\n\n        takefocus=False\n\n    )\n\n    self.listbox_suggerimenti.pack(fill=\'both\', expand=True)\n\n    # ✅ ANTI-FOCUS-STEAL: se la listbox prende focus mentre si digita, rimandalo all\'entry\n    def _redirect_focus(e):\n        # Permetti focus solo se l\'utente ha cliccato col mouse\n        if not getattr(self, \'_listbox_click\', False):\n            self.entry_filtro.focus_set()\n    self.listbox_suggerimenti.bind(\'<FocusIn>\', _redirect_focus)\n    self.listbox_suggerimenti.bind(\'<ButtonPress-1>\', lambda e: setattr(self, \'_listbox_click\', True))\n    self.listbox_suggerimenti.bind(\'<ButtonRelease-1>\', lambda e: self.parent.after(100, lambda: setattr(self, \'_listbox_click\', False)))\n    \n    # Navigazione frecce sulla listbox (manuale perché takefocus=False disabilita la nativa)\n    def _lb_down(e):\n        sz = self.listbox_suggerimenti.size()\n        if sz == 0: return \'break\'\n        cur = self.listbox_suggerimenti.curselection()\n        idx = (cur[0] + 1) if cur else 0\n        if idx >= sz: idx = sz - 1  # ferma in fondo\n        self.listbox_suggerimenti.selection_clear(0, tk.END)\n        self.listbox_suggerimenti.selection_set(idx)\n        self.listbox_suggerimenti.activate(idx)\n        self.listbox_suggerimenti.see(idx)\n        return \'break\'\n    \n    def _lb_up(e):\n        sz = self.listbox_suggerimenti.size()\n        if sz == 0: return \'break\'\n        cur = self.listbox_suggerimenti.curselection()\n        idx = (cur[0] - 1) if cur else 0\n        if idx < 0:\n            # Torna all\'entry filtro\n            try: self.entry_filtro.focus_set()\n            except: pass\n            return \'break\'\n        self.listbox_suggerimenti.selection_clear(0, tk.END)\n        self.listbox_suggerimenti.selection_set(idx)\n        self.listbox_suggerimenti.activate(idx)\n        self.listbox_suggerimenti.see(idx)\n        return \'break\'\n    \n    self.listbox_suggerimenti.bind(\'<Down>\', _lb_down)\n    self.listbox_suggerimenti.bind(\'<Up>\', _lb_up)\n    self.listbox_suggerimenti.bind(\'<Escape>\',\n        lambda e: (self.container_suggerimenti.place_forget(),\n                    self.entry_filtro.focus_set(), \'break\')[2])\n\n    \n\n    # ✅ SCROLL MOUSE per listbox suggerimenti\n\n    def on_suggest_scroll(event):\n\n        self.listbox_suggerimenti.yview_scroll(-1 * int(event.delta / 120), \'units\')\n\n    \n\n    self.listbox_suggerimenti.bind(\'<MouseWheel>\', on_suggest_scroll)\n\n    self.listbox_suggerimenti.bind(\'<Button-4>\', lambda e: self.listbox_suggerimenti.yview_scroll(-1, \'units\'))\n\n    self.listbox_suggerimenti.bind(\'<Button-5>\', lambda e: self.listbox_suggerimenti.yview_scroll(1, \'units\'))\n\n    \n\n    self.nascondi_suggerimenti()\n\n    # Nascondiamo inizialmente\n\n    self.container_suggerimenti.place_forget() \n\n\n\n    # Bind per la ricerca real-time (già bindato in create_widgets, NON duplicare)\n\n    \n\n    # Click singolo immediato (Risolve il problema del doppio click)\n\n    self.listbox_suggerimenti.bind(\'<<ListboxSelect>>\', self.seleziona_suggerimento)\n\n    \n\n    # Supporto tastiera (Invio): seleziona e passa al campo Ton\n    def _lb_return(event=None):\n        self.seleziona_suggerimento()\n        try: self.entry_ton.focus_set()\n        except: pass\n        return \'break\'\n    self.listbox_suggerimenti.bind(\'<Return>\', _lb_return)\n\n    \n\n    # CARICA RIGHE SALVATE DAL DATABASE\n\n    self.carica_righe_salvate()\n\n    # Carica subito l\'elenco delle playlist (per autocomplete cantante e per il pannello playlist)\n    try: self.carica_lista_playlist()\n    except Exception as _e: print(f"[carica playlist init] {_e}")\n\n    # ✅ Click fuori dai suggerimenti li nasconde (evita che il popup blocchi Aggiungi e altri bottoni)\n    self.slider_frame.bind_all(\'<Button-1>\', self._global_click_handler, add=\'+\')\n\n    # ⭐ Due invii di fila sul brano selezionato lo avviano. Va agganciato\n    #    QUI con bind_all: sul riquadro non arriverebbe mai, perche\' il\n    #    fuoco sta dentro i campi della riga (vedi _doppio_invio_play).\n    self.slider_frame.bind_all(\'<Return>\', self._doppio_invio_play, add=\'+\')\n\n# ---------------- il tasto della voce (al posto della vecchia X) --------\n\n\n# ⭐ RIMESSE il 10-09-2026 insieme al tasto: sono le quattro che gli\n#    servono. Riprese TALI E QUALI dalla patch 033 (`publish/`), non\n#    riscritte a memoria: dentro ci sono correzioni pagate sul campo, come\n#    l\'ordine con cui si cerca il brano scelto.\n\n\ndef _voce_su_giu(self):\n    """Abbassa la voce del brano, o la rimette.\n\n    ⭐ Si puo\' premere anche a base FERMA: la scelta resta e parte\n       insieme al brano. Chi prepara la serata decide prima, non a\n       musica gia\' partita.\n    """\n    giu = not getattr(self, \'_voce_giu_attiva\', False)\n    livello = 0\n    if giu:\n        try:\n            from .database import Database\n            # 100 = il massimo che si puo\' fare. Chi ne vuole meno\n            # abbassa `voce_giu` da Opzioni.\n            livello = int(str(Database.get_config(\'voce_giu\', \'100\')).strip())\n        except Exception:\n            livello = 100\n        livello = max(1, min(100, livello))\n    try:\n        self.system.set_voce(livello, brano=self._voce_brano_scelto())\n    except Exception as e:\n        print("[voce] %s" % e)\n    self._voce_giu_attiva = giu\n    try:\n        if giu:\n            self.btn_voce.config(text=_("Rimetti\\nla voce"), bg=\'#d35400\')\n            # ⭐ DEVE FUNZIONARE AL PRIMO GIRO. Prima il brano partiva\n            #    subito e il modello lo inseguiva: da li\' venivano l\'inizio\n            #    sporco, lo scatto alla giunzione e la seconda passata che\n            #    non partiva mai. Adesso il tasto dice a che punto e\' la\n            #    preparazione e quando e\' PRONTA: si fa partire allora.\n            self._voce_segui_preparazione()\n        else:\n            self.btn_voce.config(text=_("Devocalizza"), bg=\'#8e44ad\')\n    except Exception:\n        pass\n\n\ndef _voce_brano_scelto(self):\n    """Qual e\' il brano scelto ADESSO, con la base ancora ferma.\n\n    ⛔ SERVE: `system.current_file` a base ferma e\' vuoto — il programma\n       sa quale file suonare solo quando si preme play. Il brano scelto\n       lo sa la libreria: o la riga cliccata nei risultati, oppure la\n       prima riga della scaletta, che e\' quella che parte.\n    """\n    # ⛔ SI USA LA STESSA REGOLA DEL PLAY, nello stesso ordine: se il tasto\n    #    e il play guardano in due posti diversi, si abbassa la voce a un\n    #    brano e ne parte un altro. E\' successo: incollando un secondo\n    #    link nel campo, il play faceva partire QUELLO mentre il tasto\n    #    stava ancora sulla riga scelta prima, e usciva l\'audio del primo\n    #    brano. Vedi `play_brano_da_filtro`, che ha questo stesso ordine.\n    def annota(da, che):\n        # ⚠️ si SCRIVE da dove viene il brano: senza, quando prepara\n        #    quello sbagliato non c\'e\' modo di sapere quale dei quattro\n        #    posti ha risposto, e si va a tentativi.\n        try:\n            self.system._voce_log(\'brano scelto: %s  (da: %s)\'\n                                  % (str(che)[:70], da))\n        except Exception:\n            pass\n        return che\n\n    # 1) LA RIGA SELEZIONATA, che e\' quella che parte davvero.\n    # ⛔ PRIMA DI TUTTO IL RESTO: prendevo la PRIMA riga della scaletta, e\n    #    cosi\' si preparava sempre il primo brano dell\'elenco invece di\n    #    quello scelto — poi partiva quello selezionato e si sentiva la\n    #    voce. E\' la stessa riga che usa l\'invio (`_on_enter_play`).\n    try:\n        righe = getattr(self, \'righe\', [])\n        i = getattr(self, \'selected_riga_index\', -1)\n        fuoco = False\n        if i is None or i < 0 or i >= len(righe):\n            i = self._riga_del_fuoco(righe)\n            fuoco = True\n        if i is not None and 0 <= i < len(righe):\n            riga = righe[i]\n            dove = \'riga %d %s\' % (i + 1,\n                                   \'sotto il cursore\' if fuoco else \'selezionata\')\n            p = riga.get(\'path\')\n            if p:\n                return annota(dove, p)\n            t = riga[\'brano\'].get().strip() if hasattr(riga[\'brano\'], \'get\') else \'\'\n            if \'youtu.be/\' in t.lower() or \'youtube.com/\' in t.lower():\n                return annota(dove, t)\n    except Exception:\n        pass\n\n    # 2) il link scritto nel campo (come fa `play_brano_da_filtro`)\n    try:\n        testo = self.entry_filtro.get().strip()\n        if \'youtu.be/\' in testo.lower() or \'youtube.com/\' in testo.lower():\n            return annota(\'link nel campo\', testo)\n    except Exception:\n        pass\n\n    # 3) l\'ultimo brano cliccato nei suggerimenti\n    p = getattr(self, \'brano_selezionato_path\', None)\n    if p:\n        return annota(\'suggerimento cliccato\', p)\n\n    # 4) ultimo ripiego: la prima riga che si vede\n    try:\n        for n, riga in enumerate(getattr(self, \'righe\', [])):\n            if riga[\'frame\'].winfo_viewable() and riga.get(\'path\'):\n                return annota(\'RIPIEGO: prima riga visibile (%d)\' % (n + 1),\n                              riga[\'path\'])\n    except Exception:\n        pass\n    try:\n        self.system._voce_log(\'brano scelto: NESSUNO, non so quale sia\')\n    except Exception:\n        pass\n    return None\n\n\ndef _voce_nuovo_brano(self, percorso):\n    """Il brano scelto e\' cambiato.\n\n    ⭐ Se il tasto e\' gia\' armato si comincia a preparare SUBITO, senza\n       aspettare che si prema play: quando la base parte e\' gia\' pronta.\n       Se il tasto non e\' armato non si fa niente — non si mette il\n       computer a lavorare per un brano che forse non parte nemmeno.\n    """\n    if not percorso or not getattr(self, \'_voce_giu_attiva\', False):\n        return\n    try:\n        from .database import Database\n        liv = int(str(Database.get_config(\'voce_giu\', \'100\')).strip())\n    except Exception:\n        liv = 100\n    try:\n        self.system.set_voce(max(1, min(100, liv)), brano=percorso)\n    except Exception as e:\n        print("[voce] %s" % e)\n\n\ndef _voce_disarma(self):\n    """Rimette il tasto della voce come nuovo, a brano finito.\n\n    Serve perche\' la scelta vale per UN brano: chi canta dopo parte con la\n    voce originale, e se la vuole giu\' preme lui. Senza questo il tasto\n    restava acceso per tutta la serata.\n    """\n    if not getattr(self, \'_voce_giu_attiva\', False):\n        return\n    self._voce_giu_attiva = False\n    try:\n        self.btn_voce.config(text=_("Devocalizza"), bg=\'#8e44ad\')\n    except Exception:\n        pass\n\n# ⚠️ `_doppio_invio_play` e `_riga_del_fuoco` NON c\'entrano col tasto: sono\n#    la scorciatoia dei due invii, chiesta a parte. Restano dove sono.\n\n\ndef _voce_segui_preparazione(self):\n    """Aggiorna il tasto mentre il brano si prepara.\n\n    ⚠️ Si usa `after`, non un\'attesa: bloccando qui si congelerebbe tutta\n       la finestra, e il programma sembrerebbe piantato.\n    """\n    if not getattr(self, \'_voce_giu_attiva\', False):\n        return\n    try:\n        fatti, totali = getattr(self.system, \'_voce_avanzamento\', (0, 0))\n        pronto = getattr(self.system, \'_voce_pronto\', False)\n        if pronto:\n            self.btn_voce.config(text=_("PRONTA\\nsuona pure"), bg=\'#27ae60\')\n            return\n        if totali > 0 and getattr(self.system, \'_voce_si_parte\', False):\n            # ⭐ si puo\' gia\' mandare: il resto lo finisce mentre suona\n            self.btn_voce.config(\n                text=_("VAI\\n%d%%") % int(100.0 * fatti / totali),\n                bg=\'#27ae60\')\n        elif totali > 0:\n            self.btn_voce.config(\n                text=_("Preparo\\n%d%%") % int(100.0 * fatti / totali),\n                bg=\'#d35400\')\n        else:\n            self.btn_voce.config(text=_("Preparo…"), bg=\'#d35400\')\n    except Exception:\n        pass\n    try:\n        self.parent.after(500, self._voce_segui_preparazione)\n    except Exception:\n        pass\n\n\ndef _doppio_invio_play(self, event=None):\n    """Due invii di fila su un brano selezionato lo fanno partire.\n\n    ⛔ PERCHE\' NON BASTA UN INVIO: il primo invio serve ancora a\n       confermare quello che si sta scrivendo — la tonalita\', il\n       cantante, il suggerimento scelto dall\'elenco. Prendendosi il primo\n       si romperebbe il modo di lavorare di adesso. Parte il SECONDO,\n       entro un secondo e mezzo e sulla STESSA riga.\n\n    ⚠️ Si aggancia con `bind_all`: la scorciatoia c\'era gia\' sul riquadro\n       (`_on_enter_play`) ma NON SI ATTIVAVA MAI, perche\' in Tk il tasto\n       va al campo che ha il fuoco e non risale a un riquadro che gli sta\n       intorno. E il fuoco, in una riga della scaletta, sta sempre dentro\n       un campo di testo. Ecco perche\' "con un invio non avvia niente".\n    """\n    # ⛔ NIENTE guardia su `slider_visible`: le righe della scaletta si\n    #    usano anche a libreria chiusa, e quella guardia bloccava tutto.\n    try:\n        righe = getattr(self, \'righe\', [])\n        i = getattr(self, \'selected_riga_index\', -1)\n        if i < 0 or i >= len(righe):\n            # ⭐ nessuna riga "selezionata": si guarda dove sta il cursore.\n            #    Chi scrive dentro un campo della riga sta lavorando su\n            #    QUELLA riga, anche se non l\'ha mai cliccata — e senza\n            #    questo l\'invio non avviava niente.\n            i = self._riga_del_fuoco(righe)\n        if i is None or i < 0 or i >= len(righe):\n            return\n    except Exception:\n        return\n\n    import time as _t\n    adesso = _t.time()\n    ultimo, quale = getattr(self, \'_invio_ultimo\', (0.0, -1))\n    self._invio_ultimo = (adesso, i)\n    if quale != i or (adesso - ultimo) > 1.5:\n        return                       # era il primo: si lascia lavorare\n\n    self._invio_ultimo = (0.0, -1)   # cosi\' non parte tre volte di fila\n    riga = righe[i]\n    percorso = riga.get(\'path\')\n    testo = riga[\'brano\'].get().strip() if hasattr(riga[\'brano\'], \'get\') else \'\'\n    if not percorso and (\'youtu.be/\' in testo.lower()\n                         or \'youtube.com/\' in testo.lower()):\n        percorso = testo\n    if not percorso:\n        return\n    try:\n        self.play_brano(percorso, riga[\'ton\'],\n                        riga[\'cantante\'].get(), testo)\n    except Exception as e:\n        print("[invio] %s" % e)\n    return \'break\'\n\n\ndef _riga_del_fuoco(self, righe):\n    """In quale riga della scaletta sta il cursore adesso.\n\n    Si parte dal campo che ha il fuoco e si risale di padre in padre\n    finche\' non si riconosce il riquadro di una riga.\n    """\n    try:\n        w = self.parent.focus_get()\n    except Exception:\n        w = None\n    for _ in range(8):\n        if w is None:\n            return None\n        for i, riga in enumerate(righe):\n            if riga.get(\'frame\') is w:\n                return i\n        try:\n            w = w.master\n        except Exception:\n            return None\n    return None\n\n\ndef crea_riga(self, cantante, brano, tonalita, path, from_playlist=False, salta_dedup=False):\n    """Crea riga su Canvas unico — layout: [≡][+][🗑][🔄] Cant: VALUE [▶] Brano: VALUE Ton: VALUE EXT"""\n    cantante_upper = cantante.strip().upper()\n    brano_original = brano.strip()\n    _is_yt_link = \'youtu.be/\' in brano_original.lower() or \'youtube.com/\' in brano_original.lower()\n    _is_yt_path = path and (\'youtu.be/\' in path.lower() or \'youtube.com/\' in path.lower())\n    if _is_yt_link:\n        # brano tipo "Artista - Titolo — https://youtu.be/ID": in scaletta mostro SOLO il\n        # titolo (artista/brano); l\'URL diventa il percorso per la riproduzione. Se è un\n        # link "nudo" (nessun testo oltre l\'URL) lo lascio così com\'è.\n        _m = re.search(r\'https?://\\S+\', brano_original)\n        _url = _m.group(0).rstrip(\'.,;)\') if _m else brano_original\n        _testo = re.sub(r\'https?://\\S+\', \'\', brano_original)\n        _testo = re.sub(r\'(?:www\\.)?(?:youtu\\.be|youtube\\.com)/\\S+\', \'\', _testo, flags=re.I)\n        _testo = _testo.strip(\' \\t—–-|:•\').strip()\n        if _testo:\n            brano_upper = _testo.upper()\n            if not path: path = _url\n        else:\n            brano_upper = brano_original\n            if not path: path = brano_original\n        ext_str = "YT"\n    elif _is_yt_path:\n        brano_upper = brano_original.upper()\n        ext_str = "YT"\n    else:\n        brano_upper = brano_original.upper()\n    if not _is_yt_link and not _is_yt_path:\n        ext_str = ""\n        if path: ext_str = os.path.splitext(path)[1][1:].upper()\n\n    # ✅ PRE-SCARICO YouTube: appena il brano entra in scaletta il video viene\n    #    scaricato in background, cosi\' quando tocca a quella persona parte\n    #    SUBITO. Non si fa al ricaricamento della scaletta salvata\n    #    (from_playlist) per non scaricare tutto in blocco all\'avvio.\n    if (_is_yt_link or _is_yt_path) and not from_playlist:\n        try:\n            from .youtube_local import prescarica_youtube\n            prescarica_youtube(path)\n        except Exception as _e:\n            print(f"[YT-PRE] non avviato: {_e}")\n\n    # Cerca cantante esistente (salta durante caricamento batch)\n    if not from_playlist and not salta_dedup and not getattr(self, \'_batch_loading\', False):\n        for riga in self.righe:\n            riga_cantante = riga[\'cantante\'].get().strip().upper()\n            if riga_cantante == cantante_upper:\n                brano_attuale = riga[\'brano\'].get().strip()\n                ha_brano = brano_attuale and brano_attuale.upper() not in (\'\', _(\'Digita per cercare...\').upper())\n                if ha_brano:\n                    risposta = messagebox.askyesno(_("Cantante già in scaletta"),\n                        _("{cantante} ha già il brano:\\n\\n🎵 {brano_attuale}\\n\\nVuoi sostituirlo con:\\n\\n🎵 {brano_nuovo}?").format(\n                            cantante=cantante_upper, brano_attuale=brano_attuale, brano_nuovo=brano_upper),\n                        parent=self.parent)\n                    if not risposta: return\n                riga[\'brano\'].insert(0, brano_upper)\n                riga[\'ton\'].insert(0, tonalita)\n                riga[\'path\'] = path\n                # Aggiorna anche _sc_row_data\n                _iid = riga.get(\'iid\')\n                if _iid and _iid in self._sc_row_data:\n                    self._sc_row_data[_iid][\'path\'] = path\n                riga[\'ext_label\'].config(text=ext_str)\n                self.salva_righe()\n                return\n\n    # ── Genera iid unico ──\n    self._sc_iid_counter += 1\n    iid = f\'r{self._sc_iid_counter}\'\n\n    # ── Salva dati ──\n    self._sc_row_data[iid] = {\n        \'cantante\': cantante_upper, \'brano\': brano_upper,\n        \'ton\': str(tonalita), \'ext\': ext_str, \'path\': path or \'\'\n    }\n\n    # ✅ Durante batch loading, salta TUTTO il disegno canvas\n    # (verrà fatto da _sc_redraw_all alla fine, con virtualizzazione)\n    _batch = getattr(self, \'_batch_loading\', False)\n    \n    if not _batch:\n        cv = self._sc_cv\n        cv.update_idletasks()\n        cw = max(cv.winfo_width(), 900)\n        row_idx = len(self.righe)\n        h = self._sc_row_h\n        y_top = row_idx * h\n        y_mid = y_top + h // 2\n        bg = \'#0a0a0a\' if row_idx % 2 == 0 else \'#141414\'\n\n        # Background\n        cv.create_rectangle(0, y_top, cw + 2000, y_top + h,\n            fill=bg, outline=\'\', tags=(iid, f\'bg_{iid}\'))\n\n        # ── Bottoni sinistri ──\n        bw, pad, x = self._S(36), self._S(2), self._S(4)\n        _bstep = bw + self._S(2)\n\n        _is_placeholder = brano_upper.upper().startswith(_(\'Digita per cercare...\').rstrip(\'.\').upper()) or brano_upper == \'\'\n        btn_add_open = (\'openpl\', \'📂\', \'#8B5CF6\', \'white\') if _is_placeholder else (\'add\', \'+\', \'#0078D7\', \'white\')\n\n        for act, sym, col, fg in [\n            (\'drag\',\'≡\',\'#333333\',\'#888888\'), btn_add_open,\n            (\'del\',\'🗑\',\'#dc3545\',\'white\'), (\'rot\',\'🔄\',\'#ffa500\',\'white\')]:\n            cv.create_rectangle(x, y_top+pad, x+bw, y_top+h-pad,\n                fill=col, outline=\'\', tags=(iid, f\'btn_{act}_{iid}\', \'btn\'))\n            cv.create_text(x+bw//2, y_mid, text=sym, fill=fg,\n                font=self._F(\'Segoe UI\', 14, \'bold\'), tags=(iid, f\'btn_{act}_{iid}\', \'btn\'))\n            x += _bstep\n\n        # ── valore cantante ──\n        x_cant, x_brano, x_ton = self._sc_get_col_x()\n        cv.create_text(x_cant, y_mid, text=cantante_upper, fill=\'#ffcc00\',\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_cantante_{iid}\', \'click_cantante\'))\n\n        # ── valore brano (troncato) ──\n        x = x_brano\n        max_brano_px = max(x_ton - x - self._S(15), self._S(50))\n\n        if not self._sc_brano_font: self._sc_brano_font = tkfont.Font(family=\'Arial\', size=self._S(18), weight=\'bold\')\n        _bf = self._sc_brano_font\n        brano_trunc = brano_upper\n        if brano_trunc and _bf.measure(brano_trunc) > max_brano_px:\n            lo, hi = 0, len(brano_trunc)\n            while lo < hi:\n                mid = (lo + hi + 1) // 2\n                if _bf.measure(brano_trunc[:mid] + \'...\') <= max_brano_px:\n                    lo = mid\n                else:\n                    hi = mid - 1\n            brano_trunc = brano_trunc[:lo] + \'...\' if lo > 0 else \'...\'\n        _is_placeholder = brano_upper.upper().startswith(_(\'Digita per cercare...\').rstrip(\'.\').upper()) or brano_upper == \'\'\n        _brano_color = \'#555555\' if _is_placeholder else \'#ffcc00\'\n        cv.create_text(x, y_mid, text=brano_trunc, fill=_brano_color,\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_brano_{iid}\', \'click_brano\'))\n\n        # ── valore ton ──\n        cv.create_text(x_ton, y_mid, text=str(tonalita), fill=\'#ffcc00\',\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_ton_{iid}\', \'click_ton\'))\n\n        # ── Estensione ──\n        # ⚠️ spostata a sinistra per fare posto al tasto della voce\n        cv.create_text(cw - self._S(200), y_mid, text=ext_str, fill=\'#888888\',\n            font=self._F(\'Arial\', 16, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_ext_{iid}\'))\n\n        # ── il tasto che toglie la voce a QUESTO brano ──\n        # ⭐ In fondo alla riga, dopo il tipo (YT, MP3...). Serve perche\'\n        #    il tasto in alto lavora sul brano "scelto", che non e\' sempre\n        #    quello che si ha in mente: qui non c\'e\' dubbio, e\' il brano\n        #    di questa riga e basta.\n        # ⚠️ largo abbastanza per la parola intera "DEVOCALIZZA": con 78 px\n        #    veniva tagliata. Il carattere e\' piccolo per lo stesso motivo.\n        _vx = cw - self._S(122)\n        _vw = self._S(112)\n        cv.create_rectangle(_vx, y_top + pad, _vx + _vw, y_top + h - pad,\n            fill=self._voce_colore_riga(iid), outline=\'\',\n            tags=(iid, f\'btn_voce_{iid}\', \'btn\'))\n        cv.create_text(_vx + _vw // 2, y_mid,\n            text=self._voce_scritta_stato(iid), fill=\'white\',\n            font=self._F(\'Segoe UI\', 9, \'bold\'),\n            tags=(iid, f\'btn_voce_{iid}\', \'btn\'))\n\n        total_h = (row_idx + 1) * h\n        cv.config(scrollregion=(0, 0, cw, total_h))\n\n    # ── Proxy ──\n    riga_dict = {\n        \'frame\': _TF(self, iid),\n        \'cantante\': _TV(self, iid, \'cantante\'),\n        \'brano\': _TV(self, iid, \'brano\'),\n        \'ton\': _TV(self, iid, \'ton\'),\n        \'path\': path or \'\',\n        \'ext_label\': _TE(self, iid),\n        \'iid\': iid\n    }\n\n    if not from_playlist:\n        self.righe.append(riga_dict)\n        if not getattr(self, \'_batch_loading\', False):\n            self.salva_righe()\n            self._sc_update_scroll()\n\n# ═══════════════════════════════════════════════════\n# SCALETTA: Canvas event handlers\n# ═══════════════════════════════════════════════════\n\n_SC_BTN_COLORS = {\n    \'drag\': (\'#333333\', \'#555555\'), \'add\': (\'#0078D7\', \'#3da0e8\'),\n    \'del\': (\'#dc3545\', \'#e8636f\'), \'rot\': (\'#ffa500\', \'#ffb733\'),\n    \'openpl\': (\'#8B5CF6\', \'#a78bfa\'),\n}\n\n\ndef _sc_redraw_all(self):\n    """Ridisegna TUTTE le righe nell\'ordine di self.righe"""\n    if getattr(self, \'_sc_redrawing\', False): return\n    self._sc_redrawing = True\n    cv = self._sc_cv\n    cv.delete(\'all\')\n    # ✅ Skip se nessuna riga\n    if not self.righe:\n        self._sc_redrawing = False\n        return\n    cv.update_idletasks()\n    cw = max(cv.winfo_width(), 900)\n    h = self._sc_row_h\n    \n    for row_idx, riga in enumerate(self.righe):\n        iid = riga.get(\'iid\')\n        if not iid: continue\n        d = self._sc_row_data.get(iid, {})\n        # ✅ Colore sfondo: selezione o alternanza\n        if row_idx == self.selected_riga_index:\n            bg = \'#1a3a6c\'\n        else:\n            bg = \'#0a0a0a\' if row_idx % 2 == 0 else \'#141414\'\n        y_top = row_idx * h\n        y_mid = y_top + h // 2\n\n        cv.create_rectangle(0, y_top, cw+2000, y_top+h,\n            fill=bg, outline=\'\', tags=(iid, f\'bg_{iid}\'))\n\n        bw, pad, x = self._S(36), self._S(2), self._S(4)\n        _bstep = bw + self._S(2)\n\n        _orig_brano = d.get(\'brano\',\'\')\n        _is_placeholder = _orig_brano.upper().startswith(_(\'Digita per cercare...\').rstrip(\'.\').upper()) or _orig_brano == \'\'\n        btn_add_open = (\'openpl\', \'📂\', \'#8B5CF6\', \'white\') if _is_placeholder else (\'add\', \'+\', \'#0078D7\', \'white\')\n\n        for act, sym, col, fg in [\n            (\'drag\',\'≡\',\'#333333\',\'#888888\'), btn_add_open,\n            (\'del\',\'🗑\',\'#dc3545\',\'white\'), (\'rot\',\'🔄\',\'#ffa500\',\'white\')]:\n            cv.create_rectangle(x, y_top+pad, x+bw, y_top+h-pad,\n                fill=col, outline=\'\', tags=(iid, f\'btn_{act}_{iid}\', \'btn\'))\n            cv.create_text(x+bw//2, y_mid, text=sym, fill=fg,\n                font=self._F(\'Segoe UI\', 14, \'bold\'), tags=(iid, f\'btn_{act}_{iid}\', \'btn\'))\n            x += _bstep\n\n        x_cant, x_brano, x_ton = self._sc_get_col_x()\n        cv.create_text(x_cant, y_mid, text=d.get(\'cantante\',\'\'), fill=\'#ffcc00\',\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_cantante_{iid}\', \'click_cantante\'))\n\n        x = x_brano\n        max_brano_px = max(x_ton - x - self._S(15), self._S(50))\n        if not self._sc_brano_font: self._sc_brano_font = tkfont.Font(family=\'Arial\', size=self._S(18), weight=\'bold\')\n        _bf = self._sc_brano_font\n        _btxt = d.get(\'brano\',\'\')\n        if _btxt and _bf.measure(_btxt) > max_brano_px:\n            lo, hi = 0, len(_btxt)\n            while lo < hi:\n                mid = (lo + hi + 1) // 2\n                if _bf.measure(_btxt[:mid] + \'...\') <= max_brano_px:\n                    lo = mid\n                else:\n                    hi = mid - 1\n            _btxt = _btxt[:lo] + \'...\' if lo > 0 else \'...\'\n        _orig_brano = d.get(\'brano\',\'\')\n        _is_placeholder = _orig_brano.upper().startswith(_(\'Digita per cercare...\').rstrip(\'.\').upper()) or _orig_brano == \'\'\n        _brano_color = \'#555555\' if _is_placeholder else \'#ffcc00\'\n        cv.create_text(x, y_mid, text=_btxt, fill=_brano_color,\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_brano_{iid}\', \'click_brano\'))\n\n        cv.create_text(x_ton, y_mid, text=d.get(\'ton\',\'0\'), fill=\'#ffcc00\',\n            font=self._F(\'Arial\', 18, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_ton_{iid}\', \'click_ton\'))\n\n        # ⚠️ spostata a sinistra per fare posto al tasto della voce\n        cv.create_text(cw-self._S(200), y_mid, text=d.get(\'ext\',\'\'), fill=\'#888888\',\n            font=self._F(\'Arial\', 16, \'bold\'), anchor=\'w\',\n            tags=(iid, f\'txt_ext_{iid}\'))\n\n        # ⛔⛔ IL TASTO VA DISEGNATO ANCHE QUI. Le righe si disegnano in DUE\n        #    posti: `crea_riga` (quando se ne aggiunge una) e questa, che\n        #    le ridisegna tutte — ed e\' questa a girare quasi sempre.\n        #    Mettendolo solo nella prima, il tasto non compariva mai.\n        # ⚠️ largo abbastanza per la parola intera "DEVOCALIZZA": con 78 px\n        #    veniva tagliata. Il carattere e\' piccolo per lo stesso motivo.\n        _vx = cw - self._S(122)\n        _vw = self._S(112)\n        cv.create_rectangle(_vx, y_top + pad, _vx + _vw, y_top + h - pad,\n            fill=self._voce_colore_riga(iid), outline=\'\',\n            tags=(iid, f\'btn_voce_{iid}\', \'btn\'))\n        cv.create_text(_vx + _vw // 2, y_mid,\n            text=self._voce_scritta_stato(iid), fill=\'white\',\n            font=self._F(\'Segoe UI\', 9, \'bold\'),\n            tags=(iid, f\'btn_voce_{iid}\', \'btn\'))\n\n    total_h = len(self.righe) * h\n    cv.config(scrollregion=(0, 0, cw, total_h))\n    self._sc_redrawing = False\n    self._sc_update_scroll()\n\n\ndef _sc_on_click(self, event):\n    cx = self._sc_cv.canvasx(event.x)\n    cy = self._sc_cv.canvasy(event.y)\n\n    # Check button click\n    action, iid = self._sc_find_btn(cx, cy)\n    if action and iid:\n        idx, riga = self._sc_find_riga_by_iid(iid)\n        if not riga: return\n        if action == \'drag\':\n            self._sc_dragging = True\n            self._sc_drag_iid = iid\n            self._sc_cv.config(cursor=\'fleur\')\n            # ✅ Seleziona la riga cliccata e dai focus al canvas per i tasti freccia\n            self.select_riga(idx)\n            self._sc_cv.focus_set()\n            return\n        elif action == \'play\':\n            p = riga[\'path\']\n            b = riga[\'brano\'].get()\n            if not p and (\'youtu.be/\' in b.lower() or \'youtube.com/\' in b.lower()): p = b\n            try: ton = int(riga[\'ton\'].get().strip() or \'0\')\n            except: ton = 0\n            self.play_brano(p, tonalita=ton, cantante=riga[\'cantante\'].get(), brano=b)\n        elif action == \'del\':\n            self.elimina_riga(riga[\'frame\'])\n        elif action == \'rot\':\n            self.sposta_in_fondo(riga[\'frame\'])\n        elif action == \'add\':\n            self.aggiungi_a_playlist(riga[\'frame\'])\n        elif action == \'openpl\':\n            self._apri_playlist_cantante(riga[\'cantante\'].get())\n        elif action == \'voce\':\n            self._voce_riga_accendi(iid, riga)\n        return\n\n    # Click su cantante → seleziona riga e focus per frecce/spazio\n    for item_id in self._sc_cv.find_overlapping(cx-1, cy-1, cx+1, cy+1):\n        tags = self._sc_cv.gettags(item_id)\n        if \'click_cantante\' in tags:\n            iid = None\n            for t in tags:\n                if t.startswith(\'txt_cantante_\'):\n                    iid = t[len(\'txt_cantante_\'):]\n                    break\n            if iid:\n                idx, riga = self._sc_find_riga_by_iid(iid)\n                if riga:\n                    self.select_riga(idx)\n                    self._sc_cv.focus_set()\n                return\n\n    # Check ton click (edit inline)\n    for item_id in self._sc_cv.find_overlapping(cx-1, cy-1, cx+1, cy+1):\n        tags = self._sc_cv.gettags(item_id)\n        if \'click_ton\' in tags:\n            for t in tags:\n                if t.startswith(\'txt_ton_\'):\n                    iid = t[len(\'txt_ton_\'):]\n                    self._sc_edit_field(iid, \'ton\', item_id)\n                    return\n\n    # Check brano click → seleziona riga (edit solo dopo "Pulisci campo")\n    for item_id in self._sc_cv.find_overlapping(cx-1, cy-1, cx+1, cy+1):\n        tags = self._sc_cv.gettags(item_id)\n        if \'click_brano\' in tags:\n            for t in tags:\n                if t.startswith(\'txt_brano_\'):\n                    iid = t[len(\'txt_brano_\'):]\n                    idx, riga = self._sc_find_riga_by_iid(iid)\n                    if riga:\n                        self.select_riga(idx)\n                        self._sc_cv.focus_set()\n                    return\n\n    # Fallback: click su sfondo riga → seleziona\n    row_idx = self._sc_find_row_at_y(cy)\n    if row_idx is not None and row_idx < len(self.righe):\n        self.select_riga(row_idx)\n        self._sc_cv.focus_set()\n\n\ndef _voce_stato_riga(self, iid):\n    """0 = spenta, 1 = in coda o in lavorazione, 2 = pronta.\n\n    ⛔⛔ LO STATO VALE PER IL BRANO, NON PER LA RIGA. Caricando un altro\n        brano in una riga gia\' armata, la riga restava armata e partiva\n        a preparare il brano nuovo da sola ("e\' partito e arrivato al 69%\n        senza che l\'abbia premuto"). Adesso lo stato ricorda PER QUALE\n        brano e\' stato acceso: se il brano della riga e\' cambiato, si\n        spegne.\n    """\n    try:\n        dati = self._sc_row_data.get(iid, {})\n        stato = int(dati.get(\'voce\', 0))\n        per = dati.get(\'voce_per\')\n        if stato and per is not None:\n            _i, riga = self._sc_find_riga_by_iid(iid)\n            ora = self._voce_percorso_riga(riga) if riga else dati.get(\'path\', \'\')\n            if (ora or \'\') != per:\n                dati[\'voce\'] = 0\n                try:\n                    self._voce_coda = [x for x in getattr(self, \'_voce_coda\', [])\n                                       if x[0] != iid]\n                except Exception:\n                    pass\n                return 0\n        return stato\n    except Exception:\n        return 0\n\n\ndef _voce_scritta_stato(self, iid):\n    """Cosa c\'e\' scritto sul tasto quando si ridisegna la riga.\n\n    ⚠️ Mentre lavora la scritta la cambia `_voce_coda_guarda` con la\n       percentuale vera; questa serve quando la scaletta si ridisegna\n       (scorrimento, riordino), per non far tornare tutto a "VOCE".\n    """\n    stato = self._voce_stato_riga(iid)\n    if stato == 2:\n        return \'PRONTA\' + self._voce_segno_testo(iid)\n    if stato == 1:\n        try:\n            fatti, totali = self._voce_lavoro_riga(iid).get(\'av\') or (0, 0)\n            if totali > 0:\n                pc = int(100.0 * fatti / totali)\n                if self._voce_si_parte_riga(iid):\n                    return \'VAI %d%%\' % pc + self._voce_segno_testo(iid)\n                return \'%d%%\' % pc\n        except Exception:\n            pass\n        return \'···\'\n    return \'DEVOCALIZZA\'\n\n\ndef _voce_colore_riga(self, iid):\n    if self._voce_stato_riga(iid) == 1 and self._voce_si_parte_riga(iid):\n        return \'#27ae60\'\n    return {0: \'#8e44ad\', 1: \'#d35400\', 2: \'#27ae60\'}[\n        min(2, max(0, self._voce_stato_riga(iid)))]\n\n\ndef _voce_percorso_riga(self, riga):\n    """Il file (o il link) di QUESTA riga."""\n    p = riga.get(\'path\') or \'\'\n    try:\n        b = riga[\'brano\'].get()\n    except Exception:\n        b = \'\'\n    if not p and (\'youtu.be/\' in b.lower() or \'youtube.com/\' in b.lower()):\n        p = b\n    return p\n\n\ndef _voce_scritta_riga(self, iid, testo):\n    """Cambia la scritta sul tasto VOCE di una riga, senza ridisegnare\n    tutta la scaletta (che a ogni mezzo secondo si vedrebbe lampeggiare).\n\n    ⚠️ Rettangolo e scritta hanno lo STESSO marcatore: si riconosce la\n       scritta perche\' e\' l\'unico elemento di tipo `text`.\n    """\n    try:\n        for item in self._sc_cv.find_withtag(\'btn_voce_%s\' % iid):\n            if self._sc_cv.type(item) == \'text\':\n                self._sc_cv.itemconfig(item, text=testo)\n    except Exception:\n        pass\n\n\ndef _voce_riga_accendi(self, iid, riga):\n    """Accende o spegne la voce SOLO per questa riga."""\n    stato = self._voce_stato_riga(iid)\n    dati = self._sc_row_data.setdefault(iid, {})\n    if stato:                                   # era accesa: si spegne\n        dati[\'voce\'] = 0\n        try:\n            self._voce_coda = [x for x in getattr(self, \'_voce_coda\', [])\n                               if x[0] != iid]\n        except Exception:\n            pass\n    else:\n        p = self._voce_percorso_riga(riga)\n        if not p:\n            return\n        dati[\'voce\'] = 1\n        dati[\'voce_per\'] = p          # per QUESTO brano (vedi _voce_stato_riga)\n        # ⭐ come si ridisegna la scaletta: serve al comando per far\n        #    comparire la ♪ quando il testo arriva a riga gia\' PRONTA\n        try:\n            self.system._voce_ridisegna = self._sc_redraw_all\n        except Exception:\n            pass\n        coda = getattr(self, \'_voce_coda\', None)\n        if coda is None:\n            coda = self._voce_coda = []\n        if iid not in [x[0] for x in coda]:\n            coda.append((iid, p))\n        self._voce_coda_avanti()\n    self._sc_redraw_all()\n\n\ndef _voce_coda_avanti(self):\n    """Manda avanti la coda.\n\n    ⭐⭐ LE RIGHE LAVORANO IN PARALLELO ("anche se sta caricando altrove,\n        deve dare modo di caricare in parallelo"). Prima si aspettava che\n        la riga in corso fosse PRONTA — col roformer, minuti. Adesso la\n        prossima parte appena la precedente e\' VERDE (la testa del brano\n        e\' pulita, pochi secondi): il modello veloce lavora per tutte,\n        il roformer le fa una dopo l\'altra (vedi `_voce_ibrido`).\n    ⚠️ Una sola per volta nella fase veloce, pero\': due teste insieme si\n       dividerebbero il processore e diventerebbero verdi tutte e due\n       piu\' tardi.\n    """\n    coda = getattr(self, \'_voce_coda\', None)\n    if coda and not getattr(self, \'_voce_in_corso\', None):\n        iid, percorso = coda[0]\n        self._voce_in_corso = iid\n        # ⛔ lo stato di QUESTO brano si azzera prima di chiederlo: se era\n        #    gia\' stato fatto una volta, la riga leggerebbe "pronta" subito\n        try:\n            self.system._voce_nota(self.system._voce_chiave(percorso),\n                                   av=(0, 0), vai=False, pronto=False,\n                                   fallito=False)\n        except Exception:\n            pass\n        # ⭐ il NOME del brano, com\'e\' scritto nella riga: serve al testo al\n        #    volo per capire artista e titolo (un link di YouTube non lo dice)\n        try:\n            _i, _riga = self._sc_find_riga_by_iid(iid)\n            if _riga:\n                self.system.__dict__.setdefault(\'_voce_titoli\', {})[\n                    self.system._voce_chiave(percorso)] = _riga[\'brano\'].get()\n        except Exception:\n            pass\n        try:\n            liv = 100\n            try:\n                from .database import Database\n                liv = int(str(Database.get_config(\'voce_giu\', \'100\')).strip())\n            except Exception:\n                pass\n            self.system.set_voce(max(1, min(100, liv)), brano=percorso,\n                                 riga=True)\n        except Exception as e:\n            print("[voce riga] %s" % e)\n            self._voce_in_corso = None\n    # un solo giro di controllo alla volta, per tutte le righe\n    if not getattr(self, \'_voce_guardia_on\', False):\n        self._voce_guardia_on = True\n        try:\n            self.parent.after(700, self._voce_coda_guarda)\n        except Exception:\n            self._voce_guardia_on = False\n\n\ndef _voce_coda_guarda(self):\n    """Aggiorna TUTTE le righe al lavoro e fa partire la prossima in coda.\n\n    Ogni riga legge il SUO stato (`_voce_lavoro_riga`): percentuale,\n    verde "VAI", PRONTA, oppure torna viola se il lavoro e\' fallito.\n    """\n    self._voce_guardia_on = False\n    ridisegna = False\n    al_lavoro = False\n    for r in list(getattr(self, \'righe\', [])):\n        iid = r.get(\'iid\')\n        if self._voce_stato_riga(iid) != 1:\n            continue\n        lav = self._voce_lavoro_riga(iid)\n        if lav.get(\'pronto\'):\n            self._sc_row_data.setdefault(iid, {})[\'voce\'] = 2\n            ridisegna = True\n            continue\n        if lav.get(\'fallito\'):\n            self._sc_row_data.setdefault(iid, {})[\'voce\'] = 0\n            ridisegna = True\n            continue\n        al_lavoro = True\n        # ⭐ la percentuale si scrive SUL TASTO DELLA RIGA: e\' li\' che\n        #    l\'utente guarda\n        try:\n            fatti, totali = lav.get(\'av\') or (0, 0)\n            if totali > 0:\n                pc = int(100.0 * fatti / totali)\n                if lav.get(\'vai\'):\n                    # verde e "VAI": si puo\' mandare, finisce mentre suona\n                    self._voce_scritta_riga(iid, \'VAI %d%%\' % pc\n                                            + self._voce_segno_testo(iid))\n                    for item in self._sc_cv.find_withtag(\'btn_voce_%s\' % iid):\n                        if self._sc_cv.type(item) == \'rectangle\':\n                            self._sc_cv.itemconfig(item, fill=\'#27ae60\')\n                else:\n                    self._voce_scritta_riga(iid, \'%d%%\' % pc)\n            else:\n                self._voce_scritta_riga(iid, \'···\')\n        except Exception:\n            pass\n\n    # la prossima in coda parte appena quella in corso e\' verde (o finita)\n    corrente = getattr(self, \'_voce_in_corso\', None)\n    if corrente:\n        lav = self._voce_lavoro_riga(corrente)\n        if (self._voce_stato_riga(corrente) != 1 or lav.get(\'vai\')\n                or lav.get(\'pronto\') or lav.get(\'fallito\')):\n            self._voce_coda = [x for x in getattr(self, \'_voce_coda\', [])\n                               if x[0] != corrente]\n            self._voce_in_corso = None\n    if ridisegna:\n        self._sc_redraw_all()\n    if getattr(self, \'_voce_coda\', None) and not getattr(self, \'_voce_in_corso\', None):\n        self._voce_coda_avanti()          # riprogramma lui il controllo\n        return\n    if al_lavoro or getattr(self, \'_voce_coda\', None):\n        self._voce_guardia_on = True\n        try:\n            self.parent.after(700, self._voce_coda_guarda)\n        except Exception:\n            self._voce_guardia_on = False\n\n\ndef _voce_decidi_per(self, path, brano=""):\n    """Al play di un brano della scaletta, la voce la decide LA SUA RIGA.\n\n    ⛔ Il livello della voce e\' uno solo per tutto il programma\n       (`system.voce_giu`), e questo rompeva l\'indipendenza delle righe in\n       due modi:\n         - a fine brano viene azzerato (`_voce_fine_brano`): armando B\n           mentre suonava A, finito A il brano B partiva CON LA VOCE pur\n           avendo la riga verde;\n         - la coda delle righe lo accende per preparare: dopo averne\n           armata una, anche le righe NON armate partivano senza voce.\n       Qui, un attimo prima del play, lo si rimette com\'e\' giusto per\n       QUESTO brano. Se il brano non e\' una riga della scaletta (parte dai\n       suggerimenti, per esempio) non si tocca niente: vale il tasto in\n       alto, come prima.\n    """\n    import re as _re2\n    sistema = getattr(self, \'system\', None)\n    if sistema is None:\n        return\n\n    def norm(s):\n        s = str(s or \'\').strip()\n        if not s:\n            return \'\'\n        m = _re2.search(r\'(?:v=|youtu\\.be/|shorts/|embed/)([A-Za-z0-9_-]{11})\', s)\n        if m:\n            return \'yt:\' + m.group(1)\n        try:\n            return os.path.abspath(s).lower()\n        except Exception:\n            return s.lower()\n\n    cercati = {norm(path), norm(brano)} - {\'\'}\n    armata = None\n    for r in getattr(self, \'righe\', []):\n        if norm(self._voce_percorso_riga(r)) in cercati:\n            armata = self._voce_stato_riga(r.get(\'iid\')) > 0\n            break\n    if armata is None:\n        # ⛔ brano che NON e\' in scaletta: prima si lasciava il livello\n        #    com\'era, e se il brano di prima era devocalizzato partiva\n        #    devocalizzato anche questo. Vale solo il tasto in alto.\n        if not getattr(self, \'_voce_giu_attiva\', False):\n            sistema.voce_giu = 0\n        return\n    if armata:\n        liv = 100\n        try:\n            from .database import Database\n            liv = int(str(Database.get_config(\'voce_giu\', \'100\')).strip())\n        except Exception:\n            pass\n        sistema.voce_giu = max(1, min(100, liv))\n        sistema._voce_brano_scelto = path or brano\n    elif not getattr(self, \'_voce_giu_attiva\', False):\n        # riga non armata e tasto in alto spento: si canta con la voce\n        sistema.voce_giu = 0\n\n\ndef play_brano(self, path, entry_ton=None, cantante="", brano="", tonalita=None):\n\n    """Riproduce brano con tonalità dalla riga E aggiorna info centrale"""\n    # ⭐ prima di tutto: la voce di QUESTO brano la decide la sua riga\n    try:\n        self._voce_decidi_per(path, brano)\n    except Exception as _e:\n        print("[voce riga] %s" % _e)\n\n    # ✅ Intercetta link YouTube — estrazione robusta video_id\n    import re as _re\n    from urllib.parse import urlparse, parse_qs\n    \n    check_str = str(path or \'\') + \' \' + str(brano or \'\')\n    dbg("LIBRERIA", f" path={repr(path)[:100]} brano={repr(brano)[:100]}")\n    video_id = None\n    \n    # Metodo 1: Regex standard\n    yt_match = _re.search(r\'(?:youtube\\.com/watch\\?v=|youtu\\.be/|youtube\\.com/embed/|youtube\\.com/shorts/)([a-zA-Z0-9_-]{11})\', check_str, _re.IGNORECASE)\n    if yt_match:\n        video_id = yt_match.group(1)\n    \n    # Metodo 2: Fallback con urllib.parse (gestisce parametri extra, encoding, etc.)\n    if not video_id:\n        for s in [str(path or \'\'), str(brano or \'\')]:\n            s = s.strip()\n            if \'youtu\' not in s.lower():\n                continue\n            try:\n                parsed = urlparse(s if \'://\' in s else \'https://\' + s)\n                if \'youtu.be\' in parsed.hostname:\n                    # youtu.be/VIDEO_ID\n                    vid = parsed.path.lstrip(\'/\')\n                    if len(vid) >= 11:\n                        video_id = vid[:11]\n                elif \'youtube.com\' in parsed.hostname:\n                    # youtube.com/watch?v=VIDEO_ID\n                    qs = parse_qs(parsed.query)\n                    if \'v\' in qs and len(qs[\'v\'][0]) == 11:\n                        video_id = qs[\'v\'][0]\n            except:\n                pass\n            if video_id:\n                break\n    \n    if video_id and len(video_id) == 11:\n        dbg("LIBRERIA", f" YouTube ID estratto: {video_id}")\n\n        # Il video YouTube va riprodotto COME UN VIDEO NORMALE (VLC, su\n        # principale + pubblico), non in una finestra Chromium: yt-dlp lo\n        # scarica e si passa a load_file. Se fallisce si ripiega sul browser.\n        # Per tornare al vecchio comportamento: YT_COME_VIDEO = False.\n        YT_COME_VIDEO = True\n\n        def _apri_browser():\n            if not hasattr(self.system, \'youtube_browser\') or self.system.youtube_browser is None:\n                from .youtube_browser import YouTubeWebViewBrowser\n                self.system.youtube_browser = YouTubeWebViewBrowser(self.parent, self.system)\n            self.system.youtube_browser.play_video(video_id)\n\n        if YT_COME_VIDEO:\n            try:\n                from .youtube_local import riproduci_youtube\n                riproduci_youtube(self.system, self.parent, video_id,\n                                  tonalita=(tonalita or 0),\n                                  ripiego_browser=_apri_browser)\n            except Exception as _e:\n                print(f"[YT-STREAM] non disponibile ({_e}) -> browser")\n                _apri_browser()\n        else:\n            _apri_browser()\n\n        # ✅ APPLICA PITCH dalla riga della libreria (non-bloccante)\n        try:\n            if tonalita is not None:\n                yt_pitch = tonalita\n            elif entry_ton:\n                try:\n                    yt_pitch = int(entry_ton.get().strip() or "0")\n                except:\n                    yt_pitch = 0\n            else:\n                yt_pitch = self.pitch_var.get() if self.pitch_var else 0\n            \n            if yt_pitch != 0:\n                self.system.current_pitch = yt_pitch\n                if self.pitch_var is not None:\n                    self.pitch_var.set(yt_pitch)\n                if self.pitch_label_ref and self.pitch_label_ref[\'label\']:\n                    self.pitch_label_ref[\'label\'].config(text=f"{yt_pitch:+d}")\n                # ⛔ LA TONALITA\' SI DA\' AL PROGRAMMA, NON AL BROWSER.\n                #    Qui si chiamava `youtube_browser.set_pitch`, ma quel\n                #    browser esiste solo nel vecchio percorso: da quando le\n                #    basi online si riproducono come un video normale\n                #    (YT_COME_VIDEO) non viene piu\' creato, e la chiamata\n                #    moriva con "no attribute \'youtube_browser\'" un secondo\n                #    e mezzo dopo la partenza. Risultato: sulle basi prese\n                #    da internet la tonalita\' non arrivava a destinazione.\n                #    `system.set_pitch` sceglie da se\' il motore giusto -\n                #    e avvisa il browser solo se c\'e\' davvero.\n                _p = yt_pitch\n\n                def _dai_la_tonalita(_p=_p):\n                    try:\n                        self.system.set_pitch(_p)\n                    except Exception as e:\n                        print(f"⚠️ tonalita\' base online: {e}")\n\n                self.parent.after(1500, _dai_la_tonalita)\n                print(f"🎵 YouTube pitch dalla riga: {yt_pitch:+d}")\n        except Exception as e:\n            print(f"⚠️ YouTube pitch errore: {e}")\n\n        if self.info_brano_ref:\n\n            if self.info_brano_ref.get(\'cantante\'):\n\n                self.info_brano_ref[\'cantante\'].config(text=cantante.upper() if cantante else "---")\n\n            if self.info_brano_ref.get(\'brano\'):\n\n                self.info_brano_ref[\'brano\'].config(text=brano.upper() if brano else video_id)\n\n            if self.info_brano_ref.get(\'ext\'):\n\n                self.info_brano_ref[\'ext\'].config(text="[YT]")\n\n        print(f"▶ YouTube: {cantante} - {brano} [{video_id}]")\n        \n        # ✅ Chiudi libreria automaticamente dopo play YouTube\n        if self.slider_visible:\n            self.toggle_slider()\n\n        try:\n\n            from .history import log_brano\n\n            log_brano(f"YT:{brano or video_id}", cantante)\n\n        except Exception:\n\n            pass\n\n        return\n\n\n\n    # ✅ BASI ONLINE (KDM): il brano non e\' un file locale ma sta sul db online.\n    #    path = \'kdmonline://<sorgente:rowid>\'. Lo scarichiamo PRIMA in un file\n    #    temporaneo, poi proseguiamo col normale flusso di riproduzione locale.\n    if isinstance(path, str) and path.startswith(\'kdmonline://\'):\n        db_id = path[len(\'kdmonline://\'):]\n        try:\n            import tempfile\n            from .basi_online import scarica, is_video\n            suffix = \'.mp4\' if is_video(db_id) else \'.mp3\'\n            fd, temp_path = tempfile.mkstemp(suffix=suffix, prefix=\'kdm_\')\n            os.close(fd)\n            dbg("LIBRERIA", f" Download online {db_id} -> {temp_path}")\n            res = scarica(db_id, temp_path)\n        except Exception as e:\n            dbg("LIBRERIA", f" ❌ Errore download online: {e}")\n            res = None\n        if not res:\n            messagebox.showerror(_("Errore"), _("Impossibile scaricare il brano online.\\nVerifica la connessione o la licenza."), parent=self.parent)\n            return\n        path = res\n        dbg("LIBRERIA", f" Brano online pronto: {path}")\n\n    if path and os.path.exists(path):\n        dbg("LIBRERIA", f" File trovato: {path}")\n        # Prendi tonalità: prima da parametro diretto, poi da entry_ton, infine mantieni corrente\n\n        if tonalita is not None:\n\n            # Tonalità specificata esplicitamente\n\n            pass\n\n        elif entry_ton:\n\n            # Prendi da campo entry\n\n            try:\n\n                tonalita = int(entry_ton.get().strip() or "0")\n\n            except:\n\n                tonalita = 0\n\n        else:\n\n            # ✅ MANTIENI PITCH CORRENTE se non specificato\n\n            tonalita = self.pitch_var.get() if self.pitch_var else 0\n\n        \n\n        # AGGIORNA controlli pitch in basso\n\n        if self.pitch_var is not None:\n\n            self.pitch_var.set(tonalita)\n\n        if self.pitch_label_ref and self.pitch_label_ref[\'label\']:\n\n            if tonalita == 0:\n\n                self.pitch_label_ref[\'label\'].config(text="0")\n\n            else:\n\n                self.pitch_label_ref[\'label\'].config(text=f"{tonalita:+d}")\n\n        \n\n        # AGGIORNA INFO BRANO CENTRALE (cantante e brano separati)\n\n        if self.info_brano_ref:\n\n            if self.info_brano_ref.get(\'cantante\'):\n\n                self.info_brano_ref[\'cantante\'].config(text=cantante if cantante else "---")\n\n            if self.info_brano_ref.get(\'brano\'):\n\n                self.info_brano_ref[\'brano\'].config(text=brano if brano else "---")\n\n            if self.info_brano_ref.get(\'ext\'):\n\n                ext = Path(path).suffix[1:].upper()\n\n                self.info_brano_ref[\'ext\'].config(text=ext)\n\n        \n\n        print(f"▶ Caricamento: {os.path.basename(path)} (Ton: {tonalita:+d})")\n\n        \n        # ✅ Se è lo STESSO FILE già in riproduzione → swap senza riavvolgimento\n        same_file = (self.system.current_file and \n                    os.path.normpath(self.system.current_file) == os.path.normpath(path))\n        \n        if same_file and self.system.is_playing and tonalita == getattr(self.system, \'current_pitch\', 0):\n            # Stesso file, stesso pitch → restart istantaneo\n            self.system.restart()\n            print(f"▶ {os.path.basename(path)}")\n            \n            # ✅ Chiudi libreria automaticamente dopo play\n            if self.slider_visible:\n                self.toggle_slider()\n        elif self.system.load_file(path, tonalita):\n\n            # ✅ AGGIORNA DURATA nei controlli in basso\n\n            if self.info_brano_ref and self.info_brano_ref.get(\'duration\'):\n\n                if self.system.engine and self.system.engine.total_duration_ms > 0:\n\n                    total_sec = int(self.system.engine.total_duration_ms / 1000)\n\n                    self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n\n                elif self.system.monitor.syllables_data:\n\n                    total_ms = self.system.monitor.syllables_data[-1][1]\n\n                    total_sec = int(total_ms / 1000)\n\n                    self.info_brano_ref[\'duration\'].config(text=f"{total_sec//60:02d}:{total_sec%60:02d}")\n\n            \n\n            # Play con tonalità\n\n            self.system.play(tonalita)\n\n            print(f"▶ {os.path.basename(path)}")\n            \n            # ✅ Chiudi libreria automaticamente dopo play\n            if self.slider_visible:\n                self.toggle_slider()\n\n            \n\n# ✅ AGGIORNA MIXER se è un file MIDI\n\n            if path.lower().endswith((\'.mid\', \'.kar\', \'.midi\')):\n\n                from .mixer import MIDIMixerPanel\n\n                mixer = MIDIMixerPanel.get_instance()\n\n                \n\n                if not mixer:\n\n                    # Crea il mixer (rimane chiuso)\n\n                    mixer = MIDIMixerPanel(self.parent, self.system)\n\n                    print("🎚️ Libreria: Mixer creato automaticamente")\n\n                \n\n                # Melody muted: sempre True per default\n\n                melody_is_muted = True\n\n                \n\n                mixer.load_midi_file(path, melody_muted=melody_is_muted)\n\n                print(f"🎚️ Libreria: Chiamato mixer.load_midi_file({os.path.basename(path)})")\n\n            \n\n            # ✅ Log brano nella history SIAE\n\n            try:\n\n                from .history import log_brano\n\n                titolo = Path(path).stem\n\n                log_brano(titolo)\n\n            except Exception as e:\n\n                print(f"⚠️ Errore log history: {e}")\n\n        else:\n\n            # ✅ Mostra errore dettagliato per diagnostica\n            errore_dettaglio = getattr(self.system, \'last_error\', \'\') or \'Errore sconosciuto\'\n            messagebox.showerror(_("Errore"), _("Impossibile caricare:\\n{path}\\n\\nDettaglio: {errore_dettaglio}").format(path=path, errore_dettaglio=errore_dettaglio), parent=self.parent)\n\n    else:\n        # ✅ Se è un URL YouTube che non è stato intercettato, non mostrare "File non trovato"\n        _path_str = str(path or \'\').lower()\n        if \'youtu.be/\' in _path_str or \'youtube.com/\' in _path_str:\n            dbg("LIBRERIA", f" ❌ URL YouTube non intercettato! path={path}")\n            messagebox.showerror(_("Errore"), _("Impossibile estrarre Video ID da:\\n{path}\\n\\nFormati supportati:\\nhttps://youtu.be/XXXXXXXXXXX\\nhttps://www.youtube.com/watch?v=XXXXXXXXXXX").format(path=path), parent=self.parent)\n        else:\n            dbg("LIBRERIA", f" ❌ File non trovato! path={repr(path)}")\n            messagebox.showerror(_("Errore"), _("File non trovato!"), parent=self.parent)\n\n\ndef _voce_si_parte_riga(self, iid):\n    """La riga e\' ancora al lavoro, ma il brano si puo\' gia\' mandare:\n    la puntina non raggiungera\' il modello (vedi `_voce_ibrido`)."""\n    return bool(self._voce_lavoro_riga(iid).get(\'vai\'))\n\n\ndef _voce_lavoro_riga(self, iid):\n    """Lo stato del lavoro del brano di QUESTA riga (vedi `_voce_nota` nel\n    comando): av, vai, pronto, fallito. Vuoto se non e\' mai partito.\n\n    ⛔ Prima c\'era un solo stato per tutto il programma: con piu\' righe\n       al lavoro insieme si leggevano la percentuale una dell\'altra.\n    """\n    try:\n        dati = self._sc_row_data.get(iid, {})\n        per = dati.get(\'voce_per\')\n        if not per:\n            _i, riga = self._sc_find_riga_by_iid(iid)\n            per = self._voce_percorso_riga(riga) if riga else \'\'\n        if not per:\n            return {}\n        chiave = self.system._voce_chiave(per)\n        return self.system.__dict__.get(\'_voce_lavori\', {}).get(chiave, {}) or {}\n    except Exception:\n        return {}\n\n\ndef _voce_segno_testo(self, iid):\n    """♪ sul tasto quando il TESTO AL VOLO e\' pronto: il brano partira\'\n    come base col testo, senza video (vedi `_testo_scambio` nel comando)."""\n    try:\n        if self._voce_lavoro_riga(iid).get(\'testo\') in (\'sillabe\', \'righe\'):\n            return \' ♪\'\n    except Exception:\n        pass\n    return \'\''

CODICE_SPLASH = 'def _riga_tecnica_di(hd_id, chipset_id):\n    """La riga piccola sotto il seriale: impronta, versione, patch attive.\n\n    ⛔ NON DEVE MAI FAR SALTARE LO SPLASH. E\' la finestra che si apre a chi non\n       ha licenza: se un errore qui impedisse di aprirla, il cliente non\n       potrebbe nemmeno far partire la prova. Ogni pezzo sta nel suo `try` e\n       quello che non si sa diventa un trattino.\n    """\n    hw = \'—\'\n    try:\n        hw = (_collect_pc_fingerprint(hd_id, chipset_id)[0] or \'—\')[:16]\n    except Exception:\n        pass\n    ver = \'—\'\n    for come in (\'moduli.versione\', \'versione\'):\n        try:\n            ver = __import__(come, fromlist=[\'APP_VERSION\']).APP_VERSION\n            break\n        except Exception:\n            continue\n    patch = \'—\'\n    try:\n        from . import hotfix\n        r = hotfix.riassunto() or {}\n        attive = sorted(n for n, v in r.items() if v and v[0])\n        patch = (\',\'.join(attive) if attive\n                 else (\'nessuna\' if r else \'—\'))\n    except Exception:\n        pass\n    return \'hw %s   ·   v %s   ·   patch %s\' % (hw, ver, patch)\n\n\ndef _crea_contenuto(self):\n    """Il contenuto vero e proprio della finestra di attivazione."""\n\n    # ===== LOGO =====\n    logo_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n    logo_frame.pack(pady=S(15))\n    \n    logo_path = self._get_logo_path()\n    if logo_path:\n        try:\n            from PIL import Image, ImageTk\n            img = Image.open(logo_path)\n            # mantiene le proporzioni (il logo orizzontale non va schiacciato)\n            img.thumbnail((S(340), S(150)), Image.Resampling.LANCZOS)\n            self.logo_img = ImageTk.PhotoImage(img)\n            logo_label = tk.Label(logo_frame, image=self.logo_img, bg=\'#1a1a2e\')\n            # serve a _rimpicciolisci_logo: su schermi bassi il logo si\n            # ridisegna piu\' piccolo invece di rubare spazio ai campi\n            logo_label._kd_logo_path = logo_path\n            logo_label.pack()\n            tk.Label(self.root, text=_("Sistema Karaoke Professionale"), \n            font=F(\'Arial\', 9), bg=\'#1a1a2e\', fg=\'#888888\').pack()\n        except:\n            tk.Label(logo_frame, text="🎤", font=F(\'Arial\', 50), \n                    bg=\'#1a1a2e\', fg=\'#0078D7\').pack()\n    else:\n        tk.Label(logo_frame, text="🎤", font=F(\'Arial\', 50), \n                bg=\'#1a1a2e\', fg=\'#0078D7\').pack()\n    \n    # Titolo\n    #tk.Label(self.root, text=_("KaraDom"), font=F(\'Arial\', 22, \'bold\'),\n    #        bg=\'#1a1a2e\', fg=\'white\').pack()\n    #tk.Label(self.root, text=_("Sistema Karaoke Professionale"), \n    #        font=F(\'Arial\', 9), bg=\'#1a1a2e\', fg=\'#888888\').pack()\n    \n    # ===== FORM LICENZA =====\n    form_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n    form_frame.pack(pady=S(15), padx=S(30), fill=\'x\')\n    \n    # Nome\n    tk.Label(form_frame, text=_("Nome"), font=F(\'Arial\', 10, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n    self.entry_nome = tk.Entry(form_frame, font=F(\'Arial\', 12), \n                               bg=\'#2d2d44\', fg=\'white\',\n                               insertbackground=\'white\', relief=\'flat\')\n    self.entry_nome.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n    \n    # Cognome\n    tk.Label(form_frame, text=_("Cognome"), font=F(\'Arial\', 10, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n    self.entry_cognome = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                  bg=\'#2d2d44\', fg=\'white\',\n                                  insertbackground=\'white\', relief=\'flat\')\n    self.entry_cognome.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n    \n    # Email\n    tk.Label(form_frame, text=_("Email"), font=F(\'Arial\', 10, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n    self.entry_email = tk.Entry(form_frame, font=F(\'Arial\', 12),\n                                bg=\'#2d2d44\', fg=\'white\',\n                                insertbackground=\'white\', relief=\'flat\')\n    self.entry_email.pack(fill=\'x\', ipady=S(6), pady=(0, S(8)))\n    \n    # Seriale (readonly)\n    tk.Label(form_frame, text=_("Seriale PC"), font=F(\'Arial\', 10, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n    \n    serial_frame = tk.Frame(form_frame, bg=\'#1a1a2e\')\n    serial_frame.pack(fill=\'x\', pady=(0, S(8)))\n    \n    # Il seriale va LETTO e ricopiato al telefono: era verde acceso su\n    # fondo chiaro (readonly schiarisce lo sfondo) e si leggeva male.\n    # Bianco su fondo scuro, grassetto e a spaziatura fissa: le cifre e le\n    # lettere non si confondono (0/O, 1/I).\n    self.entry_serial = tk.Entry(serial_frame,\n                                 font=F(\'Consolas\', 12, \'bold\'),\n                                 bg=\'#2d2d44\', fg=\'#ffffff\',\n                                 readonlybackground=\'#2d2d44\',\n                                 disabledbackground=\'#2d2d44\',\n                                 insertbackground=\'white\', relief=\'flat\',\n                                 state=\'readonly\')\n    self.entry_serial.pack(side=\'left\', fill=\'x\', expand=True, ipady=S(6))\n    \n    self.entry_serial.config(state=\'normal\')\n    self.entry_serial.insert(0, self.serial)\n    self.entry_serial.config(state=\'readonly\')\n    \n    # Bottone richiedi licenza\n    btn_request = tk.Button(serial_frame, text=_("📧 Richiedi"), \n                           font=F(\'Arial\', 9, \'bold\'),\n                           bg=\'#0078D7\', fg=\'white\', relief=\'flat\',\n                           cursor=\'hand2\', padx=S(12),\n                           command=self._request_license)\n    btn_request.pack(side=\'right\', padx=(S(8), 0), ipady=S(4))\n\n    # ⭐ Impronta hardware, versione e patch attive, SOTTO il seriale.\n    #    Serve all\'assistenza: al telefono il cliente legge questa riga e\n    #    si sa subito su che PC si sta lavorando e se le patch sono\n    #    arrivate. Prima l\'impronta non si vedeva da nessuna parte e le\n    #    patch si potevano solo chiedere — con risposte sbagliate anche in\n    #    buona fede (vedi `hotfix.riassunto`, che riporta cio\' che il\n    #    caricatore ha VISTO, non cio\' che si spera).\n    #\n    # ⚠️ UNA RIGA SOLA, carattere piccolo: questa finestra su 1366x768 non\n    #    ci stava gia\' prima e il bottone della prova finiva fuori schermo.\n    #    Niente blocchi alti (vedi la nota sull\'altezza dello splash).\n    tk.Label(form_frame, text=_riga_tecnica_di(self.hd_id, self.chipset_id),\n             font=F(\'Consolas\', 8), bg=\'#1a1a2e\', fg=\'#7a7a95\',\n             anchor=\'w\', justify=\'left\').pack(fill=\'x\', pady=(0, S(4)))\n\n    # Separatore\n    tk.Frame(form_frame, bg=\'#444444\', height=S(1)).pack(fill=\'x\', pady=S(12))\n    \n    # Campo Licenza\n    tk.Label(form_frame, text=_("Codice Licenza"), font=F(\'Arial\', 10, \'bold\'),\n            bg=\'#1a1a2e\', fg=\'white\', anchor=\'w\').pack(fill=\'x\')\n    self.entry_license = tk.Entry(form_frame, font=F(\'Arial\', 13),\n                                  bg=\'#2d2d44\', fg=\'#ffcc00\',\n                                  insertbackground=\'white\', relief=\'flat\',\n                                  justify=\'center\')\n    self.entry_license.pack(fill=\'x\', ipady=S(8), pady=(0, S(8)))\n    \n    # Bottone Attiva\n    btn_activate = tk.Button(form_frame, text=_("✓ ATTIVA LICENZA"),\n                            font=F(\'Arial\', 11, \'bold\'),\n                            bg=\'#28a745\', fg=\'white\', relief=\'flat\',\n                            cursor=\'hand2\', pady=S(8),\n                            command=self._activate_license)\n    btn_activate.pack(fill=\'x\', pady=(0, S(15)))\n    \n    btn_activate.bind("<Enter>", lambda e: btn_activate.config(bg=\'#218838\'))\n    btn_activate.bind("<Leave>", lambda e: btn_activate.config(bg=\'#28a745\'))\n    \n    # ===== SEPARATORE =====\n    sep_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n    sep_frame.pack(fill=\'x\', padx=S(30))\n    tk.Frame(sep_frame, bg=\'#444444\', height=S(1)).pack(fill=\'x\')\n    tk.Label(sep_frame, text=_(" oppure "), bg=\'#1a1a2e\', fg=\'#666666\',\n            font=F(\'Arial\', 9)).place(relx=0.5, rely=0.5, anchor=\'center\')\n    \n    # ===== ACCESSO SENZA LICENZA =====\n    trial_frame = tk.Frame(self.root, bg=\'#1a1a2e\')\n    trial_frame.pack(pady=S(15))\n    \n    tk.Label(trial_frame, text=_("Non hai una licenza?"), \n            font=F(\'Arial\', 10), bg=\'#1a1a2e\', fg=\'#aaaaaa\').pack()\n    \n    btn_trial = tk.Button(trial_frame, text=_("▶ ACCEDI (Prova 60 minuti)"),\n                         font=F(\'Arial\', 14, \'bold\'),\n                         bg=\'#e67e22\', fg=\'white\', relief=\'flat\',\n                         cursor=\'hand2\', padx=S(40), pady=S(15),\n                         command=self._start_trial)\n    btn_trial.pack(pady=S(10))\n    \n    btn_trial.bind("<Enter>", lambda e: btn_trial.config(bg=\'#d35400\'))\n    btn_trial.bind("<Leave>", lambda e: btn_trial.config(bg=\'#e67e22\'))\n    \n    tk.Label(trial_frame, text=_("Il programma si chiuderà automaticamente\\ndopo 60 minuti di utilizzo"), \n            font=F(\'Arial\', 8), bg=\'#1a1a2e\', fg=\'#666666\').pack()\n    \n    # Footer (anno dinamico - si aggiorna automaticamente ogni 1 gennaio)\n    tk.Label(self.root, text=_("© {year} KaraDom - Tutti i diritti riservati").format(year=datetime.now().year),\n            font=F(\'Arial\', 8), bg=\'#1a1a2e\', fg=\'#444444\').pack(side=\'bottom\', pady=S(10))'
NOMI_SPLASH_MOD = ('_riga_tecnica_di',)
NOMI_SPLASH_CLS = ('_crea_contenuto',)


def _spenta():
    try:
        from moduli.database import Database
        v = str(Database.get_config('patch_' + NUMERO, '1')).strip()
        if v in ('0', 'no', 'off'):
            traccia('spenta a mano (patch_' + NUMERO + ' = %s)' % v)
            return True
    except Exception as e:
        # ⛔ L'ECCEZIONE NON VALE "SPENTA": nel compilato l'import puo'
        #    fallire, e trattarlo come uno spegnimento aveva tenuto ferma la
        #    patch per ore senza un motivo visibile.
        traccia('non riesco a leggere la configurazione (%s): vado avanti lo stesso' % e)
    return False


def traccia(testo):
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch033.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                testo) + chr(10))
    except Exception:
        pass


def apply():
    if _spenta():
        return False
    fatte = []

    # 0) il modulo che separa la voce: nel compilato non c'e', glielo si mette
    try:
        import sys as _s
        import types as _t
        import moduli as _pkg
        if _s.modules.get('moduli.devocalizza') is None:
            _m = _t.ModuleType('moduli.devocalizza')
            _m.__package__ = 'moduli'          # cosi' i suoi `from .x` funzionano
            _m.__file__ = '<patch_voce_devoc>'
            exec(compile(CODICE_DEVOC, '<patch_voce_devoc>', 'exec'), _m.__dict__)
            _s.modules['moduli.devocalizza'] = _m
            setattr(_pkg, 'devocalizza', _m)
            fatte.append('modello (messo)')
        else:
            # ⛔⛔ SI AGGIORNA LO STESSO. Prima qui si lasciava quello che
            #     c'era: ma le patch si applicano in fila (033, 034, 035...)
            #     e la PRIMA metteva il modulo vecchio — la nuova lo trovava
            #     e se lo teneva, e il roformer non arrivava mai.
            _m = _s.modules['moduli.devocalizza']
            exec(compile(CODICE_DEVOC, '<patch_voce_devoc>', 'exec'), _m.__dict__)
            fatte.append('modello (aggiornato)')
    except Exception as e:
        # non e' fatale: senza modello resta il metodo del centro, che suona
        traccia('modello NON messo: %s: %s' % (type(e).__name__, e))

    # ⛔ Via il vecchio filtro dentro il motore audio, se una versione
    #    precedente l'aveva agganciato: era codice Python dentro il thread del
    #    suono e bloccava il programma.
    try:
        import sys as _s2
        mb = _s2.modules.get('moduli.bass_engine')
        if mb and hasattr(mb, 'BassEngine'):
            for n in ('set_voce', '_togli_dsp_voce', '_aggancia_dsp_voce'):
                if n in mb.BassEngine.__dict__:
                    delattr(mb.BassEngine, n)
    except Exception:
        pass

    # ⛔ Via la voce "Avvia DOM SVC (Camera Controller)" dal menu Strumenti.
    #    Nel sorgente non c'e' piu' (resta solo nei backup vecchi), ma
    #    l'eseguibile in uso e' precedente e continua a mostrarla: quel codice
    #    li' dentro e' gia' compilato e non lo si tocca modificando un file.
    #    Si mette un filtro su chi aggiunge le voci ai menu.
    try:
        import tkinter as _tk
        _agg = _tk.Menu.add_command
        if not getattr(_agg, '_voce_avvolta', False):
            def _add_command(self, cnf={}, **kw):
                try:
                    testo = str(kw.get('label') or (cnf or {}).get('label') or '')
                    if 'DOM SVC' in testo:
                        return None
                except Exception:
                    pass
                return _agg(self, cnf, **kw)
            _add_command._voce_avvolta = True
            _tk.Menu.add_command = _add_command
        fatte.append('voce DOM SVC tolta')
    except Exception as e:
        traccia('voce DOM SVC NON tolta: %s: %s' % (type(e).__name__, e))

    # ⛔ E via anche il MOTORE del DOM SVC, non solo la sua voce di menu: il
    #    programma compilato lancia `adb` all'avvio per vedere se c'e' un
    #    telefono collegato, e lascia in giro adb.log. Togliere la voce non
    #    bastava — si vedeva dal file che continuava a nascere.
    #    Gli si fa credere che adb non ci sia: e' la stessa strada che il
    #    programma prevede gia' ("SKV disabilitato: dipendenze non trovate").
    try:
        import os as _os2
        import subprocess as _sp
        _Popen = _sp.Popen
        if not getattr(_Popen, '_voce_avvolta', False):
            def _popen_senza_adb(args, *a, **k):
                try:
                    primo = args[0] if isinstance(args, (list, tuple)) and args else args
                    if _os2.path.basename(str(primo)).lower() in (
                            'adb.exe', 'adb', 'fastboot.exe'):
                        raise FileNotFoundError(
                            2, 'adb spento da patch_' + NUMERO, str(primo))
                except FileNotFoundError:
                    raise
                except Exception:
                    pass
                return _Popen(args, *a, **k)
            _popen_senza_adb._voce_avvolta = True
            _sp.Popen = _popen_senza_adb
        fatte.append('adb del DOM SVC spento')
    except Exception as e:
        traccia('adb NON spento: %s: %s' % (type(e).__name__, e))

    # Le scritte nuove tradotte. ⛔ Devono viaggiare CON LA PATCH: en.json e'
    # un file di dati e la patch porta solo codice, quindi in inglese il tasto
    # resterebbe in italiano fino alla ricompilazione.
    try:
        import moduli.i18n as mi
        if isinstance(getattr(mi, '_translations', None), dict):
            mi._translations.update(TRADUZIONI)
        _carica = getattr(mi, 'load_language', None)
        if _carica is not None and not getattr(_carica, '_voce_avvolta', False):
            def _carica_e_aggiungi(lang, _o=_carica):
                r = _o(lang)
                try:
                    if isinstance(mi._translations, dict):
                        mi._translations.update(TRADUZIONI)
                except Exception:
                    pass
                return r
            _carica_e_aggiungi._voce_avvolta = True
            mi.load_language = _carica_e_aggiungi
        fatte.append('scritte tradotte')
    except Exception as e:
        traccia('traduzioni NON messe: %s: %s' % (type(e).__name__, e))

    try:
        # le dipendenze si scaricano in sottofondo, non tenendo fermo il
        # programma: adesso fra quelle c'e' anche il motore che separa la voce
        import moduli.dep_sync as md
        sp = md.__dict__
        exec(compile(CODICE_DEP, "<patch_voce_dep>", "exec"), sp)
        md.completa_mancanti = sp['completa_mancanti']
        md._completa_mancanti_ora = sp['_completa_mancanti_ora']
        fatte.append('dipendenze in sottofondo')
    except Exception as e:
        traccia('dipendenze NON sistemate: %s: %s' % (type(e).__name__, e))

    try:
        import moduli.system as ms
        sp = ms.__dict__
        exec(compile(CODICE_SYS, "<patch_voce_sys>", "exec"), sp)
        for n in NOMI_SYS:
            setattr(ms.KaraokeMonitorSystem, n, sp[n])
        # ⚠️ i valori scritti nella classe: `prendi` copia solo le funzioni,
        #    e senza questi il filtro userebbe i ripieghi scritti a mano
        ms.KaraokeMonitorSystem.TAGLIO_GRAVE = 120
        ms.KaraokeMonitorSystem.TAGLIO_ARIA = 12000
        ms.KaraokeMonitorSystem.RIPIDITA = 2
        fatte.append('comando')
    except Exception as e:
        traccia('comando NON agganciato: %s: %s' % (type(e).__name__, e))
        return False

    try:
        import moduli.yt2mp3 as my
        C = my.YoutubePanel
        sp = my.__dict__
        exec(compile(CODICE_YT, "<patch_voce_yt>", "exec"), sp)
        for n in NOMI_YT:
            setattr(C, n, sp[n])
        if getattr(C, 'btn_karaoke', None) is None:
            C.btn_karaoke = None
        fatte.append('barra youtube')
    except Exception as e:
        traccia('barra youtube NON agganciata: %s: %s' % (type(e).__name__, e))

    try:
        # ⭐ Lo splash della prova: sotto il seriale compaiono impronta
        #    hardware, versione e patch attive. Serve all'assistenza al
        #    telefono — prima l'impronta non si vedeva da nessuna parte.
        # ⚠️ `_riga_tecnica_di` sta nel MODULO, `_crea_contenuto` e' un metodo
        #    della classe `SplashScreen`: si attaccano in due posti diversi.
        import moduli.splash as msp
        ssp = msp.__dict__
        exec(compile(CODICE_SPLASH, "<patch_voce_splash>", "exec"), ssp)
        for n in NOMI_SPLASH_MOD:
            setattr(msp, n, ssp[n])
        for n in NOMI_SPLASH_CLS:
            setattr(msp.SplashScreen, n, ssp[n])
        fatte.append('splash con impronta e patch')
    except Exception as e:
        traccia('splash NON agganciato: %s: %s' % (type(e).__name__, e))

    try:
        import moduli.libreria as ml
        sp = ml.__dict__
        exec(compile(CODICE_LIB, "<patch_voce_lib>", "exec"), sp)
        for n in NOMI_LIB:
            setattr(ml.LibreriaSlider, n, sp[n])
        # ⛔⛔ QUI C'ERA UNA PULIZIA CHE STACCAVA `_voce_su_giu`,
        #    `_voce_disarma`, `_voce_nuovo_brano` e `_voce_brano_scelto`.
        #    Aveva senso quando il tasto non c'era piu'. Col tasto rimesso
        #    faceva questo: il ciclo qui sopra le attaccava, e due righe dopo
        #    questa le staccava — quindi `create_slider` chiamava un metodo
        #    che non esisteva piu' e il programma MORIVA ALL'AVVIO:
        #        CRASH: 'LibreriaSlider' object has no attribute '_voce_su_giu'
        #    Se un domani il tasto si toglie di nuovo, si toglie da `LIB`:
        #    cosi' non vengono nemmeno attaccate, invece di attaccarle e
        #    staccarle.
        # Appena si SCEGLIE un brano, se il tasto e' gia' armato la
        # preparazione comincia subito.
        # ⭐ La funzione originale non si riscrive: le si mette un cappotto
        #    intorno e la si chiama (come nella 017).
        C = ml.LibreriaSlider
        for n in ('seleziona_suggerimento', 'seleziona_suggerimento_auto'):
            orig = getattr(C, n, None)
            if orig is None or getattr(orig, '_voce_avvolta', False):
                continue

            def cappotto(self, event=None, _orig=orig):
                r = _orig(self, event)
                try:
                    self._voce_nuovo_brano(
                        getattr(self, 'brano_selezionato_path', None))
                except Exception:
                    pass
                return r

            cappotto._voce_avvolta = True
            setattr(C, n, cappotto)
        fatte.append('tasto nella barra')
    except Exception as e:
        traccia('barra libreria NON agganciata: %s: %s' % (type(e).__name__, e))

    traccia('AGGANCIATA: ' + ', '.join(fatte))
    print("patch " + NUMERO + ": si puo' togliere la voce dal brano")
    return True


def revert():
    print("patch " + NUMERO + ": si toglie riavviando")
    return True


try:
    apply()
except Exception:
    pass
